export type OutputKey = '01-signin.dashboard_url' | '01-signin.panel_1_title' | '01-signin.panel_2_title' | '01-signin.panel_3_title' | '01-signin.panel_titles_1' | '01-signin.panel_titles_2' | '01-signin.panel_titles_3' | '02-create.dashboard_title' | '02-create.dashboard_url' | '02-create.datasource' | '02-create.minted' | '02-create.panel_title' | '02-create.ref' | '02-create.save_confirmation' | '02-create.url.p1' | '02-create.url.p2' | '02-create.visualization' | '03-open.dashboard_title' | '03-open.dashboard_url' | '03-open.other_panel' | '03-open.ref' | '03-open.save_confirmation' | '03-open.text_panel_content' | '03-open.text_panel_editor_content' | '03-open.text_panel_title' | '03-open.text_visible_after_reload' | '04-set.dashboard_json_version' | '04-set.dashboard_tags' | '04-set.dashboard_title' | '04-set.dashboard_uid' | '04-set.dashboard_url' | '04-set.default_time_range_from' | '04-set.default_time_range_to' | '04-set.final_dashboard_url' | '04-set.json_model_tag' | '04-set.json_model_tag_value' | '04-set.json_model_tags_line' | '04-set.json_model_tail' | '04-set.json_model_time_from' | '04-set.json_model_time_from_line' | '04-set.json_model_time_line' | '04-set.json_model_time_to' | '04-set.json_model_time_to_line' | '04-set.json_model_visible_lines' | '04-set.panels_1' | '04-set.panels_2' | '04-set.ref' | '04-set.save_confirmation' | '04-set.tag_added' | '04-set.time_options_section' | '04-set.time_picker_label' | '04-set.update_default_time_range_checkbox' | '05-set.auto_refresh_in_settings_after_reload' | '05-set.auto_refresh_input' | '05-set.auto_refresh_interval' | '05-set.dashboard_title' | '05-set.dashboard_uid' | '05-set.dashboard_url' | '05-set.dashboard_url_2' | '05-set.dashboard_url_with_params' | '05-set.json_model' | '05-set.json_model_refresh_value' | '05-set.json_model_tag_line' | '05-set.ref' | '05-set.save_confirmation' | '05-set.saved_default_refresh' | '05-set.settings_auto_refresh' | '05-set.settings_tags' | '05-set.settings_title'