/** Known values the steps can read back, keyed "<stepId>.<output>". */
export type Outputs = Partial<Record<OutputKey, string>>;
/** Mutable state for one invocation. Pass it to runFlow to retain telemetry after a failure. */
export interface FlowRun {
  outputs: Outputs;
  drift: string[];
  /**
   * Output keys whose read only echoed what the flow itself typed or selected:
   * published, but not proof the app persisted them (replay's echoedValues).
   */
  echoed: string[];
  /**
   * Output keys a later step may use but this run never observed: a report
   * value withheld (given, typed and uncommitted, or its recorded text not
   * shown) whose one slot a consumer still needs (the daemon's references).
   * Not findings.
   */
  referenceOnly: string[];
  /**
   * Every distinct record identifier a record-creating step minted this run, in
   * order (replay's `created`); a loop body contributes one per pass.
   */
  created: string[];
  /**
   * What this run noticed about its conditions rather than its steps: today, a browser
   * that is not the one the flow was recorded in (see RECORDED_BROWSER).
   */
  warnings: string[];
}
export interface RunOptions {
  /** Absolute URL, or a relative path resolved through the Playwright project baseURL. */
  startUrl?: string;
  run?: FlowRun;
}
/**
 * The browser this flow was recorded in. Layout-dependent locators
 * (coordinates, responsive columns, a nav that collapses to a menu) hold only there;
 * runFlow compares the page it is given and says so in run.warnings when it differs.
 */
export const RECORDED_BROWSER: BrowserProfile = {"viewport":{"width":1280,"height":900}};
/** RECORDED_BROWSER as Playwright Test options: the generated spec calls `test.use(RECORDED_USE)`. */
export const RECORDED_USE = {"viewport":{"width":1280,"height":900}};
export function createFlowRun(): FlowRun {
  return { outputs: {}, drift: [], echoed: [], referenceOnly: [], created: [], warnings: [] };
}
/**
 * The wall-clock budget one run of this flow needs under a test runner: every
 * recorded step may spend a settle window, a pick, three click tiers and a 5s
 * expectation, so a flow is budgeted per recorded step, never at the runner's
 * 60s default. fwod34 (odoo, 9 flow steps, ~80 recorded steps) ran ~63s to
 * its 06-open before that default cut a click's retry short of the force
 * tier that replay reaches. The generated `.spec.ts` applies it with
 * `test.setTimeout(BUDGET_MS)`; your own spec can do the same or override it.
 *
 * Capped, because a per-step sum is not a wall-clock anyone waits out: a
 * 159-step flow summed to 79.5 minutes, longer than the bench harness's 600s
 * kill (bench/spec-replay.mjs), so the budget could never fire first and the
 * hang was collected as a SIGKILL with no reason, no stack and no stderr.
 * The cap has to stay well under whatever kills the run from outside, so the
 * test times out as a TEST — naming the step it was in — rather than dying.
 */
export const BUDGET_MS = 300000;
/**
 * Every `[sitelooper drift] …` line this run logged (see `pick` below):
 * Compatibility view of the most recently completed run. New code should
 * use `createFlowRun()` and read `run.drift`, which is invocation-local.
 * A primary locator that missed and the recorded fallback that covered for
 * it. Always exported — even a flow with no multi-candidate step today may
 * gain one after a repair — so a caller's assertion never has to guess
 * whether it exists. Attach it from the user spec if you want it in the
 * Playwright report: `test.info().attach('sitelooper-drift', { body: run.drift.join('\n') })`.
 */
export const DRIFT: string[] = [];

// Shared execution source: text.ts. Regenerate to update.
/**
 * Text rules both execution targets share: the volatile-token mask, the
 * bounded identity matcher, and the regex escape they are built on. The
 * daemon imports this module; a compiled `.flow.ts` artifact embeds its exact
 * source (spec/runtime-source.ts), so it must stay self-contained — no imports
 * beyond a sibling shared module or a Playwright type.
 */

/** `text` cut to `max` characters with an ellipsis, or unchanged when it fits. */
function clip(text: string, max: number): string {
  return text.length <= max ? text : text.slice(0, max) + '…';
}

/**
 * Whether an element's RENDERED text (`innerText`) satisfies a recorded text
 * wait — `text_equals` or `text_contains` — with whitespace runs collapsed and
 * trimmed on both sides, as Playwright's toHaveText / toContainText compare.
 * One definition for every tier: the daemon's wait_for, the held-elsewhere
 * rung (recover.ts textHeldElsewhere) and the artifact's assertions, which
 * are emitted with `useInnerText: true`. openproject fwop10: the daemon
 * compared innerText ("OVERVIEW", CSS text-transform: uppercase) and the
 * artifact textContent ("Overview"), so the compiled run failed a wait
 * replay passed.
 */
function textHolds(shown: string, state: unknown, want: string): boolean {
  const norm = (s: string) => s.replace(/\s+/g, ' ').trim();
  return state === 'text_equals' ? norm(shown) === norm(want) : norm(shown).includes(norm(want));
}

/**
 * Clock, calendar and relative-time tokens are the RECORDING's moment, not part of what a
 * page element IS: kanboard names its due-date textbox after the current
 * minute ("09/03/2026 07:22") and labels a summary row "Due date:
 * 12/31/2026 07:40". Recorded verbatim, such a name matches nothing nine
 * minutes later. maskVolatile() turns each token into the `{{*}}` wildcard
 * for stored expectations; volatileMatcher() turns a recorded locator name
 * into a RegExp that treats the same tokens as wildcards.
 */
const WILDCARD = '{{*}}';

/**
 * The volatile tokens, as regex SOURCE: a clock time, a numeric date, and a
 * relative time — anything whose value is how much wall-clock time has passed
 * since the recording, however it is spelled. ghost lists a seed post as
 * "… Bench Guides - 1 minute ago"; fwgh3's 01-signin stored that phrase in an
 * expectation, the post had aged by the replays, and n2, n3 and the compiled
 * spec all stopped on "the recorded page change did not appear".
 *
 * Only a leading capital is tolerated ("Just now", "A minute ago"), not a
 * case-insensitive flag: the same source builds the MATCHER
 * (VOLATILE_TOKEN_SHAPE, spliced into patterns whose flags it does not
 * choose), and a mask wider than its matcher turns a recorded name into one
 * nothing matches. The count may be a slot marker: compile substitutes before
 * it masks, and a run value "5" must not freeze "5 minutes ago" into
 * `{{v2}} minutes ago`. `today` is left out: it is a date picker's button as
 * often as it is a time.
 */
const CLOCK = String.raw`\d{1,2}:\d{2}(?::\d{2})?`;
const NUMERIC_DATE = String.raw`\d{1,4}[/.-]\d{1,2}[/.-]\d{1,4}`;
const TIME_COUNT = String.raw`(?:\d+|\{\{[vd]\d+\}\}|[Aa] few|[Aa]n?|[Oo]ne|[Ff]ew)`;
const TIME_UNIT = String.raw`(?:[Ss]ec(?:ond)?|[Mm]in(?:ute)?|[Hh](?:ou)?r|[Dd]ay|[Ww]eek|[Mm]onth|[Yy]ear)s?`;
const RELATIVE_TIME = String.raw`(?:${TIME_COUNT}\s+${TIME_UNIT}\s+ago|\d+\s?(?:mo|[smhdwy])\s+ago|[Ii]n\s+${TIME_COUNT}\s+${TIME_UNIT}|[Jj]ust now|[Yy]esterday|[Tt]omorrow)`;
const VOLATILE_SOURCE = `(?:${CLOCK}|${NUMERIC_DATE}|${RELATIVE_TIME})`;
const VOLATILE_TOKEN = new RegExp(String.raw`(?<!\w)${VOLATILE_SOURCE}(?!\w)`, 'g');

function maskVolatile(line: string): string {
  return line.replace(VOLATILE_TOKEN, WILDCARD);
}

/**
 * Counters at the head of a control's name: odoo's user menu is
 * `- menu "6 3 YourCompany"` — the activity and message counts, then the
 * company. The counts are how much has happened since the recording, not the
 * control; the artifact insisted on "6 3" and failed a sign-in the daemon
 * had replayed clean (fwod88-cv3). Only a leading run of short integers that
 * a word follows, on a named control, is masked — `- cell "3"` and a bare
 * number stay what they are. Applied to expectation lines beside maskVolatile
 * (expect.ts), in both runners.
 */
const LEADING_COUNTERS = /^(- (?:menu|menuitem|button|link|tab|treeitem) ")(\d{1,3}(?: \d{1,3})*) (?=[\p{L}])/u;

function maskCounters(line: string): string {
  return line.replace(LEADING_COUNTERS, `$1${WILDCARD} `);
}

/** A value interpolated into a pattern is DATA: its own metacharacters must not become pattern. */
function escapeRe(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/**
 * The recorded string itself when it carries no volatile token, else an
 * anchored RegExp in which each token matches any token of the same shape —
 * another time, another date — and nothing else, so the rest of the name is
 * still matched exactly.
 */
/**
 * What one masked token stood for, as regex SOURCE. Exported because a
 * compiled spec has to rebuild the same matcher from a line the store already
 * masked (see spec/locators.ts, maskedMatcherSource) and a second copy of this
 * shape would be free to drift away from this one.
 */
const VOLATILE_TOKEN_SHAPE = VOLATILE_SOURCE;

/**
 * What may NOT sit against an identity marker: a letter or a digit.
 *
 * An identity marker is the only thing in the system that can tell ticket t15
 * from ticket t14 — a url pattern and a page fingerprint match every record of
 * a template, so when the url gate proceeds optimistically on a disagreeing
 * segment, this is the gate the decision falls to. Matched by plain substring
 * it does not decide anything: `fwgr25-n1` is satisfied by a page showing
 * `fwgr25-n10`, `RD-1015` by `RD-10150`, and a bare runid is the commonest
 * marker shape there is.
 *
 * So a marker matches only where neither edge is glued to another letter or
 * digit. BOTH lookarounds, unconditionally — not "when the marker looks like
 * an identifier". The shape is not a property of the MARKER but of what the
 * page may put beside it: `fwod28-n1 Bench Customer` is prose-shaped and
 * `…Bench Customers` is a different record. Punctuation is not a letter or a
 * digit, so `(INV-2024/17)` still matches while `INV-2024/170` does not, and
 * `\p{L}` (with `u`) keeps `Ångström` and `田中` right.
 *
 * Exported as SOURCE because a compiled spec must rebuild the same rule inside
 * the emitted artifact, and a second copy of the class would be free to drift
 * away from this one — the same reason VOLATILE_TOKEN_SHAPE is exported.
 */
const IDENTITY_EDGE = '[\\p{L}\\p{N}]';

/**
 * `marker` as regex SOURCE for the bounded identity rule: whitespace-normalised,
 * every literal run of spaces matching any whitespace (the daemon's snapshot and
 * a DOM's textContent space things differently), `{{*}}` matching anything
 * within one line, and both edges guarded by IDENTITY_EDGE.
 */
function identitySource(marker: string): string {
  const body = marker
    .replace(/\s+/g, ' ')
    .trim()
    .split(WILDCARD)
    .map((part) => escapeRe(part).replace(/ /g, '\\s+'))
    .join('[^\\n]*?');
  return `(?<!${IDENTITY_EDGE})${body}(?!${IDENTITY_EDGE})`;
}

/**
 * identitySource as a RegExp. Case-INSENSITIVE: the daemon was case-sensitive
 * here and the emitted artifact was not, and a case-insensitive BOUNDED match
 * is strictly tighter than the case-sensitive SUBSTRING it replaces — so
 * unifying on `i` is not a loosening, and it settles a real parity gap (a
 * rendered value is not always cased as it was typed).
 */
function identityRe(marker: string): RegExp {
  return new RegExp(identitySource(marker), 'iu');
}
function volatileMatcher(text: string): string | RegExp {
  const masked = maskVolatile(text);
  if (masked === text) return text;
  return new RegExp(`^${masked.split(WILDCARD).map(escapeRe).join(VOLATILE_TOKEN_SHAPE)}$`);
}

/**
 * A scoped candidate's `hasText`, as both runners pass it to
 * `locator(container, { hasText })`: the recorded text itself when it carries
 * no volatile token — Playwright's own substring match, case- and
 * whitespace-insensitive, unchanged — else a RegExp keeping those three
 * properties (unanchored, `i`, any whitespace run) with each volatile token
 * wildcarded as volatileMatcher does. fwgh4's s_17f69b scoped every read to
 * `li.gh-list-row` with hasText "{{v2}} By Bench Admin - a few seconds ago
 * Draft", which only held because the replay came seconds after the
 * recording. Called on the text with its slots already filled, in both
 * runners, so they cannot disagree about what a slot value contributes.
 */
function hasTextMatcher(text: string): string | RegExp {
  const masked = maskVolatile(text);
  if (masked === text) return text;
  const body = masked
    .replace(/\s+/g, ' ')
    .trim()
    .split(WILDCARD)
    .map((part) => escapeRe(part).replace(/ /g, '\\s+'))
    .join(VOLATILE_TOKEN_SHAPE);
  return new RegExp(body, 'i');
}

/**
 * What an ACCESSIBLE NAME may carry that a recorded name never does.
 *
 * A recorded role name comes from this project's own DOM walk (execution/
 * snapshot.ts), which names an element by its text and collapses whitespace.
 * The browser's accessible name, which a role query compares against, is
 * computed from the rendered tree — including CSS-generated content. Kanboard's
 * column header is `<a>Ready <i class="fa fa-caret-down"></i></a>`: the walk
 * says `link "Ready"`, Chromium says "Ready " (the icon font's glyph,
 * a private-use code point), and `exact: true` on 'Ready' finds nothing. Every
 * synthesized column read of fwkb24 missed that way, on both replays, on the
 * very page the recording had seen them on.
 *
 * So the edges of a name may carry whitespace, private-use glyphs (icon
 * fonts), other symbols (a check mark, an emoji — \p{So}; not a math or
 * currency sign, which can be the name's own) and format characters, and every
 * run of whitespace inside it matches any run. Nothing else: a letter, a digit
 * or punctuation beside the name is a different name ("Ready?" is not
 * "Ready"), and two elements the tolerance makes indistinguishable are
 * refused by the resolver's own uniqueness rule, never picked. Exported as
 * SOURCE for the same reason VOLATILE_TOKEN_SHAPE is: the artifact rebuilds
 * the matcher from it.
 */
const NAME_NOISE_SHAPE = '[\\s\\p{Co}\\p{So}\\p{Cf}]*';

/**
 * The matcher for a recorded ROLE name: volatileMatcher's wildcards for clock
 * and calendar tokens, with the accessible-name tolerance above at both edges
 * and across whitespace. Always a RegExp, so `exact: true` is moot — the
 * anchors carry the whole-string rule and the case stays as recorded.
 * One function for both runners: makeLocator (daemon/recorder.ts) calls it
 * and the compiled artifact calls the embedded copy (spec/locators.ts).
 */
function roleName(text: string): RegExp {
  const masked = maskVolatile(text.replace(/\s+/g, ' ').trim());
  const body = masked
    .split(WILDCARD)
    .map((part) => escapeRe(part).replace(/ /g, '\\s+'))
    .join(VOLATILE_TOKEN_SHAPE);
  return new RegExp(`^${NAME_NOISE_SHAPE}${body}${NAME_NOISE_SHAPE}$`, 'u');
}

/** Roles a <label> names. */
const LABELLED_ROLES = new Set(['textbox', 'searchbox', 'spinbutton', 'combobox', 'listbox', 'checkbox', 'radio', 'switch', 'slider']);

/**
 * A selector naming a labelled field as `role=textbox[name="Part name *"]`,
 * optionally as the last link of a scoped chain (`dialog >> role=…`): the
 * scope, role and name, or null for any other selector.
 *
 * WHY IT IS SHARED. A label's text is not always the field's accessible name:
 * "Part name <span aria-hidden>*</span>" reads `Part name *` in our snapshot
 * and `Part name` to Playwright's role engine, so this selector matches
 * nothing as written. The daemon's live target resolution (daemon/refs.ts)
 * already accepted the field by its label's exact text; a STORED candidate of
 * this shape did not, in either runner. fwrd79's 03-open stored exactly this
 * as its fill's only candidate, and the compiled spec failed there with
 * "none of 1 recorded locators resolved". One parse, used by live resolution,
 * makeLocator and the emitted artifact alike.
 */
function fieldByName(selector: string): { scope: string | null; role: string; name: string } | null {
  const cut = selector.lastIndexOf(' >> ');
  const last = (cut < 0 ? selector : selector.slice(cut + 4)).trim();
  const m = /^role=([a-z]+)\[name="((?:[^"\\]|\\.)*)"\]$/.exec(last);
  if (!m || !LABELLED_ROLES.has(m[1])) return null;
  return { scope: cut < 0 ? null : selector.slice(0, cut), role: m[1], name: m[2].replace(/\\(.)/g, '$1') };
}

/**
 * WHERE A READ'S VALUE SAT ON ITS LINE.
 *
 * A read-back the model pinned to a wrapper is accepted by CONTAINMENT
 * (recorder.ts captureReadBackAt): the element's line carries the value and a
 * label or sibling beside it. The read then published the element's whole
 * text on every replay — fwvk3's runid "fwvk3-n1" was pinned to the <h1>
 * "fwvk3-n1 Bench Task", and n2 published "fwvk3-n2 Bench Task"; fwgh5
 * s_5ee393's `ref` published "fwgh5-n2 Bench Post" — and the summary rewrite
 * that swaps each recorded value for the replayed one garbled the report.
 *
 * So a contained read records its FRAME: the value's line with the value cut
 * out and FRAME_MARK in its place ("{{=}} Bench Task"), and both runners
 * publish only the text at the mark (extractFramed). Not a `{{vN}}` slot:
 * compile fills the run's slots into the frame's literal text like any other
 * arg, and the mark must survive that.
 */
const FRAME_MARK = '{{=}}';

/** One rendered line as a frame compares it: whitespace runs collapsed, trimmed. */
function frameLine(line: string): string {
  return line.replace(/\s+/g, ' ').trim();
}

/**
 * `text`'s frame for `value` — see FRAME_MARK — or null when no line of
 * `text` carries the value. The line is the SHORTEST carrying it (the value's
 * own line, the one captureReadBackAt's own-line rule accepted); within it,
 * an occurrence bounded by IDENTITY_EDGE is preferred to a bare substring.
 * A line that IS the value names no position by itself inside a multi-line
 * element, so the neighbouring line (the one before, else the one after) is
 * kept with it: "Folder\n{{=}}".
 */
function frameValue(text: string, value: string): string | null {
  const v = frameLine(value);
  if (!v) return null;
  const lines = text.split(/\r?\n/).map(frameLine).filter(Boolean);
  const body = escapeRe(v).replace(/ /g, '\\s+');
  const bounded = new RegExp(`(?<!${IDENTITY_EDGE})${body}(?!${IDENTITY_EDGE})`, 'iu');
  const loose = new RegExp(body, 'iu');
  let at = -1;
  for (let i = 0; i < lines.length; i++) {
    if (loose.test(lines[i]) && (at < 0 || lines[i].length < lines[at].length)) at = i;
  }
  if (at < 0) return null;
  const line = lines[at];
  const hit = bounded.exec(line) ?? loose.exec(line)!;
  const framed = line.slice(0, hit.index) + FRAME_MARK + line.slice(hit.index + hit[0].length);
  if (framed !== FRAME_MARK || lines.length < 2) return framed;
  return at > 0 ? `${lines[at - 1]}\n${framed}` : `${framed}\n${lines[at + 1]}`;
}

/**
 * `frame` — a mark-less frame, its slots already filled with this run's
 * values — with FRAME_MARK put where `value` sits in it, or null when the
 * value is not there exactly once (bounded by IDENTITY_EDGE, whitespace runs
 * matching any whitespace). The run-time half of a slot-scoped frame
 * (skills/readscope.ts): repairdesk fwrd87 s_9e190d pinned the runid to Part
 * A's name cell as "{{=}} RD Part A", and replaying for Part B the element no
 * longer showed that line; the frame stored as `{{v4}}`, marked at `{{v3}}`,
 * is this run's line.
 */
function markFrame(frame: string, value: string): string | null {
  const v = frameLine(value);
  if (!v || frame.includes(FRAME_MARK)) return null;
  const re = new RegExp(`(?<!${IDENTITY_EDGE})${escapeRe(v).replace(/ /g, '\\s+')}(?!${IDENTITY_EDGE})`, 'giu');
  const hits = [...frame.matchAll(re)];
  if (hits.length !== 1 || hits[0].index === undefined) return null;
  return frame.slice(0, hits[0].index) + FRAME_MARK + frame.slice(hits[0].index + hits[0][0].length);
}

/** Any `{{…}}` in a frame but the mark: a masked volatile token, or a slot the run left unfilled ("asks for no particular value"). */
const FRAME_HOLE = /\{\{[^{}]*\}\}/;

/** One frame line as an anchored RegExp: the mark captures, each hole matches anything within the line. */
function frameLineRe(line: string): RegExp {
  const lit = (part: string) =>
    part
      .split(FRAME_HOLE)
      .map((p) => escapeRe(p).replace(/ /g, '\\s+'))
      .join('.*?');
  const body = maskVolatile(line).split(FRAME_MARK).map(lit).join('(.+?)');
  return new RegExp(`^${body}$`, 'iu');
}

/**
 * The text at `frame`'s mark in `text` (an element's rendered text), or null
 * when the element no longer shows the frame. Compared the way foldValue
 * compares a displayed value — whitespace collapsed, case folded — with
 * clock, date and relative-time tokens wildcarded (maskVolatile), line by
 * line: the frame's lines must match consecutive lines of `text`, whole.
 * Every window that matches must capture the same text; two different
 * captures are two candidates, and a read that has to guess publishes
 * nothing. Null is a failed read, never a wrong value.
 */
function extractFramed(text: string, frame: string): string | null {
  const want = frame.split(/\r?\n/).map(frameLine).filter(Boolean);
  if (want.filter((l) => l.includes(FRAME_MARK)).length !== 1) return null;
  const res = want.map(frameLineRe);
  const lines = text.split(/\r?\n/).map(frameLine).filter(Boolean);
  let got: string | null = null;
  for (let i = 0; i + want.length <= lines.length; i++) {
    let captured: string | null = null;
    let ok = true;
    for (let j = 0; j < want.length && ok; j++) {
      const m = res[j].exec(lines[i + j]);
      if (!m) ok = false;
      else if (m[1] !== undefined) captured = m[1].trim();
    }
    if (!ok || !captured) continue;
    if (got !== null && got !== captured) return null;
    got = captured;
  }
  return got;
}

/**
 * `frame` with each whole-token occurrence of a value THIS RUN produced in its
 * literal text replaced by the wildcard, the mark left alone. A frame's
 * residue is the line around the value as the recording saw it, and whatever
 * in it the run made is a different value on the next run: fwgt4 s_4580f2
 * pinned the runid to gitea's heading as "{{=}} Bench Issue #4", and every
 * replay's "#5" missed the frame, so the read was skipped each time. Whole
 * tokens only (IDENTITY_EDGE), so a record id "4" frees the "4" of "#4" and
 * not the one in "x4". extractFramed reads every `{{…}}` as a wildcard.
 */
function unfreezeFrame(frame: string, runValues: readonly string[]): string {
  const values = [...new Set(runValues.map((v) => v.trim()).filter(Boolean))].sort((a, b) => b.length - a.length);
  if (!values.length) return frame;
  const re = new RegExp(`(?<!${IDENTITY_EDGE})(?:${values.map(escapeRe).join('|')})(?!${IDENTITY_EDGE})`, 'gu');
  return frame
    .split(FRAME_MARK)
    .map((part) => part.replace(re, WILDCARD))
    .join(FRAME_MARK);
}

/**
 * `[role=dialog]` as a whole chain segment means "the dialog", and the agent
 * writes it because the snapshot and the diff both SAY `dialog`. But as CSS it
 * matches only an explicit role attribute: a native <dialog>, <nav> or <main>
 * has the role and no attribute, so the scope matched nothing. fxon1-n1 lost
 * five batches (3s each, plus the snapshot turn after) to `[role=dialog] >> …`
 * on an app that uses <dialog>. The role engine matches both kinds, and is a
 * strict superset, so the segment is handed to it instead.
 *
 * Shared (fwrd82): the live action resolved `[role=dialog] >> role=textbox[…]`
 * through this rewrite, but the recorder probed the raw text, matched nothing,
 * and stored the unrewritten selector as the step's only candidate; the daemon
 * healed it by testid on every replay and the compiled artifact could not.
 * So describeTarget probes as resolveTarget does, and makeLocator and the
 * artifact's candidateSource rewrite a stored selector the same way.
 */
function implicitRoles(selector: string): string {
  return selector
    .split(' >> ')
    .map((segment) => segment.trim().replace(/^\[role=["']?([a-z]+)["']?\]$/, 'role=$1'))
    .join(' >> ');
}

// Shared execution source: url.ts. Regenerate to update.
/**
 * Url rules both execution targets share: how a url is reduced to the shape
 * that identifies its page, how a stored pattern is judged against a live url,
 * and how the addressable parts of a url are labelled for derived values.
 *
 * The daemon imports this module (through skills/compile.ts) and a compiled
 * `.flow.ts` artifact embeds its exact source (spec/runtime-source.ts), so it
 * must stay self-contained: nothing but a sibling shared module or a
 * Playwright type may be imported. `urlPattern`, which needs the slot
 * substitution and id-shape heuristics of compile.ts, deliberately stays there.
 */

/** Inverse of substitute(): fill "{{vN}}" (caller param) and "{{dN}}" (derived,
 * bound from the live run's own urls) markers from a param map. */
function fillParams(text: string, params: Record<string, string>): string {
  return text.replace(/\{\{([vd]\d+)\}\}/g, (m, name: string) => (name in params ? params[name] : m));
}

function fillParamsDeep(value: unknown, params: Record<string, string>): unknown {
  if (typeof value === 'string') return fillParams(value, params);
  if (Array.isArray(value)) return value.map((v) => fillParamsDeep(v, params));
  if (value && typeof value === 'object') {
    return Object.fromEntries(Object.entries(value as Record<string, unknown>).map(([k, v]) => [k, fillParamsDeep(v, params)]));
  }
  return value;
}

/**
 * The origin a url (or a stored url pattern) is "home" to: `http(s)://host`,
 * the opaque `file://` for a local page, null for anything else or for text
 * that is not a url. Both runners derive a step's `stayOnOrigin` from this —
 * the recorded url pattern first, the live page otherwise — so it lives here
 * rather than in the skill store, which re-exports it.
 */
function originOf(url: string): string | null {
  try {
    const u = new URL(url);
    if (!/^https?:$/.test(u.protocol)) return u.protocol === 'file:' ? 'file://' : null;
    return u.origin;
  } catch {
    return null;
  }
}

/**
 * A url decomposed for structural matching: origin, path segments, query
 * pairs, and the hash fragment as either route segments or state pairs.
 * Parses stored patterns (which may carry `:id` / `:var` / `{{…}}` markers)
 * and live urls alike.
 *
 * The query string used to be dropped, so `edit?id=123` and `edit?id=999`
 * were one page and kanboard's every `?controller=…&action=…` route read as
 * `/` (notes/ROBUSTNESS.md, finding 3). It is kept now, less the keys `noiseQueryKey`
 * names: tracking tags and cache busters say nothing about which page it is.
 */
interface UrlShape {
  origin: string;
  path: string[];
  query: Map<string, string>;
  hashKind: 'none' | 'path' | 'state';
  hashPath: string[];
  hashState: Map<string, string>;
  /** Whether a path-shaped fragment began with '/', for round-tripping. */
  hashSlash: boolean;
  /**
   * The fragment is an in-page ANCHOR, not a route: one bare word, with no
   * '/' anywhere and no '=' (`#history`, a tab). Still kept as a one-segment
   * hash path, so a pattern that names it matches it; see urlDiff.
   */
  hashAnchor?: boolean;
}

/** A query key that never identifies a page: campaign tags, click ids, a cache buster. */
function noiseQueryKey(key: string): boolean {
  return /^utm_/i.test(key) || /^(fbclid|gclid|msclkid|_|_t|cb)$/i.test(key);
}

/**
 * A url key whose value is a credential: OAuth tokens, codes, sessions,
 * signatures. Its value is masked wherever a url is shown, and a recorded
 * pattern stores it as a wildcard, never the value.
 */
const CREDENTIAL_KEY = /token|secret|passw|session|auth|code|sig|key|credential|nonce|jwt/i;

/** The query string's pairs, decoded, noise keys dropped; a repeated key keeps every value, comma-joined. */
function queryPairs(search: string): Map<string, string> {
  const out = new Map<string, string>();
  const body = search.startsWith('?') ? search.slice(1) : search;
  for (const pair of body.split('&').filter(Boolean)) {
    const eq = pair.indexOf('=');
    const key = safeDecode(eq < 0 ? pair : pair.slice(0, eq));
    if (!key || noiseQueryKey(key)) continue;
    const value = eq < 0 ? '' : safeDecode(pair.slice(eq + 1).replace(/\+/g, ' '));
    out.set(key, out.has(key) ? `${out.get(key)},${value}` : value);
  }
  return out;
}

function safeDecode(s: string): string {
  try {
    return decodeURIComponent(s);
  } catch {
    return s;
  }
}

function urlShapeOf(s: string): UrlShape | null {
  let u: URL;
  try {
    u = new URL(s);
  } catch {
    return null;
  }
  const origin = u.protocol === 'file:' ? 'file://' : u.origin;
  const shape: UrlShape = {
    origin,
    path: u.pathname.split('/').filter(Boolean).map(safeDecode),
    query: queryPairs(u.search),
    hashKind: 'none',
    hashPath: [],
    hashState: new Map(),
    hashSlash: false,
  };
  const body = u.hash && u.hash.length > 1 ? u.hash.slice(1).split('?')[0] : '';
  if (!body) return shape;
  if (body.startsWith('/') || !body.includes('=')) {
    shape.hashKind = 'path';
    shape.hashSlash = body.startsWith('/');
    shape.hashPath = body.split('/').filter(Boolean).map(safeDecode);
    if (!body.includes('/')) shape.hashAnchor = true;
    return shape;
  }
  shape.hashKind = 'state';
  for (const pair of body.split('&').filter(Boolean)) {
    const eq = pair.indexOf('=');
    if (eq < 0) shape.hashState.set(pair, '');
    else shape.hashState.set(pair.slice(0, eq), safeDecode(pair.slice(eq + 1)));
  }
  return shape;
}

function serializeShape(s: UrlShape): string {
  let hash = '';
  if (s.hashKind === 'path') hash = '#' + (s.hashSlash ? '/' : '') + s.hashPath.join('/');
  else if (s.hashKind === 'state') {
    hash = '#' + [...s.hashState].map(([k, v]) => `${k}=${v}`).sort().join('&');
  }
  const query = s.query.size ? '?' + [...s.query].map(([k, v]) => `${k}=${v}`).sort().join('&') : '';
  return `${s.origin}/${s.path.join('/')}${query}${hash}`;
}

/** A pattern segment that stands for "any value here". */
function isWildcardSeg(seg: string): boolean {
  return seg === ':id' || seg === ':var' || /\{\{[\w.-]+\}\}/.test(seg);
}

/**
 * A slot the run could not fill asks for no particular value. `fillParams`
 * substitutes on `name in params`, so a slot whose value is '' becomes an
 * empty literal, and an empty literal matches only emptiness. But '' is how
 * an unpublished reference reaches a call site — the artifact defaults one to
 * the empty string — so it means NEVER PUBLISHED, not "known to be empty".
 * Everything else that reads a bound slot already says so: boundQueryKeys,
 * markersBound, urlRecordParts, gotoLandingVerdict's `want !== ''`, and the
 * artifact's own `need`, whose message for '' is "this run never published it".
 *
 * fwgr45: a step reported the word "browser", the flow threaded it into
 * `timezone={{v5}}`, no read published it, so v5 filled to '' and the compiled
 * arm stopped on the RIGHT dashboard — `timezone=` against `timezone=browser`
 * — while both replays ran 7/7 at 0 turns.
 */
function unfilled(seg: string): boolean {
  return seg === '';
}

/** One segment where a pattern's literal disagrees with the live url. */
interface UrlSegDiff {
  where: 'path' | 'query' | 'hashPath' | 'hashState';
  index?: number;
  key?: string;
  expected: string;
  actual: string;
}

/**
 * Structural comparison of a stored pattern against a live url: `null` when
 * the two are not even the same page shape (different origin, path length,
 * route, or a required state key missing), otherwise the list of segments
 * where a literal in the pattern disagrees with the live value — empty list
 * means a match. Wildcard segments (`:id`, `:var`, unfilled `{{…}}`) match
 * anything: matching consults the pattern's own markers, never a shape
 * heuristic on the live value (that is what made the url shape test load-bearing).
 *
 * A query-shaped fragment is application STATE, and state accumulates (Odoo
 * lands on "#cids=1" and has grown "#action=…&menu_id=…" by the next
 * segment) — so it is a necessary condition: every pair the pattern names
 * must be present, extra live pairs are allowed, and a pattern with no hash
 * requires nothing of a live state fragment. A path-shaped fragment is a
 * route and must match segment for segment.
 *
 * The query is judged on the keys BOTH urls carry: a value that disagrees
 * there is a segment that disagrees (`?status=success` against
 * `?status=failure`). A key only one side has is not evidence of a different
 * page — grafana adds and drops `refresh=1m` on the same dashboard, and a
 * recording can catch its url before or after the app rewrites it — with one
 * exception: a key in `boundKeys`, which the pattern fills from a caller or
 * derived value (`edit?id={{v1}}`), names the record, and a live url without
 * it is not that record. `urlMatches` and `softUrlMatch` pass those keys,
 * read off the pattern before its markers are filled.
 */
function urlDiff(pattern: string, url: string, boundKeys: ReadonlySet<string> = new Set()): UrlSegDiff[] | null {
  const p = urlShapeOf(pattern);
  const l = urlShapeOf(url);
  if (!p || !l) return pattern === url ? [] : null;
  if (p.origin !== l.origin || p.path.length !== l.path.length) return null;
  const diffs: UrlSegDiff[] = [];
  p.path.forEach((seg, i) => {
    if (!isWildcardSeg(seg) && seg !== l.path[i]) diffs.push({ where: 'path', index: i, expected: seg, actual: l.path[i] });
  });
  for (const [key, val] of p.query) {
    if (!l.query.has(key)) {
      if (boundKeys.has(key)) return null;
      continue;
    }
    const lv = l.query.get(key)!;
    if (!isWildcardSeg(val) && !unfilled(val) && val !== lv) diffs.push({ where: 'query', key, expected: val, actual: lv });
  }
  if (p.hashKind === 'path') {
    if (l.hashKind !== 'path' || p.hashPath.length !== l.hashPath.length) return null;
    p.hashPath.forEach((seg, i) => {
      if (!isWildcardSeg(seg) && seg !== l.hashPath[i]) diffs.push({ where: 'hashPath', index: i, expected: seg, actual: l.hashPath[i] });
    });
  } else if (p.hashKind === 'state') {
    if (l.hashKind !== 'state') return null;
    for (const [key, val] of p.hashState) {
      // A key the pattern only knows as a wildcard (`:id`, a {{dN}} it never
      // learned a value for) is app-minted state, not identity: odoo adds
      // `cids=1` to a url on one run and not the next, and fwod32's sign-in
      // stopped on every replay because the live url lacked it. A missing
      // key with a LITERAL value is still a different page.
      if (!l.hashState.has(key)) {
        if (isWildcardSeg(val)) continue;
        return null;
      }
      const lv = l.hashState.get(key)!;
      if (!isWildcardSeg(val) && !unfilled(val) && val !== lv) diffs.push({ where: 'hashState', key, expected: val, actual: lv });
    }
  } else if (l.hashKind === 'path' && l.hashPath.length && !l.hashAnchor) {
    // Pattern names no route; the live url is on one. An in-page anchor is
    // not a route: snipeit fwsi2-n2's 04-create recovery ended on
    // `/hardware/5#history` (the History tab), and the next step's start gate
    // refused it against `/hardware/:id`. EspoCRM's `#Opportunity/view/<id>`
    // and `#/…` routes carry a '/', odoo's state carries '=': both still count.
    return null;
  }
  return diffs;
}

/**
 * The query keys only one side of a match carries, which urlDiff lets pass
 * (see its note): a literal-valued key the pattern names and the live url
 * lacks, and a key the live url has that the pattern does not name. Wildcard
 * pattern keys are app-minted state and not listed. These are the keys a
 * strict match took on trust — `editview=json-model` is one of them, and it is
 * a different VIEW of the dashboard, not the same page (fwgr36 04-open).
 */
function oneSidedQueryKeys(pattern: string, url: string): string[] {
  const p = urlShapeOf(pattern);
  const l = urlShapeOf(url);
  if (!p || !l) return [];
  const out: string[] = [];
  for (const [key, val] of p.query) if (!l.query.has(key) && !isWildcardSeg(val)) out.push(key);
  for (const key of l.query.keys()) if (!p.query.has(key)) out.push(key);
  return out;
}

/** Whether a live url matches a stored pattern exactly (wildcards aside). */
function urlMatches(pattern: string, url: string, params: Record<string, string> = {}): boolean {
  return urlDiff(fillParams(pattern, params), url, boundQueryKeys(pattern, params))?.length === 0;
}

/** The query keys a pattern fills from a marker `params` binds — see urlDiff. */
function boundQueryKeys(pattern: string, params: Record<string, string>): Set<string> {
  const shape = urlShapeOf(pattern);
  // Typed on the binding, not the constructor: execution-echo.test.ts tells a
  // ledger-free artifact by the constructor spelling a ledger uses.
  const out: Set<string> = new Set();
  if (!shape) return out;
  for (const [key, val] of shape.query) {
    if ([...val.matchAll(/\{\{([vd]\d+)\}\}/g)].some((m) => params[m[1]])) out.add(key);
  }
  return out;
}

/**
 * The default soft-match budget: how many disagreeing positions a caller who
 * has nothing but the url will soften. It is a PROXY for "is this a different
 * page?" — many disagreements used to stand in for that question — and it is
 * the weakest thing in this module, so it is a default and not a law.
 *
 * What actually makes a softening safe is enforced PER DIFF in softUrlMatch,
 * not by this count: no WORD position (`/orders/success` against
 * `/orders/failure`), no position the pattern fills from a parameter. Those
 * hold at any budget.
 *
 * fwgr49: three positions disagreed on one grafana dashboard — the uid and the
 * two halves of a `from`/`to` range — and the count alone refused the segment,
 * while the SAME round's sibling skill carried the uid in a derived slot,
 * left two diffs, soft-matched and ran. Two vary and it works, three and it
 * collapses: the discriminator was the count, on a page measuring 0.994
 * similar to the recording. A caller that can ask the real question instead
 * passes its own budget (see preconditionVerdict).
 */
const MAX_SOFT_DIFFS = 2;

/**
 * Whether a url value has the shape of something an environment MINTS: one
 * unbroken token carrying a digit (`rec-1`, `afw6yy5xx9`, `133`), or with no
 * '-'/'_' at least twelve characters or eight hex letters. A word or a slug of
 * words (`edit`, `success`, `order-history`) is a route an application chose,
 * and a different one is a different page. The generous arm of
 * skills/shape.ts's `generatedToken`, restated because this module may import
 * nothing.
 */
function mintedShape(value: string): boolean {
  if (!value || /\s/.test(value)) return false;
  if (/\d/.test(value)) return true;
  if (/[_-]/.test(value)) return false;
  return value.length >= 12 || /^[0-9a-f]{8,}$/i.test(value);
}

/**
 * Mechanism-2 tolerance (PLAN-replay-v2): the live url is the same page
 * SHAPE as the pattern but a few literal segments disagree — the signature of
 * an environment-minted identifier (a Grafana uid, an Odoo action id) that
 * this run minted differently. Returns the pattern with exactly the
 * disagreeing segments generalised to `:var`, for the caller to proceed
 * optimistically and PERSIST only once the run past this point succeeds —
 * the segment has then demonstrated volatility. Null when the urls differ in
 * shape, everything matched already, or a slot value broke segmentation.
 *
 * A disagreement alone is not evidence of volatility, so two kinds are never
 * soft (notes/ROBUSTNESS.md, finding 3):
 *  - a segment where either side is a WORD rather than a minted shape:
 *    `/orders/success` against `/orders/failure`, `/items/7/edit` against
 *    `/items/7/view`, are different pages, and generalising them to `:var`
 *    would have let the url gate — and every later run — accept either;
 *  - a segment the pattern fills from a PARAMETER (`{{v1}}`, a bound
 *    `{{d1}}`): the caller named that record, and a different value there is
 *    a different record, not a volatile one.
 *
 * `maxDiffs` is how many disagreeing positions this caller will soften,
 * defaulting to MAX_SOFT_DIFFS — see there for why it is a proxy and what a
 * caller has to hold to raise it. The two guards above are per diff and do not
 * move with it.
 */
function softUrlMatch(
  pattern: string,
  url: string,
  params: Record<string, string> = {},
  maxDiffs: number = MAX_SOFT_DIFFS,
): { generalised: string; diffs: UrlSegDiff[] } | null {
  const filled = fillParams(pattern, params);
  const diffs = urlDiff(filled, url, boundQueryKeys(pattern, params));
  if (!diffs || !diffs.length || diffs.length > maxDiffs) return null;
  // Generalise in the ORIGINAL pattern (markers intact). A param value
  // containing '/' would shift segment positions between the two — bail.
  const orig = urlShapeOf(pattern);
  const fld = urlShapeOf(filled);
  if (!orig || !fld || orig.path.length !== fld.path.length || orig.hashPath.length !== fld.hashPath.length) return null;
  for (const d of diffs) {
    if (!mintedShape(d.expected) || !mintedShape(d.actual)) return null;
    const recorded =
      d.where === 'path' ? orig.path[d.index!] : d.where === 'hashPath' ? orig.hashPath[d.index!] : d.where === 'query' ? orig.query.get(d.key!) : orig.hashState.get(d.key!);
    if (recorded === undefined || recorded.includes('{{')) return null;
  }
  for (const d of diffs) {
    if (d.where === 'path') orig.path[d.index!] = ':var';
    else if (d.where === 'query') orig.query.set(d.key!, ':var');
    else if (d.where === 'hashPath') orig.hashPath[d.index!] = ':var';
    else orig.hashState.set(d.key!, ':var');
  }
  return { generalised: serializeShape(orig), diffs };
}

/**
 * The addressable parts of a url, labelled stably so a value observed at
 * record time can be re-extracted from the live run's url at the same
 * position: path segments `p<i>`, hash-route segments `h<i>`, hash-state
 * values `q.<key>`.
 */
function urlParts(url: string): { label: string; value: string }[] {
  const s = urlShapeOf(url);
  if (!s) return [];
  const out: { label: string; value: string }[] = [];
  s.path.forEach((value, i) => out.push({ label: `p${i}`, value }));
  s.hashPath.forEach((value, i) => out.push({ label: `h${i}`, value }));
  for (const [k, value] of s.hashState) out.push({ label: `q.${k}`, value });
  return out;
}

/**
 * One labelled part of a url. A `q.<key>` label reads the hash state first,
 * as urlParts enumerates it, and otherwise the ordinary query string: a
 * record id minted into `?task_id=4` (kanboard fwkb41, ledger.ts
 * linkMintedParts) is bound, published and checked by this label in both
 * runners. urlParts itself still enumerates hash state only, so nothing that
 * walks every part starts seeing query values.
 */
/**
 * The ROUTE a labelled part sits on: the url's origin and every path and
 * hash-route segment before it (all of them, for a `q.<key>` label) — never
 * the part's own value. Two urls with the same route at a label address the
 * same kind of record there (`#/editor/post/<id>`), which is how a part a step
 * VISITED is told apart from the same label on another page. Null when the url
 * has no part at `label`.
 */
function routeAt(url: string, label: string): string | null {
  const parts = urlParts(url).filter((p) => !p.label.startsWith('q.'));
  const origin = originOf(url);
  if (!origin) return null;
  let before: { label: string; value: string }[];
  if (label.startsWith('q.')) {
    if (urlPart(url, label) === undefined) return null;
    before = parts;
  } else {
    const at = parts.findIndex((p) => p.label === label);
    if (at < 0) return null;
    before = parts.slice(0, at);
  }
  return [origin, ...before.map((p) => `${p.label}=${p.value}`)].join(' ');
}

/**
 * The value a step publishes at `label` — rule A, round 60, ghost fwgh14.
 *
 * Its END url's part, whenever the end url carries one: a step's end state is
 * what later steps start from, and an output a step has always published does
 * not change. Otherwise, when the flow recorded the ROUTE the part was minted
 * on (FlowStep.urlRoutes, routeAt), the part of the LAST url the step visited
 * on that route. fwgh14's 02-create typed its post into Ghost's editor, whose
 * autosave routed to `#/editor/post/<id>`, then went back to the posts list:
 * the id was the step's, and nothing published it. Last, so a record the step
 * opened and backed out of for another is never the one published.
 *
 * `visited` is the step's url trail (browser.ts urlTrail), in order. Both
 * runners call this: the daemon's flow runner and the artifact's step body.
 */
function visitedUrlPart(visited: readonly string[], endUrl: string, label: string, route: string | undefined): string | undefined {
  const end = urlPart(endUrl, label);
  // The end url's part only on the recorded route (round 62, vikunja fwvk13):
  // 02-create ended on /projects/2/5, whose p1 is the PROJECT, and published
  // it as the task id the step had visited at p1 on /tasks/:id.
  if (end && (!route || routeAt(endUrl, label) === route)) return end;
  if (!route) return undefined;
  for (let i = visited.length - 1; i >= 0; i--) {
    if (routeAt(visited[i], label) !== route) continue;
    const value = urlPart(visited[i], label);
    if (value) return value;
  }
  return undefined;
}

function urlPart(url: string, label: string): string | undefined {
  const hit = urlParts(url).find((p) => p.label === label)?.value;
  if (hit !== undefined || !label.startsWith('q.')) return hit;
  return urlShapeOf(url)?.query.get(label.slice(2));
}

// Shared execution source: facts.ts. Regenerate to update.
/**
 * SITE FACTS: what the runner has OBSERVED about an app, per origin, with
 * counts and provenance, so a judgment about the app is made once from
 * evidence and then relied on (notes/design/design-site-facts.md).
 *
 * The survey behind it (rounds 54-65): about two thirds of the non-green rows
 * were decided by a fixed heuristic about the APP while the run already held
 * the evidence to decide it by observation — fwop15-cv2 refused five whole
 * recordings of 01-open on `?query_props` alone (view state, not a record);
 * espo rendered a typed 12500 as "12,500"; odoo's FURN_7777 is a catalogue
 * code, not something the run minted. Each fix so far was one more heuristic,
 * recomputed from one recording and thrown away. A fact is kept.
 *
 * Two rules decide whether a fact DECIDES anything (`reliable`):
 *  - a HARD fact is a structural proof by the runner (the app rendered this
 *    typed value as that text at this control) and is relied on from its first
 *    observation; a SOFT fact is statistical and needs two sessions;
 *  - either way a contradiction drops it to ADVISORY (logged, never deciding),
 *    and contradictions in two sessions retire it.
 *
 * Everything here is pure over a `SiteFacts` document: skills/facts.ts owns
 * the files, the daemon's observers write through it, and compile freezes the
 * origin's facts into the artifact (`FLOW.facts`) so both runners read the
 * same snapshot through these same functions — no parity gap can come from the
 * store. The artifact embeds this exact source (spec/runtime-source.ts), so it
 * must stay self-contained: the sibling url module and nothing else, no node
 * builtins (the value hash is FNV-1a over BigInt, not node:crypto).
 */

type FactKind = 'route.fragment' | 'route.query' | 'route.path' | 'format' | 'value.class' | 'value.shape';
type FormatKind = 'thousands' | 'decimals' | 'affix' | 'upper' | 'date' | 'trim' | 'twice' | 'counter';
type FactValue = string | { kind: FormatKind; tpl?: string } | { re: string; n: number };

interface Fact {
  k: FactKind;
  /** Per kind: a route template with a suffix, a field key, a value hash (see the stage 0 contract). */
  key: string;
  v: FactValue;
  /** Observations of exactly this value under this key. */
  n: number;
  /** Distinct sessions (a recording's daemon session, a replay's run id), most recent last, capped at MAX_SESSIONS. */
  sessions: string[];
  /** Observations of another value under this key since this one was first seen. */
  contra: number;
  /** A structural proof: relied on from one observation. */
  hard: boolean;
  /** ISO times of the first and the last observation. */
  first: string;
  last: string;
  /** One short line of evidence for the last observation, at most MAX_EV characters. */
  ev?: string;
  /**
   * The sessions the contradictions came from (deduped, capped at
   * MAX_SESSIONS): retirement needs two of them, and `contra` alone cannot say
   * whether two contradictions were one session's flake or two sessions'
   * agreement. Absent while `contra` is 0.
   */
  contraSessions?: string[];
}

interface SiteFacts { version: 1; origin: string; facts: Fact[] }

interface Observation { k: FactKind; key: string; v: FactValue; hard: boolean; session: string; at?: string; ev?: string }

type ObserveOutcome = 'new' | 'confirmed' | 'contradicted' | 'retired';

const SITE_FACTS_VERSION = 1;
/** Facts one origin keeps; the least recently observed go first, so a busy app cannot grow the file without bound. */
const MAX_FACTS = 2000;
/** Sessions a fact remembers: the count is what matters, and two is what `reliable` asks for. */
const MAX_SESSIONS = 8;
/** Longest `ev` line. Dropping one that names a run-specific token is the caller's job; the length is this module's. */
const MAX_EV = 120;

function emptyFacts(origin: string): SiteFacts {
  return { version: SITE_FACTS_VERSION, origin, facts: [] };
}

/**
 * The same folding flow.ts:2240 applies before comparing two displayed values
 * — whitespace collapsed, trimmed, lower-cased — copied rather than imported
 * because flow.ts is not an embeddable module.
 */
function foldValue(s: string): string {
  return s.replace(/\s+/g, ' ').trim().toLowerCase();
}

const FNV_OFFSET = 0xcbf29ce484222325n;
const FNV_PRIME = 0x100000001b3n;
const MASK_64 = 0xffffffffffffffffn;

/** UTF-8 bytes without TextEncoder or Buffer, so the hash is the same in every runtime the artifact meets. */
function utf8(s: string): number[] {
  const out: number[] = [];
  for (const ch of s) {
    const c = ch.codePointAt(0) ?? 0;
    if (c < 0x80) out.push(c);
    else if (c < 0x800) out.push(0xc0 | (c >> 6), 0x80 | (c & 0x3f));
    else if (c < 0x10000) out.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 0x3f), 0x80 | (c & 0x3f));
    else out.push(0xf0 | (c >> 18), 0x80 | ((c >> 12) & 0x3f), 0x80 | ((c >> 6) & 0x3f), 0x80 | (c & 0x3f));
  }
  return out;
}

/**
 * The key of a `value.class` fact: 64-bit FNV-1a of the folded value, as 16
 * hex characters. The file never holds the text of a value that might be a
 * secret or a person's name (fwgr68/fwkb39: the password was the username),
 * only this — enough to recognise the value again, not to recover it.
 */
function valueHash(s: string): string {
  let h = FNV_OFFSET;
  for (const b of utf8(foldValue(s))) {
    h ^= BigInt(b);
    h = (h * FNV_PRIME) & MASK_64;
  }
  return h.toString(16).padStart(16, '0');
}

/**
 * A value's SHAPE, as an anchored regex source: every digit run is `\d+`,
 * letters and punctuation stay literal (escaped). Two distinct minted values
 * under one label that share a shape are what a `value.shape` fact records —
 * odoo's S00023 and S00041 are both `^S\d+$`, so the next S000xx under that
 * label is recognisably the same kind of record id at its first sighting.
 */
function shapeOf(s: string): string {
  const body = s
    .split(/(\d+)/)
    .map((part, i) => (i % 2 === 1 ? '\\d+' : part.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')))
    .join('');
  return `^${body}$`;
}

/** Two values share a shape. */
function shapeAgrees(a: string, b: string): boolean {
  return shapeOf(a) === shapeOf(b);
}

/**
 * A url segment that stands for a record rather than a page: digit-dominant
 * as shape.ts `digitDominant` reads it (at least as many digits as anything
 * else, or one '-'/'_' piece that is — "4", "S00023", "fwrd24l-n1"), or any
 * segment with two or more digits whatever its letters (an espo or grafana
 * id, "afw6yy5xx9"). A route key over-merging two pages is the weaker
 * direction; one key per record is useless as a key.
 */
function recordSeg(seg: string): boolean {
  const digits = (x: string) => (x.match(/\d/g) ?? []).length;
  const dominated = (x: string) => digits(x) > 0 && digits(x) >= x.length - digits(x);
  if (digits(seg) >= 2) return true;
  return dominated(seg) || (/[-_]/.test(seg) && seg.split(/[-_]+/).some(dominated));
}

/**
 * The ROUTE a url is on, the stem of every url-derived key: origin and path,
 * every wildcard marker (`:id`, `:var`, `{{v1}}`) and every record-shaped
 * segment written `*`, no query and no fragment — except a fragment that is
 * itself a route (`#/orders/12`, espo's `#Opportunity/view/<id>`), which is
 * appended the same way. A bare-word fragment is an in-page anchor (snipeit's
 * `/hardware/4#history`, fwsi9) and a `k=v` fragment is state (odoo): neither
 * names the page. This is compile.ts `urlPattern(url, {query: false})` with
 * the markers normalised, reimplemented over urlShapeOf because compile.ts is
 * not embeddable. Text that is not a url is its own route.
 *
 * `identityParts`: the url's parts a caller already knows to be a record, as
 * urlParts labels them with their value (`p1=afzexqoxkzoqod`, `h2=…`; any
 * other label is ignored). A path or fragment-path segment named there is
 * written `*` as a record-shaped one is — grafana's letters-only dashboard uid
 * (fwgr78) has no digits for `recordSeg` to see, and froze inside the key.
 */
function routeTemplateOf(url: string, identityParts?: readonly string[]): string {
  const shape = urlShapeOf(url);
  if (!shape) return url;
  const known = new Set(identityParts ?? []);
  const seg = (prefix: 'p' | 'h') => (s: string, i: number) =>
    isWildcardSeg(s) || s === '*' || recordSeg(s) || known.has(`${prefix}${i}=${s}`) ? '*' : s;
  let out = `${shape.origin}/${shape.path.map(seg('p')).join('/')}`;
  if (shape.hashKind === 'path' && !shape.hashAnchor) out += `#${shape.hashSlash ? '/' : ''}${shape.hashPath.map(seg('h')).join('/')}`;
  return out;
}

/**
 * Whether two observed values are the same fact value. A shape compares by
 * its regex only: its `n` is a running count of the values that agreed, not
 * part of what was observed.
 */
function sameFactValue(a: FactValue, b: FactValue): boolean {
  if (typeof a === 'string' || typeof b === 'string') return a === b;
  if ('re' in a || 're' in b) return 're' in a && 're' in b && a.re === b.re;
  return a.kind === b.kind && (a.tpl ?? '') === (b.tpl ?? '');
}

/**
 * Whether two facts under one key compete. Everywhere but `format` a key has
 * one true value, so any other value contradicts it. A field's formats
 * COMBINE — espo renders 12500 as "12,500.00", a `thousands` and a `decimals`
 * fact under one key — so only two formats of the same kind (two affix
 * templates) compete.
 */
function competes(a: Fact | Observation, b: Fact | Observation): boolean {
  if (a.k !== b.k || a.key !== b.key || sameFactValue(a.v, b.v)) return false;
  if (a.k !== 'format') return true;
  const kind = (v: FactValue) => (typeof v === 'object' && 'kind' in v ? v.kind : '');
  return kind(a.v) === kind(b.v);
}

function clipEv(ev: string | undefined): string | undefined {
  if (ev === undefined) return undefined;
  return ev.length > MAX_EV ? `${ev.slice(0, MAX_EV - 1)}…` : ev;
}

function addSession(list: string[], session: string): string[] {
  const out = list.filter((s) => s !== session);
  out.push(session);
  return out.length > MAX_SESSIONS ? out.slice(out.length - MAX_SESSIONS) : out;
}

/** Drop the least recently observed facts past MAX_FACTS. Mutates and returns `sf`. */
function evict(sf: SiteFacts, max: number = MAX_FACTS): SiteFacts {
  if (sf.facts.length <= max) return sf;
  const keep = new Set(
    [...sf.facts].sort((a, b) => (a.last < b.last ? 1 : a.last > b.last ? -1 : 0)).slice(0, max),
  );
  sf.facts = sf.facts.filter((f) => keep.has(f));
  return sf;
}

/**
 * Merge one observation into `sf` (in place) and say what it did:
 *  - `new`: nothing was known under the key;
 *  - `confirmed`: the same value was known: `n`, the session, `last`, `hard`
 *    (a proof, once seen, stays a proof) and `ev` are brought up to date;
 *  - `contradicted`: another value was known: the new value is recorded;
 *  - `retired`: as either of the two above, and a competing fact reached two
 *    contradictions from two sessions and was removed (listed in `retired`).
 *
 * A contradiction is SYMMETRIC: every observation of a value counts against
 * every competing value under the key, whether it is new or confirmed, and a
 * new value arriving over a stored one starts with the stored one's evidence
 * against it (`contra` 1). So neither side decides while the dispute lasts
 * (both advisory: never guess), and the dispute ends the way the design asks
 * — the value that is re-observed in two sessions retires the other. A fact
 * left with no rival under its key has outlived every contradiction it had,
 * so once it has been seen in two sessions they are cleared and it decides
 * again on its own evidence (a newcomer that won on one session's word stays
 * advisory until a second session sees it).
 *
 * Then the origin is evicted to MAX_FACTS by oldest `last`.
 */
function observeFact(sf: SiteFacts, o: Observation): { fact: Fact; outcome: ObserveOutcome; retired: Fact[] } {
  const at = o.at ?? new Date().toISOString();
  const rivals = sf.facts.filter((f) => competes(f, o));
  let fact = sf.facts.find((f) => f.k === o.k && f.key === o.key && sameFactValue(f.v, o.v));
  let outcome: ObserveOutcome;
  if (fact) {
    fact.n += 1;
    fact.sessions = addSession(fact.sessions, o.session);
    fact.last = at;
    fact.hard ||= o.hard;
    // a shape's n is the running count of values that agreed on it
    if (typeof fact.v === 'object' && 're' in fact.v && typeof o.v === 'object' && 're' in o.v) {
      fact.v = { re: fact.v.re, n: Math.max(fact.v.n, o.v.n) };
    }
    const ev = clipEv(o.ev);
    if (ev === undefined) delete fact.ev;
    else fact.ev = ev;
    outcome = 'confirmed';
  } else {
    fact = {
      k: o.k, key: o.key, v: typeof o.v === 'string' ? o.v : { ...o.v },
      n: 1, sessions: [o.session], contra: 0, hard: o.hard, first: at, last: at,
    };
    const ev = clipEv(o.ev);
    if (ev !== undefined) fact.ev = ev;
    if (rivals.length) {
      fact.contra = 1;
      fact.contraSessions = [o.session];
    }
    sf.facts.push(fact);
    outcome = rivals.length ? 'contradicted' : 'new';
  }
  const retired: Fact[] = [];
  for (const rival of rivals) {
    rival.contra += 1;
    rival.contraSessions = addSession(rival.contraSessions ?? [], o.session);
    if (rival.contra >= 2 && rival.contraSessions.length >= 2) retired.push(rival);
  }
  if (retired.length) {
    sf.facts = sf.facts.filter((f) => !retired.includes(f));
    outcome = 'retired';
  }
  if (fact.contra > 0 && fact.sessions.length >= 2 && !sf.facts.some((f) => competes(f, fact!))) {
    fact.contra = 0;
    delete fact.contraSessions;
  }
  evict(sf);
  return { fact, outcome, retired };
}

/** Relied on: never contradicted, and either proven or seen in two sessions. */
function reliable(f: Fact): boolean {
  return f.contra === 0 && (f.hard || f.sessions.length >= 2);
}

/** Present but not relied on: logged beside today's heuristic, never deciding. */
function advisory(f: Fact): boolean {
  return !reliable(f);
}

function factsFor(sf: SiteFacts, k: FactKind, key: string): Fact[] {
  return sf.facts.filter((f) => f.k === k && f.key === key);
}

/**
 * The one reliable fact under a key, or null. Two reliable facts under one key
 * is a contradiction the observer missed: null, never a guess between them.
 */
function factFor(sf: SiteFacts, k: FactKind, key: string): Fact | null {
  const relied = factsFor(sf, k, key).filter(reliable);
  return relied.length === 1 ? relied[0] : null;
}

function stringFact<T extends string>(sf: SiteFacts, k: FactKind, key: string, allowed: readonly T[]): T | null {
  const v = factFor(sf, k, key)?.v;
  return typeof v === 'string' && (allowed as readonly string[]).includes(v) ? (v as T) : null;
}

/** What a fragment is on this origin: a route, application state, or an in-page anchor. */
function fragmentFact(sf: SiteFacts): 'path' | 'state' | 'anchor' | null {
  return stringFact(sf, 'route.fragment', '', ['path', 'state', 'anchor'] as const);
}

/** What a query key is on the url's route: view state (fwop15's `query_props`), a record, or a page selector (kanboard's `controller`). */
function routeQueryFact(sf: SiteFacts, url: string, key: string): 'state' | 'identity' | 'routing' | null {
  return stringFact(sf, 'route.query', `${routeTemplateOf(url)}?${key}`, ['state', 'identity', 'routing'] as const);
}

/** What a path position is on the url's route: a record id or a constant. `index` is the 0-based path index, urlParts' `p<index>`. */
function pathPositionFact(sf: SiteFacts, url: string, index: number): 'identity' | 'constant' | null {
  return stringFact(sf, 'route.path', `${routeTemplateOf(url)}#${index}`, ['identity', 'constant'] as const);
}

/** Every reliable display format of a field. Formats combine, so this is a list, never factFor. */
function formatFacts(sf: SiteFacts, key: string): { kind: FormatKind; tpl?: string }[] {
  return factsFor(sf, 'format', key)
    .filter(reliable)
    .map((f) => f.v)
    .filter((v): v is { kind: FormatKind; tpl?: string } => typeof v === 'object' && 'kind' in v)
    .map((v) => (v.tpl === undefined ? { kind: v.kind } : { kind: v.kind, tpl: v.tpl }));
}

/** "12500" → "12,500": group the integer part of a plain number; anything else is left alone. */
function groupThousands(s: string): string {
  const m = /^(-?)(\d+)(\.\d+)?$/.exec(s);
  if (!m) return s;
  return `${m[1]}${m[2].replace(/\B(?=(\d{3})+(?!\d))/g, ',')}${m[3] ?? ''}`;
}

/** "12,500" → "12,500.00": a `.00` tail on a whole number, a one-digit fraction padded. */
function withDecimals(s: string): string {
  if (/^-?[\d,]+$/.test(s) && /\d/.test(s)) return `${s}.00`;
  if (/^-?[\d,]+\.\d$/.test(s)) return `${s}0`;
  return s;
}

/**
 * How the app would SHOW `value` in this field, from its reliable formats:
 * the value with every transformation applied (numbers, then case and
 * whitespace, then the affix), and, when there is an affix, the same without
 * it — a read may meet the bare core (espo's "12,500.00") or the framed title
 * (kanboard's "#4"). `date`, `twice` and `counter` describe the field without
 * saying how to spell a value, so they add nothing. Empty when no reliable
 * format applies.
 */
function renderings(sf: SiteFacts, key: string, value: string): string[] {
  const formats = formatFacts(sf, key);
  const has = (kind: FormatKind) => formats.some((f) => f.kind === kind);
  let core = value;
  let changed = false;
  const apply = (kind: FormatKind, fn: (s: string) => string) => {
    if (!has(kind)) return;
    core = fn(core);
    changed = true;
  };
  apply('thousands', groupThousands);
  apply('decimals', withDecimals);
  apply('trim', (s) => s.trim());
  apply('upper', (s) => s.toUpperCase());
  const framed = formats
    .filter((f) => f.kind === 'affix' && f.tpl?.includes('{{=}}'))
    .map((f) => f.tpl!.split('{{=}}').join(core));
  if (!changed && !framed.length) return [];
  return [...new Set([...framed, ...(changed ? [core] : [])])];
}

/** What this value is on this origin: a catalogue constant, a run's mint, or a credential. */
function valueClassFact(sf: SiteFacts, value: string): 'constant' | 'mint' | 'credential' | null {
  return stringFact(sf, 'value.class', valueHash(value), ['constant', 'mint', 'credential'] as const);
}

/** The reliable shape of the values minted under a label (`${route}|${label}`). */
function shapeFact(sf: SiteFacts, key: string): { re: string } | null {
  const v = factFor(sf, 'value.shape', key)?.v;
  return typeof v === 'object' && 're' in v ? { re: v.re } : null;
}

/** The value has the label's reliable mint shape. False when there is none, or it does not compile. */
function matchesShape(sf: SiteFacts, key: string, value: string): boolean {
  const shape = shapeFact(sf, key);
  if (!shape) return false;
  try {
    return new RegExp(shape.re).test(value);
  } catch {
    return false;
  }
}

/**
 * The counts `compile --json` reports per origin: `relied` facts (of which
 * `hard` were proven and `soft` counted across sessions) and `advisory` ones.
 * `hard + soft === relied`.
 */
function summarise(sf: SiteFacts): { origin: string; relied: number; advisory: number; hard: number; soft: number } {
  const relied = sf.facts.filter(reliable);
  return {
    origin: sf.origin,
    relied: relied.length,
    advisory: sf.facts.length - relied.length,
    hard: relied.filter((f) => f.hard).length,
    soft: relied.filter((f) => !f.hard).length,
  };
}

// Shared execution source: gates.ts. Regenerate to update.
/**
 * The step and segment GATES both execution targets judge by, as pure
 * verdicts over observations the caller supplies: an error page, where a step
 * left the url, a live-region alert, where a segment starts, and whether a
 * goal's markers are bound at all.
 *
 * Each verdict is one function called by daemon replay (src/skills/replay.ts)
 * AND by the compiled `.flow.ts` artifact, which embeds this exact source
 * (spec/runtime-source.ts). What differs per runner is only HOW it waits and
 * observes, never what it decides — a rule only one runner applies is the class
 * of defect the parity harness exists to catch. So this module must stay
 * self-contained: sibling shared modules and Playwright types only.
 *
 * `where` in every message is the caller's name for the step ("step 3" in the
 * daemon, "<stepId> <segmentId>/<n>" in the artifact).
 */

/**
 * How a LIVE url reads in a verdict's message. The message travels: into a
 * recovery prompt, onto the persisted run record, into a refusals list. The
 * url's shape (origin, path, hash route or state) is all any of those need;
 * the query string and a free-form fragment are where `?token=…` and
 * `#access_token=…` live, and they must not travel with it. A state-shaped
 * fragment is kept (its keys are app routing — odoo's `#action=9&cids=1`).
 * Of the query, only the keys `against` — the pattern the url was judged by —
 * names are kept, since those are the pairs the verdict is about
 * (`?status=failure` where `?status=success` was expected); every other query
 * pair is dropped. Either way the VALUE of any key that names a credential is
 * replaced by `***`. A url that does not parse is shown as it is.
 */
function describeUrl(url: string, against?: string): string {
  const shape = urlShapeOf(url);
  if (!shape) return url;
  const named = (against && urlShapeOf(against)?.query) || new Map<string, string>();
  for (const key of shape.query.keys()) {
    if (!named.has(key)) shape.query.delete(key);
  }
  for (const pairs of [shape.query, shape.hashState]) {
    for (const key of pairs.keys()) {
      if (CREDENTIAL_KEY.test(key)) pairs.set(key, '***');
    }
  }
  return serializeShape(shape);
}

/**
 * A stored pattern as a verdict must SHOW it: filled from this run's params,
 * and any marker the run never bound rendered as the wildcard the matcher
 * already treats it as (url.ts isWildcardSeg). DISPLAY ONLY — every matcher
 * here goes on reading the raw pattern, so which urls pass is unchanged.
 *
 * fwod51's 07-verify printed "expected url …&id={{d3}}&…": the literal text of
 * a marker no page ever shows, inside a sentence reading "expected url". The
 * gate was right — the click had overshot onto another record's list — but the
 * refusal read as a broken gate in the drift ticket, the flowrun and the
 * compile diagnostic, and sent the fix hunting in the wrong place. A `{{vN}}`
 * is a value the caller supplies and reads as `:var`; anything else is a
 * position the run derives, and reads as `:id`, which is how the compiler
 * already spells the id positions beside it.
 */
function shownPattern(pattern: string, params: Record<string, string>): string {
  return fillParams(pattern, params).replace(/\{\{([\w.-]+)\}\}/g, (_m, name: string) => (/^v\d+$/.test(name) ? ':var' : ':id'));
}

/** The tab is on a browser error page: a crashed renderer, a navigation the network refused. */
function isErrorPageUrl(url: string): boolean {
  return /^chrome-error:|^about:neterror/.test(url);
}

/**
 * Nothing recorded can hold on an error page, and every later step would
 * resolve nothing while the run pressed on. fwgr26-n2 ran eleven more steps
 * on chrome-error://chromewebdata/ before the next segment refused with the
 * unreadable "browser is at null/".
 */
function errorPageVerdict(url: string, where: string): string | null {
  return isErrorPageUrl(url) ? `after ${where} the browser is on an error page (${url}) — the tab crashed or a navigation failed` : null;
}

interface UrlEffectVerdict {
  stop?: string;
  warnings: string[];
  /** The pattern with the disagreeing segments generalised, to persist once the run past here succeeds. */
  generalised?: string;
  diffs?: UrlSegDiff[];
}

/**
 * Hard expectation: where the step was supposed to leave the browser. A
 * strict match passes. A same-shape url whose 1–2 literal segments disagree is
 * the signature of an environment-minted identifier (a Grafana uid, an Odoo
 * action id) — treated as volatile: warn, hand back the generalisation,
 * continue. Anything else stops. The WAIT for a navigation still in flight
 * belongs to the caller: judge only once the url has had its window.
 */
function urlEffectVerdict(
  pattern: string | undefined,
  liveUrl: string,
  params: Record<string, string>,
  where: string,
  link?: { from: string; href: string },
): UrlEffectVerdict {
  if (!pattern || urlMatches(pattern, liveUrl, params)) return { warnings: [] };
  const landed = linkLandingWarning(pattern, liveUrl, params, where, link);
  if (landed) return { warnings: [landed] };
  const soft = softUrlMatch(pattern, liveUrl, params);
  if (!soft) {
    const shown = shownPattern(pattern, params);
    return { warnings: [], stop: `after ${where} expected url ${shown} but browser is at ${describeUrl(liveUrl, shown)}` };
  }
  return {
    warnings: [`${where}: url segment(s) differ from recorded (${describeDiffs(soft.diffs)}) — treated as volatile`],
    generalised: soft.generalised,
    diffs: soft.diffs,
  };
}

/**
 * A link click whose recorded landing is the page the link LEFT, and which
 * this run followed to exactly where the link points: the recording captured
 * the url before the link's navigation committed, and the click did what the
 * element itself says it does. Null when that is not the case.
 *
 * fwop2 (OpenProject, round 33): the recorder's settle gave up on a cold
 * server's Turbo Drive visit, so s_f4e3b6's click on "Bench Project" was
 * stored as landing on `/projects`, the list it was clicked on. Both replays
 * went to `/projects/bench-project` — the link's own href — and were refused
 * "expected url …/projects but browser is at …/projects/bench-project", so
 * 01-signin fell back to the model on every replay of the flow.
 *
 * Narrow on purpose: the recorded url must be the one this click started on
 * (the recording saw no navigation at all), and the live url must be the
 * link's href — never merely somewhere else. `link` is what the click's
 * action observation reported (ClickObservation.linkTarget), in both runners.
 */
function linkLandingWarning(
  pattern: string,
  liveUrl: string,
  params: Record<string, string>,
  where: string,
  link: { from: string; href: string } | undefined,
): string | null {
  if (!link || !urlMatches(pattern, link.from, params)) return null;
  if (!urlMatches(link.href, liveUrl) || urlMatches(link.href, link.from)) return null;
  const shown = shownPattern(pattern, params);
  return `${where}: recorded url ${shown} is the page the clicked link left (captured before its navigation committed); the click went where the link points, ${liveUrl} — accepted`;
}

function describeDiffs(diffs: UrlSegDiff[]): string {
  return diffs.map((d) => `${d.expected}→${d.actual}`).join(', ');
}

/** How a url position reads in a message, in the spelling urlRecordParts uses. */
function positionLabel(d: UrlSegDiff): string {
  return d.where === 'path' ? `path[${d.index}]` : d.where === 'hashPath' ? `#[${d.index}]` : d.where === 'hashState' ? `#${d.key}` : `${d.key}`;
}

function samePosition(a: UrlSegDiff, b: UrlSegDiff): boolean {
  return a.where === b.where && a.index === b.index && a.key === b.key;
}

/** What a url holds at the position a diff names, or undefined when it has none there. */
function partAt(shape: UrlShape, d: UrlSegDiff): string | undefined {
  if (d.where === 'path') return shape.path[d.index!];
  if (d.where === 'hashPath') return shape.hashPath[d.index!];
  if (d.where === 'query') return shape.query.get(d.key!);
  return shape.hashState.get(d.key!);
}

/**
 * Rewrite the named positions of a url, leaving every other byte of it as it
 * was. Not serializeShape: that sorts the query, drops noise keys and decodes
 * values, and a navigation must ask for the url the recording asked for, with
 * only these positions changed. Null when a position is not in the url.
 */
function withUrlParts(url: string, edits: readonly { at: UrlSegDiff; value: string }[]): string | null {
  let u: URL;
  try {
    u = new URL(url);
  } catch {
    return null;
  }
  // The fragment is edited as text: `#` may carry a route, state pairs, and a
  // `?…` remainder urlShapeOf ignores but the app may not.
  const cut = u.hash.indexOf('?');
  let body = u.hash.length > 1 ? (cut < 0 ? u.hash.slice(1) : u.hash.slice(1, cut)) : '';
  const rest = cut < 0 ? '' : u.hash.slice(cut);
  const nthNonEmpty = (parts: string[], n: number): number => parts.reduce<number[]>((keep, part, i) => (part === '' ? keep : [...keep, i]), [])[n] ?? -1;
  for (const { at, value } of edits) {
    if (at.where === 'path') {
      const segs = u.pathname.split('/');
      const i = nthNonEmpty(segs, at.index!);
      if (i < 0) return null;
      segs[i] = encodeURIComponent(value);
      u.pathname = segs.join('/');
    } else if (at.where === 'query') {
      if (!u.searchParams.has(at.key!)) return null;
      u.searchParams.set(at.key!, value);
    } else if (at.where === 'hashPath') {
      const segs = body.split('/');
      const i = nthNonEmpty(segs, at.index!);
      if (i < 0) return null;
      segs[i] = encodeURIComponent(value);
      body = segs.join('/');
    } else {
      const pairs = body.split('&');
      const i = pairs.findIndex((p) => p.split('=')[0] === at.key);
      if (i < 0) return null;
      pairs[i] = `${at.key}=${encodeURIComponent(value)}`;
      body = pairs.join('&');
    }
  }
  u.hash = body || rest ? `#${body}${rest}` : '';
  return u.toString();
}

/** Where a navigation should actually go, and what is stale about where it was told to go. */
interface NavigationTarget {
  /** The url to navigate to: the recorded target, or it with volatile positions taken from the live url. */
  url: string;
  /** What was retargeted, for the run's warnings; absent when the recorded target stands. */
  warning?: string;
  /**
   * The target still spells a value at a position this run has shown volatile
   * — the recording's record, not this run's. Handed to the alert gate as the
   * CAUSE of an unrecorded alert on the landing (alertVerdict.navigatedToStale).
   */
  stale?: string;
}

/**
 * Where a goto should send the browser. A recorded target is a literal from
 * the RECORDING's run, and one of its positions may be an identifier the
 * environment mints afresh — the case the soft url match already treats as
 * volatile. When this run has DEMONSTRATED that a position varies (the
 * `diffs` a urlEffectVerdict or a precondition soft match handed back) and the
 * target still spells the stale value there, the recorded literal names a page
 * of the recording's run, not of this one: navigate to the value the browser
 * is already showing at that position instead.
 *
 * Evidence only, never a shape guess: the position must have been observed to
 * vary in THIS run, the target must still carry exactly the value that
 * observation found stale, the live url must be the target's own page shape
 * (urlDiff), and every position where the two disagree must be one of those
 * observed — a disagreement anywhere else is a different page, and the
 * recorded target stands. Both sides must look minted, as softUrlMatch
 * requires, so `/orders/success` is never retargeted to `/orders/failure`.
 *
 * fwgr41-n3 06-find: step 6 warned "url segment(s) differ from recorded
 * (afyd7g0300dfkc→cfyd8hqymgfeoe) — treated as volatile", and step 7 then went
 * to the recorded `/d/afyd7g0300dfkc/…` — a dashboard this environment never
 * minted — where Grafana answered "Dashboard not found".
 */
function retargetNavigation(target: string, liveUrl: string, volatile: readonly UrlSegDiff[], where = 'this navigation'): NavigationTarget {
  // An unfilled marker is not a concrete destination; whatever this would
  // compare, it is not the url the step will ask for.
  if (!volatile.length || /\{\{/.test(target)) return { url: target };
  const shape = urlShapeOf(target);
  if (!shape) return { url: target };
  const carried = volatile.filter((v) => v.expected !== v.actual && partAt(shape, v) === v.expected);
  if (!carried.length) return { url: target };
  const stale = `its url still names the recorded ${carried.map((v) => `${positionLabel(v)}=${clip(v.expected, 40)}`).join(', ')}, which this run has already shown varies (${carried.map((v) => clip(v.actual, 40)).join(', ')})`;
  const diffs = urlDiff(target, liveUrl);
  // The browser is already where the target points (or on a url that is not
  // its page at all, where nothing here can be read off it).
  if (diffs && !diffs.length) return { url: target };
  if (!diffs) return { url: target, stale };
  const edits: { at: UrlSegDiff; value: string }[] = [];
  for (const d of diffs) {
    if (!carried.some((v) => samePosition(v, d) && v.expected === d.expected)) return { url: target, stale };
    if (!mintedShape(d.expected) || !mintedShape(d.actual)) return { url: target, stale };
    edits.push({ at: d, value: d.actual });
  }
  const url = withUrlParts(target, edits);
  if (!url) return { url: target, stale };
  return {
    url,
    warning: `${where}: the recorded target names ${diffs.map((d) => `${positionLabel(d)}=${clip(d.expected, 40)}`).join(', ')}, a position this run has already shown volatile — navigating to the live ${diffs.map((d) => `${positionLabel(d)}=${clip(d.actual, 40)}`).join(', ')} instead`,
  };
}

interface AlertVerdict {
  stop?: string;
  warnings: string[];
  /** The alert evidence could not be captured; nothing here was proven either way. */
  unobserved?: true;
}

/**
 * An alert the recording never saw cannot, on its own, be told apart: it may
 * be the app talking back — a rejection ("Ticket is not ready…") that leaves
 * the page superficially intact, as fwrd4l-n3 clicked into, the step counted
 * as run and only external verification catching that the ticket never
 * reached Ready — or it may be ambient page content that simply rendered late,
 * like fwgr34's "Error loading RSS feed" on a Grafana home page whose feed an
 * offline box cannot reach (the recording's after-look came before it did).
 *
 * So an unrecorded alert is always REPORTED, and whether the run continues is
 * decided by the step's own state evidence, not by the alert:
 * - `effectConfirmed` (expect.ts ChangeVerdict.confirmed — the recorded page
 *   changes appeared in what the action added): the step demonstrably did what
 *   it was recorded doing, so the alert is a warning and the run goes on; a
 *   later gate or step stops it if the state is in fact broken.
 * - otherwise the alert is the only evidence there is about whether the step
 *   worked, and a state-changing step stops on it (the rejected Mark that
 *   would otherwise go on to Remove the item).
 * A recorded-but-missing alert stays soft — toasts are volatile — and never
 * stops; a recorded alert (`expectedContains`) is what the step is expected
 * to raise, and is checked, not treated as unexpected.
 *
 * `before`/`after` are the visible live-region texts around the action (the
 * daemon's diff already holds the surplus, so it passes `before: []`); `after`
 * is null when the page could not be captured, which is reported as
 * unobserved rather than read as "no alert was raised".
 *
 * `afterComplete` false says the after-look did not see every live region
 * (the alert cap was reached, or a rendered frame could not be read). An
 * alert it DID see still stops the step — that is evidence — but "nothing new
 * was raised" and "the expected alert is missing" are then not established:
 * both are reported unobserved, never as a clean step.
 */
function alertVerdict(
  before: string[],
  after: string[] | null,
  ctx: { where: string; isRead: boolean; expectedContains?: string; params: Record<string, string>; effectConfirmed?: boolean; navigatedToStale?: string },
  afterComplete = true,
): AlertVerdict {
  const warnings: string[] = [];
  let unobserved: true | undefined;
  const want = ctx.expectedContains ? fillParams(ctx.expectedContains, ctx.params) : undefined;
  if (after === null) {
    // Detecting a NEW alert needs both captures; with either missing there is
    // no answer to give. Say so rather than the silent nothing that reads,
    // downstream, exactly like "no alert was raised".
    if (!ctx.isRead) {
      unobserved = true;
      warnings.push(`${ctx.where}: the page could not be captured after the action — whether it raised an alert is unknown, not clear`);
    }
    if (want !== undefined) {
      unobserved = true;
      warnings.push(`${ctx.where}: expected alert containing ${JSON.stringify(want)} could not be observed`);
    }
    return unobserved ? { warnings, unobserved } : { warnings };
  }
  const raised = after.filter((a) => !before.includes(a));
  if (raised.length && !ctx.isRead && want === undefined) {
    // The step NAVIGATED to a url still spelling a value this run has shown
    // volatile (retargetNavigation.stale): the page that url names belongs to
    // the recording's run and does not exist here, which is the cause of
    // whatever the app then said. The alert's own text decides nothing — the
    // navigation does — and the stop is the same stop; only what it names is
    // different, so recovery and the drift ticket act on the cause instead of
    // "an alert the recording never saw" (fwgr41-n3 06-find step 7, where
    // Grafana answered the recording's dead dashboard uid).
    const seen = ctx.navigatedToStale
      ? `${ctx.where} navigated to a page that does not exist: ${ctx.navigatedToStale} — the app answered with an alert the recording never saw: ${clip(raised.join(' | '), 200)}`
      : `${ctx.where} raised an alert the recording never saw: ${clip(raised.join(' | '), 200)}`;
    if (!ctx.effectConfirmed) return { warnings, stop: seen };
    warnings.push(`${seen} — reported, not stopped: the step's recorded page changes appeared`);
    return { warnings };
  }
  if (!afterComplete) {
    if (!ctx.isRead && !raised.length) {
      unobserved = true;
      warnings.push(`${ctx.where}: the page's alerts could not be observed in full after the action — whether it raised an alert is unknown, not clear`);
    }
    if (want !== undefined && !raised.some((a) => a.includes(want))) {
      unobserved = true;
      warnings.push(`${ctx.where}: expected alert containing ${JSON.stringify(want)} could not be observed in full`);
    }
    return unobserved ? { warnings, unobserved } : { warnings };
  }
  if (want !== undefined && !raised.some((a) => a.includes(want))) {
    warnings.push(`${ctx.where}: expected alert containing ${JSON.stringify(want)}`);
  }
  return { warnings };
}

/**
 * A soft-matched precondition needs the page's structural fingerprint to
 * agree before a run proceeds on it. Same-template-different-record pages
 * measured 0.94–1.0 in the swg sweeps; the different-template fixture pair
 * measures 0.57.
 */
const SOFT_MATCH_MIN_SIMILARITY = 0.8;

interface PreconditionVerdict {
  refuse?: string;
  /**
   * The refusal is that the page is PAST this procedure's start: the live url
   * already carries a record the procedure creates (mintedAhead). Structured,
   * so a caller can tell it from a wrong page: the step's mutation has already
   * happened here, and a read-only sibling that reports from the record is the
   * right procedure for this page (daemon runFlow, fwod68 03-open).
   */
  past?: { key: string; value: string; step: number };
  /** The url is the same page shape with 1–2 disagreeing segments, and the run proceeds on it. */
  soft?: { diffs: UrlSegDiff[]; generalised: string };
  warnings: string[];
}

/**
 * What a caller knows about the page's structural fingerprint when it asks
 * where a segment starts:
 *  - a number: the cosine similarity it measured between the recording's
 *    fingerprint and the live page;
 *  - null: the recording kept NO fingerprint, so there is nothing to measure
 *    against and the url is the only evidence there is;
 *  - 'unmeasured': the recording kept one and this caller CANNOT measure it
 *    (a compiled artifact from before the vector travelled in the spec, with
 *    only a `fingerprinted` flag). Evidence exists that the caller cannot
 *    consult, which is not the same as no evidence.
 *
 * Both runners measure the same way (src/execution/fingerprint.ts): the
 * cosine of the recorded vector and the live page's fingerprint, where a page
 * that could not be read gives null and the url alone decides. (No call is
 * spelled out here: the emitter embeds a module whose export this text names.)
 */
type FingerprintSimilarity = number | null | 'unmeasured';

/**
 * Where a segment starts. A strict url match passes. Same page shape with 1–2
 * disagreeing segments is likely an environment-minted id (an Odoo action id,
 * a Grafana uid): proceed optimistically instead of refusing — a hard fail
 * here is what turned a one-segment difference into a dead flow, and it also
 * makes the volatility evidence uncollectible. But "likely" is not evidence,
 * so when the caller measured the page's structural fingerprint against the
 * recording's (`similarity`), that second gate decides: a different RECORD of
 * the same template fingerprints close; a different TEMPLATE does not. Only a
 * close page proceeds.
 *
 * With no fingerprint recorded (null) the url alone decides and a soft match
 * proceeds, as the daemon does for such a skill. When a fingerprint WAS
 * recorded but this caller cannot measure it ('unmeasured'), a soft match is
 * refused: the daemon would have consulted the fingerprint here, and a runner
 * that cannot must not proceed on less evidence than the daemon requires —
 * only a strict match passes. That is an old compiled artifact's case; the
 * emitter says so per segment (the `unmeasured-precondition` diagnostic).
 *
 * Asked immediately before the segment's first page-dependent step
 * (`segmentGate`), never before a step that does not look at the page.
 */
/**
 * Where a goto landed, against where it was sent. Redirects are ordinary (a
 * root that routes to its login, a uid url the app completes with a slug), so
 * a different path or a key only one side has decides nothing. What does
 * decide is a key BOTH urls carry — query or hash state — whose values are
 * different WORDS: the app chose another view. fwod45's recovery skill sent
 * the browser to `…&view_type=form&id=22` for a record the reset had deleted,
 * and Odoo landed it on `view_type=list`; the steps after it read the list as
 * if it were the order. Two values that both look minted (ids, uids) are a
 * volatile id, not a different view. Null when the landing is acceptable.
 */
function gotoLandingVerdict(target: string, landed: string, where: string): string | null {
  const t = urlShapeOf(target);
  const l = urlShapeOf(landed);
  if (!t || !l || t.origin !== l.origin) return null;
  const pairs: [string, string, string][] = [];
  for (const [key, val] of t.query) if (l.query.has(key)) pairs.push([key, val, l.query.get(key)!]);
  for (const [key, val] of t.hashState) if (l.hashState.has(key)) pairs.push([key, val, l.hashState.get(key)!]);
  // An EMPTY requested value asks for no particular view: the app filling in
  // its default is the landing the request left open. fwod48's recording
  // typed `web#action=&model=&view_type=list&cids=1&menu_id=`, Odoo landed on
  // action=123&menu_id=81 exactly as it had at record time, and both replays
  // stopped there as "another view".
  const differ = pairs.filter(([, want, got]) => want !== '' && want !== got && !/\{\{/.test(want) && !(mintedShape(want) && mintedShape(got)));
  if (!differ.length) return null;
  const said = differ.map(([key, want, got]) => `${key}=${clip(got, 40)} where it was sent to ${key}=${clip(want, 40)}`).join(', ');
  return `${where} navigated but landed on another view: ${said} — the page it asked for was not given`;
}

/** Tools that act on the browser or the tab itself and never on anything in the page. */
const PAGE_INDEPENDENT_TOOLS = new Set(['goto', 'back', 'set_viewport', 'set_offline', 'dialog_expect', 'screenshot', 'snapshot', 'tabs']);

/** The steps a segment's gate is placed by: a tool, its args, its target chains. */
interface GateStep {
  tool: string;
  args?: Record<string, unknown>;
  locators?: Record<string, readonly unknown[] | undefined>;
}

/**
 * A selector that names the document itself, not anything the page renders.
 *
 * The root has more than one spelling. A recorder that enriches a raw `body`
 * writes `html > body` beside it (fwrd68 s_bfc33c), and `html body` is the
 * same element again: a path built from NOTHING but `html`/`body` and
 * descendant/child combinators can only land on the document. Anything else in
 * the path is page content and is not the root — `body > div` must stay out,
 * which is why this reads the whole selector and not a prefix of it.
 */
function documentRoot(selector: unknown): boolean {
  return typeof selector === 'string' && /^\s*(?:html|body)(?:(?:\s*>\s*|\s+)(?:html|body))*\s*$/i.test(selector);
}

/**
 * Whether a step acts on or reads the page's CONTENT — the steps a segment's
 * gate (where it starts, and whose record it is) exists to protect. Pure, so
 * both runners and the compiler ask the same question.
 *
 * Not page-dependent:
 *  - goto, back: they take the browser somewhere; what was there before is
 *    beside the point. A navigation is a page seam (compile.ts).
 *  - set_viewport, set_offline, tabs: the browser or the tab, not the page.
 *  - dialog_expect: arms a handler; it touches nothing until a dialog opens.
 *  - screenshot, snapshot: they look and can never fail on what they see.
 *  - a `read` of `what: 'url'`: the address bar, which is no page's content.
 *  - a `press` with no target: keyboard input to whatever has focus.
 *  - a `wait_for` whose target is the document itself (`body`/`html`, as the
 *    raw selector or as every recorded candidate that can say) waiting only
 *    for it to be there: a page load, not a page. A text or count condition on
 *    `body` IS about the content, and stays page-dependent.
 * Page-dependent: everything else — every step that resolves a target in the
 * page (click, dblclick, modifier/right click, fill, type, select, check,
 * hover, scroll_into_view, drag, upload, download, press with a target, read
 * and read_all with a target, a wait_for on anything else), a loop (its guard
 * and body resolve in the page), a labelled read, and eval. An unknown tool
 * counts as page-dependent: a gate asked once too often refuses a run; one
 * skipped does its work on the wrong page.
 */
function dependsOnPage(step: GateStep): boolean {
  const args = step.args ?? {};
  if (PAGE_INDEPENDENT_TOOLS.has(step.tool)) return false;
  if (step.tool === 'loop') return true;
  if (step.tool === 'press') return Boolean(args.target);
  if (step.tool === 'read' || step.tool === 'read_all') return args.what !== 'url';
  if (step.tool === 'wait_for') {
    const state = args.state === undefined ? 'visible' : String(args.state);
    if (state !== 'visible' && state !== 'attached') return true;
    const chain = step.locators?.target ?? [];
    const candidates = chain.filter((c): c is { kind: string; selector?: unknown } => Boolean(c) && typeof c === 'object');
    // WHY THE EXEMPTION EXISTS: a `wait_for body` looks at no page, so gating
    // it asks the page the procedure is LEAVING — fwrd53 07-report asked a
    // list for a detail page's markers (replay.ts's note at its segmentGate
    // call). Here that same mistake put the gate ahead of the `goto` that
    // CHOOSES the page, and the goto never ran.
    //
    // A CHAIN IS A PREFERENCE ORDER, NOT A CONJUNCTION — the same reading
    // `fillableChain` takes of an unfilled rung. Its rungs are alternative
    // ways to reach ONE element, so a rung that cannot answer "is this the
    // document root?" is DROPPED, not counted as a no; only the rungs that can
    // speak decide. A `point` is the rung that cannot: it is a coordinate, and
    // resolve.ts reads it as "what is HERE", never as identity. Every other
    // kind does name an element, and a `role`/`text`/`id`/`scoped` rung names
    // one the page renders — an answer, and the answer is no, so a chain
    // offering a page element alongside the root stays page-dependent.
    //
    // fwrd68 s_bfc33c: step 1's chain is [css `body`, css `html > body`,
    // point] — one element under two spellings plus a coordinate — and
    // `every` over it refused the whole flow (0/6 objectives) for a step that
    // waits for the document to exist.
    const speaking = candidates.filter((c) => c.kind !== 'point');
    const onRoot = candidates.length ? speaking.length > 0 && speaking.every((c) => c.kind === 'css' && documentRoot(c.selector)) : documentRoot(args.target);
    return !onRoot;
  }
  return true;
}

/**
 * Where a segment's gate goes: immediately before its first page-dependent
 * step (1-based `at`; 0 when it has none, and then it is never gated), and
 * whether a goto or back ran inside the segment ahead of that step.
 *
 * The gate used to sit before step 1, with a special case for a segment that
 * opened by navigating — which then asked the page it LANDED on for markers
 * observed before the goto (fwrd53 07-report: a detail page's markers asked of
 * the list). A navigation is now a seam, so a newly compiled segment never has
 * one ahead of its gate; `afterNavigation` is an older skill's shape, and the
 * caller judges it with `landedOnRecordedPage`.
 */
function segmentGate(steps: readonly GateStep[]): { at: number; afterNavigation: boolean } {
  let navigated = false;
  for (const [i, step] of steps.entries()) {
    if (dependsOnPage(step)) return { at: i + 1, afterNavigation: navigated };
    if (step.tool === 'goto' || step.tool === 'back') navigated = true;
  }
  return { at: 0, afterNavigation: false };
}

/**
 * A segment compiled before navigations were seams (contract < 4) can hold a
 * goto or back ahead of its first page-dependent step, while its url pattern,
 * fingerprint and identity markers were observed on the page BEFORE that
 * navigation. Judging the landing by them is only meaningful where it is the
 * same page template: then the url precondition is not asked (the goto chose
 * the page, and the recording's start url is a race with any redirect) but
 * the identity markers are — the recorded goto carries the RECORDING run's
 * record id (fwod10). Anywhere else the markers describe a page the procedure
 * has left, and neither is asked (fwrd53: a detail page's markers asked of the
 * list, where the archived record is hidden by design). Same template = a
 * strict or a soft url match of the recorded pattern with its slots left
 * UNFILLED: a slot is the record, and which record it is is the markers'
 * question — filled, another record's url would read as another template and
 * skip the very check that tells them apart.
 */
function landedOnRecordedPage(pattern: string, url: string): boolean {
  return urlMatches(pattern, url) || softUrlMatch(pattern, url) !== null;
}

/**
 * The soft-match budget this verdict spends, above url.ts's default — BECAUSE
 * AND ONLY BECAUSE it goes on to require `structurallySame` before accepting.
 * url.ts's count is a proxy for "is this a different page?"; this caller holds
 * the real measurement (SOFT_MATCH_MIN_SIMILARITY against the recorded
 * fingerprint), so the proxy yields to it. `urlEffectVerdict` warns and
 * proceeds with no similarity check at all, and keeps the default.
 *
 * Three, derived from fwgr49 and not from taste: the positions that varied
 * between two runs of one grafana dashboard were the record identifier
 * (`path[1]`, the uid) plus a time range, which occupies TWO positions
 * (`from`, `to`) for one varying thing. One identifier plus one range is the
 * most any url in the evidence varies by; a fourth disagreeing position is not
 * something a recording has shown, so it still refuses. The per-diff guards in
 * softUrlMatch (no WORD position, no parameter-filled position) are what make
 * each of the three safe, and they do not move with this number.
 */
const PRECONDITION_SOFT_DIFFS = 3;

/** A url position a procedure's step mints (compile.ts `mints`): the label urlParts gives it, and the 1-based step. */
interface MintedPosition {
  at: string;
  step: number;
  /** compile.ts newStateKeys: false when the key arrived with other new state keys (a navigation, not a creation). */
  sole?: boolean;
}

/**
 * The record a procedure CREATES is one its start page does not have. A
 * state-shaped url accumulates (urlDiff: a live key the pattern does not name
 * is allowed, Odoo grows `cids`/`menu_id` between segments), and that rule
 * let a procedure recorded on an UNSAVED form — no `id` in the url, its save
 * step mints `q.id` — start on the SAVED form of the same model: fwod66's
 * 04-verify was recorded as the rescue of a save that had not taken, replayed
 * on a quotation the fixed 03-create had already saved, and its first click
 * ("Cancel", the modal's at record time) cancelled the order. So a key the
 * procedure itself mints later, absent from its start pattern but present on
 * the live url, is the procedure's own evidence that the page is PAST its
 * start: the record it would create exists. Only that key: a key the pattern
 * names (`id=:id`, a procedure that starts on one record and creates another)
 * is judged as before.
 */
function mintedAhead(pattern: string, url: string, params: Record<string, string>, mints: MintedPosition[]): { key: string; value: string; step: number } | null {
  if (!mints.length) return null;
  const p = urlShapeOf(fillParams(pattern, params));
  const l = urlShapeOf(url);
  if (!p || !l) return null;
  for (const m of mints) {
    // A key that arrived with other new state keys was a navigation filling
    // in its state, not a record made: odoo fwod78's app-switcher click
    // coincided with the hash gaining action=123&menu_id=81, and every replay
    // whose login had already landed on that url was refused as past its
    // start. Only a key minted ALONE (fwod66's `…&id=44`) is a creation.
    // Absent (a store compiled before the flag) is read as sole, as before.
    if (m.sole === false) continue;
    if (!m.at.startsWith('q.')) continue;
    const key = m.at.slice(2);
    if (p.hashState.has(key) || p.query.has(key)) continue;
    const value = l.hashState.get(key) ?? l.query.get(key);
    if (value) return { key, value, step: m.step };
  }
  return null;
}

function preconditionVerdict(
  pattern: string,
  url: string,
  params: Record<string, string>,
  similarity: FingerprintSimilarity,
  mints: MintedPosition[] = [],
): PreconditionVerdict {
  // What this verdict actually compared, for every message below (fwod51).
  const shown = shownPattern(pattern, params);
  const ahead = mintedAhead(pattern, url, params, mints);
  if (ahead) {
    return {
      warnings: [],
      past: ahead,
      refuse:
        `not on the page this procedure starts from (expects ${shown}, browser is at ${describeUrl(url, shown)}; ` +
        `the url already carries ${ahead.key}=${ahead.value}, the record this procedure creates at its step ${ahead.step} — the page is past where the procedure starts)`,
    };
  }
  if (urlMatches(pattern, url, params)) {
    // A strict match that let a one-sided query key pass took that key on
    // trust. When the caller measured the page, that trust is checked like a
    // soft match's: `?editview=json-model` against the plain dashboard is the
    // same url by the query rule and a different view by the page (fwgr36
    // 04-open measured 0.252), and the identity gate then refused it as a
    // "different record". A same-page drift of `refresh=1m` measures close.
    const trusted = oneSidedQueryKeys(fillParams(pattern, params), url);
    if (trusted.length && typeof similarity === 'number' && similarity < SOFT_MATCH_MIN_SIMILARITY) {
      return {
        warnings: [],
        refuse: `not on the page this procedure starts from (expects ${shown}, browser is at ${describeUrl(url, shown)}; the urls differ only in query key(s) ${trusted.join(', ')}, and the page structure is not the recorded one — similarity ${similarity}, so this is another view of the page)`,
      };
    }
    return { warnings: [] };
  }
  const soft = softUrlMatch(pattern, url, params, PRECONDITION_SOFT_DIFFS);
  const structurallySame = similarity === null || (typeof similarity === 'number' && similarity >= SOFT_MATCH_MIN_SIMILARITY);
  if (!soft || !structurallySame) {
    const because =
      !soft || structurallySame
        ? ''
        : similarity === 'unmeasured'
          ? '; the url shape is close, but the recording fingerprinted this page and this runner cannot measure the live page against it — only a strict url match can pass here'
          : `; the url shape is close but the page structure is not — similarity ${similarity}`;
    return {
      warnings: [],
      refuse: `not on the page this procedure starts from (expects ${shown}, browser is at ${describeUrl(url, shown)}${because})`,
    };
  }
  return {
    soft: { diffs: soft.diffs, generalised: soft.generalised },
    warnings: [`start url differs from the recorded pattern in ${soft.diffs.length} segment(s) (${describeDiffs(soft.diffs)}) — proceeding optimistically`],
  };
}

/**
 * Whether every marker is BOUND: each slot it names has a nonempty value in
 * `params`, and the filled text is nonempty with no marker left in it. An
 * unbound marker proves nothing, so a goal check over one must fail rather
 * than pass — and a slot bound to '' (a derived value the run never minted)
 * renders `Order {{d1}}` as `Order `, which a page shows for every order. Both
 * runners ask this at run time; a compile-time check cannot see the value.
 */
function markersBound(markers: string[], params: Record<string, string>): boolean {
  return markers.every((marker) => {
    for (const m of marker.matchAll(/\{\{([vd]\d+)\}\}/g)) {
      if (!params[m[1]]) return false;
    }
    const filled = fillParams(marker, params);
    return Boolean(filled.trim()) && !/\{\{/.test(filled);
  });
}

/**
 * The slots a value still ASKS FOR that this run has no answer for: every
 * `{{vN}}`/`{{dN}}` marker anywhere inside it (a string, or any string reached
 * through an array or object — a step's args and its locator chains alike)
 * whose name is absent from `params`.
 *
 * EVIDENCE, NOT SHAPE. The question asked of each marker is `name in params`,
 * which is exactly what `fillParams` substitutes on (url.ts): a marker still
 * standing in already-filled text is, by construction, one this run had no
 * value for. Nothing here reads what the text looks like. A slot bound to ''
 * is BOUND — an unpublished reference, whose own rule is stated at url.ts's
 * `unfilled` — and is not reported here.
 *
 * Scoped to the two markers `fillParams` itself recognises and to nothing
 * else: a `{{stepId.output}}` reference reaching a value is a different
 * mechanism, answered for an ACTION's args by `unresolvedArgMarkers` and at
 * compile time by the artifact's `need` / `unsourced-ref`; and a page that
 * legitimately displays braces is not a marker at all. This narrow reading is
 * what the locator-chain arm and every marker CHECK want, and only those.
 *
 * WHY A CALLER WOULD ASK. "A slot the run could not fill asks for no
 * particular value" is the right reading for a CHECK, and every gate here
 * already takes it: markersBound, urlRecordParts, gotoLandingVerdict's
 * `want !== ''`, isWildcardSeg. It is the wrong reading for the VALUE an
 * action carries: a `type`/`fill` whose text is still `{{v2}}` puts those
 * five characters into a live field, and a goto navigates to the literal. See
 * `fillableChain` for why a locator chain is judged differently.
 */
function unfilledSlots(value: unknown, params: Record<string, string>): string[] {
  const out: string[] = [];
  const walk = (v: unknown): void => {
    if (typeof v === 'string') {
      for (const m of v.matchAll(/\{\{([vd]\d+)\}\}/g)) {
        if (!(m[1] in params) && !out.includes(m[1])) out.push(m[1]);
      }
      return;
    }
    if (Array.isArray(v)) {
      for (const item of v) walk(item);
      return;
    }
    if (v && typeof v === 'object') for (const item of Object.values(v as Record<string, unknown>)) walk(item);
  };
  walk(value);
  return out;
}

/**
 * Any `{{…}}` marker that is not the wildcard — the same reading as
 * `expect.ts`'s UNFILLED_MARKER, restated here because this module may import
 * nothing but a sibling.
 *
 * The NAME must differ from expect.ts's. Both modules are embedded VERBATIM,
 * side by side, into the compiled artifact, so two file-scope `const`s sharing
 * a name are one `SyntaxError: Identifier 'UNFILLED_MARKER' has already been
 * declared` and every emitted flow fails to import — which is exactly what the
 * parity suite caught. A shared reading is fine; a shared identifier is not.
 * (`g` here, unlike expect.ts's, because this one is used with `matchAll`.)
 */
const UNRESOLVED_ARG_MARKER = /\{\{(?!\*\}\}|(?:env|totp):\w+\}\})[^{}]*\}\}/g;

/**
 * A `{{env:NAME}}` secret marker (shared/secrets.ts's syntax, restated: this
 * module imports siblings only). Not an unresolved reference: the executor
 * resolves it at dispatch and only there, so it is exempt from the broad
 * reading above — which is what sent every README-style sign-in (credentials
 * as `{{env:APP_PASSWORD}}`) to the model on every replay. What CAN stop the
 * step is an environment with nothing to resolve it to (`unsetSecrets`).
 */
// `{{totp:NAME}}` (execution/totp.ts) is the same kind of marker: the one-time
// code for the seed in NAME, generated at dispatch — exempt, and refused by
// NAME when the environment has no seed.
const SECRET_ARG_MARKER = /\{\{(?:env|totp):(\w+)\}\}/g;

/**
 * The secret variables a value names that the environment leaves unset or
 * empty — resolveSecrets' refusal, asked before anything is dispatched.
 * Names only: the value is never read into a message.
 */
function unsetSecrets(value: unknown, params: Record<string, string>): string[] {
  const out: string[] = [];
  const walk = (v: unknown): void => {
    if (typeof v === 'string') {
      for (const m of fillParams(v, params).matchAll(SECRET_ARG_MARKER)) {
        if (!process.env[m[1]] && !out.includes(m[1])) out.push(m[1]);
      }
      return;
    }
    if (Array.isArray(v)) {
      for (const item of v) walk(item);
      return;
    }
    if (v && typeof v === 'object') for (const item of Object.values(v as Record<string, unknown>)) walk(item);
  };
  walk(value);
  return out;
}

/**
 * Every marker still standing in a value once this run's params are in — the
 * BROAD reading, and the one `expect.ts:unfilledSlot` has taken for some time
 * (its `{{02-open.product_name}}` case, fwod49-n2). Returned as the marker text
 * (`{{03-create.product_name}}`), not a slot name, because the thing left
 * standing need not be a slot.
 *
 * WHY THE ARGS ARM NEEDS THIS AND `unfilledSlots` CANNOT GIVE IT.
 * `fillParams` is a SINGLE PASS: a param bound to the string
 * `"{{03-create.product_name}}"` substitutes that text into the args and
 * nothing re-scans the result. `unfilledSlots` asks `name in params`, and the
 * slot IS in params — bound, just bound to a placeholder — so it is
 * structurally unable to see this. The daemon has no `{{stepId.output}}`
 * diagnosis of its own either: `emit.ts`'s `need`/`unsourced-ref` is compile
 * time only. fwod56's witness: `10-verify` pinned a chain head whose `v4` held
 * `{{05-open.quotation_reference}}`, and segment 3 of that chain types `{{v4}}`
 * into odoo's search box — 31 characters of marker text, as real keystrokes.
 *
 * ACTIONS MUST NOT BE LAXER THAN ASSERTIONS. An expectation over a line this
 * run could not fill is dropped; an action carrying one would be dispatched.
 * The wildcard is excluded because it is deliberate (lineShows matches it
 * against anything), and a value bound to '' leaves no marker at all, so the
 * "bound to '' is BOUND" rule (url.ts's `unfilled`) survives untouched.
 */
function unresolvedArgMarkers(value: unknown, params: Record<string, string>): string[] {
  const out: string[] = [];
  const walk = (v: unknown): void => {
    if (typeof v === 'string') {
      // Filled here rather than trusted to the caller: replay hands this
      // already-substituted args and the predicate must answer the same for
      // both, and `fillParams` over filled text is a no-op by construction.
      for (const m of fillParams(v, params).matchAll(UNRESOLVED_ARG_MARKER)) {
        if (!out.includes(m[0])) out.push(m[0]);
      }
      return;
    }
    if (Array.isArray(v)) {
      for (const item of v) walk(item);
      return;
    }
    if (v && typeof v === 'object') for (const item of Object.values(v as Record<string, unknown>)) walk(item);
  };
  walk(value);
  return out;
}

/**
 * A recorded locator chain less the rungs this run could not fill.
 *
 * A CHAIN IS A PREFERENCE ORDER, NOT A CONJUNCTION. Its rungs are the ways
 * the recording could name one element, best first, and the resolver takes the
 * first that matches (execution/resolve.ts). A rung carrying a slot this run
 * has no value for — odoo fwod34's `#name_{{d2}}`, where `d2` is a url-pattern
 * wildcard and not a value at all — cannot match anything once `fillParams`
 * leaves the marker standing, so it is not a defect in the step: it is one
 * exhausted preference, dropped, and the `role`/`placeholder` rungs behind it
 * take the step exactly as they were recorded to.
 *
 * Only a chain whose EVERY rung is dead leaves the step with no way to name
 * its element, and that is the case a runner must act on.
 */
function fillableChain<T>(chain: readonly T[] | undefined, params: Record<string, string>): T[] {
  return (chain ?? []).filter((rung) => !unfilledSlots(rung, params).length);
}

/** A step as this verdict reads it: the values it carries, and the chains it resolves through. */
interface UnfilledStep {
  args?: unknown;
  locators?: Record<string, readonly unknown[] | undefined>;
}

/**
 * Why a step that ACTS must not act, or null when nothing stops it. The caller
 * decides what "acts" means for it (a type, fill, click, select, goto) — a
 * read, a wait and a check keep the "asks for nothing" reading and never ask
 * this.
 *
 * The split inside the step is the point, and it is not the same question
 * twice:
 *  - the ARGS carry the value the step acts WITH. ANY marker left standing
 *    there once the params are in is fatal — an unbound slot (unfilledSlots)
 *    or a slot bound to an unresolved reference (unresolvedArgMarkers, the
 *    reading expect.ts takes of a recorded line). There is no second choice,
 *    and the step would type or navigate to the literal marker text. An action
 *    must not be laxer than an assertion about the same run.
 *  - a LOCATOR CHAIN is how the step names WHAT to act on, in preference
 *    order. An unfilled rung is dropped (fillableChain); only an entirely dead
 *    chain is fatal, and then because the step has no way left to find its
 *    target, not because a marker survived.
 *
 * Since bindSkill stopped guessing a split between two adjacent slots and left
 * both unbound instead, the args case is reachable rather than theoretical.
 * What each runner DOES about it differs — daemon replay falls back to the
 * model, the artifact has no model and refuses at compile time — but the
 * question is this one, asked here, once.
 */
function unfilledStepVerdict(step: UnfilledStep, params: Record<string, string>, where: string): string | null {
  const said = (slots: string[]): string => slots.map((s) => `{{${s}}}`).join(', ');
  const inArgs = unfilledSlots(step.args, params);
  if (inArgs.length) {
    return `${where}: ${said(inArgs)} ${inArgs.length > 1 ? 'were' : 'was'} left unbound — this run has no value for ${inArgs.length > 1 ? 'those slots' : 'that slot'}, and the step would otherwise act on the literal marker text`;
  }
  // The second reading of the same question, and only over the args: a slot
  // that IS bound, to a reference nothing resolved. See unresolvedArgMarkers.
  const leftInArgs = unresolvedArgMarkers(step.args, params);
  if (leftInArgs.length) {
    const many = leftInArgs.length > 1;
    return `${where}: ${leftInArgs.join(', ')} ${many ? 'are' : 'is'} still unresolved after this run's params were filled in — ${
      many ? 'those markers name values' : 'that marker names a value'
    } nothing published, and the step would otherwise act on the literal marker text`;
  }
  // A secret marker is resolved at dispatch; one the environment cannot
  // resolve stops here, by NAME, before the step types anything.
  const unset = unsetSecrets(step.args, params);
  if (unset.length) {
    const many = unset.length > 1;
    return `${where}: the environment variable${many ? 's' : ''} ${unset.join(', ')} ${many ? 'are' : 'is'} not set (the step's secret marker${
      many ? 's name them' : ' names it'
    }) — set ${many ? 'them' : 'it'} where this runs (for the daemon, before the session starts)`;
  }
  for (const [key, chain] of Object.entries(step.locators ?? {})) {
    if (!chain?.length || fillableChain(chain, params).length) continue;
    return `${where}: every recorded locator for ${key} names ${said(unfilledSlots(chain, params))}, which this run could not fill — the step has no way left to name the element it acts on`;
  }
  return null;
}

/**
 * The parts of the live url that name THIS run's record, or null when the url
 * cannot say. A record part is one the pattern fills from a param or a minted
 * value (`/d/:var/{{v2}}-bench-dashboard`, `edit?id={{d1}}`, `#id={{d1}}`):
 * the compiler put a marker there because the recording's record lived there.
 * Every such part must be bound and equal, filled, to the live url's part, and
 * the url must be the pattern's page shape at all (urlDiff; a literal that
 * differs elsewhere is a volatile id, which the precondition gate judged
 * already). A pattern with no marker part — `:id`/`:var` wildcards match every
 * record — names no record, and neither does a marker left unbound.
 */
function urlRecordParts(pattern: string | undefined, url: string, params: Record<string, string>): string[] | null {
  if (!pattern) return null;
  const filledPattern = fillParams(pattern, params);
  const raw = urlShapeOf(pattern);
  const want = urlShapeOf(filledPattern);
  const live = urlShapeOf(url);
  if (!raw || !want || !live) return null;
  // A param value carrying '/' shifts segment positions between the raw and
  // filled pattern; positions then no longer say which part is the record.
  if (raw.path.length !== want.path.length || raw.hashPath.length !== want.hashPath.length) return null;
  if (!urlDiff(filledPattern, url, boundQueryKeys(pattern, params))) return null;
  const marked = /\{\{[vd]\d+\}\}/;
  const parts: string[] = [];
  const judge = (recorded: string | undefined, expected: string | undefined, actual: string | undefined, label: string): boolean => {
    if (recorded === undefined || !marked.test(recorded)) return true;
    if (expected === undefined || !expected.trim() || /\{\{/.test(expected) || [...recorded.matchAll(/\{\{([vd]\d+)\}\}/g)].some((m) => !params[m[1]])) return false;
    if (actual !== expected) return false;
    // The message travels (describeUrl's note): a credential key's value never does.
    parts.push(`${label}=${CREDENTIAL_KEY.test(label) ? '***' : clip(actual, 40)}`);
    return true;
  };
  for (const [i, seg] of raw.path.entries()) if (!judge(seg, want.path[i], live.path[i], `path[${i}]`)) return null;
  for (const [key, val] of raw.query) if (!judge(val, want.query.get(key), live.query.get(key), key)) return null;
  for (const [i, seg] of raw.hashPath.entries()) if (!judge(seg, want.hashPath[i], live.hashPath[i], `#[${i}]`)) return null;
  for (const [key, val] of raw.hashState) if (!judge(val, want.hashState.get(key), live.hashState.get(key), `#${key}`)) return null;
  return parts.length ? parts : null;
}

/**
 * How long a runner waits for a BOUND identity marker to appear before it
 * judges which record the page is, and the cadence of that wait. A page that
 * has not finished arriving cannot say which record it is: fwgr47-n2
 * 07-verify stopped on the RIGHT dashboard (its own verifier reported uid
 * bfyfuaptu20aoa PASS) because step 1 was a `goto` to a bare dashboard url
 * that grafana normalises a moment later, and the gate looked during the
 * boot. Stated here because BOTH runners must wait the same: the compiled
 * artifact polls it (spec/emit.ts identityChecks) and daemon replay polls it
 * (skills/replay.ts checkIdentity) — a rule only one runner applies is the
 * class of defect the parity harness exists to catch.
 */
const IDENTITY_WAIT_MS = 5_000;

/** Cadence of that wait, for a runner with no poll helper of its own. */
const IDENTITY_POLL_MS = 100;

interface IdentityMarkerVerdict {
  /** The segment may run. */
  pass: boolean;
  /** Passed on the url's word while the marker was not seen: the marker is stale. */
  warning?: string;
}

/**
 * One identity marker, judged. Present passes. Not seen ('absent', or a look
 * that could not establish absence — 'unknown') refuses — unless the live url
 * already names this run's record (urlRecordParts): then the url has answered
 * "which record" and the marker is only a stale description of the page, so
 * it warns and the segment runs. Markers still decide wherever the url cannot
 * tell records apart.
 *
 * fwgr39-n3 05-set refused s_6108b1 on the RIGHT dashboard — its url carried
 * this run's own slug, `{{v2}}-bench-dashboard` — because its second marker was
 * "Last 6 hours", a time-range setting the settings view does not render: a
 * state, not a name, and not the question the url had already answered.
 *
 * `url` must be the url as it reads AFTER the runner's identity wait
 * (IDENTITY_WAIT_MS), not the one the first look saw. The escape hatch was
 * unavailable to fwgr47-n2 at the first look for a reason that expires: the
 * pattern's bound query keys (from, to) were missing from a url the app had
 * not rewritten yet, so urlDiff — and with it urlRecordParts — said null.
 * Asking again once the wait is spent costs nothing and is the same question
 * the app has by then answered; one step earlier the SAME app warn-and-
 * proceeded twice on exactly this fallback.
 */
function identityMarkerVerdict(
  pattern: string | undefined,
  url: string,
  params: Record<string, string>,
  want: string,
  presence: 'present' | 'absent' | 'unknown',
): IdentityMarkerVerdict {
  if (presence === 'present') return { pass: true };
  const parts = urlRecordParts(pattern, url, params);
  if (!parts) return { pass: false };
  const seen = presence === 'unknown' ? 'could not be confirmed on the page' : 'is not on the page';
  return {
    pass: true,
    warning: `identity marker ${JSON.stringify(clip(want, 60))} ${seen}, but the url names this run's record (${parts.join(', ')}) — the marker is stale; proceeding`,
  };
}

// Shared execution source: facts-route.ts. Regenerate to update.
/**
 * SITE FACTS, URL ROUTE DECISIONS (stage 1, Piece F of the stage 1 contract;
 * design-site-facts.md §2 consumers 1-2): the pure verdicts the url route
 * consumers take from the facts, moved here from skills/facts-url.ts so that
 * BOTH runners decide identically — the daemon's replay from the live store's
 * snapshot, the compiled artifact from the snapshot it carries
 * (`siteFactsAt(url)`). The artifact embeds this exact source
 * (spec/runtime-source.ts), so it imports its siblings and nothing else.
 *
 * Reliable or nothing: every verdict here reads the facts through
 * `routeQueryFact` / `fragmentFact`, which only ever return a RELIABLE fact.
 * Where no reliable fact decides, the `…WithFacts` forms return today's
 * verdict, computed by the very call they replace — byte-identical.
 */

// ---------------------------------------------------------------------------
// query rewriting and key comparison
// ---------------------------------------------------------------------------

/** `a=1&b=2` with `fn` applied to each pair, textually: an unchanged pair is kept exactly as written. */
function rewritePairs(text: string, fn: (key: string, value: string) => string | null): string[] {
  const kept: string[] = [];
  for (const pair of text.split('&')) {
    if (!pair) continue;
    const eq = pair.indexOf('=');
    const rawKey = eq < 0 ? pair : pair.slice(0, eq);
    const value = eq < 0 ? '' : pair.slice(eq + 1);
    const next = fn(safeDecode(rawKey), safeDecode(value));
    if (next === null) continue;
    kept.push(next === safeDecode(value) ? pair : `${rawKey}=${next}`);
  }
  return kept;
}

/**
 * Rewrite a url's (or url pattern's) query AND its hash state in place,
 * textually, so slot markers, a route or anchor fragment and every untouched
 * pair are left exactly as written: `fn` returns the new value for a key, or
 * null to drop the pair. A state fragment (odoo's `#action=123&cids=1`) is
 * query-like and is rewritten the same way, keeping its `#a=b&c=d` shape (and
 * dropped whole when no pair is left); a route (`#/a/b`) or an anchor
 * (`#history`) fragment is not a set of keys and is left alone.
 */
function rewriteQuery(url: string, fn: (key: string, value: string) => string | null): string {
  const hashAt = url.indexOf('#');
  const head = hashAt >= 0 ? url.slice(0, hashAt) : url;
  let hash = hashAt >= 0 ? url.slice(hashAt) : '';
  const body = hash.slice(1);
  const stateEnd = body.indexOf('?') >= 0 ? body.indexOf('?') : body.length;
  const state = body.slice(0, stateEnd);
  if (state && !state.startsWith('/') && state.includes('=')) {
    const kept = rewritePairs(state, fn);
    const tail = body.slice(stateEnd);
    hash = kept.length || tail ? `#${kept.join('&')}${tail}` : '';
  }
  const q = head.indexOf('?');
  if (q < 0) return `${head}${hash}`;
  const kept = rewritePairs(head.slice(q + 1), fn);
  return `${head.slice(0, q)}${kept.length ? `?${kept.join('&')}` : ''}${hash}`;
}

/** A query value that asks for one particular value: not empty, not a wildcard, not a slot. */
function literal(v: string | undefined): v is string {
  return v !== undefined && v !== '' && !isWildcardSeg(v) && !/\{\{/.test(v);
}

/**
 * A key's value on a url: its query value, else its hash-state value. Odoo
 * keeps its view state in the fragment (`#action=123&cids=1&menu_id=81`), and
 * its facts are keyed `${route}?${key}` exactly as a query key's are.
 */
function keyValue(s: UrlShape, k: string): string | undefined {
  return s.query.get(k) ?? s.hashState.get(k);
}

/** A url names the key, in its query or its hash state. */
function hasKey(s: UrlShape, k: string): boolean {
  return s.query.has(k) || s.hashState.has(k);
}

/** Query (and hash-state) keys the two urls do not agree on: one side only, or two literals. */
function disputedKeys(a: UrlShape, b: UrlShape): { oneSided: string[]; differing: string[] } {
  const oneSided: string[] = [];
  const differing: string[] = [];
  for (const k of new Set([...a.query.keys(), ...a.hashState.keys(), ...b.query.keys(), ...b.hashState.keys()])) {
    const x = keyValue(a, k);
    const y = keyValue(b, k);
    if (x === undefined || y === undefined) oneSided.push(k);
    else if (literal(x) && literal(y) && x !== y) differing.push(k);
  }
  return { oneSided, differing };
}

/** Every route.query fact about `key` on either url's route, each once. */
function queryFacts(sf: SiteFacts, urls: readonly string[], key: string): Fact[] {
  const routes = [...new Set(urls.map((u) => routeTemplateOf(u)))];
  return routes.flatMap((r) => factsFor(sf, 'route.query', `${r}?${key}`));
}

/** The reliable route.query verdict for a key on either url's route (the first url's route first). */
function queryKind(sf: SiteFacts, urls: readonly string[], key: string): 'state' | 'identity' | 'routing' | null {
  for (const u of urls) {
    const kind = routeQueryFact(sf, u, key);
    if (kind) return kind;
  }
  return null;
}

// ---------------------------------------------------------------------------
// consumer 1: routesAgree (learn.ts pinEndsElsewhere)
// ---------------------------------------------------------------------------

type RoutesAgree = (start: string, end: string, byFragment: boolean) => boolean;

/**
 * routesAgree decided by facts, with today's rule (`today`) for everything a
 * fact does not settle: a query key of reliable `state` is dropped from both
 * sides (it never separates routes), a key of reliable `routing` that only
 * one side carries as a literal separates them (both sides' literals are
 * already compared by today's rule), and a reliable `route.fragment` replaces
 * routesByFragment's guess (a `path` or `state` fragment is a route, an
 * `anchor` is not). Null when no fact, reliable or not, bears on the pair.
 */
function routesAgreeByFacts(sf: SiteFacts, start: string, end: string, byFragment: boolean, today: RoutesAgree): { agree: boolean; decided: boolean; relevant: Fact[] } | null {
  const a = urlShapeOf(start);
  const b = urlShapeOf(end);
  const relevant: Fact[] = [];
  const fragmented = start.includes('#') || end.includes('#');
  if (fragmented) relevant.push(...factsFor(sf, 'route.fragment', ''));
  const disputed = a && b ? disputedKeys(a, b) : { oneSided: [], differing: [] };
  const keys = [...disputed.oneSided, ...disputed.differing];
  for (const k of keys) relevant.push(...queryFacts(sf, [start, end], k));
  if (!relevant.length) return null;
  const frag = fragmented ? fragmentFact(sf) : null;
  const byFragmentF = frag ? frag !== 'anchor' : byFragment;
  const kinds = new Map(keys.map((k) => [k, queryKind(sf, [start, end], k)] as const));
  const decided = relevant.some(reliable) && (frag !== null || [...kinds.values()].some((v) => v === 'state' || v === 'routing'));
  const routingSplit = disputed.oneSided.some((k) => kinds.get(k) === 'routing' && (literal(keyValue(a!, k)) || literal(keyValue(b!, k))));
  if (routingSplit) return { agree: false, decided, relevant };
  const drop = (u: string) => rewriteQuery(u, (k, v) => (kinds.get(k) === 'state' ? null : v));
  return { agree: today(drop(start), drop(end), byFragmentF), decided, relevant };
}

// ---------------------------------------------------------------------------
// consumer 2a: the goto landing (replay.ts gotoLanding, the artifact's goto check)
// ---------------------------------------------------------------------------

/** At most 40 characters of a value in a message, as gates.ts clips one. */
function shown40(v: string | undefined): string {
  if (v === undefined) return '(absent)';
  return v.length > 40 ? `${v.slice(0, 39)}…` : v;
}

interface LandingDecision {
  stop: boolean;
  decided: boolean;
  relevant: Fact[];
  /** The stop's message when the facts decided it, unprefixed; null when the landing passes. */
  message: string | null;
}

function landingDecision(sf: SiteFacts, target: string, landed: string, where: string): LandingDecision | null {
  const t = urlShapeOf(target);
  const l = urlShapeOf(landed);
  if (!t || !l || t.origin !== l.origin) return null;
  const { oneSided, differing } = disputedKeys(t, l);
  const keys = [...oneSided, ...differing];
  const relevant = keys.flatMap((k) => queryFacts(sf, [landed, target], k));
  if (!relevant.length) return null;
  const kinds = new Map(keys.map((k) => [k, queryKind(sf, [landed, target], k)] as const));
  const decided = [...kinds.values()].some((v) => v === 'state' || v === 'routing');
  const split = oneSided.filter((k) => kinds.get(k) === 'routing' && (literal(keyValue(t, k)) || literal(keyValue(l, k))));
  const asked = rewriteQuery(target, (k, v) => (kinds.get(k) === 'state' ? null : v));
  const byRule = gotoLandingVerdict(asked, landed, where);
  let message = byRule;
  if (message === null && split.length) {
    const said = split.map((k) => `${k}=${shown40(keyValue(l, k))} where it was sent to ${k}=${shown40(keyValue(t, k))}`).join(', ');
    message = `${where} navigated but landed on another view: ${said} (route.query ${split.join(', ')} selects the page on this route) — the page it asked for was not given`;
  }
  return { stop: message !== null, decided, relevant, message };
}

/**
 * gotoLandingVerdict decided by facts: a key of reliable `state` never makes
 * a landing "another view", whatever its two literals; a key of reliable
 * `routing` the target asked for (a literal) and the landing lacks, or the
 * landing carries and the target did not ask for, does. Null when no
 * route.query fact exists for a disputed key.
 */
function landingByFacts(sf: SiteFacts, target: string, landed: string): { stop: boolean; decided: boolean; relevant: Fact[] } | null {
  const d = landingDecision(sf, target, landed, '');
  return d ? { stop: d.stop, decided: d.decided, relevant: d.relevant } : null;
}

/**
 * Where a goto landed, as both runners judge it: `gotoLandingVerdict` unless
 * a reliable `route.query` fact decides a key the two urls dispute — then the
 * facts' verdict (landingByFacts), its stop written as gotoLandingVerdict
 * would write it and prefixed "by fact: ". Byte-identical to
 * gotoLandingVerdict when no reliable fact decides.
 */
function landingVerdictWithFacts(sf: SiteFacts, target: string, landed: string, where: string): string | null {
  const d = landingDecision(sf, target, landed, where);
  if (!d || !d.decided) return gotoLandingVerdict(target, landed, where);
  return d.message === null ? null : `by fact: ${d.message}`;
}

// ---------------------------------------------------------------------------
// consumer 2b: the precondition gate (replay.ts passGate, the artifact's runFlow)
// ---------------------------------------------------------------------------

/** The url without its fragment when the fragment is a bare in-page anchor (`#history`); otherwise unchanged. */
function withoutAnchor(url: string): string {
  const shape = urlShapeOf(url);
  if (!shape || shape.hashKind !== 'path' || !shape.hashAnchor) return url;
  const at = url.indexOf('#');
  return at >= 0 ? url.slice(0, at) : url;
}

/** The pattern with `key=:var` appended for each key, ahead of any fragment. */
function withWildKeys(pattern: string, keys: readonly string[]): string {
  if (!keys.length) return pattern;
  const hashAt = pattern.indexOf('#');
  const head = hashAt >= 0 ? pattern.slice(0, hashAt) : pattern;
  const hash = hashAt >= 0 ? pattern.slice(hashAt) : '';
  const pairs = keys.map((k) => `${encodeURIComponent(k)}=:var`).join('&');
  const sep = !head.includes('?') ? '?' : head.endsWith('?') || head.endsWith('&') ? '' : '&';
  return `${head}${sep}${pairs}${hash}`;
}

interface PreconditionDecision {
  verdict: PreconditionVerdict;
  decided: boolean;
  relevant: Fact[];
}

function preconditionDecision(
  sf: SiteFacts,
  pattern: string,
  url: string,
  params: Record<string, string>,
  similarity: FingerprintSimilarity,
  mints: MintedPosition[],
): PreconditionDecision | null {
  const p = urlShapeOf(pattern);
  const l = urlShapeOf(url);
  if (!p || !l || p.origin !== l.origin) return null;
  const { oneSided, differing } = disputedKeys(p, l);
  const keys = [...oneSided, ...differing];
  const relevant = keys.flatMap((k) => queryFacts(sf, [url, pattern], k));
  // A bare anchor on either side, on an origin whose fragments are known anchors.
  const anchored = (p.hashKind === 'path' && Boolean(p.hashAnchor)) || (l.hashKind === 'path' && Boolean(l.hashAnchor));
  const sameOrigin = sf.origin === originOf(url);
  if (anchored && sameOrigin) relevant.push(...factsFor(sf, 'route.fragment', ''));
  if (!relevant.length) return null;
  const kinds = new Map(keys.map((k) => [k, queryKind(sf, [url, pattern], k)] as const));
  const anchor = anchored && sameOrigin && fragmentFact(sf) === 'anchor';
  const decided = anchor || [...kinds.values()].some((v) => v === 'state' || v === 'routing');
  // Widen: every reliable `state` key the pattern names (query or hash state)
  // becomes `:var`, and a query key only the live url carries is named as
  // `:var` — view state never separates pages, on either side. (A hash-state
  // key only the live url carries already passes: state accumulates.)
  const state = (k: string) => kinds.get(k) === 'state';
  let widened = rewriteQuery(pattern, (k, v) => (state(k) ? ':var' : v));
  widened = withWildKeys(widened, oneSided.filter((k) => state(k) && !hasKey(p, k) && l.query.has(k)));
  const judged = anchor ? withoutAnchor(url) : url;
  if (anchor) widened = withoutAnchor(widened);
  const verdict = preconditionVerdict(widened, judged, params, similarity, mints);
  const split = oneSided.filter((k) => kinds.get(k) === 'routing' && (literal(keyValue(p, k)) || literal(keyValue(l, k))));
  if (verdict.refuse || !split.length) return { verdict, decided, relevant };
  const shown = shownPattern(pattern, params);
  const sides = split.map((k) => `${k} (${hasKey(p, k) ? 'the procedure names it, the page lacks it' : 'the page carries it, the procedure does not name it'})`).join(', ');
  return {
    verdict: {
      warnings: [],
      refuse: `not on the page this procedure starts from (expects ${shown}, browser is at ${describeUrl(url, shown)}; by fact: query key ${sides} selects the page on this route — route.query routing — and only one side carries it)`,
    },
    decided,
    relevant,
  };
}

/**
 * The precondition gate decided by facts: the pattern with every reliable
 * `state` key written `:var` (stage 1's pattern rewrite), and a bare anchor
 * stripped from both sides on an origin whose fragments are reliable anchors,
 * judged by the same preconditionVerdict; then a reliable `routing` key one
 * side carries alone refuses. Null when no fact bears on a disputed key or an
 * anchor.
 */
function preconditionByFacts(
  sf: SiteFacts,
  pattern: string,
  url: string,
  params: Record<string, string>,
  similarity: FingerprintSimilarity,
  mints: MintedPosition[],
): { refuse: boolean; decided: boolean; relevant: Fact[] } | null {
  const d = preconditionDecision(sf, pattern, url, params, similarity, mints);
  return d ? { refuse: Boolean(d.verdict.refuse), decided: d.decided, relevant: d.relevant } : null;
}

/**
 * Where a segment starts, as both runners judge it: `preconditionVerdict`
 * unless a reliable `route.query` (`state`, `routing`) or `route.fragment`
 * (`anchor`) fact decides — then preconditionByFacts' verdict, in full
 * (warnings, `soft`, `past`). Byte-identical to preconditionVerdict when no
 * reliable fact decides.
 */
function preconditionVerdictWithFacts(
  sf: SiteFacts,
  pattern: string,
  url: string,
  params: Record<string, string>,
  similarity: FingerprintSimilarity,
  mints: MintedPosition[] = [],
): PreconditionVerdict {
  const d = preconditionDecision(sf, pattern, url, params, similarity, mints);
  if (!d || !d.decided) return preconditionVerdict(pattern, url, params, similarity, mints);
  return d.verdict;
}

// Shared execution source: browser.ts. Regenerate to update.
/** Browser execution shared by replay and the standalone spec bundle. */

/**
 * The bound on every actionability call the shared execution code makes
 * without a tighter one of its own: playwright-core's library default, the
 * one the daemon's pages have always run under. Said explicitly, because the
 * compiled artifact runs under Playwright Test, whose actionTimeout and
 * navigationTimeout default to 0 — unbounded — so a call that leaned on the
 * library default waited forever there (fwgr70). The emitted runFlow also sets
 * it as the page's default (spec/emit.ts), for whatever the embedded code
 * does not bound itself; test/execution-source.test.ts refuses a new bare call.
 */
const DEFAULT_ACTION_TIMEOUT_MS = 30_000;

/**
 * The urls a page's main frame shows while a flow step runs, in order — its
 * url trail, for url outputs the step publishes from a url it VISITED but did
 * not end on (url.ts visitedUrlPart; ghost fwgh14's editor autosave routed to
 * `#/editor/post/<id>` before the step went back to the posts list). Same-
 * document navigations (a hash route, pushState) count: Playwright reports them
 * as frame navigations too. Both runners keep one per flow step; `stop()`
 * detaches the listener.
 */
function urlTrail(page: Page): { urls: string[]; stop(): void } {
  const urls: string[] = [];
  const note = (url: string) => {
    if (url && urls[urls.length - 1] !== url) urls.push(url);
  };
  try {
    note(page.url());
  } catch {
    /* a page that cannot say where it is starts an empty trail */
  }
  const onNavigated = (frame: { url(): string }) => {
    try {
      if (frame === (page.mainFrame() as unknown)) note(frame.url());
    } catch {
      /* a detached frame adds nothing */
    }
  };
  page.on('framenavigated', onNavigated);
  return {
    urls,
    stop: () => {
      page.off('framenavigated', onNavigated);
    },
  };
}

/**
 * What is known about an action once it has been attempted (notes/ROBUSTNESS.md
 * finding 2). The four are different facts, and every caller that decides
 * whether something may be tried again needs to tell them apart:
 *  - `not-dispatched`: there is PROOF nothing reached the app (Playwright's
 *    actionability wait gave up before the pointer event, the control is
 *    disabled, the deadline ran out before a tier began). Another attempt
 *    repeats nothing.
 *  - `dispatched`: the action went out; whether it had its effect is for the
 *    effect gates to say.
 *  - `effect-verified`: it went out and its expected effect was seen.
 *  - `unknown`: it may or may not have reached the app (the page was torn down
 *    under it, or the failure carries no proof either way). Never repeat it.
 *
 * Carried on the error a failed action throws (`actionFailure`), never parsed
 * out of its words: the message is written for a model and a person, and is
 * free to change.
 */
type ActionOutcome = 'not-dispatched' | 'dispatched' | 'effect-verified' | 'unknown';

/** Which way a dispatched action went out. */
type DispatchVia = 'actionable' | 'forced' | 'synthetic' | 'rerender-window' | 'native';

/** Why an action failed, for a caller that wants more than its outcome. */
type ActionFailureReason = 'disabled' | 'teardown' | 'strict' | 'never-attached' | 'rerender' | 'timeout' | 'deadline' | 'not-an-input';

/** An error that says what is known about the action that threw it. */
interface ActionFailure extends Error {
  actionOutcome: 'not-dispatched' | 'unknown';
  actionReason: ActionFailureReason;
}

/**
 * Tag a failure with its outcome. Given an Error, that same object is tagged
 * and returned — a caller that compares identity (or reads Playwright's own
 * message) sees the error it would have seen untagged.
 */
function actionFailure(outcome: 'not-dispatched' | 'unknown', reason: ActionFailureReason, error: string | Error): ActionFailure {
  const failure = (typeof error === 'string' ? new Error(error) : error) as ActionFailure;
  failure.actionOutcome = outcome;
  failure.actionReason = reason;
  return failure;
}

/**
 * The outcome a thrown error establishes. Only a tagged failure can say
 * `not-dispatched`: anything else carries no proof that nothing happened, so
 * it is `unknown`, the direction that never repeats an action.
 */
function outcomeOfError(err: unknown): 'not-dispatched' | 'unknown' {
  const tagged = err && typeof err === 'object' ? (err as Partial<ActionFailure>).actionOutcome : undefined;
  return tagged === 'not-dispatched' ? 'not-dispatched' : 'unknown';
}

/** The outcome as it reads beside a failure: `[outcome: not dispatched]`. */
function outcomeLabel(outcome: ActionOutcome): string {
  return `[outcome: ${outcome.replace(/-/g, ' ')}]`;
}

/**
 * What a click is told about the action it belongs to (src/execution/action.ts
 * `beginAction`): how much of the action's deadline is left, which clamps every
 * tier, and where to report the way the click went out.
 */
interface ClickObservation {
  remaining(): number;
  dispatched?(via: DispatchVia): void;
  /**
   * The clicked element is a link that navigates this tab to `href` (absolute,
   * another document than the one it is on): told BEFORE the click goes out,
   * so the settle can wait on the navigation the link itself promises.
   */
  linkTarget?(href: string): void;
}

type ClickOpts = { timeout: number; dbl?: boolean; obs?: ClickObservation };
type ClickAct = (o: { timeout: number; force?: boolean }) => Promise<void>;

/**
 * One way to land a click. `note` is appended to the result so the agent (and
 * a post-mortem) can see which tier did the work.
 */
interface ClickTier {
  note: string;
  via: DispatchVia;
  run: (loc: Locator, opts: ClickOpts, act: ClickAct) => Promise<void>;
}

/**
 * The tiers a click falls through, in order. Each is tried when the one
 * before it failed; the window tier (fireWhenAttached) comes last and its own
 * error is what the agent sees, because it is the only tier that can explain
 * WHY nothing landed.
 */
const CLICK_TIERS: ClickTier[] = [
  // Playwright's own click, actionability checks and all.
  { note: '', via: 'actionable', run: (_loc, opts, act) => act({ timeout: opts.timeout }) },
  // Scroll into view and skip the checks: a control under a sticky header,
  // or one an overlay covers in a way the app treats as fine.
  {
    note: ' (forced past actionability checks)',
    via: 'forced',
    run: async (loc, opts, act) => {
      await loc.scrollIntoViewIfNeeded({ timeout: opts.timeout }).catch(() => {});
      await act({ timeout: opts.timeout, force: true });
    },
  },
  // A synthetic event straight at the element: React's delegated handlers see
  // it even when the element is not "clickable" by Playwright's rules.
  { note: ' (dispatched DOM event — element was not normally clickable)', via: 'synthetic', run: (loc, opts) => loc.evaluate(fireClick, Boolean(opts.dbl), { timeout: opts.timeout }) },
];

/**
 * The budget one tier (or the window tier) may spend: its own timeout, cut to
 * what is left of the action's deadline. Never 0 — Playwright reads a zero
 * timeout as "no timeout" — so a spent deadline is reported by the caller
 * before the tier starts, not passed down.
 */
function tierBudget(opts: ClickOpts): number {
  const left = opts.obs ? Math.floor(opts.obs.remaining()) : Infinity;
  return Math.min(opts.timeout, left);
}

/** The refusal for a deadline that ran out before the next way of clicking could start: nothing was dispatched. */
function deadlineSpent(label: string, because: string): ActionFailure {
  const cause = because ? ` (after: ${because.split('\n')[0].slice(0, 120)})` : '';
  return actionFailure(
    'not-dispatched',
    'deadline',
    `${label === 'clicked' ? 'click' : 'double-click'} NOT dispatched: the action's deadline ran out before the control could be clicked${cause}. Observe the page — something it was waiting on (an overlay, a load) never finished.`,
  );
}

async function robustClick(loc: Locator, opts: ClickOpts): Promise<string> {
  const label = opts.dbl ? 'double-clicked' : 'clicked';
  const act: ClickAct = (o) => (opts.dbl ? loc.dblclick(o) : loc.click(o));
  let firstFailure = '';
  let waitedForEnabled = false;
  // A target that matches NOTHING is settled first, in a few seconds, and
  // said plainly. Every tier below waits its whole timeout for an element
  // that is not there — Playwright's click for attached/visible, the forced
  // click for a box, the synthetic event for a node — so a stale snapshot
  // ref or a control the app only shows in some state cost the full action
  // deadline (fwod71-n1: Odoo's "Save manually" after the form re-rendered,
  // 30s and a turn, then the deadline refusal) before the agent learned
  // that nothing was clicked. One bounded wait for it to be attached at
  // all; a control that re-mounts every render is attached most of the
  // time and passes. Skipped where the locator cannot be asked (a port
  // without waitFor).
  const probe = typeof (loc as { waitFor?: unknown }).waitFor === 'function' ? Math.min(ABSENT_PROBE_MS, tierBudget(opts)) : 0;
  if (probe >= 1) {
    const attached = await loc
      .first()
      .waitFor({ state: 'attached', timeout: probe })
      .then(
        () => true,
        (err: unknown) => {
          const message = err instanceof Error ? err.message : String(err);
          if (UNCERTAIN_DISPATCH.test(message)) throw actionFailure('unknown', 'teardown', err instanceof Error ? err : message);
          return false;
        },
      );
    if (!attached) {
      throw actionFailure(
        'not-dispatched',
        'never-attached',
        `${label === 'clicked' ? 'click' : 'double-click'} NOT dispatched: no element matched the target within ${Math.round(probe / 1000)}s, so nothing was clicked. ` +
          'The page has moved on since this reference was taken (a re-render, a closed dialog, a control the app shows only in some state): take a fresh snapshot and click what is there now.',
      );
    }
  }
  await reportLinkTarget(loc, opts);
  for (let i = 0; i < CLICK_TIERS.length; i++) {
    const tier = CLICK_TIERS[i];
    // Every tier before this one failed in a way that proves nothing went out
    // (the throws below end the loop otherwise), so a deadline spent here is
    // a click that was never dispatched.
    const budget = tierBudget(opts);
    if (budget < 1) throw deadlineSpent(label, firstFailure);
    try {
      await tier.run(loc, { ...opts, timeout: budget }, act);
      opts.obs?.dispatched?.(tier.via);
      return `${label}${tier.note}`;
    } catch (err) {
      const failure = err instanceof Error ? err.message : String(err);
      firstFailure ||= failure;
      // Two or more matches is the agent's problem to fix, not a tier's.
      if (/strict mode violation/i.test(failure)) throw err instanceof Error ? actionFailure('not-dispatched', 'strict', err) : err;
      // A DISABLED control refused the click by design, and the tiers below
      // do not get past that: a forced click on a disabled button dispatches
      // nothing the app handles, yet returned "clicked (forced past
      // actionability checks)". Asked only once Playwright's own click has
      // failed, so an ordinary click costs nothing extra; an element that
      // cannot be asked (gone, re-rendering) goes on down the tiers as before.
      if (tier === CLICK_TIERS[0] && (await loc.isDisabled({ timeout: DISABLED_PROBE_MS }).catch(() => false))) {
        // A control disabled only while the page settles (a save button
        // enabled once the form hydrates) is timing, not a wrong procedure:
        // fwgr39-n3's refusal demoted a whole skill at step 1. Give it one
        // bounded wait, inside what is left of the action's deadline, then
        // retry Playwright's own click once — its failure proved nothing
        // went out, so the retry repeats nothing. Still disabled: refuse.
        if (!waitedForEnabled) {
          waitedForEnabled = true;
          const settleMs = Math.min(DISABLED_SETTLE_MS, tierBudget(opts));
          if (settleMs >= 1 && (await enabledWithin(loc, settleMs))) {
            i = -1;
            continue;
          }
        }
        throw actionFailure(
          'not-dispatched',
          'disabled',
          `${label === 'clicked' ? 'click' : 'double-click'} NOT dispatched: the control is disabled, so the app would ignore it. ` +
            'Make whatever enables it true first (a required field, a selection, a finished load), then click it.',
        );
      }
      // The page went out from under the click. Whether it landed is unknown,
      // so no further tier may fire: see UNCERTAIN_DISPATCH.
      if (UNCERTAIN_DISPATCH.test(failure)) {
        throw actionFailure(
          'unknown',
          'teardown',
          `${label === 'clicked' ? 'click' : 'double-click'} outcome UNKNOWN: the page was torn down during the action (${failure.split('\n')[0].slice(0, 160)}). It may already have taken effect. Do not repeat it — observe the app's state and continue from what you find.`,
        );
      }
      // A control the app re-mounts on every render never passes the
      // attached→visible→stable check, and a forced click needs it attached
      // at the instant of the action just the same — so both tiers lose the
      // race and burn their full timeout (rpgr4-r2 spent 74 turns on
      // grafana's viz-picker toggle this way). Only Playwright's own detach
      // evidence sends a click straight to the window tier: its generic
      // timeout log reads "waiting for element to be visible, enabled and
      // stable" for EVERY stalled click, and matching on that routed 15
      // ordinary replay clicks per run past the tiers that had been landing
      // them (rpgr5).
      if (DETACHED.test(failure)) break;
    }
  }
  return fireWhenAttached(loc, opts, label, firstFailure);
}

/** The most robustClick spends asking whether its target is a link, and where to. */
const LINK_PROBE_MS = 500;

/**
 * Tell the action's observation where the clicked element links to, when it
 * is a link that leaves this document in this tab — the element's own
 * statement of the navigation the click is about to start. Asked only of an
 * observation that listens, never fails the click, and costs one evaluate.
 */
async function reportLinkTarget(loc: Locator, opts: ClickOpts): Promise<void> {
  if (!opts.obs?.linkTarget || typeof (loc as { evaluate?: unknown }).evaluate !== 'function') return;
  const budget = Math.min(LINK_PROBE_MS, tierBudget(opts));
  if (budget < 1) return;
  const target = typeof (loc as { first?: unknown }).first === 'function' ? loc.first() : loc;
  const href = await target.evaluate(linkHrefOf, undefined, { timeout: budget }).catch(() => null);
  if (href) opts.obs.linkTarget(href);
}

/**
 * Runs in the page: the absolute url the element (or the link around it)
 * navigates this tab to, or null when a click on it does not leave the
 * document — no href, an in-page `#` anchor or hash route, `javascript:`, a
 * download, or a link that opens another tab or frame.
 */
function linkHrefOf(el: Element): string | null {
  const a = el.closest('a[href], area[href]') as HTMLAnchorElement | HTMLAreaElement | null;
  if (!a || a.hasAttribute('download')) return null;
  const target = (a.getAttribute('target') ?? '').trim().toLowerCase();
  if (target && target !== '_self') return null;
  let url: URL;
  try {
    url = new URL(a.href, document.baseURI);
  } catch {
    return null;
  }
  if (url.protocol !== 'http:' && url.protocol !== 'https:') return null;
  const here = new URL(document.location.href);
  url.hash = '';
  here.hash = '';
  return url.href === here.href ? null : a.href;
}

/** How long robustClick waits for a target to be attached at all before refusing it as absent. */
const ABSENT_PROBE_MS = 3_000;

/** How long robustClick asks whether a control that refused a click is disabled. */
const DISABLED_PROBE_MS = 500;

/** The most robustClick waits for a disabled control to become enabled before refusing it. */
const DISABLED_SETTLE_MS = 3_000;

/** Poll until the control reads enabled or `ms` passes. An element that cannot be asked counts as not enabled. */
async function enabledWithin(loc: Locator, ms: number): Promise<boolean> {
  const end = Date.now() + ms;
  for (;;) {
    const left = end - Date.now();
    if (left <= 0) return false;
    if (await Promise.resolve().then(() => loc.isEnabled({ timeout: Math.min(DISABLED_PROBE_MS, left) })).catch(() => false)) return true;
    await new Promise((r) => setTimeout(r, Math.min(100, Math.max(1, end - Date.now()))));
  }
}

/** Playwright's own words for an element that left the DOM mid-action — never its generic actionability wording. */
const DETACHED = /element was detached|not attached to the DOM|element is not attached|element is not stable/i;

/**
 * Failures that mean the PAGE moved, not that the element was unready: the
 * context went away, the frame detached, the tab closed. Escalating through
 * the click tiers is safe only because an actionability timeout proves
 * Playwright never dispatched — it waits for visible/enabled/stable BEFORE
 * the pointer event, so nothing happened and trying harder repeats nothing.
 * These failures carry no such proof. They are the shape a click that
 * committed and then tore its own page down leaves behind, and a second,
 * forced, synthetic click would be a second commit. Stop instead, and say the
 * outcome is unknown rather than guessing either way.
 */
const UNCERTAIN_DISPATCH =
  /execution context was destroyed|target.*(?:has been|was) closed|target closed|browser has been closed|frame was detached|navigating and changing the content|page closed/i;

/** Runs in the page: a synthetic click (React's delegated handlers see it). */
function fireClick(el: Element, dbl: boolean): void {
  const fire = (type: string) => el.dispatchEvent(new MouseEvent(type, { bubbles: true, cancelable: true, view: window }));
  fire('click');
  if (dbl) {
    fire('click');
    fire('dblclick');
  }
}

/**
 * Click a control that keeps re-mounting. Polls for the element and, the
 * moment a handle resolves, dispatches the click in the same tick — no
 * actionability wait at all. A flickering element is attached for a good
 * fraction of every cycle; the normal tiers never act inside that window.
 * If no window is found within the budget, the error says what the agent is
 * fighting and what to try instead of the same click again.
 */
async function fireWhenAttached(loc: Locator, opts: ClickOpts, label = 'clicked', because = ''): Promise<string> {
  // The first line of the failure that sent us here rides along in the
  // result, so a post-mortem can see WHY a click took this route.
  const cause = because ? ` after: ${because.split('\n')[0].slice(0, 120)}` : '';
  // Cut to the action's deadline like every tier before it; one already spent
  // means no window was ever tried.
  const budget = tierBudget(opts);
  if (budget < 1) throw deadlineSpent(label, because);
  const deadline = Date.now() + budget;
  let polls = 0;
  let attached = 0;
  while (Date.now() < deadline) {
    polls++;
    const handle = await loc.elementHandle({ timeout: 100 }).catch((err: unknown) => {
      const message = err instanceof Error ? err.message : String(err);
      if (err instanceof Error && /strict mode violation/i.test(message)) throw actionFailure('not-dispatched', 'strict', err);
      if (err instanceof Error && UNCERTAIN_DISPATCH.test(message)) throw actionFailure('unknown', 'teardown', err);
      if (/strict mode violation/i.test(message) || UNCERTAIN_DISPATCH.test(message)) throw err;
      return null;
    });
    if (handle) {
      attached++;
      try {
        await handle.evaluate(fireClick, Boolean(opts.dbl));
        opts.obs?.dispatched?.('rerender-window');
        return `${label} (dispatched during a re-render window${cause} — the element re-mounts continuously, so a normal click could not land; if the app did not respond, it may need a keyboard route or a wait_for on the state that settles it)`;
      } catch (err) {
        // The element going again between resolve and fire is the ordinary
        // case: nothing was dispatched, so the next window is safe. A context
        // that was DESTROYED is not — the click may have landed and navigated
        // the page, and polling on would fire it a second time.
        const message = err instanceof Error ? err.message : String(err);
        if (UNCERTAIN_DISPATCH.test(message)) {
          throw actionFailure(
            'unknown',
            'teardown',
            `${label === 'clicked' ? 'click' : 'double-click'} outcome UNKNOWN: dispatched into a page that was being torn down (${message.split('\n')[0].slice(0, 160)}). It may already have taken effect. Do not repeat it — observe the app's state and continue from what you find.`,
          );
        }
      } finally {
        await handle.dispose().catch(() => {});
      }
    }
    await new Promise((r) => setTimeout(r, 25));
  }
  // Every window either never came or was gone before the event fired: nothing went out.
  throw actionFailure(
    'not-dispatched',
    attached ? 'rerender' : 'never-attached',
    attached
      ? `target re-rendered continuously: attached on ${attached} of ${polls} polls but never long enough to click. The app re-mounts it on every render. Do not repeat this click — wait_for an element that appears once the state settles, or drive it by keyboard (focus a stable neighbour, Tab to it, press Enter).`
      : `target was never attached during ${Math.round(budget / 1000)}s of polling after an initial detach — it was removed by a re-render. Re-snapshot and locate it afresh rather than repeating this click.`,
  );
}

/**
 * React-safe input helpers (friction #5). Plain `locator.fill()` bypasses the
 * native value setter, so React controlled components never see the change
 * (or number inputs end up appending). We set the value through the native
 * prototype setter and dispatch input/change so React's synthetic event
 * system picks it up. Invisible to the agent: `fill` just works.
 *
 * Only a target that CAN be filled is clicked: an input, a textarea, a
 * contenteditable, or an element inside a label whose control is an input or
 * textarea (Playwright's own fill retargets exactly those). Anything else is
 * refused before the focusing click, not after it. fwsi1 n1 filled select2's
 * rendered <span>: the click opened the dropdown, the fill then threw, and a
 * step that throws is never recorded — so the dropdown's search box was open
 * for the next, recorded `type`, and every replay (which never opened it)
 * typed "Bench Laptop Model" into the asset's name instead.
 */
async function reactSafeFill(locator: Locator, value: string): Promise<void> {
  await locator.waitFor({ state: 'visible', timeout: 10_000 });
  const what = await locator.evaluate(
    (el) => {
      const typed = (n: Element | null | undefined) => n?.tagName === 'INPUT' || n?.tagName === 'TEXTAREA';
      if (typed(el) || (el as HTMLElement).isContentEditable) return null;
      if (typed(el.closest('label')?.control)) return null;
      return `<${el.tagName.toLowerCase()}>`;
    },
    undefined,
    { timeout: DEFAULT_ACTION_TIMEOUT_MS },
  );
  if (what) {
    throw actionFailure(
      'not-dispatched',
      'not-an-input',
      `fill: the target is a ${what}, not a field that can be filled (an input, a textarea or a contenteditable) — nothing was clicked or typed; click it, or fill the field it opens`,
    );
  }
  await locator.scrollIntoViewIfNeeded({ timeout: DEFAULT_ACTION_TIMEOUT_MS }).catch(() => {});
  await locator.click({ timeout: 5_000 }).catch(() => {}); // focus; some widgets need it
  const handled = await locator.evaluate(
    (el, val) => {
      const input = el as HTMLInputElement | HTMLTextAreaElement;
      if (!('value' in input)) return false;
      const proto =
        input instanceof HTMLTextAreaElement
          ? HTMLTextAreaElement.prototype
          : input instanceof HTMLInputElement
            ? HTMLInputElement.prototype
            : null;
      if (!proto) return false;
      const setter = Object.getOwnPropertyDescriptor(proto, 'value')?.set;
      if (!setter) return false;
      setter.call(input, ''); // clear-then-set: number inputs otherwise append
      input.dispatchEvent(new Event('input', { bubbles: true }));
      setter.call(input, val);
      input.dispatchEvent(new Event('input', { bubbles: true }));
      input.dispatchEvent(new Event('change', { bubbles: true }));
      return true;
    },
    value,
    { timeout: DEFAULT_ACTION_TIMEOUT_MS },
  );
  if (!handled) {
    // contenteditable or non-standard widget — fall back to Playwright fill
    await locator.fill(value, { timeout: DEFAULT_ACTION_TIMEOUT_MS });
  }
}

/**
 * Select an option and fire change through the native setter, for React
 * controlled <select> elements.
 */
async function reactSafeSelect(locator: Locator, value: string, fallbackValue?: string): Promise<string[]> {
  // Look before waiting: an option present NOW is chosen at once, and the
  // recorded fallback value is tried without first sitting out the label's
  // full timeout. Only when nothing matches yet does the label wait for
  // options that may still be loading.
  const present = await locator
    .evaluate(
      (el, [v, f]) => {
        if (!(el instanceof HTMLSelectElement)) return null;
        const opts = Array.from(el.options);
        if (opts.some((o) => o.label.trim() === v)) return 'label';
        if (opts.some((o) => o.value === v)) return 'value';
        if (f && opts.some((o) => o.value === f)) return 'fallback';
        return null;
      },
      [value, fallbackValue ?? ''] as [string, string],
      { timeout: DEFAULT_ACTION_TIMEOUT_MS },
    )
    .catch(() => null);
  const timeout = DEFAULT_ACTION_TIMEOUT_MS;
  if (present === 'fallback') return locator.selectOption(fallbackValue!, { timeout });
  if (present === 'value') return locator.selectOption(value, { timeout });
  const result = await locator.selectOption({ label: value }, { timeout }).catch(() => null);
  if (result) return result;
  return locator.selectOption(value, { timeout }); // fall back to value/index matching
}

/**
 * Hover with synthetic mouse events for autocomplete/listbox widgets that key
 * off mouseenter rather than CSS :hover.
 */
async function syntheticHover(locator: Locator): Promise<void> {
  // A PROBE, bounded: the synthetic events below are what does the work, and
  // a real hover on a control the app only shows once its parent is hovered
  // (grafana's panel-menu button) never becomes actionable. Unbounded, it
  // waited out the page's default timeout — 30s in the daemon, and FOREVER in
  // the compiled artifact, whose Playwright Test actionTimeout is 0 (fwgr70
  // 02-create s_2712e5/5 hung until the test's 300s budget).
  await locator.hover({ timeout: HOVER_PROBE_MS }).catch(() => {});
  await locator.evaluate(
    (el) => {
      for (const type of ['pointerover', 'mouseover', 'mouseenter', 'mousemove']) {
        el.dispatchEvent(new MouseEvent(type, { bubbles: type !== 'mouseenter' }));
      }
    },
    undefined,
    { timeout: DEFAULT_ACTION_TIMEOUT_MS },
  );
}

/** How long syntheticHover's real hover may try before the synthetic events take over (fwgr70). */
const HOVER_PROBE_MS = 3_000;

/**
 * Tools whose effect may be a navigation the app performs on the answer to a
 * request — or a second one after the first (an app that routes to a
 * placeholder id and then replaces it with the real one). Daemon replay waits
 * on the url after each of them before it reads the step's effect (tools.ts
 * runStep, for the state-changing ones); the artifact waits in the step's
 * settle phase. Both through `urlHeldStill` below.
 */
const NAVIGATING_ACTIONS: readonly string[] = ['click', 'dblclick', 'press', 'submit', 'select'];

/**
 * The window a session records in when it is given no other: `--viewport` and
 * `--device` choose another (daemon/browser.ts `resolveBrowserProfile`).
 */
const RECORDING_VIEWPORT = { width: 1280, height: 900 } as const;

/**
 * The browser a flow was recorded in: its window, and for an emulated device
 * the rest of what Playwright's device descriptor sets. Stored on the flow
 * (`Flow.browser`), carried into the compiled artifact (`RECORDED_BROWSER`),
 * and judged at run time by `profileMismatch`.
 *
 * WHY IT TRAVELS. A page's layout is part of what a recording captured: a
 * `point` candidate is coordinates in this window, and an app that lays out by
 * size (Odoo's list columns and form panes, a responsive nav that becomes a
 * menu button) renders a different page in another one — a different
 * procedure, not merely different pixels. Playwright Test's default window is
 * 1280×720, and fwod39's compiled spec ran there: its 02-create reads found
 * nothing, a click fell to a point candidate, and 03-open resolved no quantity
 * input — steps daemon replay ran cleanly twice at 1280×900. A mobile flow is
 * the same problem from the other side, and a desktop default would override
 * the device a caller's project configured to exercise it.
 *
 * `device` is the Playwright device name it was resolved from, for people;
 * the other fields are what was applied. Chromium only: a descriptor's
 * `defaultBrowserType` (webkit, for iPhones) is not honoured.
 */
interface BrowserProfile {
  device?: string;
  viewport: { width: number; height: number };
  deviceScaleFactor?: number;
  isMobile?: boolean;
  hasTouch?: boolean;
  userAgent?: string;
}

/** What a flow recorded before profiles were stored was recorded in. */
const DEFAULT_BROWSER_PROFILE: BrowserProfile = { viewport: { ...RECORDING_VIEWPORT } };

/** What a runner can observe of the browser it was handed. `null` viewport: the page has none (it follows the window). */
interface LiveBrowser {
  viewport: { width: number; height: number } | null;
  userAgent?: string;
  hasTouch?: boolean;
}

/**
 * The device facts profileMismatch compares, read off the live page the same
 * way by both runners. A page that cannot be evaluated yet (about:blank before
 * the first navigation evaluates fine; a crashed one does not) gives only its
 * size, and the facts it could not read are not compared.
 */
async function readLiveBrowser(page: Pick<Page, 'viewportSize' | 'evaluate'>): Promise<LiveBrowser> {
  const facts = await page
    .evaluate(() => ({ userAgent: navigator.userAgent, hasTouch: navigator.maxTouchPoints > 0 }))
    .catch(() => ({}));
  return { viewport: page.viewportSize(), ...facts };
}

/**
 * Why the browser a flow is about to run in is not the one it was recorded in,
 * or null when it is. Width and height, the user agent and touch support are
 * compared — the device facts a page can act on; scale factor and `isMobile`
 * cannot be read back from a page and are applied, never judged. A field the
 * recording did not set is not compared.
 *
 * Both runners warn with it and neither refuses: a flow run at another size
 * may still work (role and text candidates survive most reflows), and when it
 * does not, the failure then says why.
 */
function profileMismatch(recorded: BrowserProfile, live: LiveBrowser): string | null {
  const diffs: string[] = [];
  const size = (v: { width: number; height: number }) => `${v.width}x${v.height}`;
  if (live.viewport && (live.viewport.width !== recorded.viewport.width || live.viewport.height !== recorded.viewport.height)) {
    diffs.push(`window ${size(live.viewport)} (recorded ${size(recorded.viewport)})`);
  }
  if (recorded.userAgent !== undefined && live.userAgent !== undefined && live.userAgent !== recorded.userAgent) {
    diffs.push('a different user agent');
  }
  if (recorded.hasTouch !== undefined && live.hasTouch !== undefined && live.hasTouch !== recorded.hasTouch) {
    diffs.push(live.hasTouch ? 'touch input (recorded without)' : 'no touch input (recorded with)');
  }
  if (!diffs.length) return null;
  const was = recorded.device ? ` on ${recorded.device}` : '';
  return `the browser has ${diffs.join(', ')} — the flow was recorded${was} at ${size(recorded.viewport)}, and locators that depend on layout may not hold`;
}

function isNavigatingAction(tool: string): boolean {
  return NAVIGATING_ACTIONS.includes(tool);
}

/** How long a click's late navigation is given before its effect is captured as final. */
const LATE_NAV_MS = 1_500;
/** A url that has not moved for this long, after moving, is where the step left the page. */
const URL_STILL_MS = 500;
/**
 * How long "no request in flight" must hold before it means "no navigation
 * coming". Zero: the DOM settle that precedes this wait (≥250ms quiet) is the
 * grace, and a request the click started is already counted by then.
 */
const LATE_NAV_GRACE_MS = 0;

/**
 * Where a navigating tool left the url once it has held still. A late
 * navigation rides on a request the tool started, so a page with no request
 * in flight and the url it began on is not going anywhere: the wait ends
 * there rather than at the deadline. Set 30's zero-model replays ran at
 * twice set 28's wall clock because every non-navigating click sat out the
 * full LATE_NAV_MS (78 actions, ~30s of nothing on repairdesk).
 *
 * A url that moved and then moves AGAIN is followed: the value a step's
 * derived binding needs is on the url the step settles on, and a DOM settle
 * alone cannot see a redirect that changes nothing on the page first.
 */
async function urlHeldStill(
  page: Pick<Page, 'url'>,
  beforeUrl: string,
  inFlightNow: () => number,
  timing: { lateNavMs?: number; stillMs?: number; graceMs?: number; pollMs?: number } = {},
): Promise<string> {
  const lateNavMs = timing.lateNavMs ?? LATE_NAV_MS;
  const stillMs = timing.stillMs ?? URL_STILL_MS;
  const graceMs = timing.graceMs ?? LATE_NAV_GRACE_MS;
  const pollMs = timing.pollMs ?? 100;
  const start = Date.now();
  const deadline = start + lateNavMs;
  let seen = page.url();
  let stillSince = start;
  // Check first, sleep after: the caller has already let the DOM settle, so
  // a request the click started is registered by now, and the common case
  // (a click that navigates nowhere) should cost nothing here.
  for (;;) {
    const now = page.url();
    if (now !== seen) {
      seen = now;
      stillSince = Date.now();
    } else if (now !== beforeUrl) {
      if (Date.now() - stillSince >= stillMs) break;
    } else if (Date.now() - start >= graceMs && inFlightNow() === 0) {
      break; // nothing asked of the server, so nothing to route on
    }
    if (Date.now() >= deadline) break;
    await new Promise((r) => setTimeout(r, pollMs));
  }
  return seen;
}

const SETTLE_QUIET_MS = 250;
const SETTLE_MAX_MS = 2_000;
/**
 * How long a page gets to show it is busy before it is called quiet. The
 * quiet window used to be the floor too — 250ms per step even on a static
 * page, ~20s across an 80-step replay that was otherwise at the engine's
 * floor. Now the full quiet window is demanded only once a mutation shows.
 */
const SETTLE_PROBE_MS = 60;

/** Resolve once no DOM mutation has happened for SETTLE_QUIET_MS, or after `maxMs` (SETTLE_MAX_MS). */
async function settleDom(page: Page, maxMs: number = SETTLE_MAX_MS): Promise<void> {
  await domQuiet(page, { maxMs });
}

/**
 * Wait until the page exposes something to act on, or the deadline passes.
 *
 * `load` fires before a client-rendered app has painted, so snapshotting a
 * heavy SPA the instant navigation "finishes" returns an EMPTY tree —
 * NocoDB's dashboard did exactly that, with an empty title to match. Waiting
 * on the content itself is the app-agnostic way: network idleness is unusable
 * (Odoo long-polls forever) and a fixed sleep is either too short or wasted.
 *
 * The wait is a MutationObserver inside the page, not a poll: the check is
 * made once up front (a ready page returns in one round-trip) and then again
 * only when the DOM actually changes, so the app paints and we return in the
 * same tick instead of up to a poll interval later.
 *
 * Best-effort and bounded: a page that really has nothing costs the deadline
 * and no more, and a navigation mid-wait (evaluate throws) is retried until
 * the deadline rather than reported.
 *
 * Shared, because BOTH runners make the flow's start navigation and judge the
 * first segment's start page right after it: the daemon's runFlow waited here
 * and the compiled artifact did not, so fwrd75's artifact read the hash-routed
 * app's url before its router had sent a signed-out visitor to `#/login` and
 * refused the sign-in segment on `#/tickets`, where the daemon passed 3/3.
 */
async function waitForContent(page: Page, timeoutMs = 5000): Promise<void> {
  const deadline = Date.now() + timeoutMs;
  for (;;) {
    const remaining = deadline - Date.now();
    if (remaining <= 0) return;
    const ready = await page
      .evaluate(
        (budget) =>
          new Promise<boolean>((resolve) => {
            const has = () => {
              const b = document.body;
              if (!b) return false;
              if (b.querySelector('a,button,input,select,textarea,[role],h1,h2')) return true;
              return (b.innerText ?? '').trim().length > 0;
            };
            if (has()) return resolve(true);
            const stop = setTimeout(() => {
              observer.disconnect();
              resolve(false);
            }, budget);
            const observer = new MutationObserver(() => {
              if (!has()) return;
              observer.disconnect();
              clearTimeout(stop);
              resolve(true);
            });
            // document, not document.body: on a page whose body has not been
            // parsed yet there is nothing else to observe, and the body's
            // arrival is itself the mutation we are waiting for.
            observer.observe(document, { childList: true, subtree: true, characterData: true });
          }),
        remaining,
      )
      .catch(() => null); // navigating / detached: re-evaluate against the new document
    if (ready === true || ready === false) return;
    if (Date.now() >= deadline) return;
    // The document went out from under the evaluate. Back off a beat on a
    // plain timer (a detached page's own clock throws) before looking at the
    // new one, so a page navigating in a loop cannot spin this hot.
    await new Promise((r) => setTimeout(r, 50));
  }
}

/**
 * settleDom that says what it saw: whether the DOM mutated at all while it
 * watched, and how long before it returned the last mutation was. An action's
 * observation (src/execution/action.ts) reads the second as evidence — a page
 * that changed a moment ago may be about to ask the server for something.
 * Null when the page could not be evaluated (navigating, detached, closed).
 */
async function domQuiet(
  page: Page,
  timing: { probeMs?: number; quietMs?: number; maxMs?: number } = {},
): Promise<{ mutated: boolean; sinceMs: number } | null> {
  try {
    return await page.evaluate(
      ({ probe, quiet, max }) =>
        new Promise<{ mutated: boolean; sinceMs: number }>((resolve) => {
          let last = 0;
          const finish = () => {
            observer.disconnect();
            clearTimeout(timer);
            clearTimeout(stop);
            resolve({ mutated: last > 0, sinceMs: last > 0 ? Date.now() - last : 0 });
          };
          let timer = setTimeout(finish, probe);
          const stop = setTimeout(finish, max);
          const observer = new MutationObserver(() => {
            last = Date.now();
            clearTimeout(timer);
            timer = setTimeout(finish, quiet);
          });
          observer.observe(document, { childList: true, subtree: true, attributes: true, characterData: true });
        }),
      { probe: timing.probeMs ?? SETTLE_PROBE_MS, quiet: timing.quietMs ?? SETTLE_QUIET_MS, max: timing.maxMs ?? SETTLE_MAX_MS },
    );
  } catch {
    // navigating / detached — the locator resolution will report it
    return null;
  }
}

// Shared execution source: snapshot.ts. Regenerate to update.
/**
 * The page-observation model both execution targets share: one STRUCTURED
 * observation of the live page (roles, names, values, states, where each
 * element sits, and how much of the page the look actually covered), the
 * snapshot-line dialects rendered from it (`- role "name": value`), and the
 * matchers that read those lines. The daemon imports this module (through
 * daemon/diff.ts and skills/replay.ts); a compiled `.flow.ts` artifact embeds
 * its exact source (spec/runtime-source.ts), so both runners ask their effect
 * and identity questions of the same observation. It must stay
 * self-contained: nothing but a sibling shared module or a Playwright type may
 * be imported.
 *
 * WHY TWO DIALECTS. Recorded lines are persisted — in recordings, in stored
 * step expectations, in compiled artifacts — and matched as substrings. The
 * first dialect named a `<label for>` input `""`, walked no frame or shadow
 * root, and carried no disabled state; fixing any of that in place would make
 * every stored line for such an element disagree with the live page. So a
 * recorded step says which dialect its lines are in (StepExpectation
 * .lineDialect, absent = 1), and each runner renders the live observation in
 * THAT dialect before comparing. Dialect 1 is byte-identical to the capture it
 * replaced (test/observation.browser.test.ts keeps the old function as its
 * oracle); dialect 2 is what new recordings are written in.
 *
 * WHY COVERAGE. A capture that walked 4,000 of 9,000 elements, stopped at the
 * line cap, could not read a visible iframe, or looked at a virtualised grid
 * showing 20 of 340 rows, has NOT established that something is absent. Every
 * absence question goes through `presence`, which answers 'unknown' there
 * instead of 'absent'.
 */

/** Which rendering of an observation a set of recorded lines is in. Absent on a stored step means 1. */
type LineDialect = 1 | 2;

/** What new recordings are written in. */
const CURRENT_DIALECT = 2 as const;

/** What a capture is allowed to walk and return — passed INTO the page, since observeDocumentInPage is serialised. */
const SNAPSHOT_LIMITS = { maxAlerts: 5, maxAlertChars: 200, maxNodes: 4_000, maxLines: 400 };

/**
 * The budget open shadow roots are walked under, ON TOP of SNAPSHOT_LIMITS: a
 * separate budget, so the dialect-1 walk (and so every dialect-1 line) is
 * untouched by how much shadow content a page carries.
 */
const SHADOW_LIMITS = { maxExtraNodes: 4_000, maxExtraLines: 400 };

/** A capture that has not answered in this long is a navigating or hung page: null, never a wait. */
const CAPTURE_TIMEOUT_MS = 2_000;

/** How many visible child frames one observation evaluates; a visible frame past this is a coverage gap. */
const MAX_FRAMES = 10;

/** The least time frames are given once the main document has answered, however long it took. */
const FRAME_MIN_BUDGET_MS = 500;

/** Where an element sits: `frame` is the child-index path from the main frame ([] = main document); `shadow` the open shadow hosts above it, as `tag#id`. */
interface NodeContext {
  frame: number[];
  shadow: string[];
}

interface ObservedNode {
  role: string;
  /** The dialect-2 name: dialect 1's, except that an element with no name of its own is named by its `<label>`s and a shadow-scoped aria-labelledby resolves. */
  name: string;
  /** The dialect-1 name, exactly as the first capture computed it. */
  legacyName: string;
  /** Present when the element carries a nonempty string value (not for a checkbox or radio). */
  value?: string;
  /** Present for a checkbox or radio input: whether it is checked. */
  checked?: boolean;
  disabled?: boolean;
  context: NodeContext;
  /** Part of the dialect-1 walk: the main document, light DOM, within SNAPSHOT_LIMITS. */
  legacy: boolean;
}

interface ObservedAlert {
  text: string;
  legacy: boolean;
}

interface ObservationCoverage {
  nodesWalked: number;
  nodeCap: number;
  /** More elements existed than any walk was allowed to look at. */
  nodesTruncated: boolean;
  /** A walk stopped at its line cap. */
  linesTruncated: boolean;
  /** More visible live regions existed than were kept. */
  alertsTruncated: boolean;
  shadowRootsWalked: number;
  frames: {
    observed: number;
    /** Not rendered (no box): nothing in them is on screen, so not a gap. */
    hidden: number;
    /** Visible, or of unknown visibility, and past MAX_FRAMES: a gap. */
    overCap: number;
    /** Visible and could not be evaluated: a gap. */
    inaccessible: { path: number[]; url: string; reason: string }[];
  };
  /** A collection the page says is larger than what it rendered (aria-rowcount, aria-setsize) or still loading (aria-busy). */
  collections: { partial: boolean; evidence: string[] };
}

interface PageObservation {
  url: string;
  nodes: ObservedNode[];
  alerts: ObservedAlert[];
  coverage: ObservationCoverage;
}

/** One document's half of an observation, as the page function returns it; frames are the caller's. */
interface DocumentObservation {
  nodes: ObservedNode[];
  alerts: ObservedAlert[];
  coverage: Omit<ObservationCoverage, 'frames'>;
}

/** The answer to "is this on the page?": `unknown` when the look could not establish absence. */
type Presence = 'present' | 'absent' | 'unknown';

interface ObserveDocumentOptions {
  maxAlerts: number;
  maxAlertChars: number;
  maxNodes: number;
  maxLines: number;
  maxExtraNodes: number;
  maxExtraLines: number;
  /** This document is the main one, whose light-DOM walk is dialect 1's. False inside a frame. */
  legacy: boolean;
  /** Roles whose elements are named in full, past NAME_CAP (see FullNameLook). Absent: every name is capped, as it always was. */
  fullNameRoles?: string[];
}

/**
 * How long a name the observation gives an element: an attribute name is cut
 * to this, and an element named by its own text is named only while that text
 * is this short — longer, it reads as a container's text, which would make
 * the line churn on unrelated changes. Written into the page function as the
 * literal 80, since that function is serialised into the page.
 */
const NAME_CAP = 80;

/**
 * A second look, for a recorded line not shown on the first (round 63,
 * openproject fwop17 04-create): the elements of `fullNameRoles` are named in
 * full. A row named by its text was recorded at 79 characters with n1's
 * subject; the compiled run's longer runid took it to 81, past NAME_CAP, the
 * row was observed with no name, and its saved record's line "did not show".
 * Only asked after the capped look missed, and only of the roles the missing
 * lines name, so every stored line and every diff stays as it was.
 */
interface FullNameLook {
  fullNameRoles?: string[];
}

/**
 * Runs in the page (or a frame's document): the roles, names, values and
 * states currently on screen, plus live-region text and how much of the
 * document the walk covered. Deliberately hand-rolled rather than delegated
 * to ariaSnapshot — see daemon/diff.ts captureSignature. Everything it needs
 * is passed in: it is serialised into the page, so nothing at module level is
 * in scope there.
 *
 * ORDER IS WHAT KEEPS DIALECT 1 EXACT. Pass A is the first capture's loop,
 * unchanged — the first `maxNodes` elements of `querySelectorAll('*')`, the
 * line counter, the visibility and role rules, the name and value rules — so
 * the legacy nodes it produces render to the very lines it produced. Pass B
 * (open shadow roots) and the frames the caller adds come after, on their own
 * budgets, and are never legacy.
 */
function observeDocumentInPage(opts: ObserveDocumentOptions): DocumentObservation {
  const clean = (s: string | null | undefined) => (s ?? '').replace(/\s+/g, ' ').trim();

  const roleOf = (el: Element): string | null => {
    const explicit = clean(el.getAttribute('role'));
    if (explicit) return explicit.split(' ')[0];
    const tag = el.tagName.toLowerCase();
    const type = (el.getAttribute('type') || '').toLowerCase();
    if (tag === 'button') return 'button';
    if (tag === 'a') return el.hasAttribute('href') ? 'link' : null;
    if (tag === 'select') return el.hasAttribute('multiple') ? 'listbox' : 'combobox';
    if (tag === 'textarea') return 'textbox';
    if (tag === 'option') return 'option';
    if (tag === 'td' || tag === 'th') return 'cell';
    if (tag === 'tr') return 'row';
    if (tag === 'dialog') return 'dialog';
    if (/^h[1-6]$/.test(tag)) return 'heading';
    if (tag === 'input') {
      if (type === 'checkbox') return 'checkbox';
      if (type === 'radio') return 'radio';
      if (type === 'range') return 'slider';
      if (type === 'search') return 'searchbox';
      if (type === 'number') return 'spinbutton';
      if (type === 'submit' || type === 'button' || type === 'reset') return 'button';
      if (type === 'hidden' || type === 'file') return null;
      return 'textbox';
    }
    return null;
  };

  // The attribute half of a name. `byRoot` resolves aria-labelledby ids in
  // the element's own root (a shadow root has its own id space); the first
  // capture resolved them in the owner document, and dialect 1 still does.
  const ownName = (el: Element, byRoot: boolean): string => {
    const labelledBy = el.getAttribute('aria-labelledby');
    const root = el.getRootNode() as Document | ShadowRoot;
    const lookup = (id: string) =>
      byRoot && typeof root.getElementById === 'function' ? root.getElementById(id) : el.ownerDocument.getElementById(id);
    const fromIds = labelledBy
      ? labelledBy
          .split(/\s+/)
          .map((id) => lookup(id)?.textContent ?? '')
          .join(' ')
      : '';
    return clean(
      el.getAttribute('aria-label') ||
        fromIds ||
        el.getAttribute('alt') ||
        el.getAttribute('title') ||
        el.getAttribute('placeholder'),
    );
  };

  // The text of the element's own <label>s — `for` and enclosing alike — with
  // the control's own subtree left out (a select's options are not its name).
  const labelsText = (el: Element): string => {
    const labels = (el as HTMLInputElement).labels;
    if (!labels || !labels.length) return '';
    const parts: string[] = [];
    for (const label of Array.from(labels)) {
      if (!label.contains(el)) {
        parts.push(label.textContent ?? '');
        continue;
      }
      let text = '';
      const walker = label.ownerDocument.createTreeWalker(label, NodeFilter.SHOW_TEXT);
      for (let t = walker.nextNode(); t; t = walker.nextNode()) if (!el.contains(t)) text += t.textContent ?? '';
      parts.push(text);
    }
    return clean(parts.join(' '));
  };

  const namesOf = (el: Element, cap: number): { name: string; legacyName: string } => {
    const own = ownName(el, false);
    const labelledBy = el.hasAttribute('aria-labelledby');
    const own2 = labelledBy ? ownName(el, true) : own;
    let label: string | undefined;
    let text: string | undefined;
    const enclosing = () => (label ??= clean(el.closest('label')?.textContent));
    // Only a short subtree reads as this element's own name; anything longer is
    // a container's text and would make the line churn on unrelated changes.
    const inner = () => (text ??= clean((el as HTMLElement).innerText));
    const fallback = () => (enclosing() ? enclosing().slice(0, cap) : inner().length <= cap ? inner() : '');
    const legacyName = own ? own.slice(0, cap) : fallback();
    let name: string;
    if (own2) name = own2.slice(0, cap);
    else {
      const labels = labelsText(el);
      name = labels ? labels.slice(0, cap) : fallback();
    }
    return { name, legacyName };
  };

  const describe = (el: Element, shadow: string[], legacy: boolean): ObservedNode | null => {
    const role = roleOf(el);
    if (!role) return null;
    if (el.getClientRects().length === 0) return null;
    const { name, legacyName } = namesOf(el, opts.fullNameRoles?.includes(role) ? Number.MAX_SAFE_INTEGER : 80);
    const node: ObservedNode = { role, name, legacyName, context: { frame: [], shadow }, legacy };
    const input = el as HTMLInputElement;
    if (input.type === 'checkbox' || input.type === 'radio') {
      node.checked = Boolean(input.checked);
    } else if (typeof input.value === 'string' && input.value) {
      node.value = clean(input.value).slice(0, 80);
    }
    if (el.matches(':disabled') || el.getAttribute('aria-disabled') === 'true') node.disabled = true;
    return node;
  };

  const LIVE_REGION = '[role=alert],[role=status]';
  const visibleText = (els: Element[]) =>
    els.map((el) => clean((el as HTMLElement).innerText).slice(0, opts.maxAlertChars)).filter((text) => text.length > 0);

  const coverage: DocumentObservation['coverage'] = {
    nodesWalked: 0,
    nodeCap: opts.maxNodes,
    nodesTruncated: false,
    linesTruncated: false,
    alertsTruncated: false,
    shadowRootsWalked: 0,
    collections: { partial: false, evidence: [] },
  };
  const nodes: ObservedNode[] = [];

  // Pass A: the dialect-1 walk, exactly as the first capture walked.
  const all = Array.from(document.querySelectorAll('*'));
  coverage.nodesTruncated = all.length > opts.maxNodes;
  const walked = all.slice(0, opts.maxNodes);
  let lines = 0;
  for (const el of walked) {
    if (lines >= opts.maxLines) {
      coverage.linesTruncated = true;
      break;
    }
    coverage.nodesWalked++;
    const node = describe(el, [], opts.legacy);
    if (node) {
      nodes.push(node);
      lines++;
    }
  }

  // Pass B: open shadow roots, on their own budget. A CLOSED root reports
  // `shadowRoot === null` and cannot be seen from script at all — it is
  // invisible here, and nothing can count it as a gap.
  let extraNodes = 0;
  let extraLines = 0;
  const shadowAlerts: Element[] = [];
  const hostKey = (el: Element) => `${el.tagName.toLowerCase()}${el.id ? `#${el.id}` : ''}`;
  const walkShadow = (host: Element, path: string[]): void => {
    const root = host.shadowRoot;
    if (!root) return;
    coverage.shadowRootsWalked++;
    const inner = [...path, hostKey(host)];
    for (const el of Array.from(root.querySelectorAll('*'))) {
      if (extraNodes >= opts.maxExtraNodes) {
        coverage.nodesTruncated = true;
        return;
      }
      extraNodes++;
      coverage.nodesWalked++;
      const node = extraLines < opts.maxExtraLines ? describe(el, inner, false) : null;
      if (node) {
        nodes.push(node);
        extraLines++;
      }
      if (extraLines >= opts.maxExtraLines && !node && roleOf(el)) coverage.linesTruncated = true;
      if (el.matches(LIVE_REGION) && el.getClientRects().length > 0) shadowAlerts.push(el);
      if (el.shadowRoot) walkShadow(el, inner);
    }
  };
  for (const el of walked) if (el.shadowRoot) walkShadow(el, []);

  const lightAlerts = Array.from(document.querySelectorAll(LIVE_REGION)).filter((el) => el.getClientRects().length > 0);
  coverage.alertsTruncated = lightAlerts.length > opts.maxAlerts || shadowAlerts.length > opts.maxAlerts;
  const alerts: ObservedAlert[] = [
    ...visibleText(lightAlerts.slice(0, opts.maxAlerts)).map((text) => ({ text, legacy: opts.legacy })),
    ...visibleText(shadowAlerts.slice(0, opts.maxAlerts)).map((text) => ({ text, legacy: false })),
  ];

  // A collection the page itself says is bigger than what it rendered: a
  // virtualised grid (aria-rowcount), a windowed listbox (aria-setsize), or
  // one still loading (aria-busy). What is not rendered cannot be found
  // absent.
  const evidence: string[] = [];
  const nameForEvidence = (el: Element) => clean(el.getAttribute('aria-label')) || ownName(el, true);
  for (const el of Array.from(document.querySelectorAll('[aria-rowcount]'))) {
    if (el.getClientRects().length === 0) continue;
    const total = parseInt(el.getAttribute('aria-rowcount') ?? '', 10);
    if (!Number.isFinite(total)) continue;
    const rendered = el.querySelectorAll('[role=row],tr').length;
    if (total === -1 || total > rendered) {
      evidence.push(`${roleOf(el) ?? el.tagName.toLowerCase()} '${nameForEvidence(el)}' ${rendered}/${total === -1 ? '?' : total}`);
    }
  }
  const sized = new Set<Element>();
  for (const item of Array.from(document.querySelectorAll('[aria-setsize]'))) {
    const parent = item.parentElement;
    if (!parent || sized.has(parent) || item.getClientRects().length === 0) continue;
    sized.add(parent);
    const total = parseInt(item.getAttribute('aria-setsize') ?? '', 10);
    if (!Number.isFinite(total)) continue;
    const rendered = Array.from(parent.children).filter((c) => c.hasAttribute('aria-setsize')).length;
    if (total === -1 || total > rendered) {
      evidence.push(`${roleOf(parent) ?? parent.tagName.toLowerCase()} '${nameForEvidence(parent)}' ${rendered}/${total === -1 ? '?' : total}`);
    }
  }
  for (const el of Array.from(document.querySelectorAll('[aria-busy="true"]'))) {
    const role = roleOf(el) ?? '';
    if (!/^(grid|treegrid|table|list|listbox|tree|feed|rowgroup)$/.test(role) || el.getClientRects().length === 0) continue;
    evidence.push(`${role} '${nameForEvidence(el)}' busy`);
  }
  coverage.collections = { partial: evidence.length > 0, evidence: evidence.slice(0, 5) };

  return { nodes, alerts, coverage };
}

function isDocumentObservation(value: unknown): value is DocumentObservation {
  const v = value as DocumentObservation | null;
  return Boolean(v && Array.isArray(v.nodes) && Array.isArray(v.alerts) && v.coverage && typeof v.coverage === 'object');
}

/** A promise's value, or why it did not produce one within `ms` — never a throw. */
async function within<T>(work: Promise<T>, ms: number): Promise<{ value: T } | { error: string }> {
  let timer: ReturnType<typeof setTimeout> | undefined;
  try {
    return await Promise.race([
      work.then((value) => ({ value })),
      new Promise<{ error: string }>((resolve) => {
        timer = setTimeout(() => resolve({ error: `did not answer within ${ms}ms` }), Math.max(1, ms));
      }),
    ]);
  } catch (err) {
    return { error: (err instanceof Error ? err.message : String(err)).split('\n')[0].slice(0, 120) };
  } finally {
    clearTimeout(timer);
  }
}

/**
 * Playwright's Frame, named through Page: the artifact imports only `Page`
 * (and `Locator`) from @playwright/test, so this module may not name a third
 * Playwright type.
 */
type PageFrame = ReturnType<Page['mainFrame']>;

/** A frame's child-index path from the main frame. */
function framePath(frame: PageFrame): number[] {
  const path: number[] = [];
  for (let f: PageFrame | null = frame; f; ) {
    const parent: PageFrame | null = f.parentFrame();
    if (!parent) break;
    path.unshift(parent.childFrames().indexOf(f));
    f = parent;
  }
  return path;
}

/**
 * The page's child frames, observed: each rendered frame's document through
 * the same page function (cross-origin frames included — Playwright evaluates
 * out-of-process iframes), under what is left of the capture deadline. A
 * frame with no box is hidden and skipped; a visible frame that cannot be
 * evaluated, or one past MAX_FRAMES, is recorded as a gap.
 */
/** The page function's share of a FullNameLook: nothing at all when no role is named, so a plain look is sent exactly as before. */
const fullNames = (look: FullNameLook): { fullNameRoles?: string[] } => (look.fullNameRoles?.length ? { fullNameRoles: look.fullNameRoles } : {});

async function observeFrames(
  page: Page,
  budgetMs: number,
  look: FullNameLook = {},
): Promise<{ nodes: ObservedNode[]; alerts: ObservedAlert[]; frames: ObservationCoverage['frames']; documents: DocumentObservation['coverage'][] }> {
  const frames: ObservationCoverage['frames'] = { observed: 0, hidden: 0, overCap: 0, inaccessible: [] };
  const out = { nodes: [] as ObservedNode[], alerts: [] as ObservedAlert[], frames, documents: [] as DocumentObservation['coverage'][] };
  // A stand-in page (a unit test's) has no frame tree; a real page always does.
  if (typeof (page as Partial<Page>).frames !== 'function' || typeof (page as Partial<Page>).mainFrame !== 'function') return out;
  let children: PageFrame[];
  try {
    const main = page.mainFrame();
    children = page.frames().filter((f) => f !== main && !f.isDetached());
  } catch (err) {
    frames.inaccessible.push({ path: [], url: '', reason: `the frame tree could not be listed: ${err instanceof Error ? err.message.split('\n')[0] : String(err)}` });
    return out;
  }
  if (!children.length) return out;
  const deadline = Date.now() + budgetMs;
  const remaining = () => Math.max(1, deadline - Date.now());
  const url = (f: PageFrame) => {
    try {
      return f.url();
    } catch {
      return '';
    }
  };

  // Which are rendered. Checked for a bounded number of frames: a page with
  // dozens of iframes past that is not claimed to be covered.
  const checked = children.slice(0, MAX_FRAMES * 3);
  frames.overCap += children.length - checked.length;
  const visibility = await Promise.all(
    checked.map(async (frame) => {
      const seen = await within(
        (async () => {
          const handle = await frame.frameElement();
          try {
            const box = await handle.boundingBox();
            return Boolean(box && box.width > 0 && box.height > 0);
          } finally {
            await handle.dispose().catch(() => {});
          }
        })(),
        remaining(),
      );
      return { frame, seen };
    }),
  );
  const visible: PageFrame[] = [];
  for (const { frame, seen } of visibility) {
    if ('error' in seen) {
      if (frame.isDetached()) continue; // gone, not hidden from us
      frames.inaccessible.push({ path: framePath(frame), url: url(frame), reason: `its visibility could not be read (${seen.error})` });
    } else if (!seen.value) frames.hidden++;
    else if (visible.length >= MAX_FRAMES) frames.overCap++;
    else visible.push(frame);
  }

  const looks = await Promise.all(
    visible.map(async (frame) => ({
      frame,
      look: await within(frame.evaluate(observeDocumentInPage, { ...SNAPSHOT_LIMITS, ...SHADOW_LIMITS, legacy: false, ...fullNames(look) }), remaining()),
    })),
  );
  for (const { frame, look } of looks) {
    if ('error' in look || !isDocumentObservation(look.value)) {
      if (frame.isDetached()) continue;
      frames.inaccessible.push({ path: framePath(frame), url: url(frame), reason: 'error' in look ? look.error : 'it answered with something other than an observation' });
      continue;
    }
    const path = framePath(frame);
    frames.observed++;
    for (const node of look.value.nodes) out.nodes.push({ ...node, legacy: false, context: { ...node.context, frame: path } });
    for (const alert of look.value.alerts) out.alerts.push({ text: alert.text, legacy: false });
    out.documents.push(look.value.coverage);
  }
  return out;
}

/**
 * One structured look at the live page — the main document, its open shadow
 * roots and its rendered frames — or null when the main document cannot be
 * read (navigating, closed, a renderer that does not answer within
 * CAPTURE_TIMEOUT_MS). Null is "unavailable", never "empty". A frame that
 * cannot be read does not null the observation: it is recorded in the
 * coverage, which is what stops the observation proving an absence.
 */
async function observePage(page: Page, look: FullNameLook = {}): Promise<PageObservation | null> {
  const started = Date.now();
  const main = await within(page.evaluate(observeDocumentInPage, { ...SNAPSHOT_LIMITS, ...SHADOW_LIMITS, legacy: true, ...fullNames(look) }), CAPTURE_TIMEOUT_MS);
  // A page that answered with something other than a capture (a frame torn
  // down mid-evaluate) is as unreadable as one that did not answer.
  if ('error' in main || !isDocumentObservation(main.value)) return null;
  const doc = main.value;
  const framed = await observeFrames(page, Math.max(FRAME_MIN_BUDGET_MS, CAPTURE_TIMEOUT_MS - (Date.now() - started)), look);
  const coverage: ObservationCoverage = { ...doc.coverage, collections: { ...doc.coverage.collections, evidence: [...doc.coverage.collections.evidence] }, frames: framed.frames };
  for (const c of framed.documents) {
    coverage.nodesWalked += c.nodesWalked;
    coverage.shadowRootsWalked += c.shadowRootsWalked;
    coverage.nodesTruncated ||= c.nodesTruncated;
    coverage.linesTruncated ||= c.linesTruncated;
    coverage.alertsTruncated ||= c.alertsTruncated;
    coverage.collections.partial ||= c.collections.partial;
    coverage.collections.evidence.push(...c.collections.evidence);
  }
  coverage.collections.evidence = coverage.collections.evidence.slice(0, 5);
  let url = '';
  try {
    url = page.url();
  } catch {
    // a stand-in page with no url; the observation is still one
  }
  return { url, nodes: [...doc.nodes, ...framed.nodes], alerts: [...doc.alerts, ...framed.alerts], coverage };
}

const INTERACTIVE_ROLES =
  /\b(button|link|textbox|searchbox|combobox|checkbox|radio|switch|slider|spinbutton|menu|menubar|menuitem|option|tab|listbox|grid|row|cell|dialog|alertdialog|heading|alert|status)\b/;

/**
 * The per-line heuristic behind the daemon's filterInteractive; shared with
 * signature capture, so the lines a step is judged against are the same lines
 * the recording kept. Matches any ref, in-frame ones included — testing for
 * "[@e" silently dropped every line inside an iframe, so an embedded editor or
 * payment form was invisible in the snapshot the agent works from.
 */
function isInteractiveLine(line: string): boolean {
  return line.includes('[@') || INTERACTIVE_ROLES.test(line);
}

/**
 * An observation as snapshot lines, interactive lines only.
 *
 * Dialect 1 is the first capture's exact text: legacy nodes only (main
 * document, light DOM), the legacy name, ` [checked]` for a checked
 * checkbox/radio or `: value` otherwise. Dialect 2 is every node — shadow and
 * frame content included — with the dialect-2 name, ` [checked]`,
 * ` [disabled]`, then `: value`. Where an element sits (its frame, its shadow
 * host) is never part of the line text: a line says what is shown, and the
 * same control in an iframe reads as it does in the page.
 */
function renderLines(o: PageObservation, d: LineDialect): string[] {
  const out: string[] = [];
  for (const n of o.nodes) {
    if (d === 1) {
      if (!n.legacy) continue;
      let line = `- ${n.role} ${JSON.stringify(n.legacyName)}`;
      if (n.checked !== undefined) line += n.checked ? ' [checked]' : '';
      else if (n.value !== undefined) line += `: ${n.value}`;
      out.push(line);
      continue;
    }
    let line = `- ${n.role} ${JSON.stringify(n.name)}`;
    if (n.checked) line += ' [checked]';
    if (n.disabled) line += ' [disabled]';
    if (n.checked === undefined && n.value !== undefined) line += `: ${n.value}`;
    out.push(line);
  }
  return out.filter(isInteractiveLine);
}

/** The observation's live-region texts in a dialect: dialect 1 keeps the main document's light DOM only. */
function renderAlerts(o: PageObservation, d: LineDialect): string[] {
  return o.alerts.filter((a) => d === 2 || a.legacy).map((a) => a.text);
}

/**
 * Whether the observation covered enough of the page for a missing LINE to
 * mean absent: every element walked, no line cap reached, every rendered
 * frame read and none past the cap, and no collection the page says is only
 * partly rendered. A hidden frame is not a gap — nothing in it is on screen.
 */
function coverageComplete(c: ObservationCoverage): boolean {
  return !c.nodesTruncated && !c.linesTruncated && c.frames.inaccessible.length === 0 && c.frames.overCap === 0 && !c.collections.partial;
}

/** The same question for live regions: every visible alert kept, and every rendered frame read. */
function alertsComplete(c: ObservationCoverage): boolean {
  return !c.alertsTruncated && c.frames.inaccessible.length === 0 && c.frames.overCap === 0;
}

/** Why an observation is not complete, in a few words for a verdict message; '' when it is. */
function describeCoverage(c: ObservationCoverage): string {
  const parts: string[] = [];
  if (c.nodesTruncated) parts.push(`the element cap was reached (${c.nodesWalked} walked)`);
  if (c.linesTruncated) parts.push('the line cap was reached');
  if (c.frames.inaccessible.length) {
    parts.push(`${c.frames.inaccessible.length} visible frame(s) could not be read (${c.frames.inaccessible.map((f) => f.reason).slice(0, 2).join('; ')})`);
  }
  if (c.frames.overCap) parts.push(`${c.frames.overCap} frame(s) past the frame cap`);
  if (c.collections.partial) parts.push(`a collection is only partly rendered (${c.collections.evidence.join(', ')})`);
  if (c.alertsTruncated) parts.push('the alert cap was reached');
  return parts.join('; ');
}

/**
 * One look at the live page in a dialect — its lines, its live-region
 * alerts, and the coverage behind them — or null when the page cannot be
 * read. Null is "unavailable", never "empty": a caller deciding whether an
 * effect landed, or whether an alert was raised, must not read a failed look
 * as a clean one. The single capture `capturePageLines`, `captureLines` and
 * the alert observation (observe.ts liveAlerts) are views of, so the walk,
 * the caps and the timeout exist once.
 */
async function capturePage(page: Page, d: LineDialect = 1, look: FullNameLook = {}): Promise<{ lines: string[]; alerts: string[]; coverage: ObservationCoverage } | null> {
  const o = await observePage(page, look);
  return o ? { lines: renderLines(o, d), alerts: renderAlerts(o, d), coverage: o.coverage } : null;
}

/**
 * The lines the page shows right now, in a dialect (dialect 1 unless asked),
 * or null when the page cannot be read (see capturePage).
 */
async function capturePageLines(page: Page, d: LineDialect = 1): Promise<string[] | null> {
  const captured = await capturePage(page, d);
  return captured ? captured.lines : null;
}

/** The lines, and whether the look covered enough of the page for a missing line to mean absent. */
async function captureLines(page: Page, d: LineDialect, look: FullNameLook = {}): Promise<{ lines: string[]; complete: boolean; coverage: ObservationCoverage } | null> {
  const captured = await capturePage(page, d, look);
  return captured ? { lines: captured.lines, complete: coverageComplete(captured.coverage), coverage: captured.coverage } : null;
}

/** How many added lines a step diff keeps — the recorder's own cap, so a replay diff and an artifact diff carry the same evidence. */
const MAX_ADDED_LINES = 20;

/**
 * The lines a step ADDED, as the recorder diffs its before/after signatures:
 * every after-line not present before, capped. Null when either capture
 * failed — a diff needs both legs, and a missing leg is not an empty change.
 */
function addedLines(before: string[] | null, after: string[] | null): string[] | null {
  if (before === null || after === null) return null;
  return after.filter((l) => !before.includes(l)).slice(0, MAX_ADDED_LINES);
}

/** The mirror of addedLines: what was on the page before the action and is gone after it. */
function removedLines(before: string[] | null, after: string[] | null): string[] | null {
  if (before === null || after === null) return null;
  return before.filter((l) => !after.includes(l)).slice(0, MAX_ADDED_LINES);
}

interface LineShowsOptions {
  /**
   * Identity matching: the want must sit at a letter/digit boundary on both
   * sides (see IDENTITY_EDGE) instead of anywhere inside a longer run of
   * characters. Only for "is this the right RECORD" — the effect gate asks
   * whether a change LANDED, which is a substring question and stays one.
   */
  whole?: boolean;
}

const normWs = (s: string) => s.replace(/\s+/g, ' ').trim();

/**
 * Does any of `wants` appear in `haystack` (recorded page lines, or a diff's
 * added lines)? Whitespace-insensitive on both sides — a marker copied with
 * a trailing space is the same word — and a `{{*}}` wildcard (see
 * maskVolatile) matches anything within one line.
 *
 * `opts.whole` switches to the IDENTITY rule: same wildcards, but bounded at
 * both edges so `fwgr25-n1` is no longer satisfied by `fwgr25-n10`. Only the
 * identity callers pass it; the effect gate asks a different question.
 */
function lineShows(haystack: string[], wants: string[], opts: LineShowsOptions = {}): boolean {
  const all = haystack.map(normWs).join('\n');
  return wants.some((raw) => {
    const want = normWs(raw);
    if (!want) return false;
    if (opts.whole) return identityRe(want).test(all);
    if (!want.includes(WILDCARD)) return all.includes(want);
    const re = new RegExp(want.split(WILDCARD).map(escapeRe).join('[^\\n]*?'));
    return re.test(all);
  });
}

/**
 * Is any of `lines` on the live page, in dialect `d`? 'present' needs only a
 * match. 'absent' needs a look that covered the page (coverageComplete);
 * a look that did not, or a page that could not be read at all, is
 * 'unknown' — a missing line there is not evidence of anything.
 */
async function presence(page: Page, lines: string[], d: LineDialect, opts: LineShowsOptions = {}): Promise<Presence> {
  return (await lookFor(page, lines, d, opts)).presence;
}

/** presence, with why an 'unknown' is unknown. */
async function lookFor(page: Page, lines: string[], d: LineDialect, opts: LineShowsOptions): Promise<{ presence: Presence; why?: string }> {
  const live = await captureLines(page, d);
  if (!live) return { presence: 'unknown', why: 'the page could not be read' };
  if (lineShows(live.lines, lines, opts)) return { presence: 'present' };
  return live.complete ? { presence: 'absent' } : { presence: 'unknown', why: describeCoverage(live.coverage) };
}

/**
 * presence, asked once more after sweeping the page when the first answer is
 * 'unknown' — a lazily rendered page paints what it has once scrolled end to
 * end (sweepPage). Still 'unknown' after that is the answer; `why` says what
 * the look could not cover.
 */
async function confirmPresence(page: Page, lines: string[], d: LineDialect, opts: LineShowsOptions = {}): Promise<{ presence: Presence; why?: string }> {
  const first = await lookFor(page, lines, d, opts);
  if (first.presence !== 'unknown' || !(await sweepPage(page))) return first;
  return lookFor(page, lines, d, opts);
}

/**
 * A parameterised line that did not *appear* may still be *there*: filling a
 * field with the value it already held produces no diff. One fresh look at the
 * live page settles it; only a match is a yes — a page that cannot be read,
 * or a look that could not cover it, shows nothing. Dialect 1 unless asked.
 */
async function presentOnPage(page: Page, lines: string[], opts: LineShowsOptions = {}, d: LineDialect = 1): Promise<boolean> {
  return (await presence(page, lines, d, opts)) === 'present';
}

/**
 * Runs in the page: do the identity and the goal hold of the SAME record?
 *
 * The record's container is the OUTERMOST ancestor of the goal text that is
 * one of several siblings of its kind — the row among rows, the card among
 * cards. Outermost, not nearest: a cell is one of several cells too, and
 * stopping there would ask whether the identity is inside the status cell,
 * which it never is. The row above it is the scope the page itself asserts is
 * one record, and it is what a `scoped` locator names. If the goal text has
 * no repeated ancestor at all the page is not listing records, and page-wide
 * agreement is the right answer there (a detail page's heading and its status
 * field share no small container).
 *
 * `identity` arrives as regex SOURCE (identitySource), already bounded: this
 * function is serialised into the page, so it cannot call identityRe, and a
 * second hand-written copy of the boundary rule here would be free to drift.
 */
function scopeCheckInPage(opts: { identity: string[]; goal: string[] }): boolean {
  const norm = (s: string | null | undefined) => (s ?? '').replace(/\s+/g, ' ').trim();
  const textOf = (el: Element) => norm((el as HTMLElement).innerText || el.textContent);
  const all = Array.from(document.querySelectorAll('*'));

  // The smallest elements that show a goal string: a container shows it too,
  // and starting from the container would skip the record scope below it.
  const holders: Element[] = [];
  for (const raw of opts.goal) {
    const want = norm(raw);
    if (!want) continue;
    const hits = all.filter((el) => textOf(el).includes(want));
    for (const el of hits) if (!hits.some((other) => other !== el && el.contains(other))) holders.push(el);
  }
  if (!holders.length) return false;

  // Siblings of a kind means STRUCTURALLY alike, not merely same-tag: two
  // unrelated buttons that happen to sit side by side are not a record list,
  // and treating them as one would scope a lone control to itself. Rows of a
  // list are rendered by one template and carry the same classes.
  const kindOf = (el: Element) => `${el.tagName}.${norm(el.getAttribute('class'))}`;
  const oneOfSeveral = (el: Element): boolean => {
    const parent = el.parentElement;
    // A direct child of <body> is a section of the page, not a record: a list
    // of records sits inside something. Without this, two unrelated top-level
    // controls make either of them its own "record" scope.
    if (!parent || parent === document.body) return false;
    const kind = kindOf(el);
    let same = 0;
    for (const sib of Array.from(parent.children)) if (kindOf(sib) === kind) same++;
    return same >= 2;
  };

  for (const holder of holders) {
    let node: Element | null = holder;
    let record: Element | null = null;
    while (node && node !== document.body) {
      if (oneOfSeveral(node)) record = node;
      node = node.parentElement;
    }
    if (!record) return true; // not a list: the whole page is about one record
    const inside = textOf(record);
    if (opts.identity.some((src) => new RegExp(src, 'iu').test(inside))) return true;
  }
  return false;
}

/**
 * Scroll the page end to end so a virtualised or lazily rendered UI paints
 * everything it has, then let the DOM settle. Returns false when the page
 * cannot be scripted (gone, cross-origin frame), in which case the caller
 * simply does not retry.
 */
async function sweepPage(page: Page): Promise<boolean> {
  try {
    await page.evaluate(() => window.scrollTo(0, document.documentElement.scrollHeight));
    await settleDom(page);
    await page.evaluate(() => window.scrollTo(0, 0));
    await settleDom(page);
    return true;
  } catch {
    return false;
  }
}

/**
 * Does the live page show a flow reference's RECORDED value, so that value may
 * stand in for one this run did not publish? Asked by both runners at the
 * moment a step's references are resolved, before the step runs (the daemon's
 * runFlow; the artifact's `needShown`). fwrd54: 06-change replays at tier A
 * without re-reading `mark_ready_button` ("Mark Ready"), and 07-edit — whose
 * pinned procedure clicks that button — fell to model recovery on n2 and n3
 * although the button was on the page it started from.
 *
 * Only a whole-token match (identityRe's bounded rule, via lineShows) on the
 * observation — visible text and accessible names alike — counts. A value
 * holding one of this run's own values (a var: `fwrd54-n2 RD Part A`) is
 * refused before looking: it names this run's record, and a page showing the
 * RECORDING's version of it would be the wrong record. The caller refuses what
 * it knows beyond that (id shapes, recorded vars, ledger evidence).
 */
async function recordedValueShown(page: Page, value: string, runValues: readonly string[]): Promise<boolean> {
  const want = value.replace(/\s+/g, ' ').trim();
  if (!want || want.includes('{{')) return false;
  const lower = want.toLowerCase();
  for (const raw of runValues) {
    const run = String(raw ?? '').trim().toLowerCase();
    if (run.length >= 2 && lower.includes(run)) return false;
  }
  try {
    return await presentOnPage(page, [want], { whole: true });
  } catch {
    return false;
  }
}

// Shared execution source: observe.ts. Regenerate to update.
/**
 * Observations both execution targets take of a live page, so that a shared
 * verdict (./gates.ts) is asked the same question in the same dialect by the
 * daemon and by a compiled `.flow.ts` artifact. Self-contained: this module is
 * embedded verbatim in the artifact (spec/runtime-source.ts), so nothing but
 * a sibling shared module or a Playwright type may be imported.
 */

/** What a recorded read takes off its element. A page url read has no element and is not one of these. */
type ReadWhat = 'text' | 'value' | 'attr' | 'count';

function isElementRead(what: unknown): what is ReadWhat {
  return what === 'text' || what === 'value' || what === 'attr' || what === 'count';
}

/** The part of a procedure step observedNothing looks at. */
interface ObservingStep {
  tool: string;
  args?: Record<string, unknown>;
  locators?: Record<string, readonly unknown[] | undefined>;
  /** What the read publishes as; an unlabelled read is only an observation, and the artifact does not take it. */
  label?: string;
}

/** Tools that neither set nor select anything: a procedure of only these (and reads) is read-only. */
const LOOKING_TOOLS = new Set(['goto', 'back', 'wait_for', 'screenshot', 'scroll', 'hover']);

/**
 * A READ-ONLY procedure (navigation and reads, nothing that sets anything)
 * that took none of the reads it could take has not replayed: it looked at a
 * page and saw nothing it was recorded seeing. Each skipped read alone is an
 * observation lost, never a failure — but when every one of them is lost the
 * procedure is on the wrong page, and "ran" would be a false pass.
 *
 * fwop4-n2 08-open is that pass: s_c4a13c's goto kept run 1's work package
 * (41, deleted by the reset), all nine reads skipped, the step reported tier A
 * 10/10 and its report came from the template, naming run 2's record. Only
 * reads with a recorded way to find their element count: one whose chain is
 * empty is skipped on every run by design ("has no locator left"), and only
 * LABELLED reads, the ones both runners take (an unlabelled read is a comment
 * in the artifact).
 */
function observedNothing(steps: readonly ObservingStep[], skippedReads: number): boolean {
  const reads = steps.filter(
    (s) => (s.tool === 'read' || s.tool === 'read_all') && Boolean(s.label) && isElementRead(s.args?.what ?? 'text') && (s.locators?.target?.length ?? 0) > 0,
  ).length;
  if (!reads || skippedReads < reads) return false;
  return steps.every((s) => s.tool === 'read' || s.tool === 'read_all' || LOOKING_TOOLS.has(s.tool));
}

/**
 * What an element that renders NO text is called: its aria-label, its title,
 * its own alt, else the alt of an image inside it — the accessible name the
 * recording located it by, where innerText has nothing. fwgt5 01-signin's
 * `org_link` read found gitea's image-only org link by its name "bench",
 * read innerText, and published "" on both replays and in the artifact.
 * Runs in the page, so it names nothing outside itself.
 */
const RENDERED_NAME = (el: Element): string =>
  (
    el.getAttribute('aria-label') ||
    el.getAttribute('title') ||
    el.getAttribute('alt') ||
    el.querySelector('img[alt]')?.getAttribute('alt') ||
    ''
  ).trim();

/**
 * RENDERED_NAME over every match, for a `read_all`. Its own copy of the rule,
 * because a function handed to the page is serialised ALONE: calling
 * RENDERED_NAME from inside an evaluateAll callback threw "RENDERED_NAME is
 * not defined" in the page and failed every plural text read with a blank
 * match (test/browser.test.ts, hidden `.ghost` rows).
 */
const RENDERED_NAMES = (els: Element[]): string[] =>
  els.map((el) =>
    (
      el.getAttribute('aria-label') ||
      el.getAttribute('title') ||
      el.getAttribute('alt') ||
      el.querySelector('img[alt]')?.getAttribute('alt') ||
      ''
    ).trim(),
  );

/**
 * A recorded `read` (one element) or `read_all` (every match), as the daemon's
 * read tools take it and a compiled artifact replays it. `read_all` reads
 * EVERY match: an artifact that took `inputValue()` threw Playwright's
 * strict-mode error on a selector made to match many (odoo's
 * `tr.o_data_row input`, four reads skipped on every compiled run of fwod41
 * while the daemon read them each time). Text is `innerText`, the rendered
 * text the recording saw, never `textContent`, edges trimmed — and, for an
 * element that renders none, its name (RENDERED_NAME). A count is plural by nature,
 * whichever tool asked.
 */
async function readElements(
  loc: Locator,
  plural: boolean,
  what: ReadWhat,
  opts: { attr?: string; timeout?: number } = {},
): Promise<string | number | null | (string | null)[]> {
  const { attr = '', timeout } = opts;
  if (what === 'count') return await loc.count();
  if (plural) {
    if (what === 'text') {
      // Edges trimmed, as the singular read below (fwkb39).
      const texts = (await loc.allInnerTexts()).map((t) => t.trim());
      if (texts.every((t) => t)) return texts;
      const names = await loc.evaluateAll(RENDERED_NAMES);
      return texts.map((t, i) => (t ? t : (names[i] ?? t)));
    }
    if (what === 'value') return await loc.evaluateAll((els) => els.map((e) => (e as HTMLInputElement).value ?? null));
    return await loc.evaluateAll((els, a) => els.map((e) => e.getAttribute(a)), attr);
  }
  if (what === 'text') {
    // A text read is banked with its edge whitespace trimmed: kanboard fwkb39
    // published innerText "Backlog " (a trailing space inside the link), and
    // the value then travelled into an expectation line no snapshot matches.
    // Inner line breaks are the element's own and stay.
    const text = (await loc.innerText({ timeout })).trim();
    return text ? text : (await loc.evaluate(RENDERED_NAME, undefined, { timeout })) || text;
  }
  if (what === 'value') return await loc.inputValue({ timeout });
  return await loc.getAttribute(attr, { timeout });
}

/** A read as the one string a step publishes: every match of a `read_all`, in page order, joined by ` | `. */
function flattenRead(value: unknown): string {
  return Array.isArray(value) ? value.map(String).join(' | ') : String(value);
}

/**
 * A read as its step publishes it: the whole value, or — for a read recorded
 * with a FRAME (a read-back pinned by containment, text.ts FRAME_MARK) — only
 * the text at the frame's mark. A frame the element no longer shows THROWS,
 * so takeRead turns it into a skipped read: the value goes unpublished and a
 * reference to it goes to recovery, never out as the element's whole line
 * (fwvk3 n2 published "fwvk3-n2 Bench Task" for a runid). Both runners call
 * this inside takeRead, so they publish the same span or skip the same read.
 */
function framedRead(value: unknown, frame: unknown): unknown {
  if (typeof frame !== 'string' || !frame) return value;
  const got = extractFramed(flattenRead(value), frame);
  if (got === null) throw new Error(`the element no longer shows the value where the recording saw it (${JSON.stringify(clip(frame, 80))})`);
  return got;
}

/**
 * What a slot-scoped read (skills/readscope.ts) carries, its slots already
 * resolved to this run's values: the recorded `frame`; `slotFrame`, the same
 * frame with its line written in a slot's value and no mark; `mark`, the value
 * of the slot the mark stands for; `within`, the value of the slot the read's
 * recorded value contained.
 */
interface ReadScope {
  frame?: unknown;
  slotFrame?: unknown;
  mark?: unknown;
  within?: unknown;
}

/**
 * A read as its step publishes it once its SCOPE is applied — framedRead,
 * with the frame taken from this run's slot values when they place the mark
 * (text.ts markFrame; the recorded frame otherwise), and then the record check:
 * a read whose recorded value contained a slot's value must show THIS run's
 * value for that slot, or it resolved onto another record and THROWS, which
 * takeRead turns into a skipped read — absent, never another record's value.
 *
 * repairdesk fwrd87 04-add: s_9e190d, recorded adding Part A, replayed for
 * Part B. Its part_name reads had no candidate scoped by the part-name slot;
 * the positional primary matched both rows and the fallback was Part A's own
 * test hook, so both replays published Part A's name beside Part B's cost.
 * Both runners call this inside takeRead, so they publish the same value or
 * skip the same read. A slot this run did not bind asks nothing.
 */
function scopedRead(value: unknown, scope: ReadScope): unknown {
  const placed =
    typeof scope.slotFrame === 'string' && scope.slotFrame && typeof scope.mark === 'string' ? markFrame(scope.slotFrame, scope.mark) : null;
  const got = framedRead(value, placed ?? scope.frame);
  const fold = (s: string) => s.replace(/\s+/g, ' ').trim().toLowerCase();
  const within = typeof scope.within === 'string' ? fold(scope.within) : '';
  if (within && !fold(flattenRead(got)).includes(within)) {
    throw new ScopeMiss(`the element shows another record than ${JSON.stringify(clip(String(scope.within), 80))} — not published`, flattenRead(got));
  }
  return got;
}

/** scopedRead's record check failing: the element read shows another value than the scope's. */
class ScopeMiss extends Error {
  constructor(
    message: string,
    readonly shown: string,
  ) {
    super(message);
  }
}

/** A scoped read that proves the value the procedure SET did not land (scopedReadLanded); takeRead reports it `lost`. */
class ScopedValueLost extends Error {}

/**
 * Whether a procedure SET the value slot `slot` names: a fill, type or select
 * of it, or a click on the element named by it exactly (its target's quoted
 * name, or a candidate whose name or text is the slot).
 * gitea fwgt12 s_f54a5a set `{{v4}}` ("bug") by filling and clicking it.
 */
function scopeSetBy(
  steps: readonly { tool: string; args?: Record<string, unknown>; locators?: { target?: readonly object[] } }[],
  slot: unknown,
): boolean {
  if (typeof slot !== 'string' || !/^[vd]\d+$/.test(slot)) return false;
  const marker = `{{${slot}}}`;
  const has = (v: unknown) => typeof v === 'string' && v.includes(marker);
  return steps.some((s) => {
    if (s.tool === 'fill' || s.tool === 'type' || s.tool === 'select') return has(s.args?.value) || has(s.args?.text) || has(s.args?.option);
    if (s.tool !== 'click' && s.tool !== 'check' && s.tool !== 'dblclick') return false;
    // A click SETS the value when it picks the element named by it exactly —
    // an option or item called `{{v4}}` — not one whose name merely includes
    // it (a heading `{{v2}} #5` names a record; clicking it sets nothing).
    const exact = (v: unknown) => v === marker;
    const target = typeof s.args?.target === 'string' ? s.args.target : '';
    return target.includes(`"${marker}"`) || (s.locators?.target ?? []).some((c) => exact((c as { name?: unknown }).name) || exact((c as { text?: unknown }).text));
  });
}

/**
 * scopedRead, and then (round 61, gitea fwgt12 03-set) the difference between
 * a read that landed on ANOTHER record and one whose value is gone. A scope
 * miss on a text read of a value the procedure SET (`set`), where no element
 * the read's locator matches shows that value, is evidence that what the step
 * set did not land: s_f54a5a read the sidebar labels scoped to "bug" and
 * found "priority-high", and the artifact skipped the read and passed while
 * the issue lost "bug". That throws ScopedValueLost, which both runners turn
 * into a failed step. A miss where some match still shows the value is
 * another record read (fwrd87's Part A row for Part B): skipped, as before.
 */
async function scopedReadLanded(value: unknown, scope: ReadScope, loc: Locator | null, o: { set: boolean; what: string }): Promise<unknown> {
  try {
    return scopedRead(value, scope);
  } catch (err) {
    if (!(err instanceof ScopeMiss) || !o.set || o.what !== 'text' || !loc || typeof scope.within !== 'string') throw err;
    const fold = (s: string) => s.replace(/\s+/g, ' ').trim().toLowerCase();
    const within = fold(scope.within);
    const texts = await loc.allInnerTexts().catch(() => null);
    if (texts === null || texts.some((t) => fold(t).includes(within))) throw err;
    throw new ScopedValueLost(
      `the read scoped to ${JSON.stringify(clip(scope.within, 80))}, a value this procedure set, shows ${JSON.stringify(clip(err.shown, 80))} and nothing it reads shows ${JSON.stringify(clip(scope.within, 80))}: what the step set did not land`,
    );
  }
}


/**
 * Where a read's target is, for an OBSERVATION: the runner's own resolution,
 * and when that finds nothing, one sweep of the page and the resolution once
 * more with no wait (`again`), the wait having already been spent. A
 * virtualised page renders below-the-fold content only once it has been
 * scrolled to, and the agent's scrolls were evals, which never compile
 * (fwgr23 01-open lost the third panel heading without it). A page that
 * cannot be swept is not asked again.
 *
 * The runner supplies `resolve` because what it books around a resolution
 * differs (replay's candidate evidence and misses, the artifact's drift lines
 * and loop sink); WHEN it is asked, and how often, is this rule. Whatever
 * `resolve` throws (a loop progress guard stopping the pass) is not a miss and
 * propagates.
 */
async function resolveForRead<H>(page: Page, resolve: (again: boolean) => Promise<H | null>): Promise<H | null> {
  const hit = await resolve(false);
  if (hit || !(await sweepPage(page))) return hit;
  return resolve(true);
}

type ReadTaken = { ok: true; value: string } | { ok: false; message: string; lost?: true };

/**
 * A resolved read, taken. A read is an observation and never fails the step:
 * a read that throws (the element detached, a strict-mode match, a closed
 * page) comes back as `ok: false` with the error's first part, and the
 * runner skips it with that message. Values are flattened (flattenRead) so
 * both runners publish the same string for the same page.
 */
async function takeRead(read: () => Promise<unknown>): Promise<ReadTaken> {
  try {
    return { ok: true, value: flattenRead(await read()) };
  } catch (err) {
    const message = (err instanceof Error ? err.message : String(err)).split('\nCall log:')[0];
    return err instanceof ScopedValueLost ? { ok: false, message, lost: true } : { ok: false, message };
  }
}

/**
 * Where a count read looks: the container its candidate counts INSIDE, as a
 * locator both runners build from the root (`selector`, with the scoped
 * candidate's `hasText`), or `'root'` when the candidate counts across the
 * whole page or recorded frame.
 */
type CountScope = 'root' | { selector: string; hasText?: string };

/**
 * One css selector's container: everything before its last top-level
 * combinator (`>`, `+`, `~` or a descendant space), outside brackets,
 * parentheses and quotes. `'root'` for a single compound (`#list`, `li.row`),
 * null for a selector list — a `,` at top level scopes nothing in particular.
 */
/** A css selector list's members, split at its top-level commas (brackets, parentheses and quotes respected); one member when it is no list. */
function selectorListMembers(selector: string): string[] {
  const out: string[] = [];
  let depth = 0;
  let quote = '';
  let from = 0;
  for (let i = 0; i < selector.length; i++) {
    const ch = selector[i];
    if (quote) {
      if (ch === '\\') i++;
      else if (ch === quote) quote = '';
      continue;
    }
    if (ch === '"' || ch === "'") quote = ch;
    else if (ch === '[' || ch === '(') depth++;
    else if (ch === ']' || ch === ')') depth--;
    else if (depth === 0 && ch === ',') {
      out.push(selector.slice(from, i).trim());
      from = i + 1;
    }
  }
  out.push(selector.slice(from).trim());
  return out.filter(Boolean);
}

function cssContainer(selector: string): CountScope | null {
  let depth = 0;
  let quote = '';
  let cut = -1;
  for (let i = 0; i < selector.length; i++) {
    const ch = selector[i];
    if (quote) {
      if (ch === '\\') i++;
      else if (ch === quote) quote = '';
      continue;
    }
    if (ch === '"' || ch === "'") quote = ch;
    else if (ch === '[' || ch === '(') depth++;
    else if (ch === ']' || ch === ')') depth--;
    else if (depth === 0 && ch === ',') return null;
    else if (depth === 0 && (ch === '>' || ch === '+' || ch === '~' || /\s/.test(ch))) cut = i;
  }
  if (cut < 0) return 'root';
  const prefix = selector.slice(0, cut).replace(/[\s>+~]+$/, '').trim();
  return prefix ? { selector: prefix } : 'root';
}

/**
 * The scope of each candidate of a COUNT read's chain (its params filled), or
 * null when one of them has a scope this rule cannot name — then a miss is
 * never read as a count of nothing. Points are left out: a place on the
 * page counts nothing.
 *
 *  - `scoped`: its container with its text (hasTextMatcher, as makeLocator
 *    builds it).
 *  - `css` / `id`: a Playwright chain (`a >> b`) is scoped by everything
 *    before its last segment (a trailing `nth=` is the element, not a scope);
 *    a single segment that is an engine selector (`role=…`, `text=…`,
 *    an xpath) counts across the root; a css selector is scoped by what comes
 *    before its last combinator (`#list > li` by `#list`).
 *  - `role`, `testid`, `text`, `label`, `placeholder`: across the root.
 */
function countScopes(chain: readonly { kind: string; selector?: string; container?: string; hasText?: string }[]): CountScope[] | null {
  const out: CountScope[] = [];
  for (const c of chain) {
    if (c.kind === 'point') continue;
    if (c.kind === 'scoped') {
      if (!c.container) return null;
      out.push({ selector: implicitRoles(c.container), hasText: c.hasText ?? '' });
      continue;
    }
    if (c.kind === 'css' || c.kind === 'id') {
      if (!c.selector) return null;
      const segments = implicitRoles(c.selector).split(' >> ').map((s) => s.trim());
      while (segments.length > 1 && /^nth=-?\d+$/.test(segments[segments.length - 1])) segments.pop();
      if (segments.length > 1) {
        out.push({ selector: segments.slice(0, -1).join(' >> ') });
        continue;
      }
      const only = segments[0];
      if (/^[a-z][\w-]*=/i.test(only) || only.startsWith('/') || only.startsWith('(')) {
        out.push('root');
        continue;
      }
      // A selector LIST is a union: counted across the page when every member
      // is (fwgt10 s_2ea0ba step 1, `.issue-title, .issue-title-link`,
      // skipped on every replay); a member with a container of its own still
      // names nothing — which container would have to be present is not one
      // question.
      const members = selectorListMembers(only);
      if (members.length > 1) {
        if (!members.every((m) => cssContainer(m) === 'root')) return null;
        out.push('root');
        continue;
      }
      const scope = cssContainer(only);
      if (!scope) return null;
      out.push(scope);
      continue;
    }
    if (['role', 'testid', 'text', 'label', 'placeholder'].includes(c.kind)) out.push('root');
    else return null;
  }
  return out;
}

/**
 * Whether a COUNT read that resolved nothing observed a count of nothing —
 * "0", a value — rather than failing to look. repairdesk fwrd88 05-change:
 * s_4b0e31 counted the page's alerts (by role) after a status change and recorded "0"; on
 * replay nothing matched, and both runners skipped the read, so a correct,
 * observed answer went unpublished and the step read as partial.
 *
 * Asked only after the runner's full resolve wait and the page sweep
 * (resolveForRead). "Nothing" must be the page's answer, not a page that has
 * not drawn its list yet, so, once the DOM has gone quiet:
 *  - every candidate (points aside) matches no element at all — a miss for
 *    any other reason (identity, a thrown selector) is not a count;
 *  - every candidate's SCOPE (countScopes) is there: the whole root, or its
 *    container matching at least one element. A count of `#list > li`
 *    whose `#list` never rendered is a page that did not arrive, and the read
 *    is skipped as before.
 * Both runners call this with their own candidate locators and root, so they
 * publish "0" or skip on the same page.
 */
async function countedNothing(
  page: Page,
  root: { locator(selector: string, options?: { hasText?: string | RegExp }): Locator },
  candidates: readonly { kind: string; locator: Locator }[],
  scopes: readonly CountScope[] | null,
): Promise<boolean> {
  if (!scopes) return false;
  const counted = candidates.filter((c) => c.kind !== 'point');
  if (!counted.length) return false;
  try {
    await settleDom(page);
    for (const c of counted) if ((await c.locator.count()) !== 0) return false;
    for (const scope of scopes) {
      if (scope === 'root') continue;
      const within = root.locator(scope.selector, scope.hasText !== undefined ? { hasText: hasTextMatcher(scope.hasText) } : undefined);
      if ((await within.count()) < 1) return false;
    }
    return true;
  } catch {
    return false;
  }
}

/**
 * The visible live-region texts on the page right now — the alerts half of
 * the ONE page capture the daemon diffs (observeDocumentInPage under
 * SNAPSHOT_LIMITS, src/execution/snapshot.ts), rendered in the step's line
 * dialect: the same elements, visibility rule, caps and whitespace cleaning
 * by construction, not by a second copy kept in step. An alert the daemon
 * would diff is one the artifact sees. These are toasts and status lines, not
 * native `window.alert` dialogs. Null when the page cannot be read
 * (navigating, closed, not answering): "unobserved", never "no alert".
 */
async function liveAlerts(page: Page, d: LineDialect = 1): Promise<string[] | null> {
  const captured = await capturePage(page, d);
  return captured ? captured.alerts : null;
}

/** Live-region texts with whether the look saw every one of them (alertsComplete) — what alertVerdict needs to tell "none raised" from "none seen". */
interface ObservedAlerts {
  alerts: string[];
  complete: boolean;
}

/** liveAlerts, with its coverage: null when the page cannot be read. */
async function liveAlertsObserved(page: Page, d: LineDialect = 1): Promise<ObservedAlerts | null> {
  const captured = await capturePage(page, d);
  return captured ? { alerts: captured.alerts, complete: alertsComplete(captured.coverage) } : null;
}

// Shared execution source: action.ts. Regenerate to update.
/**
 * One observation per action (notes/ROBUSTNESS.md finding 6): begun BEFORE the
 * action dispatches, it owns the action's whole deadline, its baseline of the
 * page's traffic, and what it expects to see, and it says afterwards how the
 * action ended — not dispatched, dispatched, effect verified, or unknown.
 *
 * It replaces two request trackers that disagreed about what "busy" means
 * (every request since the page was adopted, in the old shared counter;
 * fetch/XHR minus paths NAMED like streams, in the daemon's settle). Traffic
 * is recorded once per page here, and whether a request is long-lived is
 * decided by what it does — its transport, its content type, a body that
 * keeps streaming, a request that was already open before the action, one
 * that has waited far longer than an answer takes — never by its url. An app
 * whose ordinary endpoint is called `/api/notifications` is waited for like
 * any other; an event stream on `/api/save` is not.
 *
 * Waiting is evidence, not a sleep: the DOM going quiet, requests the action
 * started landing, a request that starts in the moment after an input (a
 * debounced save), the url holding still after a navigating action, and the
 * expected effect when the caller has one. Completion is the expectation when
 * there is one; quiet alone never verifies an effect.
 *
 * Daemon: tools.ts runStep, around every state-changing tool. Artifact: the
 * emitted step, around its action. Self-contained: sibling shared modules and
 * Playwright types only. Every port (clock, page events, DOM) can be faked, so
 * the policy is tested without a browser or a wall clock.
 */

/**
 * What counts as an action's traffic, and when an open request stops being
 * something to wait for.
 *  - `countedTypes`: resource types an action can be waiting on. Images,
 *    fonts, media and beacons are recorded but never waited for.
 *  - `streamBodyMs`: a fetch/XHR whose headers arrived and whose body is
 *    still open this long later is streaming, not answering.
 *  - `longOpenMs`: a fetch/XHR open this long with no answer at all is a
 *    long-poll, not a save.
 *  - `recentMs`: a request started this long or less before the action began
 *    may still be the action's (a click handler's fetch races the click call
 *    returning); an older one still open is the page's own.
 */
interface TrafficPolicy {
  countedTypes: readonly string[];
  streamBodyMs: number;
  longOpenMs: number;
  recentMs: number;
}

const DEFAULT_TRAFFIC_POLICY: TrafficPolicy = {
  countedTypes: ['fetch', 'xhr', 'document', 'script'],
  streamBodyMs: 1_000,
  longOpenMs: 5_000,
  recentMs: 300,
};

/** Why an open request is not one an action waits for. */
type LongLivedWhy = 'transport' | 'event-stream' | 'streaming-body' | 'open-at-baseline' | 'open-too-long' | 'known-long-poll';

/** One request as the page's traffic recorded it. Times are the traffic clock's. */
interface RequestRecord {
  type: string;
  method: string;
  /** origin + pathname: the endpoint, without the query a poll varies. */
  endpoint: string;
  url: string;
  startedAt: number;
  responseAt?: number;
  contentType?: string;
  finishedAt?: number;
  /** The endpoint the request's redirect chain began at, when it was redirected there. */
  chainEndpoint?: string;
}

interface ActionClock {
  now(): number;
  sleep(ms: number): Promise<void>;
}

/** The page events traffic is recorded from — a Playwright Page, or a fake. */
interface PageEventsPort {
  on(event: string, listener: (arg: never) => void): unknown;
  off(event: string, listener: (arg: never) => void): unknown;
  url(): string;
  mainFrame?(): unknown;
}

/** The DOM as an action's observation asks it: go quiet within `maxMs`, and say when it last changed. */
interface DomPort {
  quiet(quietMs: number, maxMs: number): Promise<{ mutated: boolean; lastMutationAt?: number }>;
  /**
   * What the page's live regions are announcing right now: the visible text of
   * every `aria-live` region and `status`/`alert` role. Optional — a port that
   * cannot say announces nothing, and the observation waits on nothing.
   */
  announced?(): Promise<string[]>;
}

/** An action's expected effect: true when it holds, false when it does not, null when it could not be observed. */
interface ActionExpectation {
  holds(): Promise<boolean | null>;
}

/** One page's recorded traffic, installed once and shared by every action on that page. */
interface PageTraffic {
  readonly policy: TrafficPolicy;
  readonly clock: ActionClock;
  /** Requests still open, in start order. */
  pending(): RequestRecord[];
  /** When a counted request last finished (-Infinity before any did). */
  lastFinish(): number;
  /** Endpoints (`METHOD origin/path`) that have behaved as long-polls or streams on this page. */
  readonly knownLongPoll: ReadonlySet<string>;
  /** classifyLongLived over this page's learned endpoints; learns the endpoint of a request that proves long-lived by behaviour. */
  classify(r: RequestRecord, now: number, baselineAt: number): LongLivedWhy | null;
  /** Called on every request, response, finish and main-frame navigation; returns the unsubscribe. */
  subscribe(listener: () => void): () => void;
  /** Requests started at or after `since` (open or finished), from a bounded recent history, in start order. */
  startedSince(since: number): RequestRecord[];
}

const realClock: ActionClock = {
  now: () => Date.now(),
  sleep: (ms) => new Promise<void>((resolve) => setTimeout(resolve, Math.max(0, ms))),
};

/** The endpoint key a long-poll is remembered by. */
function endpointKey(r: Pick<RequestRecord, 'method' | 'endpoint'>): string {
  return `${r.method} ${r.endpoint}`;
}

/** Transports a poll or a stream rides on: the only ones judged by how long they stay open. */
function polling(r: RequestRecord): boolean {
  return r.type === 'fetch' || r.type === 'xhr';
}

/**
 * Whether an open request is long-lived, and why — in this order:
 *  1. a stream transport (`eventsource`, `websocket`);
 *  2. a response that says it streams (`text/event-stream`,
 *     `multipart/x-mixed-replace`);
 *  3. a fetch/XHR whose headers came and whose body has stayed open past
 *     `streamBodyMs`;
 *  4. a request older than the action (started more than `recentMs` before
 *     `baselineAt`) and still open at it: the page's, not the action's;
 *  5. a fetch/XHR open past `longOpenMs` with no answer;
 *  6. a fetch/XHR to an endpoint this page has already shown to be a
 *     long-poll or a stream (`known`).
 * Null: an ordinary request, whatever its url says.
 */
function classifyLongLived(
  r: RequestRecord,
  now: number,
  baselineAt: number,
  policy: TrafficPolicy = DEFAULT_TRAFFIC_POLICY,
  known: ReadonlySet<string> = new Set(),
): LongLivedWhy | null {
  if (r.type === 'eventsource' || r.type === 'websocket') return 'transport';
  if (r.contentType && /^\s*(text\/event-stream|multipart\/x-mixed-replace)/i.test(r.contentType)) return 'event-stream';
  if (polling(r) && r.responseAt !== undefined && r.finishedAt === undefined && now - r.responseAt > policy.streamBodyMs) return 'streaming-body';
  if (r.startedAt < baselineAt - policy.recentMs && (r.finishedAt === undefined || r.finishedAt > baselineAt)) return 'open-at-baseline';
  if (polling(r) && r.responseAt === undefined && r.finishedAt === undefined && now - r.startedAt > policy.longOpenMs) return 'open-too-long';
  if (polling(r) && known.has(endpointKey(r))) return 'known-long-poll';
  return null;
}

const traffics = new WeakMap<object, PageTraffic>();

/** A Playwright request/response, as far as traffic reads one. */
interface RequestLike {
  resourceType(): string;
  method(): string;
  url(): string;
  redirectedFrom?(): RequestLike | null;
}

/** How many recent requests a page's traffic keeps for startedSince. */
const RECENT_REQUESTS = 256;

/** origin + pathname of a url: the endpoint a request is recorded under. */
function endpointOf(url: string): string {
  try {
    const parsed = new URL(url);
    return `${parsed.origin}${parsed.pathname}`;
  } catch {
    return url;
  }
}
interface ResponseLike {
  request(): RequestLike;
  headers(): Record<string, string>;
}

/**
 * The page's traffic, recorded from its own request events: installed on the
 * first call for a page and returned as-is after that, so the daemon installs
 * it when its session adopts a page and every action (daemon or artifact)
 * reads the same record. A page with no request events (a test stub) reads as
 * idle. `opts` apply only to the call that installs it.
 */
function pageTraffic(page: Page | PageEventsPort, opts: { policy?: TrafficPolicy; clock?: ActionClock } = {}): PageTraffic {
  const port = page as unknown as PageEventsPort;
  const existing = traffics.get(port);
  if (existing) return existing;
  const policy = opts.policy ?? DEFAULT_TRAFFIC_POLICY;
  const clock = opts.clock ?? realClock;
  const open = new Map<unknown, RequestRecord>();
  const recent: RequestRecord[] = [];
  const known: Set<string> = new Set();
  const listeners = new Set<() => void>();
  let lastFinish = -Infinity;
  const notify = () => {
    for (const listener of [...listeners]) listener();
  };
  // A request that proved long-lived by what it did is remembered by its
  // endpoint, so the next poll to it is not waited out for `longOpenMs` again.
  // Only the behavioural rules teach: a request that was merely open before an
  // action says nothing about its endpoint.
  const learn = (r: RequestRecord, why: LongLivedWhy | null) => {
    if (polling(r) && (why === 'event-stream' || why === 'streaming-body' || why === 'open-too-long')) known.add(endpointKey(r));
  };
  const traffic: PageTraffic = {
    policy,
    clock,
    pending: () => [...open.values()],
    lastFinish: () => lastFinish,
    knownLongPoll: known,
    classify: (r, now, baselineAt) => {
      const why = classifyLongLived(r, now, baselineAt, policy, known);
      learn(r, why);
      return why;
    },
    subscribe: (listener) => {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
    startedSince: (since) => recent.filter((r) => r.startedAt >= since),
  };
  traffics.set(port, traffic);
  if (typeof port.on !== 'function') return traffic;
  port.on('request', (req: RequestLike) => {
    let url = '';
    try {
      url = req.url();
    } catch {
      // unreadable: recorded under the empty endpoint
    }
    const record: RequestRecord = { type: req.resourceType(), method: req.method(), endpoint: endpointOf(url), url, startedAt: clock.now() };
    // A redirect hop is a new request; the chain's first url is what a link asked for.
    let first: RequestLike | null = null;
    try {
      for (let hop = req.redirectedFrom?.() ?? null; hop; hop = hop.redirectedFrom?.() ?? null) first = hop;
      if (first) record.chainEndpoint = endpointOf(first.url());
    } catch {
      // a chain that cannot be walked: the request stands for itself
    }
    open.set(req, record);
    recent.push(record);
    if (recent.length > RECENT_REQUESTS) recent.shift();
    notify();
  });
  port.on('response', (res: ResponseLike) => {
    const r = open.get(res.request());
    if (!r) return;
    // Judged once as it stood unanswered (a long-poll's wait), then as answered.
    const now = clock.now();
    learn(r, classifyLongLived(r, now, -Infinity, policy));
    r.responseAt = now;
    try {
      r.contentType = res.headers()['content-type'];
    } catch {
      // headers unreadable: judged by behaviour alone
    }
    learn(r, classifyLongLived(r, r.responseAt, -Infinity, policy));
    notify();
  });
  const done = (req: unknown) => {
    const r = open.get(req);
    if (!r) return;
    open.delete(req);
    const now = clock.now();
    // Judged at the moment before it finished: a body that streamed for
    // seconds, or an answer that took a long-poll's time, taught something.
    learn(r, classifyLongLived(r, now, -Infinity, policy));
    r.finishedAt = now;
    if (policy.countedTypes.includes(r.type)) lastFinish = now;
    notify();
  };
  port.on('requestfinished', done);
  port.on('requestfailed', done);
  // A navigation abandons the old document's requests; without this a stale
  // entry would hold the next action to its cap.
  port.on('framenavigated', (frame: unknown) => {
    if (typeof port.mainFrame === 'function' && frame !== port.mainFrame()) return;
    for (const [req, r] of open) if (r.type !== 'document') open.delete(req);
    notify();
  });
  return traffic;
}

/**
 * How many ordinary requests `page` has in flight: counted types, not
 * long-lived by behaviour. 0 for a page whose traffic was never installed.
 */
function inFlightRequests(page: Page | PageEventsPort): number {
  const traffic = traffics.get(page as unknown as object);
  if (!traffic) return 0;
  const now = traffic.clock.now();
  return traffic.pending().filter((r) => traffic.policy.countedTypes.includes(r.type) && traffic.classify(r, now, -Infinity) === null).length;
}

/**
 * How long the flow's start page gets to finish ROUTING once it shows
 * content. Longer than a click's LATE_NAV_MS: the redirect waits on a server
 * round trip the app makes after it painted (who is signed in?), and it runs
 * once per flow, not once per action.
 */
const START_SETTLE_MS = 3_000;

/**
 * Where the flow's start navigation actually leaves the browser: the url once
 * it has held still, with nothing the page asked of the server still out.
 * Both runners judge the first segment's start page right after the start
 * goto, and "shows content" (waitForContent) is not "has finished routing".
 * fwrd78's artifact refused its sign-in segment on `#/tickets` twice, while
 * the daemon passed it at tier A twice: the app paints a static shell (a skip
 * link is content), sets `#/tickets` for a bare entry url, asks `/api/me`, and
 * only on the 401 moves a signed-out visitor to `#/login`. The browser was
 * never signed in — a fresh context has no session cookie — it was read
 * mid-route. A page with nothing in flight and a url that does not move
 * returns at once (urlHeldStill), so a server-rendered start page pays nothing.
 */
async function startPageSettled(
  page: Pick<Page, 'url'>,
  inFlightNow: () => number = () => inFlightRequests(page as Page),
  timing: { lateNavMs?: number; stillMs?: number; pollMs?: number } = {},
): Promise<string> {
  return urlHeldStill(page, page.url(), inFlightNow, { lateNavMs: START_SETTLE_MS, ...timing });
}

interface ActionOptions {
  /** The whole action — dispatch, every wait, the effect — ends by this long after beginAction. */
  deadlineMs: number;
  /** When given, completion: polled after the page settles, within `effectWaitMs`. */
  expect?: ActionExpectation;
  /** A tool whose effect may be a navigation: the url is waited on to hold still (urlHeldStill). */
  navigating?: boolean;
  /**
   * An input (fill, type, press, select, check): the start grace runs from
   * the dispatch itself, because an input's own save is commonly debounced
   * and changes nothing on the page before it asks. Otherwise the grace runs
   * only from a mutation or a request finishing.
   */
  graceFromDispatch?: boolean;
  /** How long after the last evidence a request may still start and be the action's. */
  startGraceMs?: number;
  /** The most one network wait may cost. */
  networkCapMs?: number;
  /** The most the expected effect is polled for. */
  effectWaitMs?: number;
  clock?: ActionClock;
  dom?: DomPort;
  policy?: TrafficPolicy;
}

/** A click on a link: where the page was when the action began, and where the link points. */
interface LinkNavigation {
  from: string;
  href: string;
}

/** How an action ended, and what its settle waited on. */
interface SettleVerdict {
  outcome: ActionOutcome;
  /** Where the page is once the action settled. */
  url: string;
  /** The action was a click on a link that leaves the document (ClickObservation.linkTarget). */
  link?: LinkNavigation;
  via?: DispatchVia;
  waited: { domMs: number; networkMs: number; urlMs: number; effectMs: number };
  /** Open requests that were not waited for, and why. */
  ignored: { url: string; why: LongLivedWhy }[];
  /** A wait was cut short by the action's deadline. */
  deadlineHit: boolean;
}

interface ActionObservation {
  /** Milliseconds left of the action's deadline (never negative). */
  remaining(): number;
  /** The action went out, this way. */
  dispatched(via: DispatchVia): void;
  /** The action threw: its outcome is what the error proves (outcomeOfError), and the error is rethrown. */
  failed(err: unknown): never;
  /** The clicked element links this tab to `href`: the settle waits on that navigation (LINK_NAV_WAIT_MS). */
  linkTarget(href: string): void;
  /** The link this action clicked, once one was reported. */
  link(): LinkNavigation | undefined;
  /** Wait for the action's evidence; the same promise on a second call. */
  settle(): Promise<SettleVerdict>;
  /** Stop every wait now and release what the observation subscribed to. */
  cancel(): void;
}

/** DOM quiet window an action's settle demands once a mutation shows (settleDom's). */
const ACTION_QUIET_MS = 250;
/** The most one DOM settle may cost inside an action (settleDom's). */
const ACTION_DOM_MAX_MS = 2_000;
/** How long after the last evidence a request may start and still be the action's. */
const ACTION_START_GRACE_MS = 250;
/** The most one network wait may cost (the old settlePage deadline). */
const ACTION_NETWORK_CAP_MS = 2_000;
/** The most an expected effect is polled for once the page has settled. */
const ACTION_EFFECT_WAIT_MS = 3_000;
/** How often an expected effect is asked again while nothing else is happening. */
const ACTION_EFFECT_POLL_MS = 100;
/** Settle rounds (DOM, network, grace) before the observation stops looking for more. */
const MAX_SETTLE_ROUNDS = 8;
/**
 * The most an action waits, in total, on an announcement it raised.
 *
 * A LIVE REGION THE ACTION LIT IS THE PAGE'S OWN WORD THAT IT IS BUSY. The
 * bench app confirms a delete, closes the dialog, announces "Refreshing…" in
 * its polite region and repaints the table 600ms later; the recording model
 * read the announcement and waited, the replay did not. Its DOM went quiet
 * at once, no request was open, the 250ms start grace passed with nothing,
 * and the next step's Delete click landed on the row the first delete had
 * just removed — the confirm then deleted that part again and the app
 * answered "No such part: p18" (fwrd69, both replays, the pin demoted).
 *
 * So an announcement that appeared after the dispatch and is still showing
 * holds the settle: when it is withdrawn or replaced the page has moved, and
 * the round starts over — the repaint's request and mutations are then the
 * action's, as they always were. Bounded, because an announcement can be a
 * message that stays ("Saved."): the wait costs at most this once, and the
 * text is never read for what it says. Evidence, not a sleep, and not a
 * string rule: the region's role is what makes it a promise.
 */
const ACTION_ANNOUNCE_WAIT_MS = 2_000;
/** How often a standing announcement is looked at again. */
const ACTION_ANNOUNCE_POLL_MS = 100;

/**
 * The most a click on a link waits for the navigation the link promised,
 * while the request it asked for is still open and the url has not moved.
 *
 * A LINK'S HREF IS THE ELEMENT'S OWN WORD THAT THE CLICK NAVIGATES. An app
 * that fetches the next page and only then pushes its url (a Rails app under
 * Turbo Drive) leaves the url on the old page for as long as the server takes
 * to answer. fwop2-n1 clicked "Bench Project" on a cold server's project list:
 * the settle's network budget (2s) ran out, the fetch turned "long-open" at
 * 5s, the url wait saw the old url, and the step was recorded as landing on
 * `/projects` — the page it was leaving. The agent then read the url, found
 * it unmoved, clicked again (which restarts the visit), and went to the href
 * with a goto. Both replays, on a warm server, did navigate, and the url gate
 * refused them for being on the right page (s_f4e3b6 step 1).
 *
 * So a click whose target reported a link (robustClick, linkTarget) and that
 * asked the server for that link's url holds its settle while that request
 * — or a redirect it began — is still open and the url is still the old one,
 * then gives the url LINK_COMMIT_GRACE_MS to move once the answer is in.
 * Evidence, not a sleep: a link its page handles without asking for the url
 * (a modal, a client route) costs nothing, and the wait ends the moment the
 * url moves. Bounded, and within the action's deadline.
 */
const LINK_NAV_WAIT_MS = 15_000;
/** After a link's request is answered, how long the url gets to move before the page is taken to stay. */
const LINK_COMMIT_GRACE_MS = 500;
/** How often the url is looked at while a link's navigation is awaited. */
const LINK_POLL_MS = 100;
/** Request types a link's navigation rides on: a document load, or the fetch/XHR of a client-side visit. */
const LINK_REQUEST_TYPES: ReadonlySet<string> = new Set(['document', 'fetch', 'xhr']);

/** The page's own DOM, through the shared settle: the load event first, then quiet. */
function pageDom(page: Page, clock: ActionClock): DomPort {
  return {
    quiet: async (quietMs, maxMs) => {
      const started = clock.now();
      if (typeof page.waitForLoadState === 'function') {
        await page.waitForLoadState('domcontentloaded', { timeout: Math.max(1, maxMs) }).catch(() => {});
      }
      const left = maxMs - (clock.now() - started);
      if (left <= 0) return { mutated: false };
      const seen = await domQuiet(page, { quietMs, maxMs: left });
      return seen && seen.mutated ? { mutated: true, lastMutationAt: clock.now() - seen.sinceMs } : { mutated: false };
    },
    announced: async () => {
      try {
        return await page.evaluate(() => {
          const out: string[] = [];
          const regions = document.querySelectorAll('[aria-live="polite"], [aria-live="assertive"], [role="status"], [role="alert"]');
          for (const el of Array.from(regions)) {
            const h = el as HTMLElement;
            if (!h.getClientRects().length) continue; // not rendered: nothing announced to a reader either
            const text = (h.textContent ?? '').replace(/\s+/g, ' ').trim();
            if (text) out.push(text);
          }
          return out;
        });
      } catch {
        return []; // navigating / detached — the round's other evidence decides
      }
    },
  };
}

/**
 * Begin observing an action. Call it BEFORE the action dispatches — the
 * baseline is this moment, and a request the action starts must not be
 * mistaken for one that was already open — then dispatch, then `settle()`.
 * A page opener's popup listener (context.ts armPageEffect) is armed before
 * this too; the two share nothing but the moment.
 */
function beginAction(page: Page, opts: ActionOptions): ActionObservation {
  const clock = opts.clock ?? realClock;
  const port = page as unknown as PageEventsPort;
  const traffic = pageTraffic(port, { policy: opts.policy, clock });
  const policy = traffic.policy;
  const dom = opts.dom ?? pageDom(page, clock);
  const baselineAt = clock.now();
  const deadline = baselineAt + opts.deadlineMs;
  const startGraceMs = opts.startGraceMs ?? ACTION_START_GRACE_MS;
  const networkCapMs = opts.networkCapMs ?? ACTION_NETWORK_CAP_MS;
  const effectWaitMs = opts.effectWaitMs ?? ACTION_EFFECT_WAIT_MS;
  const readUrl = () => {
    try {
      return port.url();
    } catch {
      return '';
    }
  };
  const urlBefore = readUrl();
  // What the live regions already said before the action: only NEW text is
  // the action's announcement. Taken now, ahead of the dispatch; a port that
  // cannot say leaves the set empty and the announcement wait inert.
  const baselineAnnounced: Set<string> = new Set();
  const baselineTaken = dom.announced
    ? dom.announced().then((texts) => { for (const t of texts) baselineAnnounced.add(t); }, () => {})
    : Promise.resolve();
  let via: DispatchVia | undefined;
  let link: LinkNavigation | undefined;
  let dispatchedAt: number | undefined;
  let failedOutcome: 'not-dispatched' | 'unknown' | undefined;
  let cancelled = false;
  let settling: Promise<SettleVerdict> | null = null;
  const wakers = new Set<() => void>();
  const remaining = () => Math.max(0, deadline - clock.now());

  // A wait that ends at `ms`, at the next traffic event, or on cancel —
  // whichever is first. The event is only a reason to look again.
  const wake = (ms: number) =>
    new Promise<void>((resolve) => {
      let done = false;
      const finish = () => {
        if (done) return;
        done = true;
        unsubscribe();
        wakers.delete(finish);
        resolve();
      };
      const unsubscribe = traffic.subscribe(finish);
      wakers.add(finish);
      void clock.sleep(Math.max(1, ms)).then(finish);
    });

  const run = async (): Promise<SettleVerdict> => {
    await baselineTaken;
    const waited = { domMs: 0, networkMs: 0, urlMs: 0, effectMs: 0 };
    const ignored = new Map<RequestRecord, LongLivedWhy>();
    let deadlineHit = false;
    let lastMutationAt = -Infinity;
    const dispatchEnd = dispatchedAt ?? clock.now();

    // Open requests this action waits for: counted types, not long-lived.
    const relevant = (): RequestRecord[] => {
      const now = clock.now();
      const out: RequestRecord[] = [];
      for (const r of traffic.pending()) {
        if (!policy.countedTypes.includes(r.type)) continue;
        const why = traffic.classify(r, now, baselineAt);
        if (why) ignored.set(r, why);
        else out.push(r);
      }
      return out;
    };

    const quietDom = async () => {
      if (cancelled) return;
      const left = remaining();
      const budget = Math.min(ACTION_DOM_MAX_MS, left);
      if (budget <= 0) {
        deadlineHit = true;
        return;
      }
      const started = clock.now();
      const seen = await dom.quiet(ACTION_QUIET_MS, budget).catch(() => ({ mutated: false, lastMutationAt: undefined }));
      const took = clock.now() - started;
      waited.domMs += took;
      if (seen.mutated && seen.lastMutationAt !== undefined) lastMutationAt = Math.max(lastMutationAt, seen.lastMutationAt);
      if (left < ACTION_DOM_MAX_MS && took >= budget) deadlineHit = true;
    };

    // Wait while a request the action may be waiting on is open. Woken by any
    // traffic event, and by a timer at the moment the earliest open request
    // would turn long-lived, so a stream is let go as soon as it shows itself.
    // `networkCapMs` is ONE budget for the whole settle, not per wait: an app
    // that never stops asking costs it once. 'capped': requests were still
    // open when the budget or the deadline ran out.
    let networkSpent = 0;
    const waitNetwork = async (): Promise<'idle' | 'waited' | 'capped'> => {
      const started = clock.now();
      const capEnd = started + Math.max(0, networkCapMs - networkSpent);
      let state: 'idle' | 'waited' | 'capped' = 'idle';
      for (;;) {
        if (cancelled) break;
        const open = relevant();
        if (!open.length) break;
        const now = clock.now();
        const end = Math.min(capEnd, deadline);
        if (now >= end) {
          if (deadline <= capEnd) deadlineHit = true;
          state = 'capped';
          break;
        }
        let next = end;
        for (const r of open) {
          if (!polling(r)) continue;
          next = Math.min(next, r.responseAt !== undefined ? r.responseAt + policy.streamBodyMs + 1 : r.startedAt + policy.longOpenMs + 1);
        }
        await wake(next - now);
        state = 'waited';
      }
      const took = clock.now() - started;
      networkSpent += took;
      waited.networkMs += took;
      return state;
    };

    // The debounce: shortly after the last evidence (a mutation, a request
    // landing, or — for an input — the dispatch itself) a request may still
    // start and be the action's. Wait out what is left of that grace for one;
    // true when one started.
    const graceStart = async (): Promise<boolean> => {
      const finished = traffic.lastFinish();
      const anchor = Math.max(lastMutationAt, finished >= baselineAt ? finished : -Infinity, opts.graceFromDispatch ? dispatchEnd : -Infinity);
      const started = clock.now();
      let startedOne = false;
      for (;;) {
        if (cancelled) break;
        if (relevant().length) {
          startedOne = true;
          break;
        }
        const left = Math.min(anchor + startGraceMs - clock.now(), remaining());
        if (left <= 0) break;
        await wake(left);
      }
      waited.networkMs += clock.now() - started;
      return startedOne;
    };

    // An announcement the action raised (see ACTION_ANNOUNCE_WAIT_MS): a live
    // region showing text it did not show at the baseline. Held until it is
    // withdrawn or replaced, at most the budget once for the whole settle.
    let announceSpent = 0;
    const holdAnnouncement = async (): Promise<boolean> => {
      if (!dom.announced) return false;
      const started = clock.now();
      let moved = false;
      for (;;) {
        if (cancelled) break;
        const now = clock.now();
        const raised = (await dom.announced().catch(() => [] as string[])).filter((t) => !baselineAnnounced.has(t));
        if (!raised.length) break;
        const left = Math.min(ACTION_ANNOUNCE_WAIT_MS - announceSpent - (now - started), remaining());
        if (left <= 0) break;
        await clock.sleep(Math.min(ACTION_ANNOUNCE_POLL_MS, left));
        moved = true;
      }
      const took = clock.now() - started;
      announceSpent += took;
      waited.domMs += took;
      return moved;
    };

    for (let round = 0; round < MAX_SETTLE_ROUNDS && !cancelled && remaining() > 0; round++) {
      await quietDom();
      const network = await waitNetwork();
      if (network === 'capped') break;
      // An answer landed: let the DOM take it, then look again.
      if (network === 'waited') continue;
      if (await graceStart()) continue;
      // The page said it was busy and has since moved on: look again.
      if (await holdAnnouncement()) continue;
      break;
    }

    // A clicked link whose navigation is still on its way (LINK_NAV_WAIT_MS).
    if (link && !cancelled) {
      const started = clock.now();
      const target = endpointOf(link.href);
      const end = Math.min(started + LINK_NAV_WAIT_MS, deadline);
      let moved = false;
      for (;;) {
        if (cancelled || readUrl() !== urlBefore) break;
        const asked = traffic
          .startedSince(baselineAt - policy.recentMs)
          .filter((r) => LINK_REQUEST_TYPES.has(r.type) && (r.chainEndpoint ?? r.endpoint) === target);
        // The link asked the server nothing: its page handled the click.
        if (!asked.length) break;
        const now = clock.now();
        const open = asked.some((r) => r.finishedAt === undefined && traffic.pending().includes(r));
        const answeredAt = Math.max(...asked.map((r) => r.finishedAt ?? -Infinity));
        const until = open ? end : Math.min(end, answeredAt + LINK_COMMIT_GRACE_MS);
        if (now >= until) {
          if (open && deadline <= started + LINK_NAV_WAIT_MS) deadlineHit = true;
          break;
        }
        await wake(Math.min(LINK_POLL_MS, until - now));
        moved = true;
      }
      waited.urlMs += clock.now() - started;
      // The new page arrived: let it render and ask for what it needs.
      if (moved && readUrl() !== urlBefore && !cancelled) {
        await quietDom();
        await waitNetwork();
      }
    }

    if (opts.navigating && !cancelled) {
      const started = clock.now();
      const lateNavMs = Math.min(LATE_NAV_MS, remaining());
      const settledUrl = readUrl();
      const seen = await urlHeldStill(port, urlBefore, () => relevant().length, { lateNavMs });
      waited.urlMs += clock.now() - started;
      if (lateNavMs < LATE_NAV_MS && clock.now() - started >= lateNavMs) deadlineHit = true;
      if (seen !== settledUrl) {
        await quietDom();
        await waitNetwork();
      }
    }

    let verified = false;
    let observed = false;
    if (opts.expect && !cancelled) {
      const started = clock.now();
      const end = Math.min(started + effectWaitMs, deadline);
      for (;;) {
        const holds = await opts.expect.holds().catch(() => null);
        if (holds === true) {
          verified = true;
          observed = true;
          break;
        }
        if (holds === false) observed = true;
        if (cancelled) break;
        const now = clock.now();
        if (now >= end) {
          if (deadline < started + effectWaitMs) deadlineHit = true;
          break;
        }
        // Traffic still open is the effect still on its way: wait on it
        // (within what is left of the network budget) rather than on the clock.
        if (relevant().length && (await waitNetwork()) === 'waited') {
          await quietDom();
          continue;
        }
        await clock.sleep(Math.min(ACTION_EFFECT_POLL_MS, end - now));
      }
      waited.effectMs += clock.now() - started;
    }

    const outcome: ActionOutcome = failedOutcome ?? (verified ? 'effect-verified' : opts.expect && !observed ? 'unknown' : 'dispatched');
    return {
      outcome,
      url: readUrl(),
      ...(link ? { link } : {}),
      ...(via ? { via } : {}),
      waited,
      ignored: [...ignored].map(([r, why]) => ({ url: r.url, why })),
      deadlineHit,
    };
  };

  return {
    remaining,
    dispatched: (how) => {
      via ??= how;
      dispatchedAt ??= clock.now();
    },
    failed: (err) => {
      failedOutcome = outcomeOfError(err);
      throw err;
    },
    linkTarget: (href) => {
      link ??= { from: urlBefore, href };
    },
    link: () => link,
    settle: () => (settling ??= run()),
    cancel: () => {
      cancelled = true;
      for (const finish of [...wakers]) finish();
    },
  };
}

// Shared execution source: lifecycle.ts. Regenerate to update.
/**
 * An action may explicitly skip or stop; neither outcome claims completion. A
 * stopped action may say what is known about its dispatch (browser.ts
 * `ActionOutcome`): a stop whose action was proven never to have gone out is
 * a different fact from one that may have landed.
 */
type StepActionResult<T> =
  | { status: 'completed'; value: T }
  | { status: 'skipped' }
  | { status: 'stopped'; outcome?: 'not-dispatched' | 'dispatched' | 'effect-verified' | 'unknown' };

interface StepLifecycle<T, V> {
  prepare(): Promise<void>;
  act(): Promise<StepActionResult<T>>;
  settle(value: T): Promise<void>;
  bind(value: T): Promise<void>;
  verify(value: T): Promise<V>;
}

/**
 * The mandatory lifecycle used by replay and embedded in standalone tests.
 * Action handlers cannot bypass the obligations of a completed action. Binding
 * precedes verification because a step's checks may refer to values it minted.
 * There is deliberately no retry or catch here: a failed phase stops the step,
 * and an adapter must never mistake a verification failure for failed dispatch.
 */
async function runStepLifecycle<T, V>(phases: StepLifecycle<T, V>): Promise<{
  action: StepActionResult<T>;
  verification?: V;
}> {
  await phases.prepare();
  const action = await phases.act();
  if (action.status !== 'completed') return { action };
  await phases.settle(action.value);
  await phases.bind(action.value);
  const verification = await phases.verify(action.value);
  return { action, verification };
}

/** Reads are optional observations in both execution targets. */
function isReadAction(tool: string): boolean {
  return tool === 'read' || tool === 'read_all';
}

/** What a step's dispatch was told to act on, as far as ambiguity is concerned. */
interface DispatchArgs {
  state?: unknown;
  what?: unknown;
}

/**
 * Whether a step's dispatch reaches EVERY match of its target: `read_all`
 * reads across all of them, and a count — read or wait — is the question "how
 * many", which a single match could not answer. Several matches are the POINT
 * of these steps, so their locator is allowed to name several and is recorded
 * without an index.
 */
function spansEveryMatch(tool: string, args: DispatchArgs = {}): boolean {
  if (tool === 'read_all') return true;
  if (tool === 'read') return args.what === 'count';
  return tool === 'wait_for' && args.state === 'count';
}

/**
 * Whether a step's dispatch acts on the FIRST match and ignores the rest.
 * Every wait but a count one does: tools.ts `waitFor` dispatches
 * `loc.first().waitFor({ state })` for visible/hidden and reads
 * `loc.first().innerText()` for the text states.
 *
 * "May match several" has to follow the DISPATCH, not the tool name. grafana
 * fwgr43's `wait_for h2 state:visible` was resolved as if it had to name
 * exactly one element, so both replays stopped and the compiled arm failed
 * 0/6 — while the wait it would have run looks only at `h2` number one. Only
 * an ABSENCE wait was let through with ambiguity allowed, which made `hidden`
 * an exception rather than the rule it is an instance of.
 */
function dispatchesFirstMatch(tool: string, args: DispatchArgs = {}): boolean {
  return tool === 'wait_for' && args.state !== 'count';
}

/** Only a nonempty identifier changed by this step is evidence of creation. */
function changedCreation(before: string | undefined, after: string | undefined): string | undefined {
  return after && after !== before ? after : undefined;
}

/** Actions that can change application data; navigation is a separate concern. */
const MUTATING_ACTIONS = new Set([
  'click', 'dblclick', 'right_click', 'modifier_click', 'fill', 'type',
  'press', 'select', 'check', 'drag', 'upload',
]);

function isMutatingAction(tool: string): boolean {
  return MUTATING_ACTIONS.has(tool);
}

/**
 * One recorded gesture as the evidence a run has about it: the tool it used
 * and what the recording OBSERVED around it (daemon/recorder.ts RecordedStep,
 * structurally — this module may not import it).
 */
interface ObservedGesture {
  tool: string;
  diff?: { url: string; alerts: readonly string[]; added: readonly string[] };
}

/**
 * Whether this gesture minted a record identifier: the url it left is the
 * SAME page as the one it started on (urlDiff — same origin, path shape,
 * route, and every state key the before-url named), and every position whose
 * value changed gained an identifier where there was none. A position that
 * swapped one identifier for another (odoo's `action=330` → `action=156`) or
 * that changed a route word (`view_type=list` → `form`) is the app moving the
 * browser, not the run making a record — fwod51's recovery did exactly that,
 * and every part of the record it opened (`id=45`) the run already had.
 */
function mintedRecordId(before: string, after: string): boolean {
  if (!urlDiff(before, after)) return false; // not even the same page: it moved
  const was = new Map(urlParts(before).map((p) => [p.label, p.value]));
  let gained = false;
  for (const { label, value } of urlParts(after)) {
    const made = changedCreation(was.get(label), value);
    if (made === undefined) continue; // this position is as it was
    if (!mintedShape(made)) return false; // a word, not an id: the app routed
    if (mintedShape(was.get(label) ?? '')) return false; // one record swapped for another
    gained = true;
  }
  return gained;
}

/**
 * Did this gesture COST the run anything it can account for? A stop is only a
 * strike against the procedure that stopped when the repair after it actually
 * changed something, and the run has to have OBSERVED that change: content
 * left different on a page the gesture stayed on (added lines or an alert in
 * the step's recorded diff), or a record identifier minted into the url. A
 * gesture whose only observable effect was moving from one page to another is
 * navigation, which costs nothing however it was dispatched.
 *
 * fwod51 is why the tool NAME cannot answer this: 07-verify is a read-only
 * instruction, its recovery could only reach the record by clicking, and
 * `isMutatingAction('click')` read that as a mutation — two such stops demoted
 * the skill and refused the compile while both mutation logs were empty.
 *
 * Conservative where the run has no evidence: a gesture with no recorded diff
 * (learning off, or a capture that lost its race) counts as a change, and so
 * does one whose starting url is unknown and that left content behind.
 */
function observedChange(step: ObservedGesture, urlBefore: string | undefined): boolean {
  if (!isMutatingAction(step.tool)) return false;
  if (!step.diff) return true;
  if (urlBefore !== undefined && step.diff.url !== urlBefore) return mintedRecordId(urlBefore, step.diff.url);
  return step.diff.added.length > 0 || step.diff.alerts.length > 0;
}

interface ExecutionStepShape {
  tool: string;
  body?: readonly ExecutionStepShape[];
}

function mutatesSteps(steps: readonly ExecutionStepShape[]): boolean {
  return steps.some((step) => isMutatingAction(step.tool) || (step.body ? mutatesSteps(step.body) : false));
}

// Shared execution source: expect.ts. Regenerate to update.
/**
 * The content-expectation verdict both execution targets share: given what a
 * step recorded, what the run's params are, and what the page shows now, did
 * the step have its recorded effect? The daemon imports this (skills/replay.ts
 * calls it from its effect gate); a compiled `.flow.ts` artifact embeds its
 * exact source (spec/runtime-source.ts) and calls it from each step's verify
 * phase. One function, so the two runners cannot disagree about what a
 * recorded line means — an earlier emitter rebuilt each line as a Playwright
 * locator and never looked past the name, so `- combobox "Project": {{v1}}`
 * passed on any visible Project combobox whatever it showed. Self-contained:
 * nothing but a sibling shared module may be imported.
 */

/**
 * Page lines that describe the page in transit — spinners, progress bars,
 * and toasts (an alert that happened to be on screen, such as fwgr25's
 * "Error loading RSS feed", is not what the step did; a step's own alert is
 * carried by alertContains, which stays soft). Never a lasting effect.
 */
const TRANSIENT_LINE = /^-?\s*(status|progressbar|alert)\b/;

/** A recorded line carrying a `{{vN}}` slot: this run's own value, the HARD half of an expectation. */
const SLOT_LINE = /\{\{v\d+\}\}/;

/** A recorded line naming a dialog, whose absence is conditional UI rather than a failed effect. */
const DIALOG_LINE = /^-\s*dialog\s+"([^"]*)"/;

/** A popup container, whose opening is itself the effect whether or not it carries a name (replay's OPENER_LINE roles). */
const POPUP_ROLE = /^(dialog|alertdialog|menu|menubar|listbox|tooltip)$/;

/**
 * A popup's ITEMS: the entries a listbox or menu lists while it is open. The
 * container's appearance is the event (POPUP_ROLE above, which stays exempt
 * from identifiesNothing); what it happens to be listing at that instant is
 * not. An item list is the application answering the keystrokes so far — odoo's
 * product autocomplete re-queries on every character and returns whatever the
 * catalogue holds now — so an item is momentary evidence about the ENVIRONMENT,
 * never proof that the step acted on the right element. fwod49-n2's 02-open
 * recorded `- option "{{v4}}"` as its type step's hard effect and stopped every
 * replay whose catalogue answered differently.
 */
const POPUP_ITEM_ROLE = /^(option|menuitem|menuitemcheckbox|menuitemradio)$/;

/** Whether a recorded line describes an item inside an open popup (see POPUP_ITEM_ROLE). */
function popupItem(line: string): boolean {
  const m = LINE_PARTS.exec(line.trim());
  return m ? POPUP_ITEM_ROLE.test(m[1]) : false;
}

/** Any `{{…}}` marker that is not the wildcard — a slot no one filled. */
const UNFILLED_MARKER = /\{\{(?!\*\}\})[^{}]*\}\}/;

/**
 * A recorded line that this run could not fill: after params are substituted
 * it still carries a `{{…}}` marker — a `{{vN}}` the caller never bound, or a
 * param whose own value is an unresolved reference to another step's output
 * (`{{02-open.product_name}}`). The `{{*}}` wildcard is not one: that marker is
 * deliberate, and lineShows matches it against anything.
 *
 * Such a line says nothing about THIS run, exactly as identifiesNothing's do,
 * so it is dropped with a warning rather than searched for: no page has ever
 * shown the literal text of a marker, so looking for it can only stop the run.
 * fwod49-n2: an unresolved `{{02-open.product_name}}` reached the gate as a
 * param value, every replay of s_78eaaf and s_32409f stopped on "the page did
 * not show `- option \"{{02-open.product_name}}\"`", and the skills were
 * demoted for it. Judged at CHECK time in both runners, so a store compiled
 * before this rule existed is fixed without re-recording.
 */
function unfilledSlot(line: string): boolean {
  return UNFILLED_MARKER.test(line);
}

/**
 * Can a missing value in this slot change what the procedure DOES?
 *
 * Yes when some segment of the chain types or locates by it (`usedIn`, the
 * steps whose args or locators carry it), or when it names the record the
 * procedure must find (a `{{vN}}` inside `preconditions.requireText`).
 * Otherwise only the template, the report and recorded expectations carry it
 * — and a line this run cannot fill is dropped with a warning (unfilledSlot),
 * so its absence is no reason to refuse the procedure.
 *
 * ONE predicate for three readers that used to disagree: replay's refusal of
 * missing params (replay.ts), the daemon's consumption gate (flow.ts
 * ignorableRefs) and the compile's `usedSlot` (emit.ts). odoo fwod85: s_6a1629
 * declared v10 only for the Save step's `- cell "{{v10}}"`; the flow bound
 * nothing to it, the artifact ran and dropped the line, and both daemon
 * replays refused the pin outright ("missing params: v10").
 */
function slotActs(
  chain: ReadonlyArray<{
    params: Readonly<Record<string, { usedIn?: readonly number[] } | undefined>>;
    preconditions?: { requireText?: readonly string[] } | null;
  }>,
  slot: string,
): boolean {
  const marker = `{{${slot}}}`;
  return chain.some(
    (seg) => (seg.params[slot]?.usedIn?.length ?? 0) > 0 || (seg.preconditions?.requireText ?? []).some((text) => text.includes(marker)),
  );
}

/**
 * A recorded line whose slot this run bound to NOTHING. The compiled artifact
 * spells an unpublished reference as '' (`outputs[ref] ?? ''`, emit.ts), where
 * the daemon leaves the param absent — and url.ts's `unfilled`, gates.ts's
 * markersBound and urlRecordParts all read '' as "no value". This gate did not:
 * fwod67's 04-open expectation `- row "20% £ {{v9}}"` filled to
 * `- row "20% £ "` in the artifact and was searched for as literal text, while
 * the daemon (v9 absent, so unfilledSlot) dropped the line and passed. Judged
 * on the RECORDED line, before filling erases the marker.
 */
function boundToNothing(line: string, params: Record<string, string>): boolean {
  return [...line.matchAll(/\{\{([vd]\d+)\}\}/g)].some((m) => m[1] in params && params[m[1]] === '');
}

/** `- role "name" [state]…: value` — the name may be cut short by the 120-char stored-line cap, so its closing quote is optional. */
const LINE_PARTS = /^-?\s*([A-Za-z][\w-]*)(?:\s+"((?:[^"\\]|\\.)*)"?)?((?:\s+\[[^\]]*\])*)(?::\s*(.*))?$/;

/** No content once wildcards are removed: empty, or a stringified absent value ("null", "undefined") a slot was filled with. */
function blankContent(s: string | undefined): boolean {
  const rest = (s ?? '').split(WILDCARD).join('').trim();
  return !rest || /^(null|undefined)$/i.test(rest);
}

/**
 * A page line that says nothing about WHICH element appeared: no accessible
 * name (a label is part of it — dialect 2 names a control by its <label>), no
 * value, or only a wildcard or blank one. `- textbox "": {{*}}`, `- cell ""`,
 * `- generic ""`, `- checkbox [checked]`: some element of that role is on the
 * page for reasons of its own. odoo's inline list editor puts unnamed
 * textboxes in and out of the form as rows gain and lose focus, and fwod47-n3's
 * 04-open stopped on `- textbox "": null` — a click that did exactly what it
 * was recorded doing, failed on a line that could never have proved it. The
 * role alone never identifies (any role: a named row does, an unnamed one does
 * not), except a popup container, whose appearance IS the event.
 *
 * Judged on the line as it will be matched: at compile after substitution and
 * masking, at run time after params are filled — so a slot that fills to
 * nothing identifies nothing either. A line this cannot parse is kept.
 */
function identifiesNothing(line: string): boolean {
  const m = LINE_PARTS.exec(line.trim());
  if (!m) return false;
  const [, role, name, , value] = m;
  if (POPUP_ROLE.test(role)) return false;
  return blankContent(name) && blankContent(value);
}

/**
 * An effect expectation asserts what the PROCEDURE put on the page, and the
 * procedure only ever puts values there through its own fills and choices —
 * which are slots (`{{vN}}`, or a `{{dN}}` the app minted and a url showed)
 * by the time this runs, because substitute() went first. A control's
 * displayed value that is NOT a slot is therefore the app's: a default, a
 * computed figure, the id of the record the recording happened to make.
 * atelyr's project picker recorded `- combobox "…": 13f9pv52yozr` — the
 * recording's own project id — and every replay's project had another, so
 * both add-item steps stopped at "did not show … as it did when recorded".
 *
 * Provenance, not shape: no attempt is made to recognise an identifier by
 * how it looks, which breaks on the next app. The role and name still have
 * to match; only the value after the colon is wildcarded.
 */
function maskMinted(line: string): string {
  // `- role "name" [state]: value` — the value colon is the one after the
  // (quoted) name and any state markers, never one inside the name.
  return line.replace(/^(-?\s*\S+(?:\s+"(?:[^"\\]|\\.)*")?(?:\s+\[[^\]]*\])*)(:\s*)(\S.*?)\s*$/, (whole, head: string, sep: string, value: string) =>
    value.includes('{{') ? whole : `${head}${sep}${WILDCARD}`,
  );
}

/** The roles whose displayed value a PROCEDURE can put there by typing or choosing. */
const EDITABLE_ROLE = /^(textbox|searchbox|spinbutton|combobox)$/;

/**
 * The second half of maskMinted's provenance rule, for values that ARE slots.
 *
 * maskMinted wildcards a control's value when it is a literal, because the
 * procedure only ever puts a value on the page through its own fills and
 * choices, and a literal is therefore the app's. A slot is not automatically
 * the procedure's either: a skill's params carry values from ANOTHER step's
 * output (`output:i2:product_name`), and a step that merely double-clicks a
 * row is not what put that product's name in the row's combobox — the app
 * did, and on the next run it may hold whatever record the run actually
 * opened. fwod49-n2's 04-open recorded its dblclick's effect as
 * `- combobox "Type to find a product...": {{v4}}` / `- textbox "": {{v4}}`
 * and could only ever pass on the recording's own quotation.
 *
 * So a value is firm evidence only when it is one of `own` — the values this
 * step itself put on the page (its own fill/type/select args). Everything
 * else at an editable role becomes the wildcard. Provenance, not shape: no
 * attempt is made to tell an id from a title. Role, name and state are
 * untouched and still have to match, and the wildcard already in a value
 * (`{{*}}`) is left alone.
 */
function maskForeignValue(line: string, own: readonly string[]): string {
  return line.replace(
    /^(-?\s*(\S+)(?:\s+"(?:[^"\\]|\\.)*")?(?:\s+\[[^\]]*\])*)(:\s*)(\S.*?)\s*$/,
    (whole, head: string, role: string, sep: string, value: string) => {
      if (!EDITABLE_ROLE.test(role) || value === WILDCARD) return whole;
      return own.some((v) => v.trim() === value.trim()) ? whole : `${head}${sep}${WILDCARD}`;
    },
  );
}

/**
 * A popup item is never PARAMETERISED: the slots in an open menu's or
 * listbox's entry become the wildcard, which leaves `- option "{{v4}}"` as
 * `- option "{{*}}"` — a line identifying nothing, dropped by the same rule
 * that drops `- cell ""`. The popup's own container line survives to carry the
 * evidence that it opened. See POPUP_ITEM_ROLE for why (fwod49-n2 02-open).
 */
function maskPopupItem(line: string): string {
  return popupItem(line) ? line.replace(/\{\{[vd]\d+\}\}/g, WILDCARD) : line;
}

/**
 * A recorded line as it is looked for on a LIVE page: the recording's clock
 * and calendar tokens masked (a store compiled before masking existed still
 * carries them), the recording's own minted values masked, and this run's
 * params filled in. Both runners fill at run time, from the same map.
 *
 * A secret marker (`{{env:NAME}}`, `{{totp:NAME}}`) — recorded where the page
 * echoed a scrubbed value, or arriving through a param bound to one — is the
 * wildcard: the value is never written into a line, and a line cannot be
 * checked against a marker the page never shows (fwgh9: "recorded page change
 * … {{env:APP_PASSWORD}} … not checked").
 */
function liveLines(lines: readonly string[], params: Record<string, string>): string[] {
  // A value goes into a line as a snapshot would render it — whitespace runs
  // collapsed, edges trimmed (snapshot.ts `clean`) — never as it was read:
  // kanboard fwkb39's read published "Backlog ", and `- link "{{v5}}"` became
  // `- link "Backlog "`, which no snapshot name ever shows.
  const rendered = Object.fromEntries(Object.entries(params).map(([k, v]) => [k, typeof v === 'string' ? v.replace(/\s+/g, ' ').trim() : v]));
  return lines.map((l) => fillParams(maskMinted(maskCounters(maskVolatile(l))), rendered).replace(/\{\{(?:env|totp):\w+\}\}/g, WILDCARD));
}

/**
 * The expectation lines that could tell a right-element fill from a
 * wrong-element one. A recorded added-line that merely restates the fill in a
 * same-role element — `textbox "": {{v4}}` — is an ECHO: the WRONG textbox
 * produces it too, so it is no evidence at all. fwgr17-n3's 03-open passed
 * its effect gate on exactly that line after a positional fallback took the
 * step. When consequential lines exist (the heading that renders the typed
 * title, the menu button named after it), only those count; when the echo is
 * all the recording has, it is returned unchanged — a lone search-box fill
 * legitimately shows nothing else, and the caller warns instead.
 */
function isEchoLine(line: string, filledValue: string): boolean {
  return new RegExp(`^-?\\s*(textbox|searchbox|spinbutton|combobox)\\b[^:]*:\\s*${escapeRe(filledValue)}\\s*$`).test(line.trim());
}

function consequentialExpectations(lines: string[], filledValue: string | undefined): string[] {
  if (!filledValue) return lines;
  const rest = lines.filter((l) => !isEchoLine(l, filledValue));
  return rest.length ? rest : lines;
}

/** A fresh look at the live page, in the step's line dialect (see snapshot.ts captureLines). */
interface LiveLines {
  lines: string[];
  /** The look covered enough of the page for a missing line to mean absent (coverageComplete). */
  complete: boolean;
  coverage?: ObservationCoverage;
}

/** What a runner observed after the step: its diff, and a way to look again. */
interface ChangeObservation {
  /** The lines the step added (the diff), or null when that capture failed — never [] for "unavailable". */
  added: string[] | null;
  /**
   * A fresh look at the live page; null when the page cannot be read. Both
   * are rendered in the dialect the step's recorded lines are in — a diff in
   * one dialect judged against lines in another would miss by construction.
   */
  live: (look?: FullNameLook) => Promise<LiveLines | null>;
}

/** The roles recorded lines name (`- row "…"` → row): what a FullNameLook names in full. */
function lineRoles(lines: readonly string[]): string[] {
  const roles = new Set<string>();
  for (const l of lines) {
    const m = /^-?\s*([A-Za-z][\w-]*)\s+"/.exec(l.trim());
    if (m) roles.add(m[1]);
  }
  return [...roles];
}

/** The step, as the verdict needs to know it. */
interface ChangeContext {
  /** Human step tag, e.g. "5", "9.2.1", or the artifact's "<stepId> <segmentId>/<index>". */
  tag: string;
  tool: string;
  /** The value a fill/type step put on the page, params filled. */
  value?: string;
  /** Some target of this step resolved through a structural (positional) candidate. */
  positionalResolution: boolean;
}

interface ChangeVerdict {
  /** The step ran but did not have its recorded effect: the reason, and the run stops. */
  stop?: string;
  /** Always applied, whatever else the verdict says. */
  warnings: string[];
  /**
   * Part of the evidence was missing: the diff leg (a failed capture, the
   * live page decided), or a live look that could not cover the page, so a
   * stop could not be confirmed as a real absence.
   */
  unobserved?: true;
  /**
   * The recorded effect was a dialog opening and no dialog opened. A dialog
   * is conditional UI — "Discard changes?" appears only when there are
   * changes — so its absence is a legitimate state, not a failed effect; the
   * steps that were going to act inside it are skipped (see namesDialogControl).
   *
   * `lines` is the dialog's own recorded subtree — the controls it listed.
   * Membership is PROVEN against it, never inferred from a target simply
   * being missing: a step whose locator names nothing the dialog contained
   * is a step of the procedure's own, and its absence is a failure.
   */
  absentDialog?: { name: string; lines: string[] };
  /**
   * The step's recorded page changes were seen in what the action ADDED — the
   * diff, not merely the live page, where a line may simply have been there
   * already — and nothing weakened that (a positional fill proven only by its
   * own echo is not confirmation). This is the evidence that lets an alert the
   * recording never saw be reported instead of stopping the run (gates.ts
   * alertVerdict): the step demonstrably did what it was recorded doing.
   */
  confirmed?: true;
  /**
   * The recorded lines (markers intact) whose filled form THIS run's diff
   * added: what the action itself put on the page, not what the page already
   * showed. The evidence a commit is judged on (phase B provenance, stage 1):
   * a Save whose recorded row line this run's diff never added committed
   * nothing, however the live page looks. Absent when the diff was not captured.
   */
  inDiff?: string[];
}

/**
 * Page-change expectations. Lines that carry a parameter are HARD: they are
 * what distinguishes this run from the recorded one (the new title appearing
 * as a heading), so their absence means the step acted on the wrong thing
 * even though it "worked". Everything else stays soft until data says it is
 * reliable — but a plain change absent from the diff AND the live page means
 * the action did not have its recorded effect, and failing there is what
 * turns a rejected state change into a clean recovery instead of a false
 * success (the fwrd4l-n3 Ready click).
 *
 * Both halves are matched by lineShows over WHOLE snapshot lines — role,
 * name, state and the value after the colon — in the diff first and then on
 * the live page. Empty `warnings` and nothing else set means the step passed
 * with nothing to say.
 */
async function expectedChangesVerdict(
  recorded: readonly string[] | undefined,
  params: Record<string, string>,
  ctx: ChangeContext,
  obs: ChangeObservation,
): Promise<ChangeVerdict> {
  const verdict = await changesVerdict(recorded, params, ctx, obs);
  if (verdict.stop || obs.added === null || !recorded?.length) return verdict;
  const inDiff = linesInDiff(recorded, params, obs.added);
  return inDiff.length ? { ...verdict, inDiff } : verdict;
}

/**
 * The recorded lines whose filled form is in `added`, the lines this step's
 * own action added — transient lines, lines identifying nothing and lines this
 * run could not fill left out, as the verdict leaves them out.
 */
function linesInDiff(recorded: readonly string[], params: Record<string, string>, added: readonly string[]): string[] {
  return recorded.filter((line) => {
    if (TRANSIENT_LINE.test(line) || boundToNothing(line, params)) return false;
    const [filled] = liveLines([line], params);
    return !identifiesNothing(filled) && !unfilledSlot(filled) && lineShows(added as string[], [filled]);
  });
}

/**
 * A control's own line: the field showing what was typed into it, a picked
 * option, a ticked box. The line an input renders is the input, not something
 * the app did with the value.
 */
const CONTROL_LINE = /^-?\s*(textbox|searchbox|spinbutton|combobox|listbox|option|checkbox|radio|switch|slider|menuitem\w*)\b/;

/**
 * The `{{vN}}` slots a commit showed (phase B provenance, stage 1): named in a
 * line this run's diff added (ChangeVerdict.inDiff) after a click or press,
 * where the line is neither a popup item (the environment answering
 * keystrokes) nor a control's own line (the field still holding what was
 * typed). Such a slot's value is on the page because the app took it — the
 * saved row, the heading that renders the new title — so a report value made
 * of it is COMMITTED, not merely typed. Both runners collect it after the
 * action, from the same verdict.
 */
function committedSlots(tool: string, inDiff: readonly string[] | undefined): string[] {
  if (!inDiff?.length || !['click', 'dblclick', 'press'].includes(tool)) return [];
  const out = new Set<string>();
  for (const line of inDiff) {
    if (popupItem(line) || CONTROL_LINE.test(line.trim())) continue;
    for (const m of line.matchAll(/\{\{(v\d+)\}\}/g)) out.add(m[1]);
  }
  return [...out];
}

async function changesVerdict(
  recorded: readonly string[] | undefined,
  params: Record<string, string>,
  ctx: ChangeContext,
  obs: ChangeObservation,
): Promise<ChangeVerdict> {
  const warnings: string[] = [];
  if (!recorded?.length) return { warnings };
  const { tag } = ctx;
  // Confirmation (ChangeVerdict.confirmed) holds only while every recorded
  // group was found in the diff; any fallback below clears it.
  let confirmed = true;
  // The step diff is ONE source of evidence, not the authority. When the
  // capture failed there are no added lines to search — which must not read
  // as "the expected line was absent but harmlessly so", nor as a pass. The
  // checks below fall through to a fresh look at the live page, and a
  // required effect that cannot be found there still stops the run.
  // `added === null` means unavailable; `[]` means observed-empty.
  const added = obs.added;
  if (added === null) warnings.push(`step ${tag}: the page could not be captured after the action — its recorded effects were checked against the live page instead`);
  // A live look answers three ways. Shown is evidence. Not shown on a look
  // that covered the page is absence. Not shown on a look that could not
  // (the page unreadable, a cap reached, a visible frame unread, a
  // virtualised list) is NOT absence: the stop below still stands — nothing
  // established the effect — but it is marked unobserved and says why, and a
  // conditional branch (the absent dialog) is never taken on it.
  const look = async (lines: string[]): Promise<{ shown: boolean; complete: boolean; why: string }> => {
    const live = await obs.live();
    if (!live) return { shown: false, complete: false, why: 'the page could not be read' };
    if (lineShows(live.lines, lines)) return { shown: true, complete: live.complete, why: '' };
    // A NAME PAST THE CAP (round 63, openproject fwop17 04-create): an
    // element named by its text is observed with no name once that text is
    // longer than NAME_CAP, and an attribute name is cut there, so a line
    // whose value this run made longer than the recording's can be on the
    // page and never in a capped look. Looked for once more, with the
    // elements of the roles the lines name named in full; said when that is
    // what found it.
    const roles = lineRoles(lines);
    if (roles.length) {
      const full = await obs.live({ fullNameRoles: roles });
      if (full && lineShows(full.lines, lines)) {
        warnings.push(`step ${tag}: its recorded page change was found only by its full name, which is longer than the ${NAME_CAP} characters a look names an element by`);
        return { shown: true, complete: full.complete, why: '' };
      }
    }
    return { shown: false, complete: live.complete, why: live.complete ? '' : live.coverage ? describeCoverage(live.coverage) || 'coverage unknown' : 'coverage unknown' };
  };
  // A line carrying a {{vN}} slot is HARD (below). A {{dN}} derived marker
  // is filled like any other param but stays soft — the app minted it. An item
  // inside an open popup is never HARD whatever it carries: the list is the
  // environment's answer to the keystrokes so far, not proof this step acted
  // on the right element (POPUP_ITEM_ROLE; fwod49-n2 02-open stopped on
  // `- option "{{v4}}"`). A store compiled before maskPopupItem existed is
  // fixed here, without re-recording.
  const isParam = (l: string) => SLOT_LINE.test(l) && !popupItem(l);
  // Transient lines (spinners, progress bars) are dropped here too, so a
  // store compiled before TRANSIENT_LINE existed stops failing on them.
  const lines = recorded.filter((l) => !TRANSIENT_LINE.test(l));
  if (!lines.length) return { warnings: [] };
  // A line that identifies no element proves nothing either way, so it is not
  // looked for — filled first, so a store minted before compile dropped such
  // lines (fwod47-n3 04-open's `- textbox "": {{v5}}`) is fixed without
  // re-recording. All of them gone means the step has no expectation.
  // ...and a line this run could not fill (unfilledSlot) is dropped the same
  // way, with a warning: an unbound `{{vN}}`, or a param whose value is itself
  // an unresolved reference, would otherwise be searched for as literal text
  // and stop a step that did exactly what it was recorded doing (fwod49-n2).
  const unfilled: string[] = [];
  const usable = (group: string[]): string[] =>
    group.filter((l) => {
      if (identifiesNothing(l)) return false;
      if (unfilledSlot(l)) {
        unfilled.push(l);
        return false;
      }
      return true;
    });
  // A slot bound to '' is unfilled too (boundToNothing) — judged on the
  // recorded line, since filling would erase the marker it is judged by.
  // A line that would identify nothing once filled is dropped silently, as
  // identifiesNothing drops it (`- textbox "": {{v5}}` with v5 = '').
  const fillable = (group: string[]): string[] =>
    group.filter((l) => {
      if (!boundToNothing(l, params)) return true;
      if (!identifiesNothing(liveLines([l], params)[0])) unfilled.push(l);
      return false;
    });
  let parameterised = usable(liveLines(fillable(lines.filter(isParam)), params));
  const plain = usable(liveLines(fillable(lines.filter((l) => !isParam(l))), params));
  if (unfilled.length) {
    warnings.push(
      `step ${tag}: ${unfilled.length} recorded page change(s) carry a value this run could not fill (e.g. ${JSON.stringify(unfilled[0])}) — not checked`,
    );
  }
  if (!parameterised.length && !plain.length) return { warnings };
  // A positionally-resolved fill must prove itself with a CONSEQUENTIAL
  // change: its own echo in a same-role element is what the wrong element
  // produces too (see consequentialExpectations). When the echo is all the
  // recording has, the old gate stands and we say so.
  if (ctx.positionalResolution && parameterised.length && typeof ctx.value === 'string' && ctx.value) {
    const value = ctx.value;
    const consequential = parameterised.filter((l) => !isEchoLine(l, value));
    if (consequential.length) parameterised = consequential;
    else {
      confirmed = false;
      warnings.push(`step ${tag}: resolved positionally and its only recorded effect is the fill's own echo — the effect gate cannot tell right element from wrong here`);
    }
  }
  if (parameterised.length && !(added !== null && lineShows(added, parameterised))) {
    confirmed = false;
    const seen = await look(parameterised);
    if (!seen.shown) {
      const shown = parameterised.map((w) => JSON.stringify(w)).join(' / ');
      if (!seen.complete) {
        return { warnings, unobserved: true, stop: `after step ${tag} the page did not show ${shown} as it did when recorded, and that could not be confirmed: capture incomplete (${seen.why}) — the step ran but its effect was not established` };
      }
      return { warnings, stop: `after step ${tag} the page did not show ${shown} as it did when recorded — the step ran but probably acted on the wrong element` };
    }
  }
  if (plain.length && !(added !== null && lineShows(added, plain))) {
    confirmed = false;
    // None of the recorded effects in the step diff — check the live page
    // before judging (a change can land outside the diff window).
    const seen = await look(plain);
    if (!seen.shown) {
      // The recorded effect was a dialog opening. A dialog is conditional
      // UI: fwgr24's create step recorded "Exit edit" → "Discard changes to
      // dashboard?" because the RECORDING had unsaved edits at that moment;
      // a replay whose earlier steps saved cleanly has none, no dialog
      // opens, and that is the app working — not the step failing. The
      // steps that would have acted inside the dialog are skipped instead.
      const dialog = plain.map((l) => DIALOG_LINE.exec(l)?.[1]).find((n) => n !== undefined);
      // ...but only on a real observation. Concluding "the dialog did not
      // open" from a capture that failed is inferring a branch from missing
      // evidence, and it would go on to skip the steps inside it.
      if (dialog !== undefined && added === null) {
        return { warnings, unobserved: true, stop: `after step ${tag} the page could not be captured, so whether the dialog ${JSON.stringify(dialog)} opened is unknown — its absence cannot be assumed` };
      }
      // The same for a live look that could not cover the page: a dialog in
      // an unread frame, or past a cap, is not a dialog that did not open.
      if (dialog !== undefined && !seen.complete) {
        return { warnings, unobserved: true, stop: `after step ${tag} the recorded dialog ${JSON.stringify(dialog)} was not seen, but the page could not be observed in full (${seen.why}) — its absence cannot be assumed` };
      }
      if (dialog !== undefined) {
        warnings.push(`step ${tag}: the recorded dialog ${JSON.stringify(dialog)} did not open — conditional UI, treated as absent; steps that name one of its controls will be skipped`);
        return { warnings, absentDialog: { name: dialog, lines: plain } };
      }
      if (!seen.complete) {
        return { warnings, unobserved: true, stop: `after step ${tag} none of the ${plain.length} recorded page change(s) appeared (e.g. ${JSON.stringify(plain[0])}), and that could not be confirmed: capture incomplete (${seen.why}) — the step ran but its effect was not established` };
      }
      return { warnings, stop: `after step ${tag} none of the ${plain.length} recorded page change(s) appeared (e.g. ${JSON.stringify(plain[0])}) — the step ran but did not have its recorded effect` };
    }
    warnings.push(`step ${tag}: none of the ${plain.length} expected page change(s) appeared in the step diff (found on the page instead)`);
  }
  if (added === null) return { warnings, unobserved: true };
  return confirmed ? { warnings, confirmed: true } : { warnings };
}

/** The locator candidates of a step, as far as the dialog-membership rule reads them. */
interface DialogControlStep {
  locators: Record<string, readonly { kind: string; name?: string; text?: string; label?: string; hasText?: string }[] | undefined>;
}

/**
 * The name a step's target candidates put on the element, for membership
 * tests against a dialog's recorded subtree. Only NAMED candidates count: a
 * css/point/testid target says where an element was, not what it was called,
 * and a positional match against a dialog's line list would be a coincidence.
 */
function targetNames(step: DialogControlStep, params: Record<string, string>): string[] {
  const out: string[] = [];
  for (const c of [...(step.locators.target ?? []), ...(step.locators.source ?? [])]) {
    const name = c.kind === 'role' ? c.name : c.kind === 'text' ? c.text : c.kind === 'label' ? c.label : c.kind === 'scoped' ? c.hasText : undefined;
    if (name) out.push(fillParams(name, params).trim());
  }
  return out.filter((n) => n.length > 0);
}

/**
 * Whether a step acts on a control the absent dialog itself listed — the
 * control's name when it does, null when it does not. The dialog's recorded
 * effect lines carry its subtree — `- button "Confirm"`, `- textbox "Reason"`
 * — so a step naming one of them was inside it. This is the evidence
 * `dropDismissedDialogs` uses at compile time, applied at run time by both
 * runners.
 */
function namesDialogControl(step: DialogControlStep, dialogLines: readonly string[], params: Record<string, string>): string | null {
  for (const name of targetNames(step, params)) {
    if (dialogLines.some((l) => l.includes(`"${name}"`))) return name;
  }
  return null;
}

/**
 * Is this step a dismissal whose work is already done — the dialog it was
 * recorded closing is not on the page?
 *
 * A step is an action taken to reach a state, and a replay should act only
 * when the state is not already there. The toggle skip applies that to what a
 * step ADDS (a popup already open is not clicked again), `absentDialog` to a
 * dialog an earlier step of the same segment recorded opening. Neither covers
 * a dialog nothing in the procedure opened. fwop1's sign-in landed on
 * OpenProject's first-login "Welcome to OpenProject" dialog, the procedure's
 * next segment began by clicking its Close, and every later run — the admin
 * no longer a first-time user — had no dialog: both replays fell to the model
 * for 16-17 turns and the compiled spec failed 0/7 at its first action. The
 * same shape is every cookie banner, onboarding tour and what's-new dialog.
 *
 * So the evidence is the step's OWN recorded removal (StepExpectation.
 * removedContains), and the step is conditional on it. Called only once the
 * target has failed to resolve in the runner's full resolve window, so a
 * dialog that appears late has had the time to appear; and all of these must
 * hold, or it is an ordinary miss:
 *   - the recorded removals include a dialog, and the target names one of the
 *     controls they listed (namesDialogControl — membership proven, never
 *     inferred from the target being missing), by a DISMISSAL name. Compile
 *     records removals only for a step whose whole effect was the dialog
 *     going (no added line, alert, navigation, page effect or read), and the
 *     name is the second, independent guard against skipping a confirm;
 *   - the step mints nothing (a skipped mutation cannot be undone);
 *   - a live look that COVERED the page does not show the dialog. A look that
 *     could not cover it proves nothing absent, and a dialog that IS there
 *     with its control missing is a real failure.
 * Frame steps are excluded by the callers, as for `absentDialog`.
 */
/**
 * Button names that dismiss a dialog without acting — UI convention, not app
 * knowledge. A confirm ("Delete", "Save", "OK", "Accept") never matches: it
 * also closes its dialog, but skipping it when the dialog did not appear
 * would hide exactly the regression a missing confirm dialog is.
 */
const DISMISSAL = /^(cancel|close|dismiss|no|no,? thanks|not now|later|maybe later|skip|got it|back|keep editing|[×✕✖])$/i;

function dismissalAlreadyInEffect(
  step: DialogControlStep & { mints?: unknown; expect?: { removedContains?: readonly string[] } },
  live: LiveLines | null,
  params: Record<string, string>,
): { dialog: string; control: string } | null {
  const removed = step.expect?.removedContains;
  if (!removed?.length || step.mints) return null;
  const dialogLine = removed.find((l) => DIALOG_LINE.test(l));
  if (dialogLine === undefined) return null;
  const control = namesDialogControl(step, liveLines(removed, params), params);
  if (control === null || !DISMISSAL.test(control.trim()) || !live?.complete) return null;
  if (lineShows(live.lines, liveLines([dialogLine], params))) return null;
  return { dialog: DIALOG_LINE.exec(dialogLine)![1], control };
}

/**
 * What an action's observation (src/execution/action.ts `beginAction`) polls
 * for as the step's completion: the HARD half of its recorded page changes —
 * the lines carrying this run's own `{{vN}}` values, filled — in the step's
 * line dialect. It holds when any of them shows, as the effect gate
 * (expectedChangesVerdict) accepts any of them; it does not hold when none
 * shows on a look that covered the page; and it could not be observed (null)
 * otherwise. Undefined when the step has no such line: quiet is then all the
 * observation waits for, and it never calls that an effect.
 *
 * The recorded url is not part of it. Both runners' url gates already wait on
 * the url with their own window, and a url the gate would accept as volatile
 * would never strictly match here, so every such step would sit out the whole
 * effect window first.
 */
function effectExpectation(
  page: Page,
  recorded: readonly string[] | undefined,
  params: Record<string, string>,
  d: LineDialect = 1,
): { holds(): Promise<boolean | null> } | undefined {
  // The same three exclusions the effect gate makes, for the same reasons: a
  // popup item is never the hard half, and a line identifying nothing or one
  // this run could not fill is not something to wait for (fwod49-n2 — the
  // observation would have polled for the literal "{{02-open.product_name}}"
  // for the whole action window before the gate stopped on it).
  const hard = liveLines((recorded ?? []).filter((l) => SLOT_LINE.test(l) && !TRANSIENT_LINE.test(l) && !popupItem(l)), params).filter(
    (l) => !identifiesNothing(l) && !unfilledSlot(l),
  );
  if (!hard.length) return undefined;
  return {
    holds: async () => {
      const live = await captureLines(page, d);
      if (!live) return null;
      if (lineShows(live.lines, hard)) return true;
      return live.complete ? false : null;
    },
  };
}

// Shared execution source: point.ts. Regenerate to update.
/**
 * Geometry as a locator kind, shared by daemon replay and the standalone
 * artifact.
 *
 * A `point` candidate says where the element WAS: its box in document
 * coordinates and the viewport it was recorded in, plus the role (or tag) it
 * had. It is resolved in two moves — `markPoint` finds the element under the
 * recorded point, walks up to the recorded KIND of thing, and tags it; then
 * `pointLocator` names the tag — so that the result is an ordinary Locator
 * that stands only when the role matches: a locator, not a blind click.
 *
 * The same box is the yardstick a positional guess is measured against (see
 * resolve.ts's plausibility rule).
 */
interface PointGeometry {
  /** Centre of the recorded element, in document coordinates. */
  x: number;
  y: number;
  w: number;
  h: number;
  /** The role it had, or null when it had none — then `tag` decides. */
  role: string | null;
  tag: string;
  /** The viewport it was recorded in: what "near" means for the box. */
  vw: number;
  vh: number;
}

/** The attribute markPoint leaves on the element it found, so a sync Locator can name it. */
const POINT_MARK = 'data-sitelooper-point';

function pointToken(c: { x: number; y: number }): string {
  return `${c.x},${c.y}`;
}

/** The Locator naming what markPoint tagged for this point. Empty until markPoint has run on this page. */
function pointLocator(page: Page, c: { x: number; y: number }): Locator {
  return page.locator(`[${POINT_MARK}=${JSON.stringify(pointToken(c))}]`);
}

/**
 * Find the element under a recorded point, walk up to its actionable
 * ancestor, and tag it for pointLocator — but only when it is the KIND of
 * thing recorded (same role, or same tag when the recording had no role).
 * Returns what it found, or null when nothing of that kind is there. Scrolls
 * the window so the point is on screen first; a point in an inner scroller
 * is found only when that scroller sits where it was recorded.
 */
async function markPoint(page: Page, c: PointGeometry): Promise<{ role: string | null; tag: string } | null> {
  try {
    return await page.evaluate(
      ({ x, y, role, tag, mark, token }) => {
        const ACTIONABLE = 'button,a[href],input,select,textarea,summary,[role],[tabindex],label';
        const targetY = y - window.innerHeight / 2;
        if (Math.abs(window.scrollY - targetY) > window.innerHeight / 2 || x - window.scrollX > window.innerWidth) {
          window.scrollTo(Math.max(0, x - window.innerWidth / 2), Math.max(0, targetY));
        }
        const hit = document.elementFromPoint(x - window.scrollX, y - window.scrollY);
        if (!hit) return null;
        const kindOf = (el: Element): { role: string | null; tag: string } => {
          const tagOf = el.tagName.toLowerCase();
          const type = (el.getAttribute('type') || '').toLowerCase();
          const implicit = (): string | null => {
            if (tagOf === 'button') return 'button';
            if (tagOf === 'a') return el.hasAttribute('href') ? 'link' : null;
            if (tagOf === 'select') return el.hasAttribute('multiple') ? 'listbox' : 'combobox';
            if (tagOf === 'textarea') return 'textbox';
            if (tagOf === 'img') return 'img';
            if (/^h[1-6]$/.test(tagOf)) return 'heading';
            if (tagOf === 'input') {
              if (type === 'checkbox') return 'checkbox';
              if (type === 'radio') return 'radio';
              if (type === 'submit' || type === 'button' || type === 'reset') return 'button';
              if (type === 'search') return 'searchbox';
              if (type === 'number') return 'spinbutton';
              if (['text', 'email', 'tel', 'url', 'password', ''].includes(type)) return 'textbox';
              return null;
            }
            return null;
          };
          return { role: el.getAttribute('role') || implicit(), tag: tagOf };
        };
        // The point lands on whatever is painted there — a heading's text
        // span, a button's icon. Walk up a few ancestors for the recorded
        // KIND (fwgr27: every heading point missed because the hit was the
        // title's inner span); failing that, the nearest actionable ancestor.
        let el: Element | null = null;
        for (let cur: Element | null = hit, hops = 0; cur && hops < 6; cur = cur.parentElement, hops++) {
          const k = kindOf(cur);
          if (role ? k.role === role : k.tag === tag) {
            el = cur;
            break;
          }
        }
        el ??= (hit.closest(ACTIONABLE) as Element | null) ?? hit;
        const { role: roleOf, tag: tagOf } = kindOf(el);
        const same = role ? roleOf === role : tagOf === tag;
        if (!same) return null;
        for (const old of Array.from(document.querySelectorAll(`[${mark}]`))) old.removeAttribute(mark);
        el.setAttribute(mark, token);
        return { role: roleOf, tag: tagOf };
      },
      { x: c.x, y: c.y, role: c.role, tag: c.tag, mark: POINT_MARK, token: pointToken(c) },
    );
  } catch {
    return null;
  }
}

// Shared execution source: resolve.ts. Regenerate to update.
/**
 * ONE locator-resolution policy, run by daemon replay and embedded verbatim
 * in the standalone artifact.
 *
 * A recorded step carries a CHAIN of ways to find its element. Picking one at
 * replay is not "the first that matches": it is a set of rules that used to
 * live only in replay's `resolveChain`, while the artifact's `pick` had one of
 * them (policy audit B8, gaps 14 and B8). The rules, in the order they apply:
 *
 *  1. ORDER. Identity (a candidate that names a RECORD) ahead of handles (a
 *     candidate that names a CONTROL) ahead of paths (a route to wherever
 *     that shape currently sits), with the recorded point last of all — each
 *     class keeping its recorded order. Within a class a candidate that later
 *     runs showed to be volatile (`retired`) goes last: the class order is a
 *     prior about what a candidate IS, retirement is a measurement of whether
 *     it WORKS.
 *  2. A POINT NAMES A PLACE. It is marked (the element under it, of the
 *     recorded kind) before its locator can name anything; nothing of that
 *     kind there is a miss.
 *  3. UNIQUE, THEN GUARDED. A candidate that resolves to exactly one element
 *     must still (a) keep the record's identity — bear every value the step
 *     was recorded against, unless it carries that value itself; the recorded
 *     primary is trusted, unless it is itself structural; (b) be plausible —
 *     a guess that resolves far from the recorded box is a different element;
 *     (c) stay on the recorded origin — a guess inside a link that leaves it
 *     cannot be the recorded control. The primary is exempt from (b) and (c)
 *     unless structural: the recording did click it.
 *  4. AMBIGUITY. Several matches are the normal shape only for a read across
 *     every match (`allowMultiple`) and for a loop body whose per-record
 *     locator matches every record (`ambiguousNth` narrows to the cursor,
 *     still identity-guarded). Otherwise an ambiguous primary that was unique
 *     when recorded is DRIFT — keep looking — and an ambiguous fallback is
 *     simply not a way of naming one thing.
 *  5. THE HOLD. A structural hit is not taken on the spot when the chain also
 *     names the element: a path resolves instantly against whatever sits in
 *     that slot while the named control is still rendering. The guess is held
 *     until the names have had the whole wait window, and stands only when
 *     none of them came.
 *  6. THE WAIT. When a pass resolves nothing, the WHOLE chain is re-walked on
 *     a poll for `waitMs` — not the primary alone — so the preference order
 *     stays intact and the best candidate wins the moment it appears. Misses
 *     are reported per pass, from the pass that resolved: a candidate that
 *     missed while the page was still painting and hits on the next poll is
 *     not volatile, it was early.
 *  7. THE RACE. A named fallback that wins while a better candidate was
 *     merely absent is confirmed once the DOM has gone quiet, and the second
 *     pass's named answer stands (see `confirm`). Drift is a better candidate
 *     that failed, never a stored index alone (`isDrift`).
 *
 * What the runners supply is OBSERVATIONS — a locator per candidate and the
 * compile-time facts about it — and how they present the result. What they
 * must not do is reinterpret any rule above.
 */

/** One candidate, as this policy sees it. The runner builds the Locator; the policy decides. */
interface CandidateObservation {
  /** The live locator for this candidate. For a point, the marker locator (see point.ts) — empty until marked. */
  locator: Locator;
  /** Its index in the STORED chain, so telemetry names the recorded candidate that took (or missed) the step. */
  index: number;
  /** Position, not identity: a path through the document, an index into a set of matches, or a point. See structuralCandidate. */
  structural: boolean;
  /** The candidate's kind ('scoped', 'role', 'css', 'point', ...). 'scoped' is the identity class; 'point' is marked before counting. */
  kind: string;
  /**
   * Text the candidate itself names, with params filled — the daemon passes
   * the candidate's JSON. An identity value found here needs no guarding:
   * the candidate already asks for it.
   */
  carries: string;
  /** The recorded match index, when the candidate was checked against the recorded element at that index. Set means ambiguity was expected. */
  nth?: number;
  /** For a point candidate: the recorded geometry. The FIRST point in the input is also the plausibility yardstick for every guess. */
  point?: PointGeometry;
  /** Demonstrated volatile by later runs (hit 0, missed repeatedly). Ordered last within its class. */
  retired?: boolean;
  /** Names a slot in one agent snapshot, not an element (see snapshotRefCandidate). Never resolved; set only when true. */
  ephemeral?: boolean;
}

/** Policy for one resolution. Named, because seven positional flags is how a call site gets one wrong. */
interface ResolvePolicy {
  /** read_all reads across every match, so its target need not be unique. */
  allowMultiple?: boolean;
  /**
   * Loop-body cursor: when a candidate matches several records, act on THIS
   * match index (the first unprocessed record) instead of skipping to a
   * fallback. A folded loop's per-record locator is often generic across rows
   * ("Edit" on every row), so ambiguity there is the loop's normal shape, not
   * drift — and the positional fallback it used to fall through to is pinned
   * to one recorded row, which is how fwrd4l edited part A seven times.
   */
  ambiguousNth?: number;
  /**
   * Identity the step carried: values the caller vouched for that named the
   * record this step acts on ("fwrd8-n2 RD Bench Ticket"). A fallback
   * candidate is a different way of finding the SAME element, so it must
   * still land on something bearing that text — the positional and record-id
   * fallbacks recorded beside it are pinned to the recorded run's row and id,
   * and following one silently moves the whole procedure onto another record
   * (fwrd8-n2/n3 worked a seed ticket to completion this way). When no
   * fallback qualifies, the step fails to recovery, which is cheap; acting on
   * the wrong record is not. Derive it with identityValues.
   */
  requireIdentity?: readonly string[];
  /**
   * The origin the recorded step stayed on. A candidate that resolves to a
   * link leaving that origin cannot be the recorded control: diaggr1's
   * replay of fwgr26 fell from `link "New dashboard"` (its menu had been
   * toggled shut) to the structural `div > … > a:nth-of-type(1)`, which
   * matched Grafana's footer link to grafana.com; the offline box answered
   * with an error page and the whole create step went to recovery.
   */
  stayOnOrigin?: string;
  /**
   * How long to keep re-trying the WHOLE chain when nothing resolves.
   *
   * The agent never needed this: a model turn is seconds and it re-snapshots
   * each time, so anything the app was about to paint (repair-desk defers its
   * list refetch ~1s BY DESIGN) had always landed before it looked. A replay
   * has no turns, and settling only proves the DOM went quiet, which it does
   * in the gap BEFORE the refetch paints. The wait costs nothing on a healthy
   * page — it runs only after a full pass found nothing.
   *
   * Zero for a caller ASKING whether something is still there rather than
   * looking for it: the loop guard reads a null return as "the list is empty,
   * stop", so waiting there would stall every loop's normal exit.
   */
  waitMs?: number;
  /** Poll cadence inside the wait. Default RESOLVE_POLL_MS. */
  pollMs?: number;
}

/** Why a candidate ahead of the winner was passed over — the same words in both runners' telemetry. */
type MissReason =
  | 'absent' // matched nothing
  | 'unmarked' // a point with nothing of the recorded kind under it
  | 'identity' // resolved, but not to something bearing the record's identity
  | 'implausible' // resolved far from the recorded box
  | 'origin' // resolved inside a link leaving the recorded origin
  | 'ambiguous' // matched several, and this is not a place ambiguity is allowed
  | 'error'; // malformed selector or detached page

interface Resolution {
  /** The locator to act on: the candidate's own, narrowed with `.nth()` when ambiguity was allowed by cursor. */
  locator: Locator;
  /** Stored-chain index of the winning candidate. 0 is the primary; anything else is drift. */
  index: number;
  /** Set when an ambiguous candidate was narrowed to the loop cursor — the runner sinks it beside the candidate. */
  nth?: number;
  /** Whether the winner was positional — the runner sharpens its effect gate and withholds evidence on such a hit. */
  structural: boolean;
  /** Every candidate rejected in the PASS that resolved, in walk order. Empty when nothing resolved is reported as null, not here. */
  missed: { index: number; reason: MissReason }[];
}

/** Default poll cadence of the wait loop. Runs only on a page that has already failed to answer, never on the fast path. */
const RESOLVE_POLL_MS = 100;
/** Default wait window when nothing resolves, for a runner that does not configure its own. */
const RESOLVE_WAIT_MS = 3_000;

/**
 * Structural: a path through the document, or an index into a set of matches,
 * or where the element was. Position, not identity.
 *
 * Note this is NOT "kind === css". An agent-chosen `#modal-save` is a handle
 * — it names one control — while `#view > div > button:nth-of-type(2)` is a
 * route to wherever that shape currently sits. Demoting the first alongside
 * the second would push a deliberate selector below a role guess.
 *
 * A combinator is one form of position; a CHILD-INDEX pseudo-class is the
 * other, and the family is settled by CSS grammar, not by guessing at a
 * shape: `:nth-child`/`:nth-of-type` (and their `nth-last-` forms) and
 * `:first|:last|:only-child`/`-of-type` all name a slot in a sibling list BY
 * DEFINITION. Only `:nth-` was tested, so fwrd59's `table tbody tr:first-child a`
 * was classified a HANDLE: it skipped keepsIdentity, plausible and leavesOrigin
 * (all gated on `index > 0 || structural`), resolved on the first walk against
 * whatever row 1 held, and opened ticket t14 while the run's own ticket was t15.
 * Same defect, same app and page as recorder.ts's `tr:nth-of-type(1)` note.
 *
 * Matched case-insensitively because CSS pseudo-class names are: an agent may
 * type `:First-child`. The two ways to be wrong are not equal — calling a
 * handle positional only demotes it and asks it to prove identity, while
 * calling a position a handle skips every guard, which is the bug above — so
 * where the spelling is in doubt this errs toward position.
 */
function structuralCandidate(c: { kind: string; nth?: number; selector?: string }): boolean {
  if (c.nth !== undefined) return true;
  if (c.kind === 'point') return true; // where it was, not what it is
  if (c.kind !== 'css') return false;
  return /[>+~]|:nth-|:(?:first|last|only)-(?:child|of-type)/i.test(c.selector ?? '');
}

/**
 * A candidate that addresses the element through Playwright's `aria-ref`
 * engine: `aria-ref=e423` names whatever held ref e423 in the most recent AI
 * snapshot of THIS page, so it identifies nothing across runs — and worse, it
 * is not absent on a later run, it is some OTHER element. fwop3's 05-add chain
 * stored `aria-ref=e423` (the "Relations" tab, typed by the recording agent)
 * as its primary css candidate; a primary that is not structural is a handle,
 * trusted without the identity guard, so on both replays the daemon clicked
 * the Wikis tab — the element that held e423 in its own last snapshot — while
 * the stored `tab "Relations"` right behind it would have found the tab. In
 * the compiled artifact the same selector has no snapshot to resolve against
 * at all. Refs are no longer stored (daemon/refs.ts refOf); this keeps the
 * ones already in stores from ever being resolved, in both runners.
 */
function snapshotRefCandidate(c: { kind: string; selector?: string }): boolean {
  if (c.kind !== 'css' && c.kind !== 'id') return false;
  return (c.selector ?? '').split('>>').some((segment) => /^\s*aria-ref\s*=/i.test(segment));
}

/**
 * The class a candidate belongs to, as a sort key: identity (0), handle (1),
 * path (2), point (3). A point is the last resort behind every path.
 */
function candidateRank(c: { kind: string; structural: boolean }): number {
  if (c.kind === 'scoped') return 0;
  if (c.kind === 'point') return 3;
  return c.structural ? 2 : 1;
}

/**
 * Rule 1: class order, recorded order within a class, retired last within a
 * class. Stable, so nothing shuffles for free.
 */
function orderCandidates<T extends { kind: string; structural: boolean; retired?: boolean }>(cands: readonly T[]): T[] {
  return cands
    .map((c, at) => ({ c, at }))
    .sort((a, b) => candidateRank(a.c) - candidateRank(b.c) || Number(!!a.c.retired) - Number(!!b.c.retired) || a.at - b.at)
    .map(({ c }) => c);
}

/** Does the resolved element sit inside a link that leaves the recorded origin? Rule 3(c). */
async function leavesOrigin(locator: Locator, origin: string | undefined): Promise<boolean> {
  if (!origin) return false;
  try {
    return await locator.first().evaluate((el, wanted) => {
      const a = (el as Element).closest('a[href]');
      if (!a) return false;
      try {
        const target = new URL((a as HTMLAnchorElement).href, location.href);
        // file:// pages have an opaque origin; a link there is "home" when
        // it stays on the same scheme.
        if (target.origin === 'null' || location.origin === 'null') return target.protocol !== location.protocol;
        return target.origin !== wanted;
      } catch {
        return false;
      }
    }, origin, { timeout: DEFAULT_ACTION_TIMEOUT_MS });
  } catch {
    return false;
  }
}

/**
 * Rule 3(b). The recorded geometry, when the chain carries it, is the
 * yardstick a guess is measured against: a structural fallback that resolves
 * far from where the recorded element sat is a different element — rpgr13's
 * `div > … > button` took a header button for a control in the editor's side
 * pane.
 */
async function plausible(page: Page, locator: Locator, recorded: PointGeometry | null): Promise<boolean> {
  if (!recorded) return true;
  try {
    const box = await locator.first().boundingBox({ timeout: DEFAULT_ACTION_TIMEOUT_MS });
    if (!box) return true; // nothing to measure — let the other guards judge
    const scroll = await page.evaluate(() => ({ x: window.scrollX, y: window.scrollY }));
    const cx = box.x + box.width / 2 + scroll.x;
    const cy = box.y + box.height / 2 + scroll.y;
    const limit = Math.max(recorded.vw, recorded.vh) / 3;
    return Math.hypot(cx - recorded.x, cy - recorded.y) <= limit;
  } catch {
    return true;
  }
}

/**
 * Rule 3(a). Does this candidate still identify the record the step named?
 * The recorded primary is trusted — unless it is itself structural (an
 * agent-typed positional selector at the head), which names no record.
 */
async function keepsIdentity(c: CandidateObservation, locator: Locator, requireIdentity: readonly string[]): Promise<boolean> {
  if (!requireIdentity.length || (c.index === 0 && !c.structural)) return true;
  const wanted = requireIdentity.filter((v) => !c.carries.includes(v));
  if (!wanted.length) return true;
  let text: string;
  try {
    text = ((await locator.first().textContent({ timeout: 1_000 })) ?? '').replace(/\s+/g, ' ');
  } catch {
    return false;
  }
  return wanted.every((v) => text.toLowerCase().includes(v.toLowerCase()));
}

/**
 * Whether a resolution is DRIFT: a candidate the policy tried ahead of the
 * winner failed, and the step stood on a fallback. Not merely "the winner is
 * not stored index 0": rule 1 ranks a positional primary behind the
 * candidates that name the element, and a name that wins the first try has
 * replaced nothing that missed. Reading the stored index alone filed drift
 * tickets for steps where nothing had changed (fwod41 07-change's `nth: 0`
 * path, grafana's agent-typed `div.css-qpkbik:has-text("Stat") >> nth=0`),
 * on every run, in both runners.
 */
function isDrift(hit: { index: number; missed: readonly unknown[] }): boolean {
  return hit.index > 0 && hit.missed.length > 0;
}

/**
 * Resolve one chain of candidates against the page under `policy`. `cands`
 * is given in STORED order (index ascending); this function orders it.
 * Returns null when nothing resolved within the wait.
 */
async function resolveCandidates(page: Page, cands: readonly CandidateObservation[], policy: ResolvePolicy = {}): Promise<Resolution | null> {
  const { allowMultiple = false, ambiguousNth, requireIdentity = [], stayOnOrigin, waitMs = 0, pollMs = RESOLVE_POLL_MS } = policy;
  // A snapshot ref is not tried at all, and so is never a miss: it was never a
  // way of finding this element on this run (snapshotRefCandidate), and counting
  // it absent filed a drift ticket on every run for s_5749e4's `aria-ref=e417`.
  const ordered = orderCandidates(cands.filter((c) => !c.ephemeral));
  const recordedBox = cands.find((c) => c.kind === 'point' && c.point)?.point ?? null;

  /**
   * One pass over the chain, best candidate first, reporting which candidates
   * it REJECTED before the winner. Per pass, deliberately (rule 6).
   */
  const walk = async (): Promise<Resolution | null> => {
    const missed: Resolution['missed'] = [];
    const miss = (index: number, reason: MissReason) => missed.push({ index, reason });
    for (const c of ordered) {
      const guess = c.index > 0 || c.structural;
      try {
        // A point names a place; find what is there (of the recorded kind)
        // before a locator can name it.
        if (c.kind === 'point' && (!c.point || !(await markPoint(page, c.point)))) {
          miss(c.index, 'unmarked');
          continue;
        }
        const count = await c.locator.count();
        if (count === 1) {
          if (!(await keepsIdentity(c, c.locator, requireIdentity))) {
            miss(c.index, 'identity');
            continue;
          }
          if (guess && c.kind !== 'point' && !(await plausible(page, c.locator, recordedBox))) {
            miss(c.index, 'implausible');
            continue;
          }
          // The recorded primary is trusted even when it is such a link — the
          // recording clicked it (rpgr12-r2's sign-in skill had a stray click
          // on Grafana's "Support" footer link, and refusing it cost a
          // 19-turn recovery). Only a guess may not leave the origin.
          if (guess && (await leavesOrigin(c.locator, stayOnOrigin))) {
            miss(c.index, 'origin');
            continue;
          }
          return { locator: c.locator, index: c.index, structural: c.structural, missed };
        }
        if (count > 1) {
          if (allowMultiple) return { locator: c.locator, index: c.index, structural: c.structural, missed };
          if (ambiguousNth !== undefined && c.nth === undefined && ambiguousNth < count) {
            const picked = c.locator.nth(ambiguousNth);
            if (!(await keepsIdentity(c, picked, requireIdentity))) {
              miss(c.index, 'identity');
              continue;
            }
            return { locator: picked, index: c.index, nth: ambiguousNth, structural: c.structural, missed };
          }
          miss(c.index, 'ambiguous'); // a primary that was unique: drift; a fallback: not a way of naming one thing
          continue;
        }
        miss(c.index, 'absent');
      } catch {
        miss(c.index, 'error'); // malformed selector or detached page — try the next
      }
    }
    return null;
  };

  // Fast path first: on a page that is ready this returns immediately and the
  // wait below never runs. Rules 5 and 6: a structural hit is held while the
  // chain also names the element; the whole chain is re-walked each poll.
  const named = ordered.some((c) => !c.structural);
  const guess = (hit: Resolution | null) => !!hit && named && hit.structural;
  const first = await walk();
  if (first && !guess(first)) return confirm(first);
  let held = first;
  for (let waited = 0; waited < waitMs; waited += pollMs) {
    // A plain timer, not page.waitForTimeout: this path runs precisely when
    // the page is unhappy, and a navigating or detached page makes its own
    // clock throw.
    await new Promise((r) => setTimeout(r, pollMs));
    const hit = await walk();
    if (hit && !guess(hit)) return confirm(hit);
    if (hit) held = hit;
  }
  return held;

  /**
   * Rule 7, THE RACE. A named fallback that wins while a better candidate was
   * merely ABSENT may have won by being counted a moment later, on a page that
   * was still painting. Odoo's autocomplete does exactly this: the DOM goes
   * quiet in the gap before the search answers, so one pass counted the named
   * option (absent), then `#autocomplete_0_0` (absent), then the same id again
   * (present) — the list arrived mid-walk, and the step clicked "whatever is
   * first" by an id that only looks like a name (fwod42 02-create, two runs of
   * three). So: let the DOM go quiet once and walk again. The second answer
   * stands when it resolves to a named candidate; otherwise the first does.
   * A hit whose misses are all judgments (identity, ambiguity, origin) is
   * about the page as it is, not early, and is taken as it stands.
   */
  async function confirm(hit: Resolution): Promise<Resolution> {
    if (!isDrift(hit) || !hit.missed.some((m) => m.reason === 'absent')) return hit;
    await settleDom(page);
    const again = await walk();
    return again && !guess(again) ? again : hit;
  }
}

/** The text-bearing fields of a candidate: what it NAMES. A slot inside a css selector or a testid is an address, not a name. */
function identityFields(c: { name?: string; text?: string; label?: string; hasText?: string }): string[] {
  return [c.name, c.text, c.label, c.hasText].filter((v): v is string => typeof v === 'string');
}

/**
 * The identity values a step carried: known ({{known}}) slots whose value the
 * recorded run used to NAME the target by its visible text. `fields` are the
 * UNFILLED name/text/label/hasText strings of the WHOLE chain (identityFields
 * of every candidate) — identity is a property of the STEP, which record it
 * acts on, not of whichever candidate happens to sit first (fwrd26l: the
 * primary was an XPath stored as css and advertised nothing, while the scoped
 * anchor right behind it named the record). `known` maps a slot to its value
 * for KNOWN slots only; a value shorter than three characters is too weak to
 * pin a fallback to. Deduplicated, in first-seen order.
 */
function identityValues(known: Record<string, string | undefined>, fields: readonly string[]): string[] {
  const out = new Set<string>();
  for (const field of fields) {
    for (const m of field.matchAll(/\{\{(v\d+)\}\}/g)) {
      const value = known[m[1]];
      if (value && value.length >= 3) out.add(value);
    }
  }
  return [...out];
}

// Shared execution source: recipes.ts. Regenerate to update.
/**
 * Component recipes — the RUNNER, shared by daemon replay and the standalone
 * artifact.
 *
 * A recipe is an origin-independent micro-procedure for a third-party widget
 * that defeats the naive fill/type/select primitives (monaco, CodeMirror, a
 * contenteditable editor, a portal-rendered combobox): a short action list
 * with the payload parameterised as {{value}}, plus a mandatory verification
 * read. The honesty rule is structural: a recipe only succeeded if the
 * component's effective value re-observes the payload, and one that cannot
 * prove its effect reports failure so the caller falls back to the native
 * primitive.
 *
 * What lives here is everything that runs against a page: the family
 * recognition set, the shipped seed procedures, recognition, execution,
 * verification, and the "recipe first, then native" ladder each of fill,
 * type and select climbs. What does NOT live here is recipe SELECTION — the
 * ComponentStore in src/skills/components.ts (learned variants, statuses,
 * demotion, stats) — because that is daemon state. The daemon supplies a
 * `RecipeBook` that consults the store; the artifact supplies one built from
 * a compile-time snapshot of what the store would have chosen.
 */

type RecipeIntent = 'set-value' | 'read-value' | 'select-option' | 'open' | 'dismiss';

interface RecipeStep {
  action: 'click' | 'press' | 'insertText' | 'fill' | 'blur' | 'settle';
  /**
   * CSS relative to the component root; absent = the root itself. A
   * `page:<css>` prefix scopes to the whole page — for option lists rendered
   * into a portal outside the component's subtree.
   */
  target?: string;
  key?: string;
  /** For insertText/fill; "{{value}}" is replaced by the payload. */
  text?: string;
  /** A historical estimate of the re-render time; `settle` waits for the DOM to go quiet instead. */
  ms?: number;
  /** Restrict a page-scoped click to elements containing this (filled) text. */
  withText?: string;
}

/** The runnable part of a recipe: what both runners need, and all the artifact carries. */
interface RecipeProcedure {
  id: string;
  family: string;
  intent: RecipeIntent;
  steps: RecipeStep[];
  /** CSS relative to root for the verification read; absent = the root itself. */
  verifyRead?: string;
}

interface RecipeFamily {
  id: string;
  /** CSS the component ROOT matches (used with Element.closest). */
  root: string;
  /** Default verification read for learned recipes of this family. */
  verifyRead?: string;
}

/**
 * Recognition set. Order matters: more specific families first (CodeMirror's
 * .cm-content IS contenteditable; monaco embeds a textarea). Recognition may
 * be heuristic because being wrong is cheap: the recipe's verification read
 * fails, the action falls back to the naive primitive and then the model.
 */
const RECIPE_FAMILIES: RecipeFamily[] = [
  { id: 'monaco', root: '.monaco-editor', verifyRead: '.view-lines' },
  { id: 'codemirror6', root: '.cm-editor', verifyRead: '.cm-content' },
  { id: 'prosemirror', root: '.ProseMirror' },
  { id: 'contenteditable', root: '[contenteditable="true"]' },
  { id: 'aria-combobox', root: '[role="combobox"]' },
];

function recipeFamilyOf(id: string): RecipeFamily | undefined {
  return RECIPE_FAMILIES.find((f) => f.id === id);
}

/**
 * Select-all → replace → commit, the shape every keyboard-driven editor takes.
 *
 * The Escape (`escape`, on by default) dismisses a CODE editor's completion widget before the blur, so
 * the blur cannot accept a suggestion into the value. A rich-text editor has
 * no such widget, and the app hosting one often binds Escape to "cancel this
 * edit": fwvk1's task description (a tiptap/ProseMirror editor) threw the
 * inserted text away on it, every seed attempt failed its verification, and
 * two failures demoted the seed — which is how a learned recipe that appends
 * came to serve the family. So the rich-text seeds do not press it.
 */
function editorSetValueSteps(clickTarget?: string, blurTarget?: string, opts: { escape?: boolean } = {}): RecipeStep[] {
  return [
    { action: 'click', ...(clickTarget ? { target: clickTarget } : {}) },
    { action: 'press', key: 'ControlOrMeta+a' },
    { action: 'insertText', text: '{{value}}' },
    { action: 'settle', ms: 400 },
    ...(opts.escape === false ? [] : [{ action: 'press', key: 'Escape' } as RecipeStep]),
    { action: 'blur', ...(blurTarget ? { target: blurTarget } : {}) },
    { action: 'settle', ms: 200 },
  ];
}

/** A shipped procedure before the store gives it an id, a status and stats. */
type SeedRecipe = Omit<RecipeProcedure, 'id'>;

/**
 * The shipped starter library, as procedures. Seeds are a floor, not an
 * authority: in the daemon they enter the lifecycle provisional, must verify
 * on first contact, and can be demoted or superseded by learned variants when
 * a library version changes behaviour. The store assigns their ids.
 */
const SEED_RECIPES: SeedRecipe[] = [
  { family: 'monaco', intent: 'set-value', steps: editorSetValueSteps(undefined, 'textarea'), verifyRead: '.view-lines' },
  { family: 'monaco', intent: 'read-value', steps: [], verifyRead: '.view-lines' },
  { family: 'codemirror6', intent: 'set-value', steps: editorSetValueSteps('.cm-content', '.cm-content'), verifyRead: '.cm-content' },
  { family: 'codemirror6', intent: 'read-value', steps: [], verifyRead: '.cm-content' },
  { family: 'prosemirror', intent: 'set-value', steps: editorSetValueSteps(undefined, undefined, { escape: false }) },
  { family: 'contenteditable', intent: 'set-value', steps: editorSetValueSteps(undefined, undefined, { escape: false }) },
  {
    family: 'aria-combobox',
    intent: 'select-option',
    steps: [
      { action: 'click' },
      { action: 'press', key: 'ControlOrMeta+a' },
      { action: 'insertText', text: '{{value}}' },
      { action: 'settle', ms: 400 },
      { action: 'click', target: 'page:[role="option"]', withText: '{{value}}' },
      { action: 'settle', ms: 200 },
    ],
  },
];

/** How long recognition waits for the target to be attached — the element must exist for `closest` to mean anything. */
const RECIPE_RECOGNIZE_MS = 1_500;
/** Per-step budget inside a recipe. */
const RECIPE_STEP_TIMEOUT_MS = 3_000;

interface RecognizedComponent {
  family: RecipeFamily;
  /**
   * The nearest matching ancestor-or-self of the target, PINNED at
   * recognition: the component root every step's `target` is relative to. A
   * handle rather than a Locator because a recipe changes what the target
   * matches — a text or placeholder target on an editor stops matching once
   * the content is replaced, and a selector that also matches a mirrored
   * preview matches more afterwards — while every click, blur and the
   * verification read must still mean the component that was recognised.
   * Whoever recognised it disposes it (`applyRecipe` does, on every exit).
   */
  root: ElementHandle;
}

/**
 * Which component (if any) the target element sits inside: nearest matching
 * ancestor, first family in RECIPE_FAMILIES order wins. The target is
 * resolved once (strictly, waiting up to RECIPE_RECOGNIZE_MS for it to
 * attach, as HEAD's `elementHandle` did); one evaluateHandle on it pins the
 * root element of the first family whose `closest` hits; one evaluate on that pinned root names the family — the first root
 * selector it matches, which is that family, since every earlier family's
 * `closest` already missed on an ancestor-or-self of the target. Null on a
 * target that is not attached, or any evaluation failure; no handle is left
 * undisposed then.
 */
async function recognizeComponent(_page: Page, target: Locator, families: readonly RecipeFamily[] = RECIPE_FAMILIES): Promise<RecognizedComponent | null> {
  const roots = families.map((f) => f.root);
  let el: ElementHandle | null = null;
  let root: ElementHandle | null = null;
  try {
    el = await target.elementHandle({ timeout: RECIPE_RECOGNIZE_MS });
    if (!el) return null;
    const found = await el.evaluateHandle((node: Element, sels: string[]) => {
      for (const sel of sels) {
        try {
          const hit = node.closest(sel);
          if (hit) return hit;
        } catch {
          // malformed selector — try the next family
        }
      }
      return null;
    }, roots);
    root = found.asElement();
    if (!root) {
      await found.dispose().catch(() => {});
      return null;
    }
    const which = await root.evaluate(
      (node: Element, sels: string[]) =>
        sels.findIndex((sel) => {
          try {
            return node.matches(sel);
          } catch {
            return false;
          }
        }),
      roots,
    );
    if (which < 0) {
      await root.dispose().catch(() => {});
      return null;
    }
    return { family: families[which], root };
  } catch {
    if (root) await root.dispose().catch(() => {});
    return null;
  } finally {
    if (el) await el.dispose().catch(() => {});
  }
}

/**
 * Run `use` on the element a root-relative step target names inside the
 * pinned root right now (the first match; the root itself when the target is
 * absent; null when it names nothing), disposing a child handle afterwards.
 */
async function withStepTarget<T>(root: ElementHandle, target: string | undefined, use: (h: ElementHandle | null) => Promise<T>): Promise<T> {
  const h = target ? await root.$(target) : root;
  try {
    return await use(h);
  } finally {
    if (h && h !== root) await h.dispose().catch(() => {});
  }
}

/** Run a recipe's steps against a recognized component root. Throws on a step that cannot run. */
async function executeRecipe(page: Page, root: ElementHandle, recipe: RecipeProcedure, payload: string): Promise<void> {
  for (const s of recipe.steps) {
    const text = s.text?.split('{{value}}').join(payload);
    const withText = s.withText?.split('{{value}}').join(payload);
    switch (s.action) {
      case 'click': {
        if (s.target?.startsWith('page:')) {
          let loc = page.locator(s.target.slice(5));
          if (withText) loc = loc.filter({ hasText: withText });
          await loc.first().click({ timeout: RECIPE_STEP_TIMEOUT_MS });
        } else {
          await withStepTarget(root, s.target, async (h) => {
            if (!h) throw new Error(`recipe ${recipe.id}: no "${s.target}" inside the component`);
            await h.click({ timeout: RECIPE_STEP_TIMEOUT_MS });
          });
        }
        break;
      }
      case 'press':
        await page.keyboard.press(String(s.key ?? ''));
        break;
      case 'insertText':
        await page.keyboard.insertText(text ?? '');
        break;
      case 'fill': {
        await withStepTarget(root, s.target, async (h) => {
          if (!h) throw new Error(`recipe ${recipe.id}: no "${s.target}" inside the component`);
          await h.fill(text ?? '', { timeout: RECIPE_STEP_TIMEOUT_MS });
        });
        break;
      }
      case 'blur': {
        // No target blurs the root itself; a blur target the recipe names but
        // the widget does not have is simply skipped.
        await withStepTarget(root, s.target, async (h) => {
          if (h) await h.evaluate((el: Element) => (el as HTMLElement).blur?.());
        });
        break;
      }
      case 'settle':
        // The recipe's `ms` was an estimate of how long the editor takes to
        // re-render; the re-render itself is observable, so wait for the DOM
        // to go quiet instead. A component that reacted already costs ~60ms
        // rather than the full estimate, and one that keeps re-rendering is
        // followed to its own end rather than cut off at a guess.
        await settleDom(page);
        break;
    }
  }
}

/** Normalise for containment checks: monaco renders spaces as NBSP, editors rewrap lines. */
function squashText(s: string): string {
  return s.replace(/ /g, ' ').replace(/\s+/g, ' ').trim();
}

/** Read the component's effective value through the recipe's verification read; null when it cannot be read. */
async function readComponentValue(root: ElementHandle, recipe: Pick<RecipeProcedure, 'verifyRead'>): Promise<string | null> {
  try {
    return await withStepTarget(root, recipe.verifyRead, async (node) => {
      if (!node) return null;
      return node.evaluate((el: Element) => {
        const anyEl = el as HTMLInputElement;
        if (typeof anyEl.value === 'string') return anyEl.value;
        return (el as HTMLElement).innerText ?? el.textContent ?? '';
      });
    });
  } catch {
    return null;
  }
}

/**
 * The honesty rule made structural: the recipe only succeeded if the
 * component's effective value re-observes the payload. A recipe that cannot
 * prove its effect reports failure and the caller falls back.
 *
 * A SET-VALUE recipe must replace, so it verifies only when the component
 * then holds exactly the payload (whitespace-squashed). Containment let a
 * recipe that appends pass: fwvk1's learned prosemirror recipe (click, then
 * insertText — no select-all) ran twice on one description, each run
 * "verified" because the doubled text contains the value, and every replay
 * saved "Bench task created for run fwvk1-n2Bench task created for run
 * fwvk1-n2". A select-option recipe keeps containment: the combobox shows
 * the chosen option among its own chrome.
 */
async function verifyRecipe(root: ElementHandle, recipe: Pick<RecipeProcedure, 'verifyRead'> & { intent?: RecipeIntent }, payload: string, intent: RecipeIntent | undefined = recipe.intent): Promise<boolean> {
  const value = await readComponentValue(root, recipe);
  if (value === null) return false;
  if (!payload) return true;
  if (intent === 'set-value') return squashText(value) === squashText(payload);
  return squashText(value).includes(squashText(payload));
}

/** One recipe run, verified or not, for the caller's lifecycle. */
interface RecipeAttempt {
  family: string;
  intent: RecipeIntent;
  recipe: RecipeProcedure;
  /** Verified: the component re-observed the payload. */
  ok: boolean;
  /** A step that could not run at all (the recipe threw); absent when every step ran and only verification failed. */
  error?: string;
  /** The book's `onAttempt` threw (e.g. the store write failed); present only then. The attempt's outcome stands regardless. */
  warning?: string;
}

/**
 * Where a runner's recipes come from. The daemon's book consults the
 * ComponentStore; the artifact's is `snapshotBook` over a compile-time
 * snapshot. Both answer the same two questions the daemon's `tryRecipe`
 * asked: is there any usable recipe for this intent at all (if not,
 * recognising the widget can only answer null and is skipped), and which
 * recipe serves this family.
 */
interface RecipeBook {
  /** Whether ANY usable recipe exists for the intent — the gate ahead of recognition. */
  offers(intent: RecipeIntent): boolean;
  /** The recipe for a recognized family, or null when the family has none usable. */
  choose(family: string, intent: RecipeIntent): RecipeProcedure | null;
  /** Every attempt, verified or not, so a runner with a lifecycle can fold it in. */
  onAttempt?(attempt: RecipeAttempt): void;
}

/**
 * The artifact's book: a serialisable snapshot of the recipe the store would
 * choose per (family, intent) at compile time — seeds and learned variants
 * alike, demoted ones omitted. `snapshotRecipes` in src/skills/components.ts
 * builds it and says what the store holds that a static snapshot cannot
 * express.
 */
interface RecipeSnapshot {
  version: 1;
  recipes: RecipeProcedure[];
}

function snapshotBook(snapshot: RecipeSnapshot): RecipeBook {
  return {
    offers: (intent) => snapshot.recipes.some((r) => r.intent === intent),
    choose: (family, intent) => snapshot.recipes.find((r) => r.family === family && r.intent === intent) ?? null,
  };
}

/**
 * Attempt an intent through the book's recipe for whatever component the
 * target sits inside. Returns null when nothing was attempted — no recipe for
 * the intent, no recognized component, or none for its family — so the caller
 * goes straight to the native primitive; otherwise the attempt, verified or
 * not, after reporting it to the book. Execute, then verify, then report —
 * the daemon's order; a thrown step is an unverified attempt with its reason.
 */
async function applyRecipe(page: Page, target: Locator, intent: RecipeIntent, payload: string, book: RecipeBook): Promise<RecipeAttempt | null> {
  if (!book.offers(intent)) return null;
  const rec = await recognizeComponent(page, target);
  if (!rec) return null;
  let recipe: RecipeProcedure | null;
  try {
    recipe = book.choose(rec.family.id, intent);
  } catch (err) {
    await rec.root.dispose().catch(() => {});
    throw err;
  }
  if (!recipe) {
    // nothing will be attempted: release the pinned root at once
    await rec.root.dispose().catch(() => {});
    return null;
  }
  let attempt: RecipeAttempt;
  try {
    await executeRecipe(page, rec.root, recipe, payload);
    attempt = { family: rec.family.id, intent, recipe, ok: await verifyRecipe(rec.root, recipe, payload, intent) };
  } catch (err) {
    attempt = { family: rec.family.id, intent, recipe, ok: false, error: err instanceof Error ? err.message : String(err) };
  } finally {
    await rec.root.dispose().catch(() => {});
  }
  try {
    book.onAttempt?.(attempt);
  } catch (err) {
    // Lifecycle bookkeeping (a store write the OS refused — EPERM/EBUSY on a
    // rename another session holds) must never change the action's outcome:
    // a verified recipe stays verified, and an unverified one still falls
    // back to the native primitive. The failure travels as a warning.
    attempt = { ...attempt, warning: `recipe outcome not recorded: ${err instanceof Error ? err.message : String(err)}` };
  }
  return attempt;
}

/** The words both runners report a verified recipe in. */
function describeRecipeAttempt(attempt: RecipeAttempt): string {
  const verb = attempt.intent === 'select-option' ? 'selected' : 'filled';
  const base = `${verb} via recipe ${attempt.family}/${attempt.intent} (${attempt.recipe.id}); value verified on the component`;
  return attempt.warning ? `${base} (warning: ${attempt.warning})` : base;
}

/**
 * The ladders. Each is the daemon's tool case verbatim: the recipe half
 * first, the native primitive only when nothing was verified. The verified
 * attempt is returned so the caller can say so; null means the native
 * primitive did the work.
 */
async function fillWithRecipe(page: Page, target: Locator, value: string, book: RecipeBook): Promise<RecipeAttempt | null> {
  const attempt = await applyRecipe(page, target, 'set-value', value, book);
  if (attempt?.ok) return attempt;
  await reactSafeFill(target, value);
  return null;
}

async function typeWithRecipe(
  page: Page,
  target: Locator,
  text: string,
  book: RecipeBook,
  opts: { timeout?: number; delay?: number } = {},
): Promise<RecipeAttempt | null> {
  const attempt = await applyRecipe(page, target, 'set-value', text, book);
  if (attempt?.ok) return attempt;
  await focusOrRefuse(target, opts.timeout);
  await target.pressSequentially(text, { ...opts, timeout: opts.timeout ?? DEFAULT_ACTION_TIMEOUT_MS });
  return null;
}

/**
 * Keys go to whatever holds focus, so a `type` whose target cannot take focus
 * types into some OTHER field. fwsi1 03-create step 4 typed into select2's
 * rendered <span> (not focusable): the recording's keys reached the
 * dropdown's search box, which an unrecorded failed fill had opened; every
 * replay's reached the asset name field, which still had focus, and appended
 * "Bench Laptop Model" to it before the step's own check stopped it. So the
 * target is focused and must then hold focus itself — or contain what does
 * (a wrapper whose inner input takes it, across open shadow roots), or be
 * inside the label of what does — before a key is sent. Otherwise the step
 * fails with nothing typed.
 */
async function focusOrRefuse(target: Locator, timeout?: number): Promise<void> {
  await target.focus({ timeout: timeout ?? DEFAULT_ACTION_TIMEOUT_MS });
  const holds = await target.evaluate(
    (el) => {
      let active: Element | null = document.activeElement;
      const label = el.closest('label')?.control ?? null;
      while (active) {
        if (active === el || el.contains(active) || active === label) return true;
        active = active.shadowRoot?.activeElement ?? null;
      }
      return false;
    },
    undefined,
    { timeout: timeout ?? DEFAULT_ACTION_TIMEOUT_MS },
  );
  if (!holds) {
    throw actionFailure(
      'not-dispatched',
      'not-an-input',
      'type: target cannot take keyboard focus — click it or type into the field it opens (nothing was typed)',
    );
  }
}

/** Select: the verified attempt, or the options the native select chose. */
async function selectWithRecipe(
  page: Page,
  target: Locator,
  label: string,
  book: RecipeBook,
  fallbackValue?: string,
): Promise<{ attempt: RecipeAttempt; selected: null } | { attempt: null; selected: string[] }> {
  const attempt = await applyRecipe(page, target, 'select-option', label, book);
  if (attempt?.ok) return { attempt, selected: null };
  return { attempt: null, selected: await reactSafeSelect(target, label, fallbackValue) };
}

// Shared execution source: fingerprint.ts. Regenerate to update.
/**
 * Structural page fingerprint: a fixed-size hashed bag of normalised DOM paths
 * (tags, roles, stable classes — no text, ids, or generated hashes). Two pages
 * built from the same template land close under cosine similarity; pages that
 * need a different procedure land far apart.
 *
 * Shared by both execution targets. The daemon's recorder captures it
 * (src/agent/loop.ts, src/agent/tools.ts), replay measures the live page
 * against it before a segment's soft url match (src/skills/replay.ts); a
 * compiled `.flow.ts` carries the recorded vector in its FLOW constant and
 * embeds this exact source (src/spec/runtime-source.ts) to take the same
 * measurement. Self-contained: a Playwright type is the only import, and the
 * page function below is serialised into the page, so nothing at module level
 * is in scope there.
 *
 * Shape: always FINGERPRINT_DIMS numbers, L2-normalised, each rounded to three
 * decimals at capture. `cosine` rounds its result to three decimals too, so a
 * vector carried verbatim (as the IR does) yields the very number the daemon
 * computes from the store's copy.
 */
const FINGERPRINT_DIMS = 512;

/** A page that has not answered in this long is navigating or hung: null, never a wait. */
const FINGERPRINT_CAPTURE_TIMEOUT_MS = 2_000;

/** L2-normalised vector of FINGERPRINT_DIMS, or null if the page could not be read in time. */
async function fingerprintPage(page: Page): Promise<number[] | null> {
  let timer: ReturnType<typeof setTimeout> | undefined;
  try {
    const counts = await Promise.race([
      page.evaluate(fingerprintPathsInPage, { maxNodes: 3_000, dims: FINGERPRINT_DIMS }),
      new Promise<null>((resolve) => {
        timer = setTimeout(() => resolve(null), FINGERPRINT_CAPTURE_TIMEOUT_MS);
      }),
    ]);
    if (!counts) return null;
    return normaliseFingerprint(counts);
  } catch {
    return null;
  } finally {
    clearTimeout(timer);
  }
}

/**
 * Cosine similarity of two normalised vectors, rounded to three decimals; null
 * when either is missing, empty, the lengths disagree, or either holds an
 * entry that is not a finite number (nothing comparable was measured). The
 * last rule matches the IR, which omits such a stored vector, so a hand-edited
 * store makes both runners pass null rather than only the daemon measuring.
 */
function cosine(a: number[] | undefined, b: number[] | undefined): number | null {
  if (!a || !b || a.length !== b.length || !a.length) return null;
  let dot = 0;
  for (let i = 0; i < a.length; i++) {
    const x = a[i];
    const y = b[i];
    if (typeof x !== 'number' || typeof y !== 'number' || !Number.isFinite(x) || !Number.isFinite(y)) return null;
    dot += x * y;
  }
  return Math.round(dot * 1000) / 1000;
}

/** Raw bucket counts to the stored form: L2-normalised, three decimals. */
function normaliseFingerprint(counts: number[]): number[] {
  let norm = 0;
  for (const c of counts) norm += c * c;
  norm = Math.sqrt(norm) || 1;
  return counts.map((c) => Math.round((c / norm) * 1000) / 1000);
}

/**
 * Runs in the page. Emits, for every element, the path of
 * `tag[.stableClass][@role]` segments from the nearest landmark down, hashed
 * (FNV-1a) into `dims` buckets. Everything volatile is dropped: text, ids,
 * classes that look generated, inline styles, scripts.
 */
function fingerprintPathsInPage(opts: { maxNodes: number; dims: number }): number[] {
  const counts = new Array<number>(opts.dims).fill(0);
  const fnv = (s: string): number => {
    let h = 0x811c9dc5;
    for (let i = 0; i < s.length; i++) {
      h ^= s.charCodeAt(i);
      h = Math.imul(h, 0x01000193) >>> 0;
    }
    return h;
  };
  // The hex run is shape.ts CLASS_HASH_HEX_RUN, inlined because this runs in
  // the page — six, not the id rule's eight, because a build hash in a class
  // name is six; see shape.ts for why the hex rules stay three.
  const stableClass = (c: string) =>
    c.length >= 3 && c.length <= 32 && !/\d{3,}|[0-9a-f]{6,}|^(css|sc|jss|emotion)-/i.test(c) && !/^_/.test(c);
  const segment = (el: Element): string => {
    let s = el.tagName.toLowerCase();
    const role = el.getAttribute('role');
    if (role) s += '@' + role.split(' ')[0];
    const type = el.getAttribute('type');
    if (type && s.startsWith('input')) s += ':' + type.toLowerCase();
    const classes = Array.from(el.classList).filter(stableClass).sort().slice(0, 2);
    if (classes.length) s += '.' + classes.join('.');
    return s;
  };
  const skip = new Set(['SCRIPT', 'STYLE', 'NOSCRIPT', 'TEMPLATE', 'SVG', 'PATH', 'BR']);
  const segs = new Map<Element, string>();
  const all = Array.from(document.querySelectorAll('body *')).slice(0, opts.maxNodes);
  for (const el of all) {
    if (skip.has(el.tagName) || el.closest('svg')) continue;
    const own = segment(el);
    const parent = el.parentElement;
    const parentPath = parent && segs.has(parent) ? segs.get(parent)! : parent ? segment(parent) : '';
    // Keep at most four ancestors: deeper paths are all noise from the same
    // widget, shallower ones lose the region the element sits in.
    const pathParts = parentPath ? parentPath.split('/').slice(-3) : [];
    pathParts.push(own);
    const p = pathParts.join('/');
    segs.set(el, p);
    counts[fnv(p) % opts.dims] += 1;
    // Parent-child bigram and the bare segment add robustness to reordering.
    counts[fnv('seg:' + own) % opts.dims] += 0.5;
  }
  return counts;
}

// Shared execution source: echo.ts. Regenerate to update.
/**
 * The ECHO rule both execution targets share: a read-back that returns only
 * what the procedure itself typed, selected or named confirms the control's
 * display, not that the app persisted anything. grafana's time picker read
 * back "Last 6 hours" after the replay had clicked the option of that name.
 *
 * The daemon (src/skills/replay.ts) keeps one ledger per flow step's chain —
 * the flow runner passes it through every segment (round 61; a lone replay
 * keeps its own) — and reports an echoed label in `ReplayResult.echoedValues`,
 * which the flow runner drops from its confident values. A compiled `.flow.ts`
 * embeds this exact source (spec/runtime-source.ts), keeps one ledger per flow
 * step across its segments, and lists the label in `run.echoed`. Both ask
 * judgeEcho: the element first, then the text (ELEMENT BEFORE TEXT, below). Neither runner withholds the value from a later
 * step: an echo is a report-confidence finding, not a gate.
 *
 * TEXT ALONE IS NOT PROVENANCE (round 59). The ledger holds text, and text
 * alone called EspoCRM fwec11 01-signin's "Admin" — the user menu's display
 * name for the signed-in user — an echo of the "admin" typed into the
 * Username field (echoKey folds case), in both runners, on both replays; the
 * form had been submitted and was gone. So a read whose text matches the
 * ledger is OBSERVED only when both hold, for every set the text came from
 * (echoAt):
 *  (a) its element is not the control that set was made on, nor part of that
 *      control's widget — judged by the control's LOCATOR as well as its node
 *      (a re-render replaces the input; the same field is still the field),
 *      an option by the combobox or opener that owns it, and a widget as the
 *      nearest field wrapper (a display span beside a combobox input, a chip);
 *  (b) something COMMITTED the value between the set and the read: a
 *      navigation or reload, a route change (routeOf: a rewritten query string
 *      is not one), the control detaching with nothing matching its locator
 *      in its place, or a later click whose effect, as THIS run's diff added
 *      it, shows the value appearing (a Save that adds the row). Phase B
 *      (provenance, stage 1): the recorded effect alone used to count, so a
 *      Save that did nothing still "committed" a live preview's text.
 * Anything else stays an echo, as before: grafana's picker opener after
 * "Last 6 hours", ghost fwgh13's Excerpt textbox, a live preview mirroring a
 * field that was never saved.
 *
 * Self-contained: sibling shared modules and Playwright types only.
 */

/** A read's resolved element (Locator.elementHandle), named without importing another Playwright type into the artifact. */
type ReadElement = NonNullable<Awaited<ReturnType<Locator['elementHandle']>>>;

/**
 * Shortest value the TEXT rule treats as an echo. Below this the coincidence
 * rate is too high (a "1m" refresh, a "3" quantity) — a false echo would
 * wrongly drop a legitimate finding — so a shorter value is an echo only on
 * ELEMENT evidence: the read is the very control that set it, or its widget.
 * Until phase B (provenance, stage 1) a short value was never an echo at all,
 * so "150" read back from the input it was typed into was reported as observed.
 */
const MIN_ECHO_LEN = 5;

/**
 * Tools that observe or position and SET nothing, so what they name is never
 * an interaction. A scroll to the heading "Latency by endpoint" set nothing,
 * but its target's name used to land in the ledger and the later read of that
 * heading was discounted as an echo — fwgr23 published two of three panel
 * titles on every replay and objective 1 failed each time.
 */
const OBSERVATION_TOOLS = new Set(['scroll_into_view', 'wait_for', 'hover', 'screenshot']);

/** Whether a step of this tool puts something on the page the ledger should remember. */
function setsSomething(tool: string): boolean {
  return tool !== 'read' && tool !== 'read_all' && !OBSERVATION_TOOLS.has(tool);
}

/** Loosely keyed, so "Last 6 hours" matches "last 6 hours" and "Last 6 hours." */
function echoKey(text: string): string {
  return text.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
}

/**
 * Remember what a step put on the page: its filled `value`/typed `text`, and
 * the accessible name (else label) of every candidate of a target it resolved
 * — the name of a clicked option ("Last 6 hours") is the value it selects.
 * Callers pass only steps for which `setsSomething(tool)` holds, and the
 * candidates only once the chain RESOLVED, as replay does.
 */
function noteInteraction(ledger: Set<string>, texts: readonly unknown[]): void {
  for (const text of texts) {
    // Every length: a short value is judged by its element (echoAt), not dropped here.
    const key = typeof text === 'string' ? echoKey(text) : '';
    if (key) ledger.add(key);
  }
}

/** Whether `value` is short enough that only element evidence makes it an echo (see MIN_ECHO_LEN). */
function shortEcho(value: string): boolean {
  return value.trim().length < MIN_ECHO_LEN;
}

/**
 * Where a url points, for the commit rule (echoAt's rule b): origin, path and
 * the hash's path — never the query string. A debounced search box rewrites
 * `?q=` as it is typed into; nothing was saved, and the value it mirrors is
 * still an echo (phase B provenance, stage 1). A route change — a save that
 * navigates, an editor that lands on its new record's `#/editor/post/<id>` —
 * still commits.
 */
function routeOf(url: string): string {
  const [beforeHash, hash = ''] = url.split('#', 2);
  return `${beforeHash.split('?')[0]}#${hash.split('?')[0]}`;
}

/** The name, else the label, of each candidate: what a resolved target is known by. */
function candidateNames(candidates: readonly { name?: unknown; label?: unknown }[]): unknown[] {
  return candidates.map((c) => c.name ?? c.label);
}

/**
 * The warning for a read whose value is an echo, or null when it is not one.
 * `where` is the caller's name for the step ("step 3" in the daemon,
 * "<stepId> <segmentId>/<n>" in the artifact); `label` is the read's own key.
 */
function echoVerdict(ledger: Set<string>, label: string, value: string, where: string): string | null {
  if (!value || !echoKey(value) || !ledger.has(echoKey(value))) return null;
  return `${where}: read '${label}' returned a value the skill itself set/selected ('${clip(value, 60)}') — confirms the control, not persistence; dropped from the report's confident values`;
}


/** One step that set something: what it set, where, and how to find its control again. */
interface EchoSet {
  seq: number;
  /** The runner's name for the step (daemon: its tag; artifact: segment/index). */
  step: string;
  /** echoKey of every text it put on the page (its fill, its candidates' names). */
  texts: Set<string>;
  /** Its resolved target, re-evaluated at the read: a re-rendered control is found again. */
  locator: Locator;
  /** The page url when it acted. */
  url: string;
  /**
   * Its entry in the page-side list (markActed), or -1 when the element could
   * not be marked — a detached element, a closed page, a page double with no
   * evaluate. An unmarked set has no element evidence, so a read it could be
   * the source of keeps the text rule: an echo (echoAt).
   */
  index: number;
  /**
   * The step put a VALUE into a control: a fill, a type, a select, a check —
   * or an option it picked into the control that owns it. A read of that
   * control is judged by the element before any text (echoByControl, round 61).
   */
  value: boolean;
}

/** A later click whose recorded effect ADDED these lines (noteCommit). */
interface EchoCommit {
  seq: number;
  step: string;
  lines: string[];
}

interface EchoMeta {
  id: string;
  seq: number;
  sets: EchoSet[];
  commits: EchoCommit[];
}

/** The per-ledger half the text Set cannot hold. */
const ECHO_META = new WeakMap<Set<string>, EchoMeta>();
let echoLedgers = 0;
function echoMeta(ledger: Set<string>): EchoMeta {
  let meta = ECHO_META.get(ledger);
  if (!meta) {
    echoLedgers += 1;
    meta = { id: `echo-${echoLedgers}-${Date.now().toString(36)}`, seq: 0, sets: [], commits: [] };
    ECHO_META.set(ledger, meta);
  }
  return meta;
}

/**
 * Record a step that sets something on the element `loc` resolved to, with
 * the texts it set — the element half of the ledger (see echoAt). The page
 * keeps the element and its CONTROL: the element itself, or, for an option in
 * a listbox or menu, the combobox that owns it (aria-controls / aria-owns),
 * else the element the segment acted on just before (the opener). Never throws.
 */
async function markActed(page: Page, loc: Locator, ledger: Set<string>, texts: readonly unknown[], step: string, tool = ''): Promise<void> {
  const meta = echoMeta(ledger);
  const keys = new Set(texts.filter((t): t is string => typeof t === 'string').map(echoKey).filter(Boolean));
  // Best-effort, never a reason for a step to fail: whatever throws here — a
  // detached element, a closed page, a locator double — leaves the set
  // unmarked (index -1), which echoAt reads as "no element evidence".
  const marked = await markInPage(loc, meta.id);
  // A page double's evaluate may answer anything: only a mark it returned counts.
  const index = marked && typeof marked.index === 'number' ? marked.index : -1;
  const option = marked?.option === true;
  const value = VALUE_TOOLS.has(tool) || option;
  let url = '';
  try {
    url = page.url();
  } catch {
    /* a page that cannot say where it is: the url rule decides nothing */
  }
  // Every acted element is marked in the page (an option's owner may be the
  // opener before it, whatever it set); only one that put text there can be
  // the source of a read, so only those are sets.
  // A step that put a value into a control is a set whatever its text: the
  // control is what a later read is judged by (echoByControl).
  if (!keys.size && !value) return;
  meta.seq += 1;
  meta.sets.push({ seq: meta.seq, step, texts: keys, locator: loc, url, index, value });
}

/** The tools that put a VALUE into the control they act on (EchoSet.value). */
const VALUE_TOOLS = new Set(['fill', 'type', 'select', 'check', 'uncheck', 'set_checked']);

/** The page-side mark (markActed): its index (-1 on any failure) and whether the element was an option picked into its owner. */
async function markInPage(loc: Locator, key: string): Promise<{ index: number; option: boolean }> {
  try {
    return await loc.first().evaluate(
      (el, key) => {
        const w = window as unknown as { __sitelooperActed?: Record<string, { el: Element; control: Element }[]> };
        const all = (w.__sitelooperActed ??= {});
        const list = (all[key] ??= []);
        let control: Element = el;
        const role = el.getAttribute('role') ?? '';
        const owner = el.closest('[role="listbox"], [role="menu"]');
        const option = Boolean(owner || role === 'option' || role.startsWith('menuitem'));
        if (option) {
          const id = owner?.id;
          const named = id ? document.querySelector(`[aria-controls~="${CSS.escape(id)}"], [aria-owns~="${CSS.escape(id)}"]`) : null;
          control = named ?? (list.length ? list[list.length - 1].control : el);
        }
        list.push({ el, control });
        return { index: list.length - 1, option };
      },
      key,
      { timeout: 1_000 },
    );
  } catch {
    return { index: -1, option: false };
  }
}

/**
 * A click (or press) whose effect added `lines` — the recorded lines THIS
 * run's diff added (expect.ts ChangeVerdict.inDiff), filled, noted after the
 * action ran: if one of them shows a value an earlier step set, the app took
 * the value and displayed it — a commit (echoAt's rule b). The step that set
 * the value is never its own commit.
 */
function noteCommit(ledger: Set<string>, lines: readonly string[], step: string): void {
  const meta = echoMeta(ledger);
  const kept = lines.filter((l) => typeof l === 'string' && l.trim());
  if (!kept.length) return;
  meta.seq += 1;
  meta.commits.push({ seq: meta.seq, step, lines: kept });
}

/**
 * Is a read that returned `value` from `read` an ECHO of what this segment set
 * — see the module comment for the two conditions an observation must meet.
 * A value the ledger's text does not hold is never an echo. A read with no
 * element (a url or title read), or a text no marked set accounts for, keeps
 * the text rule: an echo. Anything the page cannot answer is an echo too:
 * this only ever relaxes the rule on positive evidence.
 */
async function echoAt(page: Page, ledger: Set<string>, value: string, read: Locator | null): Promise<boolean> {
  if (!value) return false;
  const want = echoKey(value);
  if (!want || !ledger.has(want)) return false;
  // A short value has no text rule (MIN_ECHO_LEN): it is an echo only where
  // the element says so, and anything the page cannot answer leaves it observed.
  const short = shortEcho(value);
  // Past the text rule, anything that throws is no evidence: an echo.
  try {
    return await echoByElement(page, ledger, want, read, short);
  } catch {
    return !short;
  }
}

/** Where a set's control stands, seen from a read's element: see sourceState. */
interface SourceState {
  /** The page the set acted on was replaced (a navigation or reload): its marks are gone. */
  replaced: boolean;
  /** The control is gone, and nothing matching its locator stands in its place. */
  detached: boolean;
  /** The read IS the control, is inside its widget, or contains it. */
  isControl: boolean;
}

/**
 * The page-side half of the element rule, one set at a time: is the read's
 * element the set's control (or its widget), and is the control still the one
 * the set acted on. Null when the page cannot answer.
 */
async function sourceState(meta: EchoMeta, set: EchoSet, readEl: ReadElement): Promise<SourceState | null> {
  const current = await set.locator.first().elementHandle({ timeout: 250 }).catch(() => null);
  try {
    return await readEl
      .evaluate(
        (r, arg) => {
          const w = window as unknown as { __sitelooperActed?: Record<string, { el: Element; control: Element }[]> };
          const list = w.__sitelooperActed?.[arg.key];
          if (!list) return { replaced: true, detached: true, isControl: false };
          const mark = arg.index >= 0 ? list[arg.index] : undefined;
          let control: Element | null = null;
          if (mark && mark.control !== mark.el) control = mark.control.isConnected ? mark.control : null;
          else if (mark && mark.el.isConnected) control = mark.el;
          else control = (arg.current as Element | null) ?? null;
          if (!control) return { replaced: false, detached: true, isControl: false };
          // The control's widget: its nearest field wrapper — the closest
          // ancestor that holds anything beside it, while it holds no
          // other control.
          const CONTROLS =
            'input:not([type="hidden"]), select, textarea, [contenteditable=""], [contenteditable="true"], [role="combobox"], [role="textbox"], [role="searchbox"], [role="spinbutton"]';
          const controls = (a: Element) => a.querySelectorAll(CONTROLS).length + (a.matches(CONTROLS) ? 1 : 0);
          let widget: Element = control;
          for (let a = control.parentElement; a && a !== document.body && a !== document.documentElement; a = a.parentElement) {
            if (controls(a) > 1) break;
            widget = a;
            const beside = Array.from(a.childNodes).some((n) => n !== control && !n.contains(control) && (n.nodeType === 1 || (n.textContent ?? '').trim() !== ''));
            if (beside) break;
          }
          const isControl = widget === r || widget.contains(r as Node) || (r as Element).contains(control);
          return { replaced: false, detached: false, isControl };
        },
        { key: meta.id, index: set.index, current },
      )
      .catch(() => null);
  } finally {
    await current?.dispose().catch(() => {});
  }
}

/**
 * Did something COMMIT between `set` and now (the module comment's rule b):
 * the page replaced, the control gone, a route change (never a rewritten query
 * string), or a later click whose own diff showed one of `keys` — the read's
 * value, or (for the element rule, where the read's text may be the app's
 * reformatting) what the set itself put there.
 */
function committedSince(page: Page, meta: EchoMeta, set: EchoSet, seen: SourceState, keys: readonly string[]): boolean {
  let url = '';
  try {
    url = page.url();
  } catch {
    /* a page that cannot say where it is: the url rule decides nothing */
  }
  return (
    seen.replaced ||
    seen.detached ||
    (set.url !== '' && url !== '' && routeOf(url) !== routeOf(set.url)) ||
    meta.commits.some((c) => c.seq > set.seq && c.step !== set.step && c.lines.some((l) => keys.some((k) => k !== '' && ` ${echoKey(l)} `.includes(` ${k} `))))
  );
}

/**
 * echoAt past the text rule: true (an echo) unless both of the module
 * comment's conditions hold for every source. For a `short` value only
 * condition (a) speaks: a read of the control that set it, or of its widget,
 * is an echo; anything else, or no evidence, is not.
 */
async function echoByElement(page: Page, ledger: Set<string>, want: string, read: Locator | null, short = false): Promise<boolean> {
  const meta = ECHO_META.get(ledger);
  const sets = meta ? meta.sets.filter((s) => s.texts.has(want)) : [];
  if (!meta || !sets.length || !read) return !short;
  // A source that could not be marked keeps the text rule for itself.
  if (sets.some((s) => s.index < 0)) return !short;
  const readEl = await read.first().elementHandle({ timeout: 1_000 }).catch(() => null);
  if (!readEl) return !short;
  try {
    for (const set of sets) {
      const seen = await sourceState(meta, set, readEl);
      if (!seen) return !short;
      if (seen.isControl) return true;
      if (short) continue;
      if (!committedSince(page, meta, set, seen, [want])) return true;
    }
    return false;
  } finally {
    await readEl.dispose().catch(() => {});
  }
}

/*
 * ELEMENT BEFORE TEXT (round 61, EspoCRM fwec13 03-create). The text rule asks
 * first whether the read's text is one the step set, and only then looks at
 * the element. EspoCRM formats what it is given: the Amount input typed with
 * "12500" read back "12,500" and "12,500.00", and the Close Date input, after
 * its picker toggled, read "2018-01-16" — neither text is in the ledger, so
 * the element rule was never asked and all three went out as observed values,
 * on n2, n3 and the compiled script alike. A control shows what it was given,
 * however it renders it; that is not what the app stored.
 *
 * So a read whose element IS a control a step of this chain put a value into
 * (EchoSet.value), or that control's widget, with nothing committed since the
 * set, is an echo whatever its text says. The text rule still decides every
 * read elsewhere. The ledger spans the flow step's whole chain (both runners
 * keep one per step, not per segment), so a control an earlier segment filled
 * is judged too — and a Save plus a reopen (odoo fwod86 02-create) is still a
 * commit: the reopened page's marks are gone.
 */

/**
 * Is the read's element a control this chain put a value into, with nothing
 * committed since? False wherever the page cannot say: this rule only ever
 * withholds on positive element evidence.
 */
async function echoByControl(page: Page, ledger: Set<string>, value: string, read: Locator | null): Promise<boolean> {
  const meta = ECHO_META.get(ledger);
  const sets = meta ? meta.sets.filter((s) => s.value && s.index >= 0) : [];
  if (!meta || !sets.length || !read) return false;
  const readEl = await read.first().elementHandle({ timeout: 1_000 }).catch(() => null);
  if (!readEl) return false;
  try {
    const want = echoKey(value);
    for (const set of sets) {
      const seen = await sourceState(meta, set, readEl).catch(() => null);
      if (!seen?.isControl) continue;
      if (!committedSince(page, meta, set, seen, [want, ...set.texts])) return true;
    }
    return false;
  } catch {
    return false;
  } finally {
    await readEl.dispose().catch(() => {});
  }
}

/**
 * THE echo judgement both runners ask of a published read: the warning when it
 * is an echo, else null. The element first (echoByControl), then the text
 * rule (echoVerdict, echoAt) for a read anywhere else.
 */
async function judgeEcho(page: Page, ledger: Set<string>, label: string, value: string, read: Locator | null, where: string): Promise<string | null> {
  if (!value) return null;
  const byText = echoVerdict(ledger, label, value, where);
  if (await echoByControl(page, ledger, value, read)) {
    return (
      byText ??
      `${where}: read '${label}' returned '${clip(value, 60)}' from a control this step set, and nothing committed it since — it shows the control, however the app formats it, not what the app stored; dropped from the report's confident values`
    );
  }
  if (!byText) return null;
  return (await echoAt(page, ledger, value, read)) ? byText : null;
}

// Shared execution source: recover.ts. Regenerate to update.
/**
 * The two RECOVERY rungs both execution targets share: a navigation step whose
 * recorded affordance is gone reaching its recorded destination another way,
 * and a text wait that timed out on its resolved target while another recorded
 * candidate for that target already shows the text.
 *
 * Daemon replay (src/skills/replay.ts) calls these from runOneStep; a compiled
 * `.flow.ts` embeds this exact source (spec/runtime-source.ts) and calls them
 * from the same places in its step bodies. Each runner supplies only how it
 * clicks and navigates (its own tool layer, or the artifact's `click` adapter).
 * Self-contained: sibling shared modules and Playwright types only.
 */

/** Tools whose miss can be substituted by navigating to the step's recorded destination: plain navigation clicks. */
const NAV_FALLBACK_TOOLS = new Set(['click', 'dblclick']);

/**
 * Whether a step whose target resolved nothing may fall back to its recorded
 * destination: a plain navigation click, with a recorded url expectation the
 * browser is not already on, outside a loop body (a loop re-acts per record;
 * navigating away from the collection is never that).
 */
function mayNavigateToDestination(tool: string, destPattern: string | undefined, liveUrl: string, params: Record<string, string>, inLoopBody: boolean): destPattern is string {
  return Boolean(destPattern) && NAV_FALLBACK_TOOLS.has(tool) && !inLoopBody && !urlMatches(destPattern!, liveUrl, params);
}

/**
 * How a runner acts during recovery: its own click on a locator, its own
 * navigation. A click that fails throws as the runner's click throws, with its
 * outcome on the error (browser.ts `actionFailure`): that is what decides
 * whether the direct navigation may follow it.
 */
interface RecoveryHooks {
  /** `selector` is the css the locator was built from, for a runner that records what it clicked. */
  click(locator: Locator, selector: string): Promise<unknown>;
  goto(url: string): Promise<unknown>;
}

/**
 * The rungs a navigation step falls through when its recorded link is gone,
 * each testing how the app works for a HUMAN before the next is tried:
 *  (a) another link on the page to the same destination — click that,
 *      exercising the app's own navigation;
 *  (b) only then, and only when the destination is fully concrete
 *      (params/derived filled, nothing volatile left), navigate there
 *      directly — the last resort before recovery (the daemon's model, the
 *      artifact's stop).
 * Returns what got the browser there, or null when neither rung did — or,
 * when the rung (a) click failed without proof that nothing went out,
 * `unknown`: the click may have landed, so the direct navigation is NOT
 * tried after it (a second commit of whatever that link does), and the caller
 * stops with the note.
 */
async function navigateToDestination(
  page: Page,
  destPattern: string,
  params: Record<string, string>,
  hooks: RecoveryHooks,
): Promise<{ used: string; note: string } | { unknown: true; note: string } | null> {
  // (a) Requires the matching anchors to agree on ONE destination —
  // ambiguity (a wildcard pattern matching many records) skips the rung.
  const link = await linkToDestination(page, destPattern, params);
  if (link) {
    try {
      await hooks.click(page.locator(link.selector).first(), link.selector);
      await settleDom(page);
      if (urlMatches(destPattern, page.url(), params)) {
        return { used: `click ${link.selector}`, note: `clicked another link to the recorded destination (${link.selector})` };
      }
    } catch (err) {
      // A click proven not to have gone out: that link did not work either —
      // try the direct navigation. Anything else may have landed.
      const outcome = outcomeOfError(err);
      if (outcome !== 'not-dispatched') {
        const message = (err instanceof Error ? err.message : String(err)).split('\n')[0].slice(0, 160);
        return {
          unknown: true,
          note: `clicked another link to the recorded destination (${link.selector}), but whether that click took effect is unknown (${message}) — not navigating there directly, which could repeat it ${outcomeLabel(outcome)}`,
        };
      }
    }
  }
  // (b)
  const dest = fillParams(destPattern, params);
  const concrete = dest && !dest.includes('{{') && !/[/=#](:id|:var)(?=[/&#]|$)/.test(dest);
  if (concrete && !urlMatches(destPattern, page.url(), params)) {
    try {
      await hooks.goto(dest);
      if (urlMatches(destPattern, page.url(), params)) {
        return { used: `goto ${dest}`, note: `navigated to the step's recorded destination instead (${dest})` };
      }
    } catch {
      // destination unreachable — the caller reports the original miss
    }
  }
  return null;
}

/**
 * A visible anchor on the page whose destination matches the recorded
 * pattern. Used by the navigation fallback's first rung: when the recorded
 * link is gone, another route to the same place may exist (a sidebar entry, a
 * search result, a breadcrumb). Returns null unless every matching anchor
 * agrees on ONE destination — a wildcard-heavy pattern matching several
 * records is ambiguity, not evidence.
 */
async function linkToDestination(
  page: Page,
  pattern: string,
  params: Record<string, string>,
): Promise<{ selector: string; href: string } | null> {
  let anchors: { attr: string; abs: string }[];
  try {
    const raw = await page.evaluate(() =>
      Array.from(document.querySelectorAll('a[href]'))
        .filter((a) => (a as HTMLElement).offsetParent !== null)
        .map((a) => ({ attr: a.getAttribute('href') ?? '', abs: (a as HTMLAnchorElement).href })),
    );
    anchors = Array.isArray(raw) ? raw : [];
  } catch {
    return null;
  }
  const hits = anchors.filter((a) => a.abs && urlMatches(pattern, a.abs, params));
  if (!hits.length || new Set(hits.map((h) => h.abs)).size !== 1) return null;
  return { selector: `a[href="${hits[0].attr.replace(/(["\\])/g, '\\$1')}"]`, href: hits[0].abs };
}

/** How long the fallback candidates are given to report their text, each. */
const HELD_TEXT_READ_MS = 1_000;

/**
 * For a text wait that timed out: another recorded candidate for its target
 * that shows the text right now, if there is one. Candidates are tried in
 * STORED order after the primary (stored index 0 is never asked — it is what
 * the wait already judged, or what missed); a point is skipped (it names a
 * place, not an element with text), and a candidate must still match exactly
 * one element. The wait already gave the page its full timeout to paint.
 *
 * fwrd43's create step waited for the new ticket's title in `label "Tickets"
 * >> nth=1`, which on replay was an empty element, while the chain's own next
 * candidate — the tickets section — already showed it.
 */
async function textHeldElsewhere(
  candidates: readonly { index: number; kind: string; locator: Locator }[],
  state: unknown,
  text: unknown,
): Promise<{ index: number; locator: Locator } | null> {
  if (typeof text !== 'string' || !text.trim()) return null;
  if (state !== 'text_contains' && state !== 'text_equals') return null;
  const ordered = [...candidates].filter((c) => c.index >= 1).sort((a, b) => a.index - b.index);
  for (const candidate of ordered) {
    if (candidate.kind === 'point') continue;
    try {
      if ((await candidate.locator.count()) !== 1) continue;
      // Rendered text, compared as the wait itself compares it (text.ts
      // textHolds): textContent missed "OVERVIEW" under text-transform (fwop10).
      const shown = await candidate.locator.innerText({ timeout: HELD_TEXT_READ_MS });
      if (textHolds(shown, state, text)) return { index: candidate.index, locator: candidate.locator };
    } catch {
      continue;
    }
  }
  return null;
}

// Shared execution source: refill.ts. Regenerate to update.
/**
 * STANDING FILLS, the rule both execution targets share: the values a
 * procedure filled must still be in their inputs when the action that submits
 * them goes.
 *
 * A fill is checked once, when it is typed — its own effect gate sees the
 * textbox show the value. Nothing looked again before the click that submits
 * it, and a page may rebuild its form in between. fwvk1 n3 01-open: both of
 * s_9f7dc9's login fills passed their checks, then the app, still starting up,
 * reloaded /login (its service worker took control of the page) and the Login
 * click submitted an empty form — "expected url http://127.0.0.1:8096/ but
 * browser is at http://127.0.0.1:8096/login", 4 recovery turns, which found
 * the fills had not landed.
 *
 * So each runner keeps a ledger per replayed segment (the daemon per
 * replaySkill, the artifact per emitted segment): a fill that ran is noted
 * with the page url it ran on, and before a click, a double click or a key
 * press — the actions that submit what was filled — every noted input on that
 * same url that is EMPTY again is filled once more. Then the action goes, and
 * its own gates judge it. The ledger is emptied by that action, and by any
 * other action that sets something (a select, a check, a navigation): those
 * may legitimately change other fields, and a field the app emptied after
 * them is the app's doing, not a lost fill.
 *
 * Deliberately narrow. Only a plain input or textarea is asked (a recipe-driven
 * editor has no value to compare); only an input that is now empty is refilled
 * — a value the app rewrote (a formatted phone number, an autocompleted name)
 * is the app's, never overwritten; only on the url the fill ran on; only once
 * per action; and a locator that no longer names exactly one element is left
 * alone. The values are never reported — a login's password is one of them.
 *
 * A REPLACED DOCUMENT (fwvk2 n2 01-open, the same login, still failing). The
 * reload is a new document at the SAME url, so the url alone cannot see it,
 * and a check made while the new document is still building its form found no
 * field (a locator naming nothing is "leave alone") and refilled nothing. So
 * each fill is noted with the identity of the document it ran in
 * (`performance.timeOrigin`). A fill whose document is gone was certainly
 * lost: the check waits (STANDING_FILL_ATTACH_MS, shared by the whole step)
 * for its field to be built again, then refills it if empty.
 *
 * And the reload can land AFTER the check — between the submit and the app's
 * answer to it, so the answer never arrives. The submit's own gates then stop
 * it on the page it started from. `standingFillsLost` says when that is this
 * failure and nothing else: the document the submit ran in was replaced, the
 * page is back on the url the fills ran on, and every field they filled is
 * there and EMPTY. Then — once per submit — the runner puts the fills back in
 * the ledger (`rearmStandingFills`) and runs the submit again, whose own check
 * refills them. A submit that went through leaves a page that fails at least
 * one of those three, and is never repeated.
 *
 * A VALUE DROPPED AT BLUR (fwec2 n1 03-create). A formatted-number widget
 * (the Amount box) keeps its own copy of the value, built from key events:
 * the native setter showed `textbox: 12500`, the fill's check passed, and the
 * widget rebuilt the field from its own, still-empty copy the moment focus
 * left it — the next fill wiped it, three times. Typed key by key it held
 * ("12,500.00"). So the submit check first takes focus off the field that
 * has it (what the submit does anyway, never on a field that drives a popup,
 * whose suggestions it would close), then refills an empty field natively,
 * blurs it, and when the value is gone again types it key by key instead.
 * A plain input keeps a native fill and is never typed into.
 *
 * A window after page load ("not settled until N ms without a same-url
 * reload") was considered and rejected: on the real app the service worker's
 * reload came anywhere from 2.5s to 7s after load, so no bound both catches it
 * and costs every other page nothing.
 *
 * Self-contained: sibling shared modules and Playwright types only.
 */

/** One fill this segment made, as the ledger remembers it. */
interface StandingFill {
  locator: Locator;
  /**
   * What the field was given — or, for a value that must not be reused (a
   * {{totp:NAME}} one-time code), how to produce it again: a refill types the
   * code current at the REFILL, never the one that went stale in the ledger.
   */
  value: string | (() => Promise<string>);
  /** The page url the fill ran on: a refill is only ever asked on the same one. */
  url: string;
  /** The document it ran in (`performance.timeOrigin`); null when it could not be read. */
  doc: number | null;
}

/** The ledger: the fills standing now, and what the last submit took with it. */
interface StandingFills {
  fills: StandingFill[];
  /** The fills the last submitting action consumed, with the document and url it went out from. */
  submitted?: { fills: StandingFill[]; doc: number | null; url: string };
}

function standingFills(): StandingFills {
  return { fills: [] };
}

/** What part a step of this tool plays for the ledger. */
type StandingFillRole = 'fill' | 'submit' | 'retire' | 'none';

const SUBMIT_TOOLS = new Set(['click', 'dblclick', 'press']);
/** Actions that may legitimately change other fields, or leave the page: they empty the ledger without asking it. */
const RETIRE_TOOLS = new Set(['right_click', 'modifier_click', 'select', 'check', 'drag', 'upload', 'goto', 'back', 'tabs']);

function standingFillRole(tool: string): StandingFillRole {
  if (tool === 'fill') return 'fill';
  if (SUBMIT_TOOLS.has(tool)) return 'submit';
  if (RETIRE_TOOLS.has(tool)) return 'retire';
  return 'none';
}

/** How long one ledger entry may take to answer before it is left alone. */
const STANDING_FILL_PROBE_MS = 1_000;
/** How long, in all, one step waits for the fields of a replaced document to be built again. */
const STANDING_FILL_ATTACH_MS = 3_000;

/** The identity of the page's current document; null when it cannot be read (a navigation that will not settle). */
async function documentOf(page: Page): Promise<number | null> {
  for (let attempt = 0; attempt < 2; attempt++) {
    try {
      return await page.evaluate(() => performance.timeOrigin);
    } catch {
      // the context went with a navigation: ask the document that replaced it
      await page.waitForLoadState('domcontentloaded', { timeout: STANDING_FILL_ATTACH_MS }).catch(() => {});
    }
  }
  return null;
}

/** Note a fill that ran: its locator, its value, and the url and document it ran in. An empty fill is a clear — nothing to keep. */
async function noteFill(ledger: StandingFills, locator: Locator, value: string | (() => Promise<string>), page: Page): Promise<void> {
  if (!value) return;
  const key = String(locator);
  const at = ledger.fills.findIndex((f) => String(f.locator) === key);
  if (at >= 0) ledger.fills.splice(at, 1);
  ledger.fills.push({ locator, value, url: page.url(), doc: await documentOf(page) });
}

/** The value a plain input or textarea holds now; null when the locator does not name exactly one, or it is not one. */
async function inputValueNow(locator: Locator): Promise<string | null> {
  try {
    if ((await locator.count()) !== 1) return null;
    return await locator.evaluate(
      (el) => (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA' ? (el as HTMLInputElement).value : null),
      undefined,
      { timeout: STANDING_FILL_PROBE_MS },
    );
  } catch {
    return null;
  }
}

/** inputValueNow, after waiting (to `deadline`) for the field to be attached — a replaced document builds its form anew. */
async function inputValueOnceBuilt(locator: Locator, deadline: number): Promise<string | null> {
  try {
    await locator.waitFor({ state: 'attached', timeout: Math.max(1, deadline - Date.now()) });
  } catch {
    return null;
  }
  return inputValueNow(locator);
}

/**
 * Take focus off the field if it has it — what the coming submit does anyway,
 * done first so a value the field drops at its blur is seen before the submit
 * sends it. Never a field that drives a popup (a combobox, an autocomplete, a
 * datalist, anything expanded): its blur closes the suggestions the submit may
 * be about to click. True when it blurred.
 */
async function blurIfPlain(locator: Locator): Promise<boolean> {
  try {
    if ((await locator.count()) !== 1) return false;
    const blurred = await locator.evaluate(
      (el) => {
        if (document.activeElement !== el) return false;
        const popup =
          el.getAttribute('role') === 'combobox' ||
          el.hasAttribute('aria-autocomplete') ||
          el.getAttribute('aria-expanded') === 'true' ||
          el.hasAttribute('list') ||
          el.closest('[role="combobox"]') !== null;
        if (popup) return false;
        (el as HTMLElement).blur();
        return true;
      },
      undefined,
      { timeout: STANDING_FILL_PROBE_MS },
    );
    if (blurred) await settleDom(locator.page());
    return blurred;
  } catch {
    return false;
  }
}

/** Clear the field and type the value key by key, as a person would: the one input a key-driven widget reads. */
async function typeInto(locator: Locator, value: string): Promise<void> {
  await locator.click({ timeout: STANDING_FILL_PROBE_MS * 5 });
  await locator.page().keyboard.press('ControlOrMeta+a');
  await locator.page().keyboard.press('Backspace');
  await locator.pressSequentially(value, { delay: 20, timeout: DEFAULT_ACTION_TIMEOUT_MS });
}

/**
 * Whether what the field holds is the value filled, as the page may format it:
 * the same text, or containing it (letters and digits only, case aside), or
 * the same number in the page's own formatting ("12500" shown "12,500.00").
 */
function sameValue(held: string, filled: string): boolean {
  if (held === filled) return true;
  const alnum = (t: string) => t.toLowerCase().replace(/[^\p{L}\p{N}]+/gu, '');
  if (alnum(filled) && alnum(held).includes(alnum(filled))) return true;
  const digits = (t: string) => t.replace(/\D+/g, '');
  const dh = digits(held);
  const df = digits(filled);
  return Boolean(df) && dh.startsWith(df) && /^0*$/.test(dh.slice(df.length));
}

const replaced = (fill: StandingFill, doc: number | null) => fill.doc !== null && doc !== null && fill.doc !== doc;

/**
 * Ahead of a step of `tool`: for a submitting action, refill every input the
 * ledger holds on this url that is empty again — waiting first for the fields
 * of a document that replaced the one the fill ran in — and remember what the
 * submit takes with it; then, for a submitting or a retiring action, empty
 * the ledger. Returns one warning per step that refilled anything (never the
 * values), for the runner to report.
 */
async function restoreStandingFills(page: Page, ledger: StandingFills, tool: string, where: string): Promise<string[]> {
  const role = standingFillRole(tool);
  if (role !== 'submit' && role !== 'retire') return [];
  const standing = ledger.fills.splice(0);
  ledger.submitted = undefined;
  if (role !== 'submit' || !standing.length) return [];
  const url = page.url();
  let doc = await documentOf(page);
  const deadline = Date.now() + STANDING_FILL_ATTACH_MS;
  let refilled = 0;
  let failed = 0;
  let reloaded = false;
  let keyed = 0;
  // A RELOAD INSIDE THE CHECK (round 62, vikunja fwvk13 01-signin): the page
  // replaced its document after the check had read the fields and before the
  // submit, which went out on the new, empty form with nothing refilled — and
  // the record of the submit named that new document, so no lost submit was
  // seen either. The check ends by asking which document it is in; a new one
  // on the same url is checked again (its fields waited for and refilled as
  // any replaced document's), once.
  for (let pass = 0; pass < 2; pass++) {
    // The submit is about to take focus off the field that has it; take it off
    // first, so a widget that rebuilds its value on blur (fwec2) has done so
    // before the fields are looked at.
    for (const fill of standing) if (fill.url === url) await blurIfPlain(fill.locator);
    for (const fill of standing) {
      if (fill.url !== url) continue;
      const gone = replaced(fill, doc);
      reloaded ||= gone;
      const now = gone ? await inputValueOnceBuilt(fill.locator, deadline) : await inputValueNow(fill.locator);
      if (now !== '') continue;
      try {
        const value = typeof fill.value === 'function' ? await fill.value() : fill.value;
        await reactSafeFill(fill.locator, value);
        await blurIfPlain(fill.locator);
        let held = await inputValueNow(fill.locator);
        // Set, and gone again at the blur: a widget that keeps its own copy of
        // the value, built from key events. Typed, as a person would.
        if (!held) {
          await typeInto(fill.locator, value);
          await blurIfPlain(fill.locator);
          held = await inputValueNow(fill.locator);
          if (held) keyed++;
        }
        if (held !== null && sameValue(held, value)) refilled++;
        else failed++;
      } catch {
        failed++;
      }
    }
    const after = await documentOf(page);
    const again = pass === 0 && after !== null && doc !== null && after !== doc && page.url() === url;
    doc = after;
    if (!again) break;
  }
  ledger.submitted = { fills: standing, doc, url: page.url() };
  if (!refilled && !failed) return [];
  const why = reloaded ? 'the page replaced its document after the fills ran' : 'the page rebuilt its form, or dropped the value when the field lost focus, after the fills were checked';
  const what = `${refilled + failed} field(s) this procedure filled were empty again before this ${tool} (${why})${keyed ? `; ${keyed} of them kept only a value typed key by key` : ''}`;
  return [`${where}: ${what} — ${failed ? `${refilled} refilled, ${failed} could not be` : 'refilled once'}`];
}

/**
 * After a submitting action whose step failed: was the submit lost to a
 * replaced document? True only when the document it went out from is gone,
 * the page is on the url the fills ran on, and every field they filled is
 * there again (waited for) and empty. The runner then rearms the ledger and
 * runs the step once more.
 */
async function standingFillsLost(page: Page, ledger: StandingFills): Promise<boolean> {
  const sent = ledger.submitted;
  if (!sent?.fills.length || sent.doc === null) return false;
  if (page.url() !== sent.url) return false;
  const doc = await documentOf(page);
  if (doc === null || doc === sent.doc) return false;
  if (page.url() !== sent.url) return false;
  const deadline = Date.now() + STANDING_FILL_ATTACH_MS;
  for (const fill of sent.fills) {
    if (fill.url !== sent.url) return false;
    if ((await inputValueOnceBuilt(fill.locator, deadline)) !== '') return false;
  }
  return true;
}

/** Put the lost submit's fills back as standing, so the repeated step's own check refills them. Once: the record of the submit is consumed. */
function rearmStandingFills(ledger: StandingFills): void {
  if (!ledger.submitted) return;
  ledger.fills = ledger.submitted.fills;
  ledger.submitted = undefined;
}

/**
 * A FILL LOST TO A REPLACED DOCUMENT (round 56, vikunja fwvk8 01-open). The
 * ledger above protects a submit; a fill's own check is asked earlier. On
 * fwvk8's login the page replaced its document after the username fill
 * dispatched and before that fill's echo check looked, so the check found
 * the rebuilt field empty ("did not show textbox …: admin") and the step
 * stopped, one step before the submit's refill would have put it back.
 *
 * After a fill whose own verification failed: true only when the document
 * it ran in (`before`, read ahead of the dispatch) is gone and the page is
 * still on the url it ran on — a reload, not a navigation. The runner then
 * runs the fill once more, whose resolution waits for the field to be built
 * again and whose check judges it anew. A fill whose value simply did not
 * take on an unchanged document is never repeated: its check's stop stands.
 */
async function fillLost(page: Page, before: number | null, url: string): Promise<boolean> {
  if (before === null || page.url() !== url) return false;
  const doc = await documentOf(page);
  return doc !== null && doc !== before && page.url() === url;
}

/**
 * A VALUE TYPED ONTO ITS OWN RESTORED COPY (round 57, espocrm fwec10). n1
 * filled Amount "12500", choosing the account then emptied the field, and the
 * model typed the amount again — so s_7d6b2f fills it at step 2 AND types it
 * at step 18. On replay the standing-fill check refilled the emptied field
 * before the next click, and step 18's `type` (keys, which never clear)
 * APPENDED: the app saved 1,250,012,500, both replays and the compiled run
 * reported success, and only the external verifier saw it.
 *
 * guardedTyping wraps a recorded `type` or `fill`, the same in both runners:
 *  - ahead of a `type`, the field is cleared when it already holds the value
 *    about to be typed (sameValue: keys typed onto their own value can only
 *    double it), or when this segment filled that very element (the ledger,
 *    standing or taken by the last submit — the recording typed the whole
 *    value into what the app had left empty);
 *  - after either, the field's resulting value is judged (valueDoubled): a
 *    field holding the given value twice over is stopped, never saved.
 * Only a plain input or textarea is asked, and a value carrying a `{{…}}`
 * marker (a secret, a one-time code) is never compared: the runners hold it
 * in different forms. `warn` is told when a field was cleared.
 */
async function guardedTyping<T>(
  ledger: StandingFills | null,
  locator: Locator,
  value: string,
  tool: string,
  warn: (warning: string) => void,
  dispatch: () => Promise<T>,
  opts: { doubledAsRecorded?: boolean } = {},
): Promise<T> {
  const comparable = value !== '' && !value.includes('{{');
  if (tool === 'type' && comparable) {
    const held = await inputValueNow(locator);
    if (held) {
      const own = sameValue(held, value);
      const filledHere = !own && ledger !== null && (await filledBy(ledger, locator));
      if (own || filledHere) {
        await locator.fill('', { timeout: DEFAULT_ACTION_TIMEOUT_MS });
        warn(
          own
            ? 'the field already held the value this type enters (restored after the recording saw it emptied), so it was cleared first rather than typed onto'
            : 'this procedure filled the field earlier, so it was cleared before typing, as the recording typed into it empty',
        );
      }
    }
  }
  const result = await dispatch();
  if (comparable && (tool === 'type' || tool === 'fill')) {
    const doubled = await valueDoubled(locator, value);
    // The recording's own field held it twice over after this very step
    // (SkillStep.doubledAsRecorded, grafana fwgr73 04-open): this is the
    // state the recording produced and went on from, not a stale copy typed
    // onto. Said, never silent.
    if (doubled && opts.doubledAsRecorded) warn(`${doubled.replace(/ — it was typed onto a copy already there, and is not saved$/, '')} — as the recording's own field did after this step, so it is not stopped`);
    else if (doubled) throw new Error(doubled);
  }
  return result;
}

/** Whether a fill this segment made (standing, or taken by the last submit) was of this very element. */
async function filledBy(ledger: StandingFills, locator: Locator): Promise<boolean> {
  const fills = [...ledger.fills, ...(ledger.submitted?.fills ?? [])];
  for (const fill of fills) {
    try {
      if ((await fill.locator.count()) !== 1) continue;
      const other = await fill.locator.elementHandle({ timeout: STANDING_FILL_PROBE_MS });
      if (!other) continue;
      const same = await locator.evaluate((el, o) => el === o, other, { timeout: STANDING_FILL_PROBE_MS });
      await other.dispose();
      if (same) return true;
    } catch {
      // a fill whose field is gone is no evidence either way
    }
  }
  return false;
}

/** Whether `held` carries the letters and digits of `value` twice over, where `value` holds them once. */
function heldTwice(held: string, value: string): boolean {
  const alnum = (t: string) => t.toLowerCase().replace(/[^\p{L}\p{N}]+/gu, '');
  const want = alnum(value);
  if (!want) return false;
  const text = alnum(held);
  let n = 0;
  for (let at = text.indexOf(want); at >= 0; at = text.indexOf(want, at + want.length)) n++;
  return n >= 2;
}

/**
 * Did the RECORDING's own field hold the value it was given twice over,
 * right after the step? Asked by compile over the step's raw recorded
 * additions (before any masking), of the line naming the step's own target —
 * the same role and name as a `role` rung, or a `label` rung's label — and
 * never of a value carrying a `{{…}}` marker. grafana fwgr73-n1 04-open line
 * 125: `- textbox "Editor content;…": "tags""tags""` after typing `"tags"`.
 * fwec10's recording saw its amount once, so its step is not flagged and its
 * replay still stops. Sets SkillStep.doubledAsRecorded.
 */
function recordedDoubled(
  added: readonly string[],
  chain: readonly unknown[],
  value: string,
): boolean {
  if (!value || value.includes('{{')) return false;
  const names: { role: string | null; name: string }[] = [];
  for (const rung of chain as { kind?: string; role?: string; name?: string; label?: string }[]) {
    if (rung.kind === 'role' && rung.role && rung.name) names.push({ role: rung.role, name: rung.name });
    else if (rung.kind === 'label' && rung.label) names.push({ role: null, name: rung.label });
  }
  if (!names.length) return false;
  for (const line of added) {
    const m = /^-?\s*([A-Za-z][\w-]*)\s+"((?:[^"\\]|\\.)*)"(?:\s+\[[^\]]*\])*:\s?(.*)$/.exec(line.trim());
    if (!m) continue;
    const [, role, rawName, held] = m;
    const name = rawName.replace(/\\(.)/g, '$1');
    if (!names.some((n) => n.name === name && (n.role === null || n.role === role))) continue;
    if (heldTwice(held, value)) return true;
  }
  return false;
}

/**
 * The stop for a field that holds the value it was given TWICE over: the
 * value's letters and digits occur twice in what the field shows, where the
 * value itself holds them once ("1,250,012,500" for "12500"). Null when the
 * field is not a plain input or textarea, is a password field, or holds the
 * value once, in whatever formatting the page gives it.
 */
async function valueDoubled(locator: Locator, value: string): Promise<string | null> {
  if (!value.toLowerCase().replace(/[^\p{L}\p{N}]+/gu, '')) return null;
  let held: string | null;
  try {
    if ((await locator.count()) !== 1) return null;
    held = await locator.evaluate(
      (el) => (el.tagName === 'TEXTAREA' || (el.tagName === 'INPUT' && (el as HTMLInputElement).type !== 'password') ? (el as HTMLInputElement).value : null),
      undefined,
      { timeout: STANDING_FILL_PROBE_MS },
    );
  } catch {
    return null;
  }
  if (!held || !heldTwice(held, value)) return null;
  const show = (t: string) => (t.length > 40 ? `${t.slice(0, 40)}…` : t);
  return `the field holds the value it was given twice over (${JSON.stringify(show(held))} for ${JSON.stringify(show(value))}) — it was typed onto a copy already there, and is not saved`;
}

// Shared execution source: positional.ts. Regenerate to update.
/**
 * RULE R2 (round 61, grafana fwgr73 05-open step 3): what both runners do
 * with a CLICK whose identifying rungs all missed, before dispatching it.
 * 04-open's model recovery had left the dashboard in edit mode, so s_c49ccb's
 * Edit click found no Edit button: its testid and role rung missed, and the
 * positional `…div:nth-of-type(5) > button` took the step onto another
 * toolbar button — none of the recorded additions appeared, and the step fell
 * to the model. Two halves, one verdict (positionalClickVerdict):
 *  (a) everything the click was recorded adding already shows: the state it
 *      produces is in place — skipped, and said (alreadyAddedLines says which
 *      clicks may be: never one that submits the segment's work);
 *  (b) otherwise a positional rung is accepted only when the element it found
 *      carries the recorded accessible name — never a different button.
 *
 * Self-contained: sibling shared modules and Playwright types only.
 */

/** How long a name probe of a resolved element may take. */
const POSITIONAL_PROBE_MS = 2_000;

/**
 * The accessible name a recorded chain gave its element, for a positional
 * fallback to be held to (positionalHitNamed): the first `role` rung's role
 * and name, else a `label` rung's label, else a `text` rung's text; null when
 * the chain names nothing. The name may carry `{{…}}` markers: the verdict
 * fills them with this run's params, and one it cannot fill vouches for
 * nothing (positionalClickVerdict).
 */
function recordedAccessibleName(
  chain: readonly unknown[],
): { by: 'role' | 'label' | 'text'; role?: string; name: string } | null {
  const rungs = chain as { kind?: string; role?: string; name?: string; label?: string; text?: string }[];
  const role = rungs.find((c) => c.kind === 'role' && c.role && c.name);
  const label = rungs.find((c) => c.kind === 'label' && c.label);
  const text = rungs.find((c) => c.kind === 'text' && c.text);
  const want = role
    ? { by: 'role' as const, role: role.role!, name: role.name! }
    : label
      ? { by: 'label' as const, name: label.label! }
      : text
        ? { by: 'text' as const, name: text.text! }
        : null;
  return want;
}

/**
 * Whether a resolution reached its element by POSITION ALONE: the chain has
 * identifying rungs (anything not structural, never a snapshot ref, which is
 * never tried), and every one of them missed; `hit` null means nothing at all
 * resolved. A chain with no identifying rung was always positional, and is
 * not what this asks about. `identifying` is the stored-chain indices of the
 * identifying rungs; `missed` the indices the resolution passed over.
 *
 * A hit by a recorded POINT is never position alone (`hit.point`): the policy
 * only takes a point when an element of the recorded kind sits under it
 * (markPoint), and it is the yardstick that refuses a path landing far from
 * the recorded box — it is how the recording found that very element, not a
 * guess at a slot (the "recorded points" parity cells: a point's click on the
 * near Mark, with the recorded primary gone, is the recorded click).
 */
function positionalOnly(hit: { structural: boolean; point?: boolean; missed: readonly number[] } | null, identifying: readonly number[]): boolean {
  if (!identifying.length) return false;
  if (!hit) return true;
  if (hit.point) return false;
  return hit.structural && identifying.every((i) => hit.missed.includes(i));
}

/**
 * RULE R2(b) — a positional fallback on an acting click must be the recorded
 * element BY NAME (round 61, grafana fwgr73 05-open step 3). The Edit click's
 * testid and role rung both missed — 04-open's recovery had left the
 * dashboard in edit mode, so there was no Edit button — and the positional
 * `…div:nth-of-type(5) > button` took the step onto whatever toolbar button
 * sat there. A path through the document names a slot, not a control; the
 * element it finds is accepted only when it carries the accessible name the
 * chain recorded (the same role, exactly that name — "Exit edit" is not
 * "Edit"). Otherwise the step stops, naming why, and never clicks a different
 * button. Asked of the element itself — its own aria snapshot's role and
 * accessible name, the terms the recording's lines are in — so both runners
 * read the name the same way.
 *
 * The resolution-time sibling of rule D (an inline heal of a different role
 * must not dispatch), which judges a HEALED locator; this judges a recorded
 * positional rung. Kept apart on purpose.
 */
async function positionalHitNamed(hit: Locator, want: { by: 'role' | 'label' | 'text'; role?: string; name: string }): Promise<boolean> {
  const norm = (t: string) => t.replace(/\s+/g, ' ').trim();
  let head: string;
  try {
    head = ((await hit.first().ariaSnapshot({ timeout: POSITIONAL_PROBE_MS })) ?? '').split('\n')[0] ?? '';
  } catch {
    return false;
  }
  // `- role "name" [state]…` — the element's own role and accessible name, as
  // the recording's lines state them.
  const m = /^-\s*([A-Za-z][\w-]*)(?:\s+"((?:[^"\\]|\\.)*)")?/.exec(head.trim());
  if (!m) return false;
  const role = m[1];
  const name = norm((m[2] ?? '').replace(/\\(.)/g, '$1'));
  if (want.by === 'role' && role !== want.role) return false;
  if (name === norm(want.name)) return true;
  if (want.by !== 'text') return false;
  try {
    return norm((await hit.first().innerText({ timeout: POSITIONAL_PROBE_MS })) ?? '') === norm(want.name);
  } catch {
    return false;
  }
}

/** A popup line: what the opener guard (replay's openerLines) owns. */
const POPUP_LINE = /^-?\s*(dialog|alertdialog|menu|menubar|listbox|tooltip)\b/;

/**
 * RULE R2(a) — the lines an ADDING-ONLY click may be skipped on, as already
 * in effect, when its identifying rungs all miss (round 61, grafana fwgr73
 * 05-open step 3: the Edit click on a dashboard 04-open's recovery had left
 * in edit mode — Add, Settings, Exit edit, Save dashboard all showing, the
 * Edit button gone). Empty — never skipped — for anything but a plain click
 * whose whole recorded effect was lines ADDED, and never for one the
 * segment's work depends on:
 *  - one that submits it: an earlier fill, type, select, check or uncheck in
 *    the same segment (the round-56 provenance: work the click may carry);
 *  - one that closes what it opened, or any recorded removal at all
 *    (`removedContains`, `removalRequired`), an alert, or a mint;
 *  - a popup opener (the opener guard's), a toggle or a re-open (their own
 *    rules).
 * Lines carrying this run's value, transient ones and ones that identify
 * nothing decide nothing, as for a toggle.
 */
function alreadyAddedLines(
  steps: readonly {
    tool: string;
    mints?: unknown;
    toggle?: unknown;
    closedBefore?: unknown;
    expect?: { addedContains?: readonly string[]; alertContains?: string; removedContains?: readonly string[]; removalRequired?: unknown };
  }[],
  index: number,
): string[] {
  const step = steps[index];
  if (!step || step.tool !== 'click' || step.mints || step.toggle || step.closedBefore) return [];
  const e = step.expect;
  if (!e?.addedContains?.length || e.alertContains || e.removedContains?.length || e.removalRequired) return [];
  if (steps.slice(0, index).some((s) => ['fill', 'type', 'select', 'check', 'uncheck'].includes(s.tool))) return [];
  const lines = e.addedContains.filter((l) => !TRANSIENT_LINE.test(l) && !SLOT_LINE.test(l) && !identifiesNothing(l));
  if (!lines.length || lines.some((l) => POPUP_LINE.test(l))) return [];
  return lines;
}

/** Every one of `lines` (filled for this run) shows on one look at the page; no look is no. */
async function everyLineShows(page: Page, lines: readonly string[], params: Record<string, string>, d: LineDialect): Promise<boolean> {
  const live = await captureLines(page, d);
  if (!live) return false;
  return liveLines(lines, params).every((line) => lineShows(live.lines, [line]));
}

/**
 * RULE R2, both halves, for a click whose identifying rungs all missed
 * (positionalOnly): what both runners do BEFORE dispatching it.
 *  (a) `skip` when it has skip lines (alreadyAddedLines) and every one of
 *      them already shows — the state it was recorded producing is in place;
 *  (b) else `stop` when a positional rung took it (`hit`) and the element
 *      there does not carry the recorded accessible name (positionalHitNamed).
 * Null otherwise — including a chain that resolved by an identifying rung,
 * and a miss with nothing to skip on, which stops as a miss always has.
 */
async function positionalClickVerdict(
  page: Page,
  hit: { locator: Locator; index: number; structural: boolean; point?: boolean; missed: readonly number[] } | null,
  identifying: readonly number[],
  lines: readonly string[],
  want: { by: 'role' | 'label' | 'text'; role?: string; name: string } | null,
  params: Record<string, string>,
  d: LineDialect = 1,
): Promise<{ skip: string } | { stop: string } | null> {
  if (!positionalOnly(hit, identifying)) return null;
  if (lines.length && (await everyLineShows(page, lines, params, d))) {
    return {
      skip: `every identifying locator missed and everything this click was recorded adding is already showing (${JSON.stringify(lines[0])}${lines.length > 1 ? ` and ${lines.length - 1} more` : ''}) — its recorded effect is in place, so it is skipped`,
    };
  }
  const name = want ? want.name.replace(/\{\{([\w.#:-]+)\}\}/g, (m, k: string) => params[k] || m) : '';
  const named = want && name && !/\{\{[^}]*\}\}/.test(name) ? { ...want, name } : null;
  if (hit && named && !(await positionalHitNamed(hit.locator, named))) {
    return {
      stop: `every identifying locator missed, and the positional fallback #${hit.index + 1} is not the recorded "${named.name}" — the element there carries another name, so it was not clicked`,
    };
  }
  return null;
}

/*
 * A READ OFF ITS RECORDED ELEMENT (round 62, gitea fwgt13 02-create). The
 * recording read the assignee LINK ("bench-assignee"); on n2 and n3 none of
 * its candidates matched, an inline heal proposed the "Add a link" BUTTON (a
 * role-and-name candidate) from the live page, and the button's text was
 * published as the assignee. A read resolved by an inline heal, or by a positional
 * candidate standing in for a better one that missed, reads an element the
 * recording's own names did not reach. It is published only where that
 * element is the KIND the recording read — the role a point or a role
 * candidate recorded, else the point's tag, as markPoint judges a point —
 * on the element itself, an ancestor it is painted inside, or the one
 * descendant that carries all its text (a wrapper the css named). Otherwise
 * the read is skipped, and said to be, in both runners. A chain that records
 * no kind has nothing to compare, and the read stands as before.
 */

/** A kind the recording read: a role, else a tag. */
interface RecordedKind {
  role: string | null;
  tag: string | null;
}

/** The kinds a recorded chain names for its target: each point's role (else its tag), each role candidate's role. */
function recordedKinds(chain: readonly unknown[] | undefined): RecordedKind[] {
  const out: RecordedKind[] = [];
  for (const c of chain ?? []) {
    const cand = c as { kind?: unknown; role?: unknown; tag?: unknown };
    if (cand.kind === 'point') out.push(typeof cand.role === 'string' && cand.role ? { role: cand.role, tag: null } : { role: null, tag: typeof cand.tag === 'string' ? cand.tag : null });
    else if (cand.kind === 'role' && typeof cand.role === 'string' && cand.role) out.push({ role: cand.role, tag: null });
  }
  return out.filter((k) => k.role || k.tag);
}

/**
 * Is the element `loc` resolved to the kind of thing the recording read (see
 * above)? True when the chain records no kind; null when the page cannot say
 * — which never withholds.
 */
async function readsRecordedKind(loc: Locator, kinds: readonly RecordedKind[]): Promise<boolean | null> {
  if (!kinds.length) return true;
  try {
    return await loc.first().evaluate(
      (el, kinds) => {
        const kindOf = (e: Element): { role: string | null; tag: string } => {
          const tagOf = e.tagName.toLowerCase();
          const type = (e.getAttribute('type') || '').toLowerCase();
          const implicit = (): string | null => {
            if (tagOf === 'button') return 'button';
            if (tagOf === 'a') return e.hasAttribute('href') ? 'link' : null;
            if (tagOf === 'select') return e.hasAttribute('multiple') ? 'listbox' : 'combobox';
            if (tagOf === 'textarea') return 'textbox';
            if (tagOf === 'img') return 'img';
            if (/^h[1-6]$/.test(tagOf)) return 'heading';
            if (tagOf === 'input') {
              if (type === 'checkbox') return 'checkbox';
              if (type === 'radio') return 'radio';
              if (type === 'submit' || type === 'button' || type === 'reset') return 'button';
              if (type === 'search') return 'searchbox';
              if (type === 'number') return 'spinbutton';
              if (['text', 'email', 'tel', 'url', 'password', ''].includes(type)) return 'textbox';
              return null;
            }
            return null;
          };
          return { role: e.getAttribute('role') || implicit(), tag: tagOf };
        };
        const is = (e: Element): boolean => {
          const k = kindOf(e);
          return kinds.some((want) => (want.role ? k.role === want.role : k.tag === want.tag));
        };
        for (let cur: Element | null = el, hops = 0; cur && hops < 6; cur = cur.parentElement, hops++) if (is(cur)) return true;
        const text = (e: Element): string => ((e as HTMLElement).innerText ?? e.textContent ?? '').replace(/\s+/g, ' ').trim();
        const own = text(el);
        return own !== '' && Array.from(el.querySelectorAll('*')).some((d) => is(d) && text(d) === own);
      },
      kinds as RecordedKind[],
      { timeout: 1_000 },
    );
  } catch {
    return null;
  }
}

/** Why both runners skip a read that resolved to another kind of element (the same words in each). */
function offRecordReadReason(label: string, how: string, kinds: readonly RecordedKind[]): string {
  const wanted = kinds.map((k) => k.role ?? k.tag).join(' or ');
  return `read '${label}' resolved by ${how} to an element that is not a ${wanted}, the kind the recording read — its value is not published`;
}

// Shared execution source: report.ts. Regenerate to update.
/**
 * REPORT-TEMPLATE VALUES, the rule both execution targets share. A zero-model
 * run reports what it read live, and — standing in for the recording's report
 * — every value of the skill's report template built from the caller's own
 * `{{vN}}` parameters, filled for this run. A recorded literal (run 1's record
 * id) is stale on any later run and is never published.
 *
 * The daemon applies it in synthesizeReport (src/skills/learn.ts) to the last
 * segment of the chain it replayed; a compiled artifact applies it after the
 * last segment of the step, for every value no live read of the step has
 * already published. fwgh4's artifact refused to compile over a value only the
 * daemon published: 03-open consumed `{{02-create.post_title_element_text}}`,
 * the template's `"{{v2}}"`, and the artifact carried the template only for a
 * goal guard.
 *
 * A PARAM DOES NOT VOUCH FOR THE TEXT AROUND IT. fwrd86's 06-delete template
 * held `list_row_RD-1015: "{{v1}} | {{v4}} RD Bench Ticket [Archived] | … |
 * Created: 2026-09-23"` and `list_default_count: "Showing 1–10 of 13 ({{v1}}
 * hidden …)"`. Each carries a slot, so each was "built from the caller's
 * params", and both replays published the recording's date and the
 * recording's counts as their own findings — n2 archived a second ticket and
 * still reported "of 15". The slot is this run's; the text between the slots
 * is the recording's. So every literal of a template value must stand on THIS
 * run's page before the value is published (unshownLiterals), and a value
 * whose literal the page does not show is withheld, in both runners, rather
 * than reported from memory.
 *
 * Self-contained: sibling shared modules and Playwright types only.
 */

/**
 * Whether a template value is built from this run's parameters at all (a
 * recorded literal is not): a caller's slot `{{vN}}`, or a value the run
 * minted and bound from its own url `{{dN}}` (fwec8 02-create's record id).
 */
function derivesFromParams(template: string): boolean {
  return /\{\{[vd]\d+\}\}/.test(template);
}

/** The `{{vN}}`/`{{dN}}` markers a template value names. */
function templateMarkers(template: string): string[] {
  return [...new Set(Array.from(template.matchAll(/\{\{([vd]\d+)\}\}/g), (m) => m[1]))];
}

/**
 * The recording's own text in a template value: what stands between its
 * slots, whitespace collapsed. A run holding no letter or digit — the ` | `
 * or `%` the report joined its slots with — states nothing about the page and
 * is not a literal to observe.
 */
function templateLiterals(template: string): string[] {
  return template
    .split(/\{\{[^{}]*\}\}/)
    .map((s) => s.replace(/\s+/g, ' ').trim())
    .filter((s) => /[\p{L}\p{N}]/u.test(s));
}

/**
 * The literals of `template` this run's page does not show. `shown` is the
 * page as shownForReport captured it once the step's work was done; null (the
 * page could not be read) observed nothing, so every literal is unshown. A
 * look that could not cover the page only ever withholds.
 *
 * Compared by WORDS — the literal's runs of letters and digits, whole and in
 * order, within one line — not by its characters. A literal is the text
 * BETWEEN slots, so its edges are whatever joined it to them: fwec8
 * 02-create's close_date `"Dec 31 ({{v5}})"` looked for `"Dec 31 ("`, the
 * page showed "Dec 31", and an observed value was withheld. The punctuation
 * is the report's joinery; the words are what the page has to show.
 */
function unshownLiterals(template: string, shown: readonly string[] | null | undefined): string[] {
  const literals = templateLiterals(template);
  if (!shown) return literals;
  const lines = shown.map((line) => ` ${wordRun(line)} `);
  return literals.filter((literal) => !lines.some((line) => line.includes(` ${wordRun(literal)} `)));
}

/** A text's words, case-folded and joined by single spaces. */
function wordRun(text: string): string {
  return words(text).join(' ');
}

/**
 * The value a template entry publishes on this run, or null when it publishes
 * nothing: a recorded literal; a value that still asks for something once
 * filled (a slot left unbound, or a param that itself still holds a
 * `{{step.output}}` reference — fwod56); one that fills to nothing (a slot
 * bound to '' — round 26's rule J: an empty value is unfilled, not a value);
 * or one whose recorded text this run's page does not show (fwrd86, above).
 *
 * `opts.literal` admits a template with no slot at all, held to the same page
 * test: the already-satisfied guard publishes the values its skipped
 * read-backs would have, and there the page it just judged is the only
 * observation there is.
 */
function templateValue(
  template: string,
  params: Record<string, string>,
  shown: readonly string[] | null | undefined,
  opts: { literal?: boolean; given?: GivenEvidence } = {},
): string | null {
  if (!opts.literal && !derivesFromParams(template)) return null;
  const filled = fillParams(template, params);
  if (!filled || /\{\{/.test(filled)) return null;
  if (unshownLiterals(template, shown).length) return null;
  // With the run's evidence, the one classification decides (classifyReportValue).
  if (opts.given) return classifyReportValue(template, params, shown, opts.given, { literal: opts.literal }).value;
  return filled;
}

/*
 * A PARAM IS GIVEN, NOT OBSERVED (round 60, Gitea fwgt11 07-add). The rule
 * above checks the text BETWEEN a template's slots; a value made of slots
 * alone has none, so it published whatever the caller passed. s_c8e15e's
 * template carried `issue_content_right_a_it: "{{v7}}"` — the recording's
 * read of the sidebar labels, split into keys — and v7 was the flow's literal
 * "bug", taken from the instruction; no step of the chain typed or read it.
 * n2 and n3's issue carried priority-high alone (their live labels_shown said
 * so), and both published "bug" beside it as a finding.
 *
 * So a slot of a value with no recorded text is published only where THIS run
 * observed it: its words stand in one line of the page the step settled on
 * (shownForReport — the url included, so an id used only in the url is
 * observed there), or in a value a read of this run returned. A slot the
 * procedure TYPED (a setting step's `value`/`text` names it) is not this
 * rule's: classifyReportValue (below) holds it to a commit (phase B). Otherwise
 * the value is withheld, and said to be given, not observed.
 *
 * "Where the recording's read-back would look" has no recorded location for a
 * value no step reads, so the page's lines are where it looks; the page is
 * judged line by line, as the literal rule judges it. A `{{dN}}` is the run's
 * own url, observed by construction.
 */

/** What a run observed besides the page: the slots its procedure typed, and the values its reads returned. */
interface GivenEvidence {
  typed: readonly string[];
  live: readonly string[];
  /**
   * The typed slots a commit showed on THIS run (expect.ts committedSlots: a
   * line the click's own diff added, not a control's, not a popup item).
   * Absent means none.
   */
  committed?: readonly string[];
  /**
   * The urls this run's page LANDED on while the chain ran, in any segment
   * (urlTrail) — not only the page it ends on (round 63, Ghost fwgh17 04-open:
   * the chain loaded the given public URL, read its title, and went back to
   * the admin list). A given value one of them shows was observed there.
   */
  visited?: readonly string[];
}

/*
 * WHAT A RUN TYPED IS NOT WHAT IT OBSERVED (phase B provenance, stage 1). The
 * given rule above used to exempt a slot the procedure typed — "the echo
 * rules' to judge" — but the echo rules only ever see READS, so a report value
 * made of a typed slot (`entered_title: "{{v1}}"`) published the caller's own
 * param with no page, read or commit check, in both runners. The census
 * (bench/provenance-census.mjs, 308 published runs) found 389 stored template
 * values carrying a typed slot; a hard effect line after the typing covered
 * only 121, and among the rest were sign-in passwords published as findings
 * (fwrd78, fwrd79, fwrd83: `password: "bench-pass-1234"`).
 *
 * So a typed slot is reported only where this run COMMITTED it — a click's own
 * diff showed it outside its control (GivenEvidence.committed) — or a read of
 * this run that was not an echo returned it. Otherwise the value is an ECHO of
 * the run's own typing: withheld from the report, still given to a later
 * step's reference, as an echoed read is. Not partial: echoes are not a
 * failure of the step (step-verdict.ts, round 55), only not a finding.
 */

/** How a report value stands on this run: the one classification both runners publish by. */
type ReportClass = 'observed' | 'committed' | 'echo' | 'given' | 'withheld';

interface ReportVerdict {
  /** The value published as a finding, or null. */
  value: string | null;
  class: ReportClass;
  /** For `echo` and `given`: the slots this run did not observe. */
  slots: string[];
}

/**
 * THE classification of one report-template value on this run, shared by the
 * daemon (learn.ts synthesize, server.ts's already-satisfied guard) and the
 * artifact (emit.ts reportTemplateLines, satisfiedGuard):
 *  - withheld: nothing to publish (templateValue: a recorded literal, an
 *    unbound or empty slot, recorded text the page does not show);
 *  - echo: a slot this run typed that nothing committed and no read returned;
 *  - given: a param-only value's slot this run never observed (round 60);
 *  - committed: every typed slot committed (or read back outside its control);
 *  - observed: no typed slot, and everything else stands on this run's page or reads.
 */
function classifyReportValue(
  template: string,
  params: Record<string, string>,
  shown: readonly string[] | null | undefined,
  evidence: GivenEvidence,
  opts: { literal?: boolean } = {},
): ReportVerdict {
  const whole = templateValue(template, params, shown, opts);
  if (whole === null) return { value: null, class: 'withheld', slots: [] };
  const typed = new Set(evidence.typed);
  const committed = new Set(evidence.committed ?? []);
  const live = evidence.live.map((line) => ` ${wordRun(line)} `);
  const typedHere = templateMarkers(template).filter((m) => m.startsWith('v') && typed.has(m));
  const open = typedHere.filter((slot) => {
    if (committed.has(slot)) return false;
    const run = wordRun(params[slot] ?? '');
    return run !== '' && !live.some((line) => line.includes(` ${run} `));
  });
  if (open.length) return { value: null, class: 'echo', slots: open };
  const given = unobservedGiven(template, params, shown, evidence);
  if (given.length) return { value: null, class: 'given', slots: given };
  return { value: whole, class: typedHere.length ? 'committed' : 'observed', slots: [] };
}

/** The warning both runners give for a report value withheld as an echo of the run's own typing. */
function typedWarning(key: string): string {
  return `report value ${key} is only what this run typed: no click's own diff showed it outside its control and no read returned it — withheld from the report (still given to a later step)`;
}

/** A step the typed-slot walk reads: its tool, its args, and a loop's body. */
interface TypingStep {
  tool: string;
  args: Record<string, unknown>;
  body?: readonly TypingStep[];
}

/** The `{{vN}}` slots a procedure TYPED: named in the `value` or `text` a setting step put on the page, loop bodies included. */
function typedSlots(steps: readonly TypingStep[]): string[] {
  const out = new Set<string>();
  const walk = (list: readonly TypingStep[]): void => {
    for (const s of list) {
      if (setsSomething(s.tool)) {
        for (const arg of [s.args.value, s.args.text]) {
          if (typeof arg === 'string') for (const m of templateMarkers(arg)) if (m.startsWith('v')) out.add(m);
        }
      }
      if (s.body) walk(s.body);
    }
  };
  walk(steps);
  return [...out];
}

/**
 * The `{{vN}}` slots of a template value made only of params that this run did
 * not observe (see above); [] when it observed them all, and for a value with
 * recorded text, which unshownLiterals governs. A slot unbound, or bound to a
 * value with no letter or digit, states nothing to observe.
 */
function unobservedGiven(template: string, params: Record<string, string>, shown: readonly string[] | null | undefined, evidence: GivenEvidence): string[] {
  if (templateLiterals(template).length) return [];
  const typed = new Set(evidence.typed);
  const lines = [...(shown ?? []), ...evidence.live].map((line) => ` ${wordRun(line)} `);
  // A url the chain LOADED observes a value that IS that url — the whole of
  // it, never a word inside it: a label "bug" is not observed by a
  // `?labels=bug` the page once had.
  const landed = new Set((evidence.visited ?? []).map(sameUrl));
  return templateMarkers(template).filter((slot) => {
    if (!slot.startsWith('v') || typed.has(slot)) return false;
    const run = wordRun(params[slot] ?? '');
    if (run === '' || landed.has(sameUrl(params[slot] ?? ''))) return false;
    return !lines.some((line) => line.includes(` ${run} `));
  });
}

/** A url as the visited rule compares it: trimmed, its fragment and a trailing slash dropped. */
function sameUrl(url: string): string {
  return url.trim().split('#')[0].replace(/\/+$/, '');
}

/** Whether a template value is withheld as given, not observed: it would publish, but for its unobserved slots. */
function withheldAsGiven(template: string, params: Record<string, string>, shown: readonly string[] | null | undefined, evidence: GivenEvidence): boolean {
  return templateValue(template, params, shown) !== null && unobservedGiven(template, params, shown, evidence).length > 0;
}

/** The warning both runners give for a value withheld as given, not observed. */
function givenWarning(key: string): string {
  return `report value ${key} is given, not observed: it is built only from the step's own parameters, and neither this run's page nor any of its reads shows it — withheld`;
}

/** Why a step whose instruction asked for such a value is PARTIAL (step-verdict.ts partialReasons; the artifact says the same). */
function givenPartialReason(key: string): string {
  return `${key}, an output this step was asked to report, is only the step's own parameter and this run never observed it, so ${key} went unreported`;
}

/** The one slot a template value is built from, or null when it names none or several. */
function templateSlot(template: string): string | null {
  const slots = templateMarkers(template);
  return slots.length === 1 ? slots[0] : null;
}

/**
 * What a LATER STEP'S REFERENCE to a template value resolves to on this run.
 * The whole value where this page shows its recorded text (templateValue);
 * otherwise, for a value built from one slot, that slot's own value — the
 * part this run supplied. fwod74's 06-open referenced 05-open's
 * `second_product_name`, templated `"[FURN_6666] {{v7}}"`: the brackets are the
 * recording's, the product is this run's, and a consumer that cannot be given
 * the product would lose the step to recovery for want of decoration. Never
 * the recording's text: a value from several slots whose text the page does
 * not show resolves to nothing, as it does in the report.
 *
 * Only for references: the report keeps the confident rule, so this is asked
 * only of outputs a later step consumes (the daemon's flow runner, the
 * artifact's reportTemplateLines — the same set, consumedReportedOutputs).
 */
function referenceValue(template: string, params: Record<string, string>, shown: readonly string[] | null | undefined, opts: { literal?: boolean } = {}): string | null {
  const whole = templateValue(template, params, shown, opts);
  if (whole !== null) return whole;
  const slot = templateSlot(template);
  const value = slot ? params[slot] : undefined;
  return value && !value.includes('{{') ? value : null;
}

/**
 * Whether a template value publishes for a reference on EVERY run whose
 * params bind: one built from slots alone, or from one slot (referenceValue's
 * fallback). A value from several slots with recorded text between them
 * publishes only on a run whose page shows that text, so it is no source a
 * compile can promise — the question publishedOutputs and the artifact's
 * unsourcedRef both ask, so compile and replay agree.
 *
 * And only if every marker in it is BOUND (`bound`): a declared param of the
 * procedure or a value its chain derives. fwec8 03-verify's s_55d615 carried
 * `record_id: "{{v2}}"` with no v2 among its params — the whole-url v1 had
 * swallowed it — and this still counted it, so compile and export promised
 * an output no replay could ever fill.
 */
function templateSource(template: string, bound: (name: string) => boolean = () => true): boolean {
  return (
    derivesFromParams(template) &&
    templateMarkers(template).every(bound) &&
    (templateLiterals(template).length === 0 || templateSlot(template) !== null)
  );
}

/**
 * Does any of these template values need the page to decide it — a value with
 * recorded text to observe, or (round 60, fwgt11) a slot of a param-only value
 * the procedure did not type (`typed`, typedSlots), which is observed there.
 */
function reportNeedsPage(templates: readonly string[], typed: readonly string[] = []): boolean {
  return templates.some((t) => templateLiterals(t).length > 0 || templateMarkers(t).some((m) => m.startsWith('v') && !typed.includes(m)));
}

/**
 * The page a report's literals are observed on, taken once the step's work is
 * done — the daemon after the chain's last segment, the artifact after the
 * step's. Two looks: the dialect-2 lines (every control's name and value,
 * frames and open shadow roots included) and the document's rendered text,
 * line by line. The lines alone carry only interactive roles, and fwrd86's
 * "Showing 1–10 of 13" is plain text: a figure the page does show would be
 * withheld on every run. The page's own url is observed too: fwrd72's
 * `landing_page` is `"{{v1}}#/tickets"`, and `#/tickets` is only ever in the
 * address bar. Null only when nothing could read the page.
 */
async function shownForReport(page: Page): Promise<string[] | null> {
  const lines = (await captureLines(page, 2).catch(() => null))?.lines ?? null;
  const text = await page
    .evaluate(() => document.body?.innerText ?? '')
    .then((t) => t.split('\n'))
    .catch(() => null);
  if (!lines && !text) return null;
  return [...(lines ?? []), ...(text ?? []), page.url()];
}



/**
 * THE SUMMARY, under the same provenance rule as the values. Recorded prose
 * is published only where every word of it was observed on this run: shown
 * on the page (`shown`), or supplied by it — the caller's instruction, a
 * slot's value, a live read, a value it kept (`observed`). fwrd86 06-delete's
 * summary still said "total 15 ({{v1}} plus the pre-existing archived
 * RD-1013)" on n2, which had archived a third ticket, and 04-edit's said
 * "(previously $375.00)", a figure 04-edit never read. Neither is a value, so
 * the value rule never reached them.
 *
 * By clause, not all or nothing. A sentence stands or falls on its lead
 * clause; inside a sentence that stands, each `;`-part and ` — `-part stands
 * or falls on its own text, and takes its parentheticals with it — an
 * enumeration label included. fwvk7 03-open, n2, published "2026-12-31; (d);
 * (e); (f) one comment …": the clauses had gone and their labels had not,
 * because a label was judged as a clause of its own. Inside a part that
 * stands, each parenthetical stands or falls alone, so "(previously
 * $375.00)" goes and the sentence around it stays. The sentence's own stop
 * is kept with the sentence. Quoted text is never cut. A clause holding an
 * unresolved `{{` goes too. Nothing left is '' (the caller then says what it
 * replayed and observed instead). Words are compared whole and case-folded,
 * and the page is one bag of words: the accepted whole-page caveat.
 */
function observedSummary(
  summary: string,
  observed: readonly string[],
  shown: readonly string[] | null | undefined,
  /** The caller's own further test of a clause (the daemon's stale-value rule); false drops it. */
  keep: (clause: string) => boolean = () => true,
): { text: string; dropped: string[] } {
  const bag = new Set<string>();
  for (const t of [...observed, ...(shown ?? [])]) for (const w of words(t)) bag.add(w);
  const ok = (clause: string): boolean => !clause.includes('{{') && words(clause).every((w) => bag.has(w)) && keep(clause);
  const whole = (part: SummaryPart): string => part.pieces.map((p) => p.text).join('');
  // A part is judged on its own words; one that has none but its
  // parentheticals (a bare "(d)") on those.
  const stands = (part: SummaryPart): boolean => {
    const own = part.pieces.filter((p) => !p.paren).map((p) => p.text).join('');
    return ok(words(own).length ? own : whole(part));
  };
  const dropped: string[] = [];
  const out: string[] = [];
  for (const sentence of summarySentences(summary)) {
    const [lead, ...rest] = sentence.parts;
    if (!lead || !stands(lead)) {
      const text = (sentence.parts.map(whole).join('') + sentence.end).trim();
      if (text) dropped.push(text);
      continue;
    }
    for (const part of [lead, ...rest]) {
      if (part !== lead && !stands(part)) {
        dropped.push(whole(part).trim());
        continue;
      }
      for (const piece of part.pieces) {
        if (!piece.paren || ok(piece.text)) out.push(piece.text);
        else dropped.push(piece.text.trim());
      }
    }
    out.push(sentence.end);
  }
  const text = out
    .join('')
    .replace(/\(\s*\)/g, '')
    .replace(/\s+([,.;:])/g, '$1')
    .replace(/[;,:]\s*([.!?])/g, '$1')
    .replace(/\s{2,}/g, ' ')
    .trim();
  return { text: /[\p{L}\p{N}]/u.test(text) ? text : '', dropped };
}

/** Case-folded words: runs of letters and digits, the unit a clause is observed in. */
function words(text: string): string[] {
  return Array.from(text.toLowerCase().matchAll(/[\p{L}\p{N}]+/gu), (m) => m[0]);
}

/** A clause of a sentence: its own text and its parentheticals, in order. */
interface SummaryPart {
  pieces: { text: string; paren: boolean }[];
}

/**
 * The prose as sentences of clauses, every character kept so the kept ones
 * rejoin as written. A sentence ends at `.`, `!` or `?` followed by
 * whitespace and then a capital, a quote or an opening bracket — or by the
 * end — so "i.e. 2026-12-31" (fwvk7) does not end one. Its stop is held
 * apart (`end`). Within it, a `;` or ` — ` starts a new clause that runs to
 * the next one; the first clause is the lead. A parenthetical is a piece of
 * the clause it stands in. Nothing is cut inside quotes, straight or curly.
 */
function summarySentences(text: string): { parts: SummaryPart[]; end: string }[] {
  const sentences: { parts: SummaryPart[]; end: string }[] = [];
  let parts: SummaryPart[] = [{ pieces: [] }];
  let cur = '';
  let depth = 0;
  let quoted = false;
  let curly = 0;
  const piece = (paren: boolean): void => {
    if (cur) parts[parts.length - 1].pieces.push({ text: cur, paren });
    cur = '';
  };
  const clause = (lead: string): void => {
    piece(false);
    parts.push({ pieces: [] });
    cur = lead;
  };
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (ch === '"') quoted = !quoted;
    else if (ch === '“') curly += 1;
    else if (ch === '”') curly = Math.max(0, curly - 1);
    const inQuote = quoted || curly > 0;
    if (!inQuote && ch === '(') {
      if (depth === 0) piece(false);
      depth += 1;
      cur += ch;
      continue;
    }
    if (!inQuote && ch === ')' && depth > 0) {
      cur += ch;
      depth -= 1;
      if (depth === 0) piece(true);
      continue;
    }
    if (inQuote || depth) {
      cur += ch;
      continue;
    }
    if ((ch === '.' || ch === '!' || ch === '?') && endsSentence(text, i)) {
      piece(false);
      sentences.push({ parts, end: ch });
      parts = [{ pieces: [] }];
    } else if (ch === ';') {
      // What follows a `;` is a clause of its own, and the `;` goes with it.
      clause(ch);
    } else if (ch === '—' && cur.endsWith(' ')) {
      cur = cur.slice(0, -1);
      clause(' —');
    } else cur += ch;
  }
  piece(false);
  if (parts.some((p) => p.pieces.length)) sentences.push({ parts, end: '' });
  return sentences;
}

/** Whether the stop at `i` ends its sentence: at the end, or before whitespace and a capital, quote or bracket. */
function endsSentence(text: string, i: number): boolean {
  const rest = text.slice(i + 1);
  if (!rest.trim()) return true;
  if (!/^\s/.test(rest)) return false;
  return /^\s+[\p{Lu}"“'‘(]/u.test(rest);
}

/**
 * The component recipes this file drives fill/type/select through: one
 * procedure per (family, intent), the daemon's own choice at compile time.
 * Compile-time state — the daemon keeps learning and demoting; this file
 * runs what it was given. Recompile to refresh it.
 */
const RECIPES: RecipeSnapshot = {"version":1,"recipes":[{"id":"r_f2510e","family":"monaco","intent":"set-value","steps":[{"action":"click"},{"action":"press","key":"ControlOrMeta+a"},{"action":"insertText","text":"{{value}}"},{"action":"settle","ms":400},{"action":"press","key":"Escape"},{"action":"blur","target":"textarea"},{"action":"settle","ms":200}],"verifyRead":".view-lines"},{"id":"r_1f3878","family":"monaco","intent":"read-value","steps":[],"verifyRead":".view-lines"},{"id":"r_cfd806","family":"codemirror6","intent":"set-value","steps":[{"action":"click","target":".cm-content"},{"action":"press","key":"ControlOrMeta+a"},{"action":"insertText","text":"{{value}}"},{"action":"settle","ms":400},{"action":"press","key":"Escape"},{"action":"blur","target":".cm-content"},{"action":"settle","ms":200}],"verifyRead":".cm-content"},{"id":"r_8cb3a2","family":"codemirror6","intent":"read-value","steps":[],"verifyRead":".cm-content"},{"id":"r_1ab693","family":"prosemirror","intent":"set-value","steps":[{"action":"click"},{"action":"press","key":"ControlOrMeta+a"},{"action":"insertText","text":"{{value}}"},{"action":"settle","ms":400},{"action":"blur"},{"action":"settle","ms":200}]},{"id":"r_7b1e49","family":"contenteditable","intent":"set-value","steps":[{"action":"click"},{"action":"press","key":"ControlOrMeta+a"},{"action":"insertText","text":"{{value}}"},{"action":"settle","ms":400},{"action":"blur"},{"action":"settle","ms":200}]},{"id":"r_1e0f2f","family":"aria-combobox","intent":"select-option","steps":[{"action":"click"},{"action":"press","key":"ControlOrMeta+a"},{"action":"insertText","text":"{{value}}"},{"action":"settle","ms":400},{"action":"click","target":"page:[role=\"option\"]","withText":"{{value}}"},{"action":"settle","ms":200}]}]};
const recipeBook = snapshotBook(RECIPES);

